class ControllerError(RuntimeError):
    pass


def utc() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def _parse_utc_instant(value: Any) -> dt.datetime:
    if not isinstance(value,str) or not value or len(value.encode())>64:
        raise ControllerError("UTC instant is malformed")
    try: parsed=dt.datetime.fromisoformat(value.replace("Z","+00:00"))
    except ValueError as exc: raise ControllerError("UTC instant is malformed") from exc
    if parsed.tzinfo is None: raise ControllerError("UTC instant must be timezone-aware")
    return parsed.astimezone(dt.timezone.utc)


def digest_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def real(path: str) -> str:
    return os.path.realpath(os.path.abspath(os.path.expanduser(path)))


def inside(path: str, root: str) -> bool:
    try:
        return os.path.commonpath([real(path), real(root)]) == real(root)
    except ValueError:
        return False


def require_regular(path: str) -> str:
    resolved = real(path)
    if os.path.islink(path) or not os.path.isfile(resolved):
        raise ControllerError("expected a regular non-symlink file")
    return resolved


def git(repo: str, args: List[str], check: bool = True) -> str:
    proc = subprocess.run(["git", "-C", repo] + args, text=True,
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and proc.returncode:
        raise ControllerError("git command failed: " + (proc.stderr.strip() or "unknown"))
    return proc.stdout


def validate_repo(repo: str, clean: bool = True) -> Tuple[str, str]:
    repo = real(repo)
    top = git(repo, ["rev-parse", "--show-toplevel"]).strip()
    if real(top) != repo:
        raise ControllerError("repo must be its git worktree top-level")
    if clean and git(repo, ["status", "--porcelain=v1"]).strip():
        raise ControllerError("repo is dirty; prepare requires a clean base repository")
    return repo, git(repo, ["rev-parse", "HEAD"]).strip()


def require_unchanged_base(repo: str, expected_head: str) -> None:
    """Permit an unignored controller `.worktrees/` directory, never base edits."""
    if git(repo, ["rev-parse", "HEAD"]).strip() != expected_head:
        raise ControllerError("base repository HEAD changed since prepare")
    for args in (["diff", "--quiet"], ["diff", "--cached", "--quiet"]):
        proc = subprocess.run(["git", "-C", repo] + args)
        if proc.returncode == 1:
            raise ControllerError("base repository has tracked changes since prepare")
        if proc.returncode > 1:
            raise ControllerError("cannot validate base repository cleanliness")
    unexpected = [line for line in git(repo, ["status", "--porcelain=v1"]).splitlines()
                  if line != "?? .worktrees/"]
    if unexpected:
        raise ControllerError("base repository has unexpected untracked changes since prepare")


def default_root(repo: str) -> str:
    key = digest_bytes(real(repo).encode())[:16]
    return os.path.join(os.path.expanduser("~/.cowork/orchestrator"), key)


def work_dir(root: str, work_id: str) -> str:
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}", work_id or ""):
        raise ControllerError("invalid work id")
    checked = subprocess.run(["git", "check-ref-format", "--branch", "codex/" + work_id],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    if checked.returncode != 0:
        raise ControllerError("work id is not a valid exact git branch suffix")
    root = real(root)
    target = os.path.join(root, work_id)
    if not inside(target, root):
        raise ControllerError("work path escapes state root")
    return target


def state_path(directory: str) -> str:
    return os.path.join(directory, "state.json")


@contextlib.contextmanager
def package_lock(directory: str) -> Iterable[None]:
    """Serialize package mutations; a lock is not state and is never trusted."""
    os.makedirs(directory, mode=0o700, exist_ok=True)
    path = os.path.join(directory, ".controller.lock")
    if os.path.islink(path):
        raise ControllerError("package lock may not be a symlink")
    fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def atomic_json(path: str, value: Any) -> None:
    directory = os.path.dirname(path)
    os.makedirs(directory, mode=0o700, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".tmp-", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as out:
            json.dump(value, out, sort_keys=True, indent=2)
            out.write("\n")
            out.flush()
            os.fsync(out.fileno())
        os.replace(temp, path)
    finally:
        try:
            os.unlink(temp)
        except FileNotFoundError:
            pass


def load(directory: str) -> Dict[str, Any]:
    path = state_path(directory)
    try:
        if os.path.islink(path):
            raise ControllerError("state file may not be a symlink")
        with open(path, encoding="utf-8") as src:
            state = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("malformed or unreadable state") from exc
    if not isinstance(state, dict) or state.get("schema_version") != SCHEMA:
        raise ControllerError("unsupported or malformed state schema")
    for key in ("work_id", "repo", "worktree", "phase", "revision"):
        if key not in state:
            raise ControllerError("malformed state: missing " + key)
    if state["work_id"] != os.path.basename(directory):
        raise ControllerError("state work id does not match its directory")
    repo = state["repo"] if isinstance(state["repo"], dict) else {}
    worktree = state["worktree"] if isinstance(state["worktree"], dict) else {}
    brief = state.get("brief") if isinstance(state.get("brief"), dict) else {}
    repo_root = repo.get("root")
    wt_path = worktree.get("path")
    if not isinstance(repo_root, str) or real(repo_root) != repo_root:
        raise ControllerError("malformed state: unsafe repository path")
    expected_wt = os.path.join(repo_root, ".worktrees", "orchestrator-" +
                               state["work_id"])
    if not isinstance(wt_path, str) or real(wt_path) != expected_wt or os.path.islink(wt_path):
        raise ControllerError("malformed state: unsafe worktree path")
    if not isinstance(brief.get("path"), str) or real(brief["path"]) != os.path.join(real(directory), "brief.md") or os.path.islink(brief["path"]):
        raise ControllerError("malformed state: unsafe brief path")
    if worktree.get("branch") != "codex/" + state["work_id"]:
        raise ControllerError("malformed state: unexpected worktree branch")
    return state


def save(directory: str, state: Dict[str, Any]) -> None:
    state["schema_version"] = SCHEMA
    state["revision"] = int(state.get("revision", 0)) + 1
    state["updated_at"] = utc()
    atomic_json(state_path(directory), state)


def load_rr(directory: str) -> Dict[str, Any]:
    """Load the Package C review-recovery state without standard worktree/repo constraints."""
    path = state_path(directory)
    try:
        if os.path.islink(path): raise ControllerError("recovery state file may not be a symlink")
        with open(path, encoding="utf-8") as src: state = json.load(src)
    except (OSError, json.JSONDecodeError) as exc: raise ControllerError("malformed or unreadable recovery state") from exc
    if not isinstance(state, dict) or state.get("schema_version") != SCHEMA: raise ControllerError("unsupported or malformed recovery state schema")
    if state.get("work_id") != os.path.basename(directory): raise ControllerError("recovery state work_id does not match its directory")
    if state.get("package_id") != PACKAGE_C_RR_PACKAGE_ID: raise ControllerError("recovery state is not Package C review recovery")
    if state.get("policy") != POLICY_ID: raise ControllerError("recovery state policy changed")
    return state


def save_rr(directory: str, state: Dict[str, Any]) -> None:
    """Save Package C review-recovery state atomically (no worktree/repo constraints)."""
    state["schema_version"] = SCHEMA
    state["revision"] = int(state.get("revision", 0)) + 1
    state["updated_at"] = utc()
    atomic_json(state_path(directory), state)


def append_event(directory: str, kind: str, **fields: Any) -> None:
    path = os.path.join(directory, "events.jsonl")
    if os.path.islink(path):
        raise ControllerError("event file may not be a symlink")
    row = {"at": utc(), "kind": kind, **fields}
    encoded = (json.dumps(row, sort_keys=True, separators=(",", ":")) + "\n").encode()
    with open(path, "ab") as out:
        out.write(encoded)
        out.flush()
        os.fsync(out.fileno())


def registered_worktree(repo: str, path: str, branch: str) -> bool:
    text = git(repo, ["worktree", "list", "--porcelain"])
    current: Dict[str, str] = {}
    for line in text.splitlines() + ["worktree __end__"]:
        if line.startswith("worktree "):
            if current and real(current.get("path", "")) == real(path):
                return current.get("branch") == "refs/heads/" + branch
            current = {"path": line[9:]}
        elif line.startswith("branch "):
            current["branch"] = line[7:]
    return False


def make_worktree(repo: str, work_id: str, head: str) -> Tuple[str, str]:
    branch = "codex/" + work_id
    base = os.path.join(repo, ".worktrees")
    path = os.path.join(base, "orchestrator-" + work_id)
    if not inside(path, base):
        raise ControllerError("worktree path escapes .worktrees")
    if os.path.exists(path):
        if not registered_worktree(repo, path, branch):
            raise ControllerError("existing worktree is not the recorded isolated branch")
        if git(path, ["rev-parse", "HEAD"]).strip() != head:
            raise ControllerError("existing worktree does not match base HEAD")
        if git(path, ["status", "--porcelain=v1"]).strip():
            raise ControllerError("existing worktree is dirty")
        return real(path), branch
    os.makedirs(base, mode=0o700, exist_ok=True)
    subprocess.run(["git", "-C", repo, "worktree", "add", path, "-b", branch, head],
                   text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
    if not registered_worktree(repo, path, branch):
        raise ControllerError("new worktree failed deterministic registration validation")
    return real(path), branch


def file_info(path: str, root: Optional[str] = None) -> Optional[Dict[str, Any]]:
    if not path or not os.path.isfile(path) or os.path.islink(path):
        return None
    if root and not inside(path, root):
        return None
    with open(path, "rb") as src:
        raw = src.read()
    return {"path": path, "bytes": len(raw), "sha256": digest_bytes(raw)}


def capped_regular_file_info(path: str, root: str, maximum: int) -> Optional[Dict[str, Any]]:
    """Hash one canonical in-root regular file without an unbounded read."""
    try:
        resolved = real(path)
        status = os.lstat(path)
    except (OSError, ValueError):
        return None
    if os.path.islink(path) or not os.path.isfile(resolved) or not inside(resolved, root):
        return None
    if not stat.S_ISREG(status.st_mode) or status.st_size > maximum:
        return None
    digest = hashlib.sha256(); total = 0
    try:
        with open(resolved, "rb") as src:
            while True:
                chunk = src.read(65536)
                if not chunk:
                    break
                total += len(chunk)
                if total > maximum:
                    return None
                digest.update(chunk)
    except OSError:
        return None
    return {"path": resolved, "bytes": total, "sha256": digest.hexdigest()}


def require_frozen_brief(state: Dict[str, Any], directory: str) -> Dict[str, Any]:
    brief = state.get("brief") if isinstance(state.get("brief"), dict) else {}
    expected_path = os.path.join(real(directory), "brief.md")
    path, expected_sha = brief.get("path"), brief.get("sha256")
    if not isinstance(path, str) or real(path) != expected_path or not isinstance(expected_sha, str):
        raise ControllerError("frozen brief binding is malformed")
    info = capped_regular_file_info(path, directory, MAX_BRIEF)
    if not info or info["sha256"] != expected_sha or info["bytes"] != brief.get("bytes"):
        raise ControllerError("frozen brief binding no longer matches")
    return info


def command_sha256(repo: str, args: List[str], limit: int = MAX_CANDIDATE_BYTES) -> Dict[str, Any]:
    """Hash command output without retaining any diff or candidate content."""
    proc = subprocess.Popen(["git", "-C", repo] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    total = 0
    digest = hashlib.sha256()
    try:
        assert proc.stdout is not None
        while True:
            chunk = proc.stdout.read(65536)
            if not chunk:
                break
            total += len(chunk)
            if total > limit:
                proc.kill()
                raise ControllerError("candidate evidence exceeds bounded digest limit")
            digest.update(chunk)
        stderr = (proc.stderr.read(4096) if proc.stderr else b"")
        if proc.wait() != 0:
            raise ControllerError("cannot fingerprint candidate evidence: " + stderr.decode("utf-8", "replace").strip()[:300])
    finally:
        if proc.poll() is None:
            proc.kill()
        # Reap before closing both pipes; close explicitly to avoid leaking
        # Popen file objects on bounded-output/error paths.
        proc.wait()
        if proc.stdout is not None:
            proc.stdout.close()
        if proc.stderr is not None:
            proc.stderr.close()
    return {"sha256": digest.hexdigest(), "bytes": total}


def declared_artifacts(worktree: str) -> List[Dict[str, Any]]:
    records = []
    for name in ("plan.md", "result.json", "review.json", "verification.json"):
        item = file_info(os.path.join(worktree, name), worktree)
        if item:
            records.append({"name": name, "bytes": item["bytes"], "sha256": item["sha256"]})
    return records


def worktree_fingerprint(worktree: str) -> Dict[str, Any]:
    """A bounded, content-sensitive candidate fingerprint; never exposes a diff."""
    head = git(worktree, ["rev-parse", "HEAD"]).strip()
    status = command_sha256(worktree, ["status", "--porcelain=v1", "-z", "--untracked-files=all"], MAX_CANDIDATE_PATH_BYTES)
    unstaged = command_sha256(worktree, ["diff", "--no-ext-diff", "--binary"])
    staged = command_sha256(worktree, ["diff", "--cached", "--no-ext-diff", "--binary"])
    listed = subprocess.run(["git", "-C", worktree, "ls-files", "--others", "--exclude-standard", "-z"],
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if listed.returncode or len(listed.stdout) > MAX_CANDIDATE_PATH_BYTES:
        raise ControllerError("cannot fingerprint bounded untracked candidate paths")
    paths = [x for x in listed.stdout.split(b"\0") if x]
    if len(paths) > MAX_CANDIDATE_FILES:
        raise ControllerError("candidate has too many untracked files to fingerprint")
    untracked = hashlib.sha256()
    total = 0
    for raw_path in paths:
        rel = os.fsdecode(raw_path)
        full = os.path.join(worktree, rel)
        if os.path.isabs(rel) or not inside(full, worktree):
            raise ControllerError("untracked candidate path escapes worktree")
        try:
            stat_result = os.lstat(full)
        except OSError as exc:
            raise ControllerError("untracked candidate changed during fingerprint") from exc
        untracked.update(raw_path + b"\0")
        if os.path.islink(full):
            target = os.fsencode(os.readlink(full))
            total += len(target)
            untracked.update(b"link\0" + target)
        elif os.path.isfile(full):
            untracked.update(b"file\0")
            with open(full, "rb") as src:
                while True:
                    chunk = src.read(65536)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > MAX_CANDIDATE_BYTES:
                        raise ControllerError("untracked candidate content exceeds bounded digest limit")
                    untracked.update(chunk)
        else:
            raise ControllerError("untracked candidate contains unsupported file type")
    value = {"head": head, "status": status, "unstaged_diff": unstaged, "staged_diff": staged,
             "untracked": {"sha256": untracked.hexdigest(), "count": len(paths), "bytes": total}}
    value["digest"] = digest_bytes(json.dumps(value, sort_keys=True, separators=(",", ":")).encode())
    return value


def process_alive(pid: Any, pgid: Any) -> bool:
    try:
        if pid:
            stat = subprocess.run(["ps", "-o", "stat=", "-p", str(int(pid))],
                                  text=True, stdout=subprocess.PIPE,
                                  stderr=subprocess.DEVNULL).stdout.strip()
            if not stat or "Z" in stat:
                return False
        if pgid:
            os.killpg(int(pgid), 0)
        elif pid:
            os.kill(int(pid), 0)
        else:
            return False
        return True
    except (OSError, ValueError, TypeError):
        return False


def bounded(value: Any, limit: int = MAX_OUTPUT) -> Any:
    encoded = json.dumps(value, sort_keys=True, separators=(",", ":"))
    if len(encoded.encode()) <= limit:
        return value
    return {"schema_version": 1, "truncated": True,
            "message": "response exceeded bounded output limit; inspect durable artifacts"}


def emit(value: Any, code: int = 0) -> int:
    print(json.dumps(bounded(value), sort_keys=True))
    return code


def resolve_executable(value: str) -> str:
    path = shutil.which(value) if not os.path.dirname(value) else real(value)
    if not path or not os.path.isfile(path) or not os.access(path, os.X_OK):
        raise ControllerError("claude executable is unavailable")
    return real(path)


def detached_spawn(argv: List[str], cwd: str, stdout_path: str, stderr_path: str) -> Tuple[int, int]:
    """POSIX double-fork/setsid spawn; the original parent receives grandchild PID."""
    read_fd, write_fd = os.pipe()
    child = os.fork()
    if child:
        os.close(write_fd)
        try:
            payload = os.read(read_fd, 128)
        finally:
            os.close(read_fd)
            os.waitpid(child, 0)
        try:
            pid, pgid = payload.decode("ascii").split(":", 1)
            return int(pid), int(pgid)
        except (ValueError, UnicodeDecodeError):
            raise ControllerError("detached worker did not report its pid")
    try:
        os.close(read_fd)
        os.setsid()
        if os.fork():
            os._exit(0)
        os.chdir(cwd)
        with open(stdout_path, "ab", buffering=0) as out, open(stderr_path, "ab", buffering=0) as err:
            os.dup2(out.fileno(), 1)
            os.dup2(err.fileno(), 2)
            null = os.open(os.devnull, os.O_RDONLY)
            os.dup2(null, 0)
            os.close(null)
            os.write(write_fd, ("%d:%d" % (os.getpid(), os.getpgrp())).encode("ascii"))
            os.close(write_fd)
            os.execv(argv[0], argv)
    except BaseException as exc:  # child: diagnostics go to raw log only
        try:
            os.write(2, ("orchestrate detached spawn failed: %s\n" % type(exc).__name__).encode())
            os.close(write_fd)
        except OSError:
            pass
        os._exit(127)


def normalize_structured(value: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(value, dict) or set(value) != set(OUTCOME_SCHEMA["required"]):
        return None
    if value.get("outcome") not in {"completed", "blocked", "needs_authority", "failed"}:
        return None
    result: Dict[str, Any] = {"outcome": value["outcome"]}
    limits = {"summary": 2000, "next_action": 1000}
    for key, limit in limits.items():
        if not isinstance(value.get(key), str) or len(value[key].encode()) > limit:
            return None
        result[key] = value[key]
    for key, maximum, item_max in (("changed_paths", 50, 300), ("checks", 20, 500),
                                   ("findings", 20, 500), ("assumptions", 20, 500)):
        items = value.get(key)
        if not isinstance(items, list) or len(items) > maximum or any(not isinstance(x, str) or len(x.encode()) > item_max for x in items):
            return None
        result[key] = items
    return result


def normalize_package_a_structured(value: Any) -> Optional[Dict[str,Any]]:
    required=set(PACKAGE_A_OUTCOME_SCHEMA["required"])
    if not isinstance(value,dict) or set(value)!=required or value.get("outcome") not in {"completed","blocked","needs_authority","failed"}:
        return None
    result={"outcome":value["outcome"]}
    for key,limit in (("summary",2000),("next_action",1000)):
        if not isinstance(value.get(key),str) or not value[key].strip() or len(value[key].encode())>limit: return None
        result[key]=value[key]
    paths=value.get("changed_paths")
    if not isinstance(paths,list) or any(not isinstance(x,str) or not x or len(x.encode())>300 for x in paths): return None
    _norm_paths=[]
    for _raw in paths:
        _rel=_raw[3:] if _raw.startswith(("?? "," M ")) else _raw
        if not _rel or os.path.isabs(_rel) or "\\" in _rel or os.path.normpath(_rel)!=_rel or _rel.startswith("../") or "/../" in _rel: return None
        _norm_paths.append(_rel)
    if len(_norm_paths)!=len(set(_norm_paths)): raise ControllerError("Package A worker changed_paths contains duplicates after normalization")
    if len(_norm_paths)>2: return None
    result["changed_paths"]=_norm_paths
    checks=value.get("checks")
    if not isinstance(checks,list) or not checks or len(checks)>20: return None
    normalized_checks=[]
    for row in checks:
        if (not isinstance(row,dict) or set(row)!={"command","cwd","exit_code","receipt_refs"} or
                not isinstance(row.get("command"),str) or not row["command"] or len(row["command"].encode())>500 or
                not isinstance(row.get("cwd"),str) or not row["cwd"] or len(row["cwd"].encode())>500 or
                isinstance(row.get("exit_code"),bool) or not isinstance(row.get("exit_code"),int) or row.get("receipt_refs")!=[]):
            return None
        normalized_checks.append({key:row[key] for key in ("command","cwd","exit_code","receipt_refs")})
    result["checks"]=normalized_checks
    api=value.get("record_api_summary")
    if (not isinstance(api,dict) or set(api)!={"records","validators","reducer","idempotency_key_builder"} or
            api.get("records")!=["DispatchContract","DispatchDecision","AttemptLink"] or
            api.get("validators")!=["validate_dispatch_contract(record)","validate_dispatch_decision(record, contract)","validate_attempt_link(record)"] or
            api.get("reducer")!="decide(contract, policy_result=None, preflight_result=None, probe_result=None)" or
            api.get("idempotency_key_builder")!="build_attempt_link_idempotency_key(role, kind, source_ref, ordinal)"):
        return None
    result["record_api_summary"]={key:api[key] for key in ("records","validators","reducer","idempotency_key_builder")}
    coverage=value.get("negative_control_coverage")
    if not isinstance(coverage,list) or not coverage or len(coverage)>40: return None
    normalized_coverage=[]; controls=set()
    for row in coverage:
        if (not isinstance(row,dict) or set(row)!={"control","test","status"} or
                not isinstance(row.get("control"),str) or not row["control"] or len(row["control"].encode())>300 or row["control"] in controls or
                not isinstance(row.get("test"),str) or not row["test"] or len(row["test"].encode())>300 or row.get("status") not in {"covered","not_covered"}):
            return None
        controls.add(row["control"]); normalized_coverage.append({key:row[key] for key in ("control","test","status")})
    result["negative_control_coverage"]=normalized_coverage
    for key,maximum,item_max in (("findings",20,500),("assumptions",20,500)):
        items=value.get(key)
        if not isinstance(items,list) or len(items)>maximum or any(not isinstance(x,str) or len(x.encode())>item_max for x in items): return None
        result[key]=list(items)
    return result


def final_structured_packet(directory: str, attempt: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Read only typed final-result events, never transcript/message content."""
    path = attempt.get("stdout")
    if not isinstance(path, str) or not inside(path, os.path.join(directory, "logs")) or os.path.islink(path):
        return None
    candidate = None
    try:
        with open(path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(event, dict):
                    continue
                if event.get("type") == "result" and isinstance(event.get("structured_output"), dict):
                    candidate = event["structured_output"]
                elif event.get("type") == "result" and isinstance(event.get("result"), dict):
                    candidate = event["result"]
    except OSError:
        return None
    _wid = os.path.basename(directory)
    if _wid == PACKAGE_B_WORK_ID:
        normalized = _normalize_package_b_structured(candidate)
    elif _wid == PACKAGE_C_WORK_ID:
        normalized = _normalize_package_c_structured(candidate)
    elif _wid in PACKAGE_A_IDENTITIES:
        normalized = normalize_package_a_structured(candidate)
    else:
        normalized = normalize_structured(candidate)
    if normalized is None:
        return None
    packet = {"schema_version": SCHEMA, "work_id": os.path.basename(directory),
              "attempt_id": attempt.get("id"), "provider_session_id": attempt.get("provider_session_id"), "structured": normalized,
              "source_log_sha256": (file_info(path, os.path.join(directory, "logs")) or {}).get("sha256")}
    packets = os.path.join(directory, "packets")
    os.makedirs(packets, mode=0o700, exist_ok=True)
    target = os.path.join(packets, str(attempt.get("id")) + ".json")
    existing=file_info(target,packets) if os.path.lexists(target) else None
    if os.path.lexists(target) and not existing:
        raise ControllerError("worker packet recovery path is unsafe")
    if existing:
        try: prior=json.loads(Path(existing["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("worker packet recovery copy is unreadable") from exc
        parsed_at=prior.get("parsed_at") if isinstance(prior,dict) else None
        stable=(isinstance(parsed_at,str) and bool(parsed_at) and len(parsed_at.encode())<=64 and
                {key:value for key,value in prior.items() if key!="parsed_at"}==packet)
        if not stable:
            intent=os.path.join(directory,"package-a-collect",str(attempt.get("id"))+".intent.json")
            if os.path.basename(directory) in PACKAGE_A_IDENTITIES and os.path.lexists(intent):
                raise ControllerError("worker packet recovery copy conflicts with durable Package A collect intent")
            packet["parsed_at"]=utc(); atomic_json(target,packet); existing=file_info(target,packets)
    else:
        packet["parsed_at"]=utc(); atomic_json(target,packet); existing=file_info(target,packets)
    return {"path": target, "sha256": (existing or {}).get("sha256"), "structured": normalized}


def provider_terminal_failure(directory: str, attempt: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Recognize a local package guard without retaining provider output text.

    ``error_max_budget_usd`` is the controller invocation's local package
    guard.  It is deliberately not evidence of a subscription/quota reset.
    """
    path = attempt.get("stdout")
    if not isinstance(path, str) or not inside(path, os.path.join(directory, "logs")) or os.path.islink(path):
        return None
    terminal = None
    try:
        with open(path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if (isinstance(event, dict) and event.get("type") == "result" and
                        event.get("subtype") == "error_max_budget_usd" and event.get("is_error") is True):
                    # Deliberately retain only the fixed protocol classification, never provider text.
                    terminal = {"type": "result", "subtype": "error_max_budget_usd", "is_error": True}
    except OSError:
        return None
    if terminal is None:
        return None
    info = file_info(path, os.path.join(directory, "logs"))
    if not info:
        return None
    packets = os.path.join(directory, "packets")
    os.makedirs(packets, mode=0o700, exist_ok=True)
    target = os.path.join(packets, str(attempt.get("id")) + ".provider_failure.json")
    existing_info = file_info(target, packets)
    if existing_info:
        try:
            with open(target, encoding="utf-8") as src:
                existing = json.load(src)
        except (OSError, json.JSONDecodeError):
            existing = None
        if (isinstance(existing, dict) and existing.get("kind") == "provider_terminal_failure" and
                existing.get("attempt_id") == attempt.get("id") and
                existing.get("provider_session_id") == attempt.get("provider_session_id") and
                existing.get("failure_class") == "local_package_budget_guard" and
                existing.get("source_log_sha256") == info["sha256"] and
                isinstance(existing.get("terminal_digest"), str)):
            return {"path": target, "sha256": existing_info["sha256"], "failure_class": "local_package_budget_guard",
                    "source_log_sha256": info["sha256"], "terminal_digest": existing["terminal_digest"]}
    packet = {"schema_version": SCHEMA, "kind": "provider_terminal_failure",
              "work_id": os.path.basename(directory), "attempt_id": attempt.get("id"),
              "provider_session_id": attempt.get("provider_session_id"),
              "failure_class": "local_package_budget_guard", "terminal": terminal,
              "source_log_sha256": info["sha256"],
              "terminal_digest": digest_bytes(json.dumps(terminal, sort_keys=True, separators=(",", ":")).encode()),
              "parsed_at": utc()}
    atomic_json(target, packet)
    item = file_info(target, packets)
    return {"path": target, "sha256": (item or {}).get("sha256"), "failure_class": packet["failure_class"],
            "source_log_sha256": info["sha256"], "terminal_digest": packet["terminal_digest"]}


def parse_retry_after(value: Any) -> Optional[str]:
    """Accept only a bounded, timezone-aware future RFC3339 reset instant."""
    if not isinstance(value, str) or len(value.encode()) > 64:
        return None
    try:
        instant = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if instant.tzinfo is None:
        return None
    now = dt.datetime.now(dt.timezone.utc)
    if instant <= now or instant > now + dt.timedelta(days=31):
        return None
    return instant.astimezone(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def parse_provider_reset_epoch(value: Any) -> Optional[str]:
    """Normalize a Claude ``resetsAt`` epoch only when it is safely bounded.

    A scheduled observer normally wakes just after the reset instant.  Keep a
    short past grace window so the typed capacity packet can still be bound and
    its one-shot lease consumed, while rejecting stale historical evidence.
    """
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    try:
        instant = dt.datetime.fromtimestamp(value, tz=dt.timezone.utc)
    except (OverflowError, OSError, ValueError):
        return None
    now = dt.datetime.now(dt.timezone.utc)
    if instant < now - PROVIDER_RESET_RECONCILE_GRACE or instant > now + dt.timedelta(days=31):
        return None
    return instant.isoformat().replace("+00:00", "Z")


def claude_subscription_quota_failure(directory: str, attempt: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Accept only a paired, same-session Claude structured quota envelope.

    This intentionally examines protocol fields only.  It does not retain or
    expose assistant/result text, provider errors, or arbitrary event fields.
    """
    path = attempt.get("stdout")
    session_id = attempt.get("provider_session_id")
    if (not isinstance(path, str) or not inside(path, os.path.join(directory, "logs")) or os.path.islink(path) or
            not isinstance(session_id, str) or not session_id):
        return None
    rate = None; terminal = None
    try:
        with open(path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(event, dict) or event.get("session_id") != session_id:
                    continue
                info = event.get("rate_limit_info")
                retry_after = parse_provider_reset_epoch(info.get("resetsAt")) if isinstance(info, dict) else None
                if (event.get("type") == "rate_limit_event" and isinstance(info, dict) and
                        info.get("status") == "rejected" and info.get("rateLimitType") == "five_hour" and
                        info.get("isUsingOverage") is False and info.get("overageStatus") == "rejected" and retry_after):
                    rate = {"type": "rate_limit_event", "session_id": session_id,
                            "rate_limit_info": {"status": "rejected", "rateLimitType": "five_hour",
                                                "resetsAt": retry_after, "isUsingOverage": False,
                                                "overageStatus": "rejected"}}
                if (event.get("type") == "result" and event.get("subtype") == "success" and
                        event.get("is_error") is True and event.get("api_error_status") == 429):
                    terminal = {"type": "result", "subtype": "success", "is_error": True,
                                "api_error_status": 429, "session_id": session_id}
    except OSError:
        return None
    if rate is None or terminal is None:
        return None
    info = file_info(path, os.path.join(directory, "logs"))
    if not info:
        return None
    source_digest = digest_bytes(json.dumps({"rate_limit_event": rate, "terminal": terminal}, sort_keys=True,
                                             separators=(",", ":")).encode())
    return {"terminal": terminal, "retry_after": rate["rate_limit_info"]["resetsAt"],
            "reset_source": "claude_rate_limit_event_resets_at", "reset_evidence_digest": source_digest,
            "source_log_sha256": info["sha256"], "provider": "claude",
            "failure_class": "subscription_quota_exhausted"}


def provider_capacity_failure(directory: str, attempt: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Recognize trusted, resettable plan capacity from a typed terminal event.

    Only the fixed subtype and a future retry instant are trusted.  Provider
    prose and arbitrary metadata are never persisted or surfaced.
    """
    claude_failure = claude_subscription_quota_failure(directory, attempt)
    if claude_failure:
        path = attempt["stdout"]
        packets = os.path.join(directory, "packets"); os.makedirs(packets, mode=0o700, exist_ok=True)
        target = os.path.join(packets, str(attempt.get("id")) + ".capacity.json")
        existing_info = file_info(target, packets)
        invocation = {"backend": attempt.get("backend"), "provider": attempt.get("provider"), "controller": attempt.get("controller"),
                      "model": attempt.get("model"), "effort": attempt.get("effort"), "policy": attempt.get("policy")}
        if invocation["backend"] != "claude_direct" or invocation["provider"] != "claude" or invocation["controller"] != "claude" or invocation["policy"] != POLICY_ID:
            raise ControllerError("provider capacity invocation identity is incomplete")
        packet = {"schema_version": SCHEMA, "kind": "provider_capacity_wait", "work_id": os.path.basename(directory),
                  "attempt_id": attempt.get("id"), "provider": "claude", "role": attempt.get("role"),
                  "provider_session_id": attempt.get("provider_session_id"), "failure_class": claude_failure["failure_class"],
                  "retry_after": claude_failure["retry_after"], "reset_source": claude_failure["reset_source"],
                  "reset_evidence_digest": claude_failure["reset_evidence_digest"], "source_log_sha256": claude_failure["source_log_sha256"],
                  "terminal_digest": digest_bytes(json.dumps(claude_failure["terminal"], sort_keys=True, separators=(",", ":")).encode()),
                  "policy_digest": digest_bytes(POLICY_ID.encode()), "invocation": invocation, "parsed_at": utc()}
        if existing_info:
            try:
                with open(target, encoding="utf-8") as src: existing = json.load(src)
            except (OSError, json.JSONDecodeError): existing = None
            keys = ("kind", "attempt_id", "role", "provider_session_id", "failure_class", "retry_after", "reset_source", "reset_evidence_digest", "source_log_sha256", "terminal_digest", "policy_digest", "invocation")
            if isinstance(existing, dict) and all(existing.get(k) == packet.get(k) for k in keys):
                return {"path": target, "sha256": existing_info["sha256"], **{k: claude_failure[k] for k in ("failure_class", "retry_after", "reset_source", "reset_evidence_digest", "source_log_sha256", "provider")}, "terminal_digest": packet["terminal_digest"]}
            raise ControllerError("matching capacity packet failed full binding validation")
        atomic_json(target, packet); item = file_info(target, packets)
        return {"path": target, "sha256": (item or {}).get("sha256"), **{k: claude_failure[k] for k in ("failure_class", "retry_after", "reset_source", "reset_evidence_digest", "source_log_sha256", "provider")}, "terminal_digest": packet["terminal_digest"]}
    path = attempt.get("stdout")
    if not isinstance(path, str) or not inside(path, os.path.join(directory, "logs")) or os.path.islink(path):
        return None
    terminal = None
    try:
        with open(path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(event, dict):
                    continue
                retry_after = parse_retry_after(event.get("retry_after"))
                if (event.get("type") == "result" and event.get("subtype") == "error_plan_quota_exhausted" and
                        event.get("is_error") is True and retry_after and
                        event.get("reset_source") == "provider_terminal_retry_after"):
                    terminal = {"type": "result", "subtype": "error_plan_quota_exhausted", "is_error": True,
                                "retry_after": retry_after, "reset_source": "provider_terminal_retry_after"}
    except OSError:
        return None
    if terminal is None:
        return None
    info = file_info(path, os.path.join(directory, "logs"))
    if not info:
        return None
    packets = os.path.join(directory, "packets"); os.makedirs(packets, mode=0o700, exist_ok=True)
    target = os.path.join(packets, str(attempt.get("id")) + ".capacity.json")
    digest = digest_bytes(json.dumps(terminal, sort_keys=True, separators=(",", ":")).encode())
    existing_info = file_info(target, packets)
    if existing_info:
        try:
            with open(target, encoding="utf-8") as src: existing = json.load(src)
        except (OSError, json.JSONDecodeError): existing = None
        if (isinstance(existing, dict) and existing.get("kind") == "provider_capacity_wait" and
                existing.get("attempt_id") == attempt.get("id") and existing.get("role") == attempt.get("role") and
                existing.get("provider_session_id") == attempt.get("provider_session_id") and
                existing.get("failure_class") == "plan_quota_exhausted_resettable" and
                existing.get("retry_after") == terminal["retry_after"] and existing.get("reset_source") == terminal["reset_source"] and
                existing.get("reset_evidence_digest") == digest and existing.get("source_log_sha256") == info["sha256"] and
                existing.get("policy_digest") == digest_bytes(POLICY_ID.encode()) and existing.get("provider") == "claude"):
            return {"path": target, "sha256": existing_info["sha256"], "failure_class": existing["failure_class"],
                    "retry_after": terminal["retry_after"], "reset_source": terminal["reset_source"],
                    "reset_evidence_digest": digest, "source_log_sha256": info["sha256"], "terminal_digest": digest, "provider": "claude"}
        raise ControllerError("matching capacity packet failed full binding validation")
    invocation = {"backend": attempt.get("backend"), "provider": attempt.get("provider"), "controller": attempt.get("controller"),
                  "model": attempt.get("model"), "effort": attempt.get("effort"), "policy": attempt.get("policy")}
    if invocation["backend"] != "claude_direct" or invocation["provider"] != "claude" or invocation["controller"] != "claude" or invocation["policy"] != POLICY_ID:
        raise ControllerError("provider capacity invocation identity is incomplete")
    packet = {"schema_version": SCHEMA, "kind": "provider_capacity_wait", "work_id": os.path.basename(directory),
              "attempt_id": attempt.get("id"), "provider": "claude", "role": attempt.get("role"), "provider_session_id": attempt.get("provider_session_id"),
              "failure_class": "plan_quota_exhausted_resettable", "retry_after": terminal["retry_after"],
              "reset_source": terminal["reset_source"], "reset_evidence_digest": digest,
              "source_log_sha256": info["sha256"], "terminal_digest": digest, "policy_digest": digest_bytes(POLICY_ID.encode()),
              "invocation": invocation, "parsed_at": utc()}
    atomic_json(target, packet); item = file_info(target, packets)
    return {"path": target, "sha256": (item or {}).get("sha256"), "failure_class": packet["failure_class"],
            "retry_after": packet["retry_after"], "reset_source": packet["reset_source"],
            "reset_evidence_digest": digest, "source_log_sha256": info["sha256"], "terminal_digest": digest, "provider": "claude"}


def provider_manual_capacity_failure(directory: str, attempt: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Recognize plan quota exhaustion without a trustworthy reset instant.

    This is deliberately a manual-signal wait, never a claim that a provider
    reset exists.  Only fixed protocol fields and log digests are retained.
    """
    path = attempt.get("stdout")
    if not isinstance(path, str) or not inside(path, os.path.join(directory, "logs")) or os.path.islink(path):
        return None
    terminal = None
    try:
        with open(path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try: event = json.loads(line)
                except json.JSONDecodeError: continue
                if isinstance(event, dict) and event.get("type") == "result" and event.get("subtype") == "error_plan_quota_exhausted" and event.get("is_error") is True:
                    terminal = {"type": "result", "subtype": "error_plan_quota_exhausted", "is_error": True}
    except OSError:
        return None
    if terminal is None or provider_capacity_failure(directory, attempt):
        return None
    info = file_info(path, os.path.join(directory, "logs"))
    if not info: return None
    packets = os.path.join(directory, "packets"); os.makedirs(packets, mode=0o700, exist_ok=True)
    target = os.path.join(packets, str(attempt.get("id")) + ".capacity_manual.json")
    digest = digest_bytes(json.dumps(terminal, sort_keys=True, separators=(",", ":")).encode())
    packet = {"schema_version": SCHEMA, "kind": "provider_capacity_manual_signal", "work_id": os.path.basename(directory),
              "attempt_id": attempt.get("id"), "provider": "claude", "role": attempt.get("role"),
              "provider_session_id": attempt.get("provider_session_id"), "failure_class": "plan_quota_exhausted_manual_signal",
              "terminal_digest": digest, "source_log_sha256": info["sha256"], "policy_digest": digest_bytes(POLICY_ID.encode()),
              "invocation": {k: attempt.get(k) for k in ("backend", "provider", "controller", "model", "effort", "policy")}, "parsed_at": utc()}
    existing = file_info(target, packets)
    if existing:
        try:
            with open(target, encoding="utf-8") as src: prior = json.load(src)
        except (OSError, json.JSONDecodeError): prior = None
        if isinstance(prior, dict) and all(prior.get(k) == packet.get(k) for k in ("kind", "attempt_id", "provider_session_id", "failure_class", "terminal_digest", "source_log_sha256", "policy_digest", "invocation")):
            return {"path": target, "sha256": existing["sha256"], "failure_class": packet["failure_class"], "source_log_sha256": info["sha256"], "terminal_digest": digest, "provider": "claude"}
        raise ControllerError("matching manual capacity packet failed full binding validation")
    atomic_json(target, packet); item = file_info(target, packets)
    return {"path": target, "sha256": (item or {}).get("sha256"), "failure_class": packet["failure_class"], "source_log_sha256": info["sha256"], "terminal_digest": digest, "provider": "claude"}


def candidate_record(packet: Dict[str, Any], changed_paths: List[str], artifacts: List[Dict[str, Any]], worktree: str,
                     packet_verified: bool = True, evidence_kind: str = "worker_packet",
                     failure_metadata: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
    """Bind a gate candidate to immutable packet and local evidence digests."""
    evidence = {
        "packet_sha256": packet["sha256"],
        "packet_path": packet["path"],
        "evidence_kind": evidence_kind,
        "changed_paths": changed_paths[:MAX_PATHS],
        "declared_artifacts": declared_artifacts(worktree),
        "worktree_fingerprint": worktree_fingerprint(worktree),
    }
    if failure_metadata:
        evidence["provider_failure"] = failure_metadata
    encoded = json.dumps(evidence, sort_keys=True, separators=(",", ":")).encode()
    return {"schema_version": SCHEMA, "id": str(uuid.uuid4()),
            "evidence_digest": digest_bytes(encoded), "evidence": evidence,
            "packet_verified": packet_verified, "created_at": utc()}


def candidate_intact(candidate: Dict[str, Any], directory: str, worktree: str) -> bool:
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    packet_path = evidence.get("packet_path")
    expected = evidence.get("packet_sha256")
    item = file_info(packet_path, os.path.join(directory, "packets")) if isinstance(packet_path, str) else None
    if not item or item.get("sha256") != expected:
        return False
    provider_failure = evidence.get("provider_failure") if isinstance(evidence.get("provider_failure"), dict) else None
    if provider_failure:
        source_path = provider_failure.get("source_log_path")
        source_digest = provider_failure.get("source_log_sha256")
        source = file_info(source_path, os.path.join(directory, "logs")) if isinstance(source_path, str) else None
        if not source or source.get("sha256") != source_digest:
            return False
    alternate_review = evidence.get("alternate_review") if isinstance(evidence.get("alternate_review"), dict) else None
    if alternate_review:
        review_path = alternate_review.get("path")
        review = file_info(review_path, os.path.join(directory, "packets", "alternate")) if isinstance(review_path, str) else None
        if not review or review.get("sha256") != alternate_review.get("sha256"):
            return False
    expected_fingerprint = evidence.get("worktree_fingerprint") if isinstance(evidence.get("worktree_fingerprint"), dict) else {}
    try:
        if worktree_fingerprint(worktree).get("digest") != expected_fingerprint.get("digest"):
            return False
    except ControllerError:
        return False
    return declared_artifacts(worktree) == evidence.get("declared_artifacts")


def _bounded_text(value: Any, maximum: int = 4000) -> bool:
    return isinstance(value, str) and bool(value.strip()) and len(value.encode()) <= maximum


def _m0b_worktree_from_brief(state: Dict[str, Any]) -> str:
    text = Path(state["brief"]["path"]).read_text(encoding="utf-8")
    match = re.search(r"M0-B candidate worktree:\s*\n\s*(`?)(/[^`\s]+)\1", text)
    if not match:
        raise ControllerError("frozen brief does not declare an M0-B candidate worktree")
    return require_regular_or_directory(match.group(2))


def require_regular_or_directory(path: str) -> str:
    resolved = real(path)
    if os.path.islink(path) or not os.path.isdir(resolved):
        raise ControllerError("declared M0-B candidate worktree is unsafe")
    return resolved


def _extract_one_json_object(raw: bytes) -> Dict[str, Any]:
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ControllerError("planner artifact must be UTF-8") from exc
    matches = re.findall(r"```json\s*\n(.*?)\n```", text, flags=re.DOTALL | re.IGNORECASE)
    candidate = text.strip() if not matches else (matches[0] if len(matches) == 1 else None)
    if candidate is None:
        raise ControllerError("planner artifact contains ambiguous JSON fences")
    try:
        value = json.loads(candidate)
    except json.JSONDecodeError as exc:
        raise ControllerError("planner artifact must contain exactly one JSON object") from exc
    if not isinstance(value, dict):
        raise ControllerError("planner artifact JSON must be an object")
    return value


def _validate_m0c_plan(packet: Dict[str, Any], state: Dict[str, Any]) -> None:
    if state.get("work_id") in {M0C_V2_WORK_ID, M0C_V3_WORK_ID}:
        return _validate_m0c_v2_plan(packet, state)
    keys = {"schema_version", "package_id", "candidate", "recommended_slice", "record_proposal", "call_site_map", "three_contracts", "legacy_strategy", "allowlist", "implementation_packages", "negative_controls", "risks", "commands_run", "assumptions", "findings"}
    if set(packet) != keys or packet.get("schema_version") != SCHEMA or packet.get("package_id") != M0C_PLAN_PACKAGE_ID:
        raise ControllerError("planner plan schema or declared package identity is invalid")
    if state["work_id"] != M0C_WORK_ID:
        raise ControllerError("planner package ID discrepancy is not an approved M0-C controller mapping")
    candidate = packet.get("candidate")
    required_binding = {"base_digest", "upstream_package_id", "upstream_candidate_id", "upstream_evidence_digest", "upstream_worktree_fingerprint_digest", "upstream_status_sha256", "upstream_untracked_sha256", "upstream_changed_paths", "upstream_result_sha256", "upstream_review_sha256"}
    if not isinstance(candidate, dict) or set(candidate) != required_binding:
        raise ControllerError("planner candidate binding schema is invalid")
    if candidate.get("base_digest") != state["repo"]["head"]:
        raise ControllerError("planner candidate binding does not match frozen base")
    _verified_m0b_binding(state, candidate)
    required_lists = ("record_proposal", "call_site_map", "allowlist", "implementation_packages", "negative_controls", "risks", "commands_run", "assumptions")
    if any(not isinstance(packet.get(k), list) or not packet[k] or len(packet[k]) > 50 for k in required_lists) or not isinstance(packet.get("findings"), list) or len(packet["findings"]) > 20:
        raise ControllerError("planner required lists are empty or unbounded")
    slice_ = packet.get("recommended_slice"); legacy = packet.get("legacy_strategy")
    if not isinstance(slice_, dict) or set(slice_) != {"summary", "included_call_sites", "deferred_call_sites"} or not _bounded_text(slice_.get("summary")) or not isinstance(slice_.get("included_call_sites"), list) or not slice_["included_call_sites"] or not isinstance(slice_.get("deferred_call_sites"), list):
        raise ControllerError("planner recommended slice is invalid")
    if not isinstance(legacy, dict) or set(legacy) != {"session_v1", "pending_turn", "migration"} or any(not _bounded_text(legacy.get(k)) for k in legacy):
        raise ControllerError("planner legacy strategy is invalid")
    contracts = packet.get("three_contracts")
    if not isinstance(contracts, list) or len(contracts) != 3 or {x.get("name") for x in contracts if isinstance(x, dict)} != M0C_CONTRACTS:
        raise ControllerError("planner must bind exactly the three M0-C contracts")
    for item in contracts:
        if (set(item) != {"name", "current_witness", "target_behavior", "call_site_adapter", "compatibility_rule", "tests"} or
                not _bounded_text(item.get("current_witness")) or not _bounded_text(item.get("target_behavior")) or
                not _bounded_text(item.get("call_site_adapter")) or not _bounded_text(item.get("compatibility_rule")) or
                not isinstance(item.get("tests"), list) or not item["tests"] or any(not _bounded_text(x, 500) for x in item["tests"])):
            raise ControllerError("planner contract evidence is incomplete")
    rendered = json.dumps(packet, sort_keys=True).lower()
    forbidden = (r"increase_budget", r"refill(?:ing)?\s+credits?", r"paid\s+overage", r"enable\s+overage",
                 r"(?:request|allow|grant|perform|will|must|shall)\s+(?:a\s+)?(?:publish|commit|push|pull request)")
    if any(re.search(pattern, rendered) for pattern in forbidden):
        raise ControllerError("planner packet requests forbidden authority or publication")


def _m0c_v2_prerequisites_root(state: Dict[str, Any]) -> str:
    # Briefs are controller-owned files directly below the durable state root.
    return real(os.path.dirname(os.path.dirname(state["brief"]["path"])))


def _m0c_v2_expected_prerequisites(root: str) -> List[Dict[str, Any]]:
    out = []
    for row in M0C_V2_PREREQUISITE_MANIFEST:
        package = row["package_id"]; alternate = os.path.join(root, package, "packets", "alternate")
        out.append({"package_id": package, "state_path": os.path.join(root, package, "state.json"),
                    "packet_refs": {"config": os.path.join(alternate, row["config_file"]) if row["config_file"] else None,
                                    "result": os.path.join(alternate, row["result_file"]), "review": os.path.join(alternate, row["review_file"])},
                    **{key: row[key] for key in ("candidate_id", "evidence_digest", "worktree_fingerprint_digest", "status_sha256", "untracked_sha256", "config_sha256", "result_sha256", "review_sha256", "changed_paths", "artifact_hashes")}})
    return out


def _validate_m0c_v2_prerequisites(prerequisites: Any, state: Dict[str, Any]) -> None:
    root = _m0c_v2_prerequisites_root(state); expected = _m0c_v2_expected_prerequisites(root)
    required = {"package_id", "state_path", "packet_refs", "candidate_id", "evidence_digest", "worktree_fingerprint_digest", "status_sha256", "untracked_sha256", "config_sha256", "result_sha256", "review_sha256", "changed_paths", "artifact_hashes"}
    if not isinstance(prerequisites, list) or len(prerequisites) != 2 or any(not isinstance(x, dict) or set(x) != required for x in prerequisites):
        raise ControllerError("v2 planner prerequisites must contain exactly two complete bindings")
    if prerequisites != expected:
        raise ControllerError("v2 planner prerequisite bindings are not the exact controller authority")
    for binding in expected:
        package = binding["package_id"]; directory = work_dir(root, package); upstream = load(directory)
        candidate = upstream.get("candidate") if isinstance(upstream.get("candidate"), dict) else {}
        evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
        fp = evidence.get("worktree_fingerprint") if isinstance(evidence.get("worktree_fingerprint"), dict) else {}
        if (upstream.get("phase") != "completed" or (upstream.get("gate") or {}).get("verdict") != "pass" or candidate.get("id") != binding["candidate_id"] or candidate.get("evidence_digest") != binding["evidence_digest"] or fp.get("digest") != binding["worktree_fingerprint_digest"] or (fp.get("status") or {}).get("sha256") != binding["status_sha256"] or (fp.get("untracked") or {}).get("sha256") != binding["untracked_sha256"] or not candidate_intact(candidate, directory, upstream["worktree"]["path"])):
            raise ControllerError("v2 prerequisite state or candidate binding is no longer authoritative")
        alt = upstream.get("alternate_evidence") if isinstance(upstream.get("alternate_evidence"), dict) else {}
        for label, sha_key in (("config", "config_sha256"), ("result", "result_sha256"), ("review", "review_sha256")):
            path, expected_sha = binding["packet_refs"][label], binding[sha_key]
            if path is None:
                if expected_sha is not None: raise ControllerError("v2 prerequisite null packet binding is inconsistent")
                continue
            item = file_info(path, os.path.join(directory, "packets", "alternate"))
            row = alt.get(label) if isinstance(alt.get(label), dict) else {}
            if not item or item.get("sha256") != expected_sha or row.get("path") != path or row.get("sha256") != expected_sha:
                raise ControllerError("v2 prerequisite canonical packet binding changed")
        try:
            result_payload = json.loads(Path(binding["packet_refs"]["result"]).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ControllerError("v2 prerequisite result packet is unreadable") from exc
        result_keys = ALTERNATE_RESULT_KEYS
        if (not isinstance(result_payload, dict) or set(result_payload) != result_keys or result_payload.get("schema_version") != SCHEMA or
                result_payload.get("kind") != "alternate_worker_result" or result_payload.get("package_id") != package or
                result_payload.get("attempt_id") != alt.get("id") or result_payload.get("backend") != ALTERNATE_BACKEND or
                result_payload.get("actor_id") != alt.get("worker_actor_id") or result_payload.get("run_id") != alt.get("worker_run_id") or
                result_payload.get("candidate_binding") != alt.get("binding") or result_payload.get("changed_paths") != binding["changed_paths"] or
                result_payload.get("outcome") != "completed" or not isinstance(result_payload.get("receipts"), list)):
            raise ControllerError("v2 prerequisite canonical result packet schema or candidate binding changed")
        artifacts = {}
        for receipt in result_payload["receipts"]:
            if (not isinstance(receipt, dict) or set(receipt) != {"kind", "path", "sha256"} or receipt.get("kind") != "candidate_artifact" or
                    not isinstance(receipt.get("path"), str) or not _sha256_hex(receipt.get("sha256")) or receipt["path"] in artifacts):
                raise ControllerError("v2 prerequisite artifact receipt is malformed")
            target = os.path.join(upstream["worktree"]["path"], receipt["path"])
            item = capped_regular_file_info(target, upstream["worktree"]["path"], MAX_CANDIDATE_PATH_BYTES)
            if not item or item.get("sha256") != receipt["sha256"]:
                raise ControllerError("v2 prerequisite artifact receipt no longer matches worktree")
            artifacts[receipt["path"]] = receipt["sha256"]
        if artifacts != binding["artifact_hashes"]:
            raise ControllerError("v2 prerequisite artifact hashes changed")
        review = alt.get("review") if isinstance(alt.get("review"), dict) else {}
        if review.get("verdict") != "pass": raise ControllerError("v2 prerequisite independent review did not pass")
        if package == M0B_WORK_ID and not _m0b_verification_receipts_valid(upstream, directory, candidate):
            raise ControllerError("v2 M0-B scoped verification receipt disposition is not authoritative")


def _validate_m0c_v2_plan(packet: Dict[str, Any], state: Dict[str, Any]) -> None:
    keys = {"schema_version", "package_id", "prerequisites", "recommended_slice", "record_proposal", "call_site_map", "three_contracts", "legacy_strategy", "allowlist", "implementation_packages", "negative_controls", "risks", "commands_run", "assumptions", "findings"}
    if set(packet) != keys or packet.get("schema_version") != SCHEMA or packet.get("package_id") != _plan_declared_package_id(state):
        raise ControllerError("v2 planner plan schema or declared package identity is invalid")
    require_frozen_brief(state, work_dir(_m0c_v2_prerequisites_root(state), state["work_id"]))
    if (not registered_worktree(state["repo"]["root"], state["worktree"]["path"], state["worktree"]["branch"]) or
            git(state["worktree"]["path"], ["status", "--porcelain=v1"]).strip()):
        raise ControllerError("v2 planner requires its fresh controller-declared worktree to remain unchanged")
    _validate_m0c_v2_prerequisites(packet.get("prerequisites"), state)
    list_fields = ("record_proposal", "call_site_map", "allowlist", "implementation_packages", "negative_controls", "risks", "assumptions")
    if any(not isinstance(packet.get(key), list) or not packet[key] or len(packet[key]) > 50 for key in list_fields) or not isinstance(packet.get("findings"), list) or len(packet["findings"]) > 20:
        raise ControllerError("v2 planner required lists are empty or unbounded")
    slice_, legacy = packet.get("recommended_slice"), packet.get("legacy_strategy")
    if (not isinstance(slice_, dict) or set(slice_) != {"summary", "included_call_sites", "deferred_call_sites"} or not _bounded_text(slice_.get("summary")) or not isinstance(slice_.get("included_call_sites"), list) or not slice_["included_call_sites"] or not isinstance(slice_.get("deferred_call_sites"), list) or
            not isinstance(legacy, dict) or set(legacy) != {"session_v1", "pending_turn", "migration"} or any(not _bounded_text(legacy.get(k)) for k in legacy)):
        raise ControllerError("v2 planner slice or legacy strategy is invalid")
    contracts = packet.get("three_contracts")
    if not isinstance(contracts, list) or len(contracts) != 3 or {x.get("name") for x in contracts if isinstance(x, dict)} != M0C_CONTRACTS:
        raise ControllerError("v2 planner must bind exactly the three M0-C contracts")
    for item in contracts:
        if (not isinstance(item, dict) or set(item) != {"name", "current_witness", "target_behavior", "tests"} or
                not _bounded_text(item.get("current_witness")) or not _bounded_text(item.get("target_behavior")) or
                not isinstance(item.get("tests"), list) or not item["tests"] or any(not _bounded_text(x, 500) for x in item["tests"])):
            raise ControllerError("v2 planner contract evidence is incomplete")
    def text_list(value: Any, allow_empty: bool = False) -> bool:
        return isinstance(value, list) and (allow_empty or bool(value)) and len(value) <= 50 and all(_bounded_text(x, 500) for x in value)
    for row in packet["record_proposal"]:
        if not isinstance(row, dict) or set(row) != {"name", "version", "fields", "validator", "storage"} or not _bounded_text(row.get("name")) or row.get("version") != 1 or not text_list(row.get("fields")) or not _bounded_text(row.get("validator")) or not _bounded_text(row.get("storage")):
            raise ControllerError("v2 planner record proposal is malformed")
    for row in packet["call_site_map"]:
        if (not isinstance(row, dict) or set(row) != {"site", "current_behavior", "adapter", "compatibility"} or
                any(not _bounded_text(row.get(key)) for key in ("site", "current_behavior", "adapter")) or
                not text_list(row.get("compatibility"))):
            raise ControllerError("v2 planner call-site map is malformed")
    for row in packet["implementation_packages"]:
        if not isinstance(row, dict) or set(row) != {"id", "objective", "paths", "gates", "risks"} or not _bounded_text(row.get("id")) or not _bounded_text(row.get("objective")) or not text_list(row.get("paths")) or not text_list(row.get("gates")) or not text_list(row.get("risks")):
            raise ControllerError("v2 planner implementation package is malformed")
    for row in packet["risks"]:
        if not isinstance(row, dict) or set(row) != {"risk", "mitigation"} or not _bounded_text(row.get("risk")) or not _bounded_text(row.get("mitigation")):
            raise ControllerError("v2 planner risk is malformed")
    # Planner claims are never a test receipt.  The bootstrap controller has
    # no command-receipt producer for planner work, so a nonempty list would
    # be a fabricated pass claim rather than evidence.  Future controller-
    # owned receipt kinds may extend this deliberately.
    if not isinstance(packet.get("commands_run"), list) or packet["commands_run"]:
        raise ControllerError("v2 planner commands require controller-owned receipts and must be empty until such receipts exist")
    package_ids = [row.get("id") for row in packet["implementation_packages"]]
    if package_ids != ["A", "B", "C", "D"]:
        raise ControllerError("v2 planner implementation packages must be staged A through D")
    rendered = json.dumps(packet, sort_keys=True).lower()
    forbidden = (r"increase_budget", r"refill(?:ing)?\s+credits?", r"paid\s+overage", r"enable\s+overage", r"(?:request|allow|grant|perform|will|must|shall)\s+(?:a\s+)?(?:publish|commit|push|pull request)")
    if any(re.search(pattern, rendered) for pattern in forbidden):
        raise ControllerError("v2 planner packet requests forbidden authority or publication")


def _verified_m0b_binding(state: Dict[str, Any], binding: Dict[str, Any]) -> None:
    """Require the known completed M0-B controller state, never planner claims."""
    expected = {"upstream_package_id": M0B_WORK_ID, "upstream_candidate_id": M0B_CANDIDATE_ID,
                "upstream_evidence_digest": M0B_EVIDENCE_DIGEST, "upstream_worktree_fingerprint_digest": M0B_FINGERPRINT,
                "upstream_status_sha256": M0B_STATUS_SHA256, "upstream_untracked_sha256": M0B_UNTRACKED_SHA256,
                "upstream_result_sha256": M0B_RESULT_SHA256, "upstream_review_sha256": M0B_REVIEW_SHA256,
                "upstream_changed_paths": ["?? scripts/fixtures/dispatch_contract_characterization_sources.json", "?? scripts/test_dispatch_contract_characterization.py"]}
    if any(binding.get(k) != v for k, v in expected.items()):
        raise ControllerError("planner upstream M0-B binding is not the authoritative completed candidate")
    upstream_dir = work_dir(os.path.dirname(os.path.dirname(state["brief"]["path"])), M0B_WORK_ID)
    upstream = load(upstream_dir); candidate = upstream.get("candidate") if isinstance(upstream.get("candidate"), dict) else {}
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    fp = evidence.get("worktree_fingerprint") if isinstance(evidence.get("worktree_fingerprint"), dict) else {}
    review = (upstream.get("alternate_evidence") or {}).get("review") if isinstance(upstream.get("alternate_evidence"), dict) else {}
    result = (upstream.get("alternate_evidence") or {}).get("result") if isinstance(upstream.get("alternate_evidence"), dict) else {}
    result_file = file_info(result.get("path"), os.path.join(upstream_dir, "packets", "alternate")) if isinstance(result.get("path"), str) else None
    review_file = file_info(review.get("path"), os.path.join(upstream_dir, "packets", "alternate")) if isinstance(review.get("path"), str) else None
    if (upstream.get("phase") != "completed" or (upstream.get("gate") or {}).get("verdict") != "pass" or
            candidate.get("id") != M0B_CANDIDATE_ID or candidate.get("evidence_digest") != M0B_EVIDENCE_DIGEST or
            fp.get("digest") != M0B_FINGERPRINT or (fp.get("status") or {}).get("sha256") != M0B_STATUS_SHA256 or
            (fp.get("untracked") or {}).get("sha256") != M0B_UNTRACKED_SHA256 or result.get("sha256") != M0B_RESULT_SHA256 or
            review.get("sha256") != M0B_REVIEW_SHA256 or review.get("verdict") != "pass" or
            not result_file or result_file.get("sha256") != M0B_RESULT_SHA256 or not review_file or review_file.get("sha256") != M0B_REVIEW_SHA256 or
            not _m0b_verification_receipts_valid(upstream, upstream_dir, candidate)):
        raise ControllerError("controller-owned M0-B completion evidence does not match authoritative binding")


_M0B_BASELINE_IDS = (
    "scripts.test_cowork.ControllerCapabilityMatrixTests.test_guarded_opencode_hard_removes_task_before_launch",
    "scripts.test_cowork.BuildPhaseFlowTest.test_baseline_read_from_cwd_not_session_file_parent",
    "scripts.test_cowork.MeasurementReportHonestyTests.test_the_source_manifest_covers_untracked_files",
    "scripts.test_cowork.RunScoutTest.test_run_scout_claude_probe_fail_aborts",
)
_M0B_VERIFICATION_SPECS = (
    {"argv": ["python3", "-m", "unittest", "scripts/test_dispatch_contract_characterization.py"],
     "expected_exit_code": 0, "classification": "candidate_characterization_pass"},
    {"argv": ["python3", "-m", "unittest", *_M0B_BASELINE_IDS],
     "expected_exit_code": 1, "classification": "baseline_known_failure"},
)


def _m0b_candidate_binding(candidate: Dict[str, Any], worktree: str) -> Dict[str, Any]:
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    fingerprint = evidence.get("worktree_fingerprint") if isinstance(evidence.get("worktree_fingerprint"), dict) else {}
    return {"candidate_id": candidate.get("id"), "evidence_digest": candidate.get("evidence_digest"),
            "worktree": worktree, "worktree_fingerprint_digest": fingerprint.get("digest")}


def _m0b_parse_verification_output(classification: str, output: bytes) -> Optional[Dict[str, Any]]:
    """Recognize only the bounded unittest summaries this evidence claims."""
    try:
        text = output.decode("utf-8")
    except UnicodeDecodeError:
        return None
    ran_rows = re.findall(r"^Ran (\d+) tests? in [^\r\n]+$", text, flags=re.MULTILINE)
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if not ran_rows or not lines:
        return None
    terminal = lines[-1]
    if classification == "candidate_characterization_pass":
        counters = {"ran": int(ran_rows[-1]), "failures": 0, "errors": 0,
                    "expected_failures": 3, "unexpected_successes": 0}
        if counters["ran"] != 32 or terminal != "OK (expected failures=3)":
            return None
    elif classification == "baseline_known_failure":
        failing_id = _M0B_BASELINE_IDS[-1]
        counters = {"ran": int(ran_rows[-1]), "failures": 1, "errors": 0,
                    "expected_failures": 0, "unexpected_successes": 0}
        fail_headers = re.findall(r"^FAIL: .+$", text, flags=re.MULTILINE)
        expected_header = "FAIL: test_run_scout_claude_probe_fail_aborts (scripts.test_cowork.RunScoutTest)"
        if (counters["ran"] != 4 or terminal != "FAILED (failures=1)" or
                fail_headers != [expected_header] or any(identifier in text for identifier in _M0B_BASELINE_IDS[:-1])):
            return None
    else:
        return None
    return counters


def _sha256_hex(value: Any) -> bool:
    return isinstance(value, str) and bool(re.fullmatch(r"[0-9a-f]{64}", value))


def _m0b_verification_receipts_valid(state: Dict[str, Any], directory: str,
                                     candidate: Dict[str, Any]) -> bool:
    """Validate the complete, controller-owned M0-B verification evidence."""
    worktree = state.get("worktree") if isinstance(state.get("worktree"), dict) else {}
    root = worktree.get("path")
    receipts = state.get("verification_receipts")
    if (not isinstance(root, str) or not isinstance(receipts, list) or
            len(receipts) != len(_M0B_VERIFICATION_SPECS) or
            not candidate_intact(candidate, directory, root)):
        return False
    receipt_root = os.path.join(directory, "receipts")
    expected_binding = _m0b_candidate_binding(candidate, root)
    historical = state.get("historical_worker_assertions")
    if (state.get("verification_disposition") != "known_baseline_failure" or not isinstance(historical, dict) or
            historical.get("provenance") != "historical_worker_assertion" or
            historical.get("result") != (state.get("alternate_evidence") or {}).get("result") or
            historical.get("review") != (state.get("alternate_evidence") or {}).get("review")):
        return False
    required = {"path", "sha256", "argv", "cwd", "timeout_seconds", "expected_exit_code", "actual_exit_code",
                "output_sha256", "classification", "parsed_counters", "candidate_binding_before", "candidate_binding_after"}
    for item, spec in zip(receipts, _M0B_VERIFICATION_SPECS):
        if (not isinstance(item, dict) or set(item) != required or
                item.get("argv") != spec["argv"] or item.get("cwd") != root or item.get("timeout_seconds") != 120 or
                item.get("expected_exit_code") != spec["expected_exit_code"] or item.get("actual_exit_code") != spec["expected_exit_code"] or
                item.get("classification") != spec["classification"] or item.get("candidate_binding_before") != expected_binding or item.get("candidate_binding_after") != expected_binding or
                not isinstance(item.get("parsed_counters"), dict) or not _sha256_hex(item.get("output_sha256")) or
                not _sha256_hex(item.get("sha256")) or not isinstance(item.get("path"), str)):
            return False
        info = capped_regular_file_info(item["path"], receipt_root, MAX_OUTPUT)
        if not info or info.get("sha256") != item["sha256"]:
            return False
        try:
            payload = json.loads(Path(info["path"]).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return False
        if (not isinstance(payload, dict) or set(payload) != required - {"path", "sha256"} or
                any(payload.get(key) != item.get(key) for key in required - {"path", "sha256"})):
            return False
        # The receipt intentionally stores only a digest of bounded output.  Its
        # parsed counters are authenticated by the controller-written payload.
        expected_counters = ({"ran": 32, "failures": 0, "errors": 0, "expected_failures": 3, "unexpected_successes": 0}
                             if spec["classification"] == "candidate_characterization_pass"
                             else {"ran": 4, "failures": 1, "errors": 0, "expected_failures": 0, "unexpected_successes": 0})
        if payload.get("parsed_counters") != expected_counters:
            return False
    return True


def _plan_candidate(packet_ref: Dict[str, Any], state: Dict[str, Any]) -> Dict[str, Any]:
    candidate = candidate_record(packet_ref, [], [], state["worktree"]["path"], evidence_kind="planner_artifact")
    candidate["plan_package_id"] = _plan_declared_package_id(state)
    candidate["controller_work_id"] = state["work_id"]
    return candidate


def _plan_declared_package_id(state: Dict[str, Any]) -> str:
    if state.get("work_id") == M0C_WORK_ID: return M0C_PLAN_PACKAGE_ID
    if state.get("work_id") == M0C_V2_WORK_ID: return M0C_V2_PLAN_PACKAGE_ID
    if state.get("work_id") == M0C_V3_WORK_ID: return M0C_V3_PLAN_PACKAGE_ID
    raise ControllerError("planner package ID discrepancy is not an approved M0-C controller mapping")


def _is_m0c_plan_work(state: Dict[str, Any]) -> bool:
    return state.get("work_id") in {M0C_WORK_ID, M0C_V2_WORK_ID, M0C_V3_WORK_ID}


def _package_a_identity(work_id: str) -> Optional[Dict[str, str]]:
    """Exact allowlist lookup for Package A identity; never a prefix match.

    Constructed dynamically so tests may override module-level constants.
    """
    if work_id == PACKAGE_A_WORK_ID:
        return {"work_id": PACKAGE_A_WORK_ID, "outcome_id": PACKAGE_A_OUTCOME_ID, "brief_sha256": PACKAGE_A_BRIEF_SHA256}
    if work_id == PACKAGE_A_V2_WORK_ID:
        return {"work_id": PACKAGE_A_V2_WORK_ID, "outcome_id": PACKAGE_A_V2_OUTCOME_ID, "brief_sha256": PACKAGE_A_V2_BRIEF_SHA256}
    if work_id == PACKAGE_A_V3_WORK_ID:
        return {"work_id": PACKAGE_A_V3_WORK_ID, "outcome_id": PACKAGE_A_V3_OUTCOME_ID, "brief_sha256": PACKAGE_A_V3_BRIEF_SHA256}
    if work_id == PACKAGE_A_V4_WORK_ID:
        return {"work_id": PACKAGE_A_V4_WORK_ID, "outcome_id": PACKAGE_A_V4_OUTCOME_ID, "brief_sha256": PACKAGE_A_V4_BRIEF_SHA256, "route": PACKAGE_A_V4_ROUTE}
    if work_id == PACKAGE_A_V5_WORK_ID:
        return {"work_id": PACKAGE_A_V5_WORK_ID, "outcome_id": PACKAGE_A_V5_OUTCOME_ID, "brief_sha256": PACKAGE_A_V5_BRIEF_SHA256, "route": PACKAGE_A_V5_ROUTE}
    return None


def _is_package_a(state: Dict[str, Any]) -> bool:
    """True iff the state work_id is an exact allowlisted Package A identity."""
    return state.get("work_id") in PACKAGE_A_IDENTITIES


def _safe_identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,159}", value):
        raise ControllerError(label + " is malformed")
    return value


def _legacy_unsealed_alternate(state: Dict[str, Any]) -> bool:
    attempt = state.get("alternate_evidence")
    return isinstance(attempt, dict) and attempt.get("backend") == ALTERNATE_BACKEND and not isinstance(attempt.get("config"), dict)


def _alternate_binding(state: Dict[str, Any], worktree: str) -> Dict[str, Any]:
    base = {"repo_root": state["repo"]["root"], "head": state["repo"]["head"],
            "worktree_branch": state["worktree"]["branch"], "brief_sha256": state["brief"]["sha256"]}
    fingerprint = worktree_fingerprint(worktree)
    changed = git(worktree, ["status", "--porcelain=v1"]).splitlines()
    binding = {"base": base, "base_digest": digest_bytes(json.dumps(base, sort_keys=True, separators=(",", ":")).encode()),
            "brief_sha256": state["brief"]["sha256"], "policy": POLICY_ID,
            "policy_digest": digest_bytes(POLICY_ID.encode()), "worktree_fingerprint": fingerprint,
            "candidate_digest": fingerprint["digest"], "changed_paths": changed}
    if (len(changed) > MAX_PATHS or any(len(x.encode()) > 300 for x in changed) or
            len(json.dumps(binding, sort_keys=True, separators=(",", ":")).encode()) > 5000):
        raise ControllerError("alternate candidate binding exceeds bounded CLI contract")
    return binding


def _read_alternate_packet(path: str) -> Dict[str, Any]:
    source = require_regular(path)
    try:
        raw = Path(source).read_bytes()
    except OSError as exc:
        raise ControllerError("alternate packet is unreadable") from exc
    if len(raw) > 64 * 1024:
        raise ControllerError("alternate packet exceeds bounded size")
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ControllerError("alternate packet is malformed JSON") from exc
    if not isinstance(value, dict):
        raise ControllerError("alternate packet must be a JSON object")
    return value


def _alternate_config_payload(state: Dict[str, Any], attempt: Dict[str, Any]) -> Dict[str, Any]:
    return {"schema_version": SCHEMA, "kind": "alternate_evidence_config", "package_id": state["work_id"],
            "attempt_id": attempt["id"], "route": attempt["route"], "backend": attempt["backend"],
            "controller": attempt["controller"], "model": attempt["model"], "effort": attempt["effort"],
            "worker_actor_id": attempt["worker_actor_id"], "worker_run_id": attempt["worker_run_id"],
            "reviewer_actor_id": attempt["reviewer_actor_id"], "reviewer_run_id": attempt["reviewer_run_id"],
            "candidate_binding": attempt["binding"], "policy": POLICY_ID}


def _seal_alternate_config(directory: str, state: Dict[str, Any], attempt: Dict[str, Any]) -> Dict[str, Any]:
    target_dir = os.path.join(directory, "packets", "alternate"); os.makedirs(target_dir, mode=0o700, exist_ok=True)
    target = os.path.join(target_dir, attempt["id"] + ".config.json")
    payload = _alternate_config_payload(state, attempt)
    atomic_json(target, payload)
    item = file_info(target, target_dir)
    if not item:
        raise ControllerError("alternate evidence config receipt write failed")
    return {"path": item["path"], "sha256": item["sha256"]}


def _validate_alternate_config(directory: str, state: Dict[str, Any], attempt: Dict[str, Any]) -> Dict[str, Any]:
    receipt = attempt.get("config") if isinstance(attempt.get("config"), dict) else {}
    path, sha = receipt.get("path"), receipt.get("sha256")
    root = os.path.join(directory, "packets", "alternate")
    item = file_info(path, root) if isinstance(path, str) else None
    if not item or item.get("sha256") != sha:
        raise ControllerError("alternate evidence config receipt binding no longer matches")
    try:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ControllerError("alternate evidence config receipt is unreadable") from exc
    if not isinstance(payload, dict) or payload != _alternate_config_payload(state, attempt):
        raise ControllerError("alternate evidence config receipt does not match attempt identity")
    return payload


def _same_binding(actual: Any, expected: Dict[str, Any]) -> bool:
    return isinstance(actual, dict) and actual == expected


def _validate_receipts(receipts: Any, worktree: str) -> bool:
    if not isinstance(receipts, list) or not receipts or len(receipts) > 20:
        return False
    seen = set()
    for receipt in receipts:
        if not isinstance(receipt, dict) or set(receipt) != {"kind", "path", "sha256"} or receipt.get("kind") != "candidate_artifact":
            return False
        path, sha = receipt.get("path"), receipt.get("sha256")
        if not isinstance(path, str) or not path or os.path.isabs(path) or "\x00" in path or not re.fullmatch(r"[0-9a-f]{64}", sha or ""):
            return False
        full = os.path.join(worktree, path)
        info = capped_regular_file_info(full, worktree, MAX_ALTERNATE_RECEIPT_BYTES)
        if not info or info["sha256"] != sha or path in seen:
            return False
        seen.add(path)
    return True


def _valid_alternate_checks(checks: Any, receipts: Any) -> bool:
    if not isinstance(checks, list) or not checks or len(checks) > 20 or not isinstance(receipts, list):
        return False
    for check in checks:
        if not isinstance(check, dict) or set(check) != {"command", "exit_code", "fact_source"} or check.get("fact_source") != "worker_assertion":
            return False
        command = check.get("command")
        if not isinstance(command, list) or not command or len(command) > 24 or any(not isinstance(x, str) or not x or len(x.encode()) > 300 for x in command):
            return False
        if not isinstance(check.get("exit_code"), int) or isinstance(check.get("exit_code"), bool) or abs(check["exit_code"]) > 255:
            return False
    return True


def _bounded_string_list(value: Any, maximum: int = 20, item_max: int = 500, minimum: int = 0) -> bool:
    return isinstance(value, list) and minimum <= len(value) <= maximum and all(isinstance(x, str) and len(x.encode()) <= item_max for x in value)


def _validate_alternate_result(packet: Dict[str, Any], state: Dict[str, Any], attempt: Dict[str, Any], binding: Dict[str, Any], worktree: str) -> None:
    if set(packet) != ALTERNATE_RESULT_KEYS or packet.get("schema_version") != SCHEMA or packet.get("kind") != "alternate_worker_result":
        raise ControllerError("alternate result packet schema is invalid")
    if packet.get("package_id") != state["work_id"] or packet.get("attempt_id") != attempt["id"] or packet.get("backend") != ALTERNATE_BACKEND:
        raise ControllerError("alternate result packet identity does not match attempt")
    _safe_identifier(packet.get("actor_id"), "result actor id"); _safe_identifier(packet.get("run_id"), "result run id")
    if not _same_binding(packet.get("candidate_binding"), binding) or packet.get("outcome") not in {"completed", "blocked", "needs_authority", "failed"}:
        raise ControllerError("alternate result packet candidate binding is invalid")
    if not isinstance(packet.get("summary"), str) or len(packet["summary"].encode()) > 2000 or not isinstance(packet.get("next_action"), str) or len(packet["next_action"].encode()) > 1000:
        raise ControllerError("alternate result packet text is invalid")
    if packet.get("changed_paths") != binding["changed_paths"] or not _validate_receipts(packet.get("receipts"), worktree) or not _valid_alternate_checks(packet.get("checks"), packet.get("receipts")):
        raise ControllerError("alternate result receipts, checks, or changed paths are invalid")
    if not _bounded_string_list(packet.get("findings")) or not _bounded_string_list(packet.get("assumptions")):
        raise ControllerError("alternate result findings or assumptions are invalid")


def _validate_alternate_review(packet: Dict[str, Any], state: Dict[str, Any], attempt: Dict[str, Any], binding: Dict[str, Any], result_actor: str, result_run: str) -> None:
    if set(packet) != ALTERNATE_REVIEW_KEYS or packet.get("schema_version") != SCHEMA or packet.get("kind") != "alternate_independent_review":
        raise ControllerError("alternate review packet schema is invalid")
    if packet.get("package_id") != state["work_id"] or packet.get("attempt_id") != attempt["id"] or packet.get("backend") != ALTERNATE_BACKEND:
        raise ControllerError("alternate review packet identity does not match attempt")
    actor, run = _safe_identifier(packet.get("actor_id"), "review actor id"), _safe_identifier(packet.get("run_id"), "review run id")
    if actor == result_actor or run == result_run:
        raise ControllerError("alternate review actor and run must be independent")
    if not _same_binding(packet.get("candidate_binding"), binding) or packet.get("verdict") not in {"pass", "fail", "needs_correction"}:
        raise ControllerError("alternate review packet candidate binding is invalid")
    if not isinstance(packet.get("summary"), str) or len(packet["summary"].encode()) > 2000 or not _bounded_string_list(packet.get("findings")) or not _bounded_string_list(packet.get("checks"), minimum=1):
        raise ControllerError("alternate review packet content is invalid")


def _copy_alternate_packet(directory: str, attempt_id: str, suffix: str, packet: Dict[str, Any]) -> Dict[str, Any]:
    target_dir = os.path.join(directory, "packets", "alternate"); os.makedirs(target_dir, mode=0o700, exist_ok=True)
    target = os.path.join(target_dir, attempt_id + "." + suffix + ".json")
    existing = file_info(target, target_dir)
    if existing:
        try:
            prior = json.loads(Path(target).read_text())
        except (OSError, json.JSONDecodeError) as exc:
            raise ControllerError("existing alternate packet is unreadable") from exc
        if prior != packet:
            raise ControllerError("alternate packet replay conflicts with controller-owned copy")
        return existing
    atomic_json(target, packet)
    copied = file_info(target, target_dir)
    if not copied:
        raise ControllerError("alternate packet copy failed")
    return copied


def bounded_authority(state: Dict[str, Any], directory: str, capability: str, role: str, principal: str,
                      candidate: Dict[str, Any], rationale: str) -> Dict[str, Any]:
    if capability not in AUTHORITY_CAPABILITIES:
        raise ControllerError("unsupported authority capability")
    if not role or len(role.encode()) > 160 or not principal or len(principal.encode()) > 300:
        raise ControllerError("target authority role and policy principal are required and bounded")
    if not rationale or len(rationale.encode()) > 2000:
        raise ControllerError("authority rationale is required and bounded")
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    artifacts = {x["name"]: x["sha256"] for x in evidence.get("declared_artifacts", [])
                 if isinstance(x, dict) and isinstance(x.get("name"), str) and isinstance(x.get("sha256"), str)}
    base_identity = {"repo_root": state["repo"]["root"], "head": state["repo"]["head"],
                     "worktree_branch": state["worktree"]["branch"], "brief_sha256": state["brief"]["sha256"]}
    base_digest = digest_bytes(json.dumps(base_identity, sort_keys=True, separators=(",", ":")).encode())
    candidate_digest = (evidence.get("worktree_fingerprint") or {}).get("digest")
    if not isinstance(candidate_digest, str):
        raise ControllerError("candidate fingerprint is required for authority escalation")
    expected_binding = {"base_digest": base_digest, "candidate_digest": candidate_digest,
               "artifact_hashes": artifacts, "finding_ids": [], "base": base_identity,
               "candidate_id": candidate.get("id"), "evidence_digest": candidate.get("evidence_digest")}
    refs = [{"kind": evidence.get("evidence_kind", "worker_packet"), "path": evidence.get("packet_path"),
             "sha256": evidence.get("packet_sha256")},
            {"kind": "worktree_fingerprint", "sha256": candidate_digest}]
    provider_failure = evidence.get("provider_failure") if isinstance(evidence.get("provider_failure"), dict) else None
    if provider_failure:
        required_failure = ("failure_class", "source_log_path", "source_log_sha256", "terminal_digest")
        if any(not isinstance(provider_failure.get(key), str) or not provider_failure[key] for key in required_failure):
            raise ControllerError("provider failure evidence is incomplete")
        refs.append({"kind": "provider_failure_log", "path": provider_failure["source_log_path"],
                     "sha256": provider_failure["source_log_sha256"],
                     "terminal_digest": provider_failure["terminal_digest"]})
    shallow_identity = {"package_id": state["work_id"], "capability_required": capability,
                        "target_authority": {"role": role, "principal": principal}, "policy_version": POLICY_ID,
                        "reason": rationale, "requested_amendment": rationale,
                        "candidate_id": expected_binding["candidate_id"], "evidence_digest": expected_binding["evidence_digest"],
                        "candidate_digest": expected_binding["candidate_digest"]}
    directory_path = os.path.join(directory, "escalations")
    if os.path.isdir(directory_path) and not os.path.islink(directory_path):
        for path in sorted(Path(directory_path).glob("*.json")):
            item = file_info(str(path), directory_path)
            if not item:
                continue
            try:
                with open(path, encoding="utf-8") as src:
                    existing = json.load(src)
            except (OSError, json.JSONDecodeError):
                continue
            existing_binding = existing.get("candidate_binding") if isinstance(existing, dict) and isinstance(existing.get("candidate_binding"), dict) else {}
            existing_identity = {"package_id": existing.get("package_id") if isinstance(existing, dict) else None,
                                 "capability_required": existing.get("capability_required") if isinstance(existing, dict) else None,
                                 "target_authority": existing.get("target_authority") if isinstance(existing, dict) else None,
                                 "policy_version": existing.get("policy_version") if isinstance(existing, dict) else None,
                                 "reason": existing.get("reason") if isinstance(existing, dict) else None,
                                 "requested_amendment": existing.get("requested_amendment") if isinstance(existing, dict) else None,
                                 "candidate_id": existing_binding.get("candidate_id"), "evidence_digest": existing_binding.get("evidence_digest"),
                                 "candidate_digest": existing_binding.get("candidate_digest")}
            if existing_identity != shallow_identity:
                continue
            expected_keys = {"schema_version", "kind", "package_id", "capability_required", "target_authority",
                             "policy_version", "policy_digest", "reason", "candidate_binding", "evidence_refs",
                             "requested_amendment", "issued_at", "resume_token", "resume_token_sha256", "causal_fingerprint"}
            token = existing.get("resume_token") if isinstance(existing, dict) else None
            causal = existing.get("causal_fingerprint") if isinstance(existing, dict) else None
            token_ok = isinstance(token, str) and re.fullmatch(r"[0-9a-f-]{36}\.[0-9a-f]{32}", token)
            issued_at = existing.get("issued_at") if isinstance(existing, dict) else None
            token_free = {k: v for k, v in existing.items() if k not in {"resume_token", "causal_fingerprint"}} if isinstance(existing, dict) else {}
            expected_causal = digest_bytes(json.dumps({"package_id": state["work_id"], "policy_version": POLICY_ID,
                                                        "candidate_digest": candidate_digest, "capability_required": capability,
                                                        "packet_without_token": token_free}, sort_keys=True, separators=(",", ":")).encode())
            if (not isinstance(existing, dict) or set(existing) != expected_keys or existing.get("schema_version") != SCHEMA or
                    existing.get("kind") != "authority_escalation" or existing.get("policy_digest") != digest_bytes(POLICY_ID.encode()) or
                    existing.get("candidate_binding") != expected_binding or existing.get("evidence_refs") != refs or
                    not isinstance(issued_at, str) or not issued_at or len(issued_at.encode()) > 64 or not token_ok or
                    existing.get("resume_token_sha256") != digest_bytes(token.encode()) or causal != expected_causal):
                raise ControllerError("matching orphan escalation packet failed full binding validation")
            if existing_identity == shallow_identity:
                return {"packet": existing, "path": str(path), "sha256": item["sha256"],
                        "token_sha256": digest_bytes(token.encode()), "causal_fingerprint": causal, "reused": True}
    token = str(uuid.uuid4()) + "." + uuid.uuid4().hex
    packet = {"schema_version": SCHEMA, "kind": "authority_escalation", "package_id": state["work_id"],
              "capability_required": capability, "target_authority": {"role": role, "principal": principal},
              "policy_version": POLICY_ID, "policy_digest": digest_bytes(POLICY_ID.encode()),
              "reason": rationale,
              "candidate_binding": expected_binding, "evidence_refs": refs,
              "requested_amendment": rationale, "issued_at": utc(), "resume_token": token,
              "resume_token_sha256": digest_bytes(token.encode())}
    token_free_packet = {k: v for k, v in packet.items() if k != "resume_token"}
    packet["causal_fingerprint"] = digest_bytes(json.dumps({"package_id": state["work_id"], "policy_version": POLICY_ID,
                                                               "candidate_digest": candidate_digest, "capability_required": capability,
                                                               "packet_without_token": token_free_packet}, sort_keys=True, separators=(",", ":")).encode())
    packet_id = str(uuid.uuid4())
    os.makedirs(directory_path, mode=0o700, exist_ok=True)
    path = os.path.join(directory_path, packet_id + ".json")
    atomic_json(path, packet)
    return {"packet": packet, "path": path, "sha256": (file_info(path, directory_path) or {}).get("sha256"),
            "token_sha256": digest_bytes(token.encode()), "causal_fingerprint": packet["causal_fingerprint"], "reused": False}


def _command_prepare(args: argparse.Namespace) -> Dict[str, Any]:
    repo, head = validate_repo(args.repo, clean=True)
    root = real(args.state_root or default_root(repo))
    brief = require_regular(args.brief_file)
    data = Path(brief).read_bytes()
    if len(data) > MAX_BRIEF:
        raise ControllerError("brief exceeds 64KiB limit")
    work_id = args.work_id or ("work-" + uuid.uuid4().hex[:12])
    directory = work_dir(root, work_id)
    if os.path.exists(state_path(directory)):
        state = load(directory)
        if state["repo"]["root"] != repo or state["brief"]["sha256"] != digest_bytes(data):
            raise ControllerError("existing work id has different repository or brief")
        return {"schema_version": SCHEMA, "operation": "prepare", "reused": True,
                "work_id": work_id, "state_root": root, "phase": state["phase"], "worktree": state["worktree"]["path"]}
    elif set(os.listdir(directory)) - {".controller.lock"}:
        raise ControllerError("new package directory is unexpectedly non-empty")
    os.makedirs(directory, mode=0o700, exist_ok=True)
    frozen = os.path.join(directory, "brief.md")
    Path(frozen).write_bytes(data)
    os.chmod(frozen, 0o600)
    worktree, branch = make_worktree(repo, work_id, head)
    state = {"schema_version": SCHEMA, "work_id": work_id, "created_at": utc(),
             "repo": {"root": repo, "head": head, "base_clean": True},
             "brief": {"path": frozen, "sha256": digest_bytes(data), "bytes": len(data)},
             "worktree": {"path": worktree, "branch": branch, "registered": True,
                          "baseline_head": head},
             "backend": {"kind": args.backend}, "phase": "prepared", "attempt": None,
             "interventions": [], "candidate": None, "escalation": None,
             "limitations": ["bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated", "publishing remains unavailable in this bootstrap controller even when publish_external is requested"],
             "revision": 0}
    append_event(directory, "prepared", repo=repo, head=head, worktree=worktree)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "prepare", "reused": False,
            "work_id": work_id, "state_root": root, "phase": "prepared", "worktree": worktree}


def launch_prompt(state: Dict[str, Any], role: str, instructions: Iterable[Dict[str, Any]]) -> str:
    brief = Path(state["brief"]["path"]).read_text(encoding="utf-8")
    lines = ["You are the %s for one bounded work package." % role,
             "Frozen brief SHA-256: " + state["brief"]["sha256"],
             "--- frozen brief ---", brief, "--- end frozen brief ---",
             "Work only in: " + state["worktree"]["path"],
             "Do not commit, push, open PRs, change permissions, or use other worktrees.",
             "Return only the requested structured outcome; the control plane validates evidence and gates it automatically."]
    if _is_package_a(state) and isinstance(state.get("package_a_prerequisites"),dict):
        bound=state["package_a_prerequisites"]
        lines.append("Controller-owned prerequisite baseline: path=%s sha256=%s fingerprint=%s" % (bound.get("path"),bound.get("sha256"),bound.get("fingerprint_digest")))
    for item in instructions:
        lines.append("Orchestrator intervention (%s): %s" % (item["id"], item["text"]))
    return "\n".join(lines)


def _command_launch(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory)
    if state.get("work_id")==PACKAGE_B_WORK_ID:
        if args.role!="implementer": raise ControllerError("Package B launch requires the implementer role")
        if state.get("backend",{}).get("kind")!="claude_direct" or args.model!="sonnet" or args.effort!="medium":
            raise ControllerError("Package B launch requires explicit claude sonnet medium under claude_direct")
        if args.resume and not state.get("attempt"): raise ControllerError("Package B cannot resume another package or absent attempt")
        prior_attempt_b=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if args.resume and any(prior_attempt_b.get(key)!=value for key,value in (("role","implementer"),("backend","claude_direct"),("provider","claude"),("controller","claude"),("model","sonnet"),("effort","medium"),("policy",POLICY_ID))):
            raise ControllerError("Package B resume attempt identity changed")
        if not isinstance(state.get("package_b_prerequisites"),dict): raise ControllerError("Package B prerequisites must be materialized before launch")
        _package_b_prerequisites_intact(directory,state)
        if not state.get("attempt") and worktree_fingerprint(state["worktree"]["path"])["digest"]!=state["package_b_prerequisites"].get("fingerprint_digest"):
            raise ControllerError("Package B worktree no longer matches the sealed prerequisite baseline")
    if _is_package_c(state):
        if args.role!="implementer": raise ControllerError("Package C launch requires the implementer role")
        if state.get("backend",{}).get("kind")!="claude_direct" or args.model!="sonnet" or args.effort!="medium":
            raise ControllerError("Package C launch requires explicit claude sonnet medium under claude_direct")
        if args.resume and not state.get("attempt"): raise ControllerError("Package C cannot resume another package or absent attempt")
        prior_attempt_c=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if args.resume and any(prior_attempt_c.get(key)!=value for key,value in (("role","implementer"),("backend","claude_direct"),("provider","claude"),("controller","claude"),("model","sonnet"),("effort","medium"),("policy",POLICY_ID))):
            raise ControllerError("Package C resume attempt identity changed")
        if not isinstance(state.get("package_c_prerequisites"),dict): raise ControllerError("Package C prerequisites must be materialized before launch")
        _package_c_prerequisites_intact(directory,state)
        _package_c_v3_plan_intact(os.path.dirname(directory))
        if not state.get("attempt") and worktree_fingerprint(state["worktree"]["path"])["digest"]!=state["package_c_prerequisites"].get("fingerprint_digest"):
            raise ControllerError("Package C worktree no longer matches the sealed prerequisite baseline")
    if _is_package_a(state):
        if args.role!="implementer": raise ControllerError("Package A launch requires the implementer role")
        if state.get("backend",{}).get("kind")!="claude_direct" or args.model!="sonnet" or args.effort!="medium":
            raise ControllerError("Package A launch requires explicit Claude Sonnet medium under claude_direct")
        if args.resume and not state.get("attempt"): raise ControllerError("Package A cannot resume another package or absent attempt")
        prior_attempt=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if args.resume and any(prior_attempt.get(key)!=value for key,value in (("role","implementer"),("backend","claude_direct"),("provider","claude"),("controller","claude"),("model","sonnet"),("effort","medium"),("policy",POLICY_ID))):
            raise ControllerError("Package A resume attempt identity changed")
        _package_a_prerequisites_intact(directory,state)
        if not state.get("attempt") and worktree_fingerprint(state["worktree"]["path"])["digest"]!=state["package_a_prerequisites"].get("fingerprint_digest"):
            raise ControllerError("Package A worktree no longer matches the sealed prerequisite baseline")
    early_recovery = state.get("recovery_constraint") if isinstance(state.get("recovery_constraint"), dict) else {}
    early_capacity = state.get("capacity") if isinstance(state.get("capacity"), dict) else {}
    correction_capacity_continuation = (
        early_recovery.get("kind") == "provider_plan_capacity_exact_resume" and not early_recovery.get("consumed_at") and
        early_capacity.get("mode") != "manual_signal" and isinstance(early_capacity.get("resumed_at"), str) and
        isinstance(early_capacity.get("lease_consumed_at"), str) and
        all(early_recovery.get(key) == early_capacity.get(key) for key in ("role", "provider_session_id", "candidate_id", "evidence_digest")) and
        early_recovery.get("capacity_packet_sha256") == early_capacity.get("sha256"))
    if _is_m0c_plan_work(state) and state.get("m0c_correction_used") and not correction_capacity_continuation:
        raise ControllerError("M0-C package has consumed its one bounded correction; no further launch or resume is permitted")
    if _is_package_a(state) and state.get("package_a_correction_used") and not correction_capacity_continuation:
        raise ControllerError("Package A has consumed its one bounded correction; no further launch or resume is permitted")
    if state.get("work_id")==PACKAGE_B_WORK_ID and state.get("package_b_correction_used") and not correction_capacity_continuation:
        raise ControllerError("Package B has consumed its one bounded correction; no further launch or resume is permitted")
    if _is_package_c(state) and state.get("package_c_correction_used") and not correction_capacity_continuation:
        raise ControllerError("Package C has consumed its one bounded correction; no further launch or resume is permitted")
    if _is_package_a(state) and correction_capacity_continuation:
        archived=_package_a_correction_archive_intact(directory,state)
        if early_capacity.get("package_a_correction_archive_sha256")!=archived["info"]["sha256"]:
            raise ControllerError("Package A capacity continuation lost its correction archive binding")
    gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
    if (gate.get("kind") in {"local_package_budget_guard", "local_package_budget_guard_retired"} or
            gate.get("failure_class") == "local_package_budget_guard"):
        raise ControllerError("local package budget guard is terminal; no launch or resume is permitted")
    capacity_state = state.get("capacity") if isinstance(state.get("capacity"), dict) else {}
    if capacity_state.get("mode") == "manual_signal":
        raise ControllerError("manual capacity wait requires an authenticated external authority adapter; no launch or resume is permitted")
    if state["backend"]["kind"] != "claude_direct":
        raise ControllerError("backend is blocked/not-ready: " + str(state["backend"]["kind"]))
    repo, _ = validate_repo(state["repo"]["root"], clean=False)
    wt = state["worktree"]
    if not registered_worktree(repo, wt["path"], wt["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    require_unchanged_base(repo, state["repo"]["head"])
    attempt = state.get("attempt") or {}
    if state.get("phase") in ACTIVE and process_alive(attempt.get("pid"), attempt.get("pgid")):
        raise ControllerError("an active attempt already owns this work package")
    if state.get("phase") in ACTIVE:
        state["phase"] = "failed"
        append_event(directory, "attempt_orphaned", attempt_id=attempt.get("id"))
    if args.role not in ROLES:
        raise ControllerError("invalid role")
    prior = state.get("attempt") or {}
    recovery = state.get("recovery_constraint") if isinstance(state.get("recovery_constraint"), dict) else None
    if (_is_package_a(state) and state.get("phase")=="failed" and
            gate.get("reason")=="invalid_or_missing_worker_packet" and not state.get("candidate") and
            not state.get("package_a_correction_used")):
        if not (recovery and not recovery.get("consumed_at") and recovery.get("kind")=="package_a_invalid_packet_exact_correction"):
            raise ControllerError("Package A invalid-packet failure requires a correction intervention before launch --resume is permitted")
    if recovery and not recovery.get("consumed_at"):
        spawn_failures = recovery.get("spawn_failures", [])
        if not isinstance(spawn_failures, list) or len(spawn_failures) > 1:
            raise ControllerError("M0-C exact correction exhausted its one bounded spawn recovery")
        required_role = recovery.get("role")
        required_session = recovery.get("provider_session_id")
        candidate = state.get("candidate") or {}
        if not args.resume:
            raise ControllerError("recovery requires an exact-session --resume launch")
        if args.role != required_role:
            raise ControllerError("recovery requires the original failed role")
        if not isinstance(required_session, str) or not required_session:
            raise ControllerError("recovery constraint lacks an exact provider session")
        if prior.get("provider_session_id") != required_session:
            raise ControllerError("recovery provider session continuity no longer matches")
        if recovery.get("kind") != "package_a_invalid_packet_exact_correction":
            if candidate.get("id") != recovery.get("candidate_id") or candidate.get("evidence_digest") != recovery.get("evidence_digest"):
                raise ControllerError("recovery candidate continuity no longer matches")
            if not candidate_intact(candidate, directory, wt["path"]):
                raise ControllerError("recovery candidate evidence binding no longer matches")
        if recovery.get("kind") == "m0c_invalidated_plan_exact_correction":
            receipt_path = recovery.get("invalidation_receipt_path")
            receipt = file_info(receipt_path, os.path.join(directory, "invalidations")) if isinstance(receipt_path, str) else None
            if not receipt or receipt.get("sha256") != recovery.get("invalidation_receipt_sha256"):
                raise ControllerError("correction invalidation receipt binding no longer matches")
            try: invalidation = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as exc: raise ControllerError("correction invalidation receipt is unreadable") from exc
            binding = invalidation.get("binding") if isinstance(invalidation, dict) else {}
            if (invalidation.get("kind") != "gate_invalidation_receipt" or binding.get("candidate_id") != candidate.get("id") or
                    binding.get("evidence_digest") != candidate.get("evidence_digest") or binding.get("reasons") != recovery.get("invalidation_reasons") or
                    recovery.get("intervention_sha256") not in {x.get("sha256") for x in state.get("interventions", []) if isinstance(x, dict)}):
                raise ControllerError("correction binding no longer matches invalidation evidence")
        elif recovery.get("kind") == "m0c_preingest_plan_exact_correction":
            if (prior.get("role") != "planner" or prior.get("provider_session_id") != recovery.get("provider_session_id") or
                    recovery.get("intervention_sha256") not in {x.get("sha256") for x in state.get("interventions", []) if isinstance(x, dict)}):
                raise ControllerError("pre-ingest correction binding no longer matches planner evidence")
        elif recovery.get("kind") == "package_a_exact_correction":
            baseline=_package_a_prerequisites_intact(directory,state)
            candidate_state={**state,"attempt":{**prior,"started_at":recovery.get("original_attempt_started_at")}}
            _package_a_candidate_intact(directory,candidate_state,candidate,baseline)
            archive_path=recovery.get("archive_path")
            archive_info=capped_regular_file_info(archive_path,os.path.join(directory,"package-a-corrections"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(archive_path,str) else None
            history=state.get("package_a_correction_history")
            if (prior.get("role")!="implementer" or prior.get("provider_session_id")!=recovery.get("provider_session_id") or
                    not archive_info or archive_info.get("sha256")!=recovery.get("archive_sha256") or not isinstance(history,list) or len(history)!=1 or
                    history[0].get("path")!=archive_info.get("path") or history[0].get("sha256")!=archive_info.get("sha256") or
                    recovery.get("intervention_sha256") not in {x.get("sha256") for x in state.get("interventions",[]) if isinstance(x,dict)}):
                raise ControllerError("Package A exact correction binding changed")
            try: archive=json.loads(Path(archive_info["path"]).read_text(encoding="utf-8"))
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A correction archive is unreadable") from exc
            if (archive.get("kind")!="package_a_correction_archive" or archive.get("candidate_id")!=candidate.get("id") or
                    archive.get("evidence_digest")!=candidate.get("evidence_digest") or archive.get("attempt_started_at")!=recovery.get("original_attempt_started_at") or
                    archive.get("delta_sha256")!=recovery.get("delta_sha256") or
                    archive.get("intervention_sha256")!=recovery.get("intervention_sha256")):
                raise ControllerError("Package A correction archive binding changed")
            archive_core={key:value for key,value in archive.items() if key not in {"archive_id","issued_at"}}
            if archive.get("archive_id")!=digest_bytes(json.dumps(archive_core,sort_keys=True,separators=(",",":")).encode()):
                raise ControllerError("Package A correction archive identity changed")
            refs=archive.get("evidence_refs")
            if not isinstance(refs,list) or not refs: raise ControllerError("Package A correction archive evidence is missing")
            for row in refs:
                if not isinstance(row,dict) or set(row)!={"path","sha256","bytes"} or not isinstance(row.get("path"),str):
                    raise ControllerError("Package A correction archive evidence row is malformed")
                item=capped_regular_file_info(row["path"],directory,MAX_CANDIDATE_PATH_BYTES)
                if not item or item.get("sha256")!=row.get("sha256") or item.get("bytes")!=row.get("bytes"):
                    raise ControllerError("Package A archived correction evidence changed")
        elif recovery.get("kind")=="package_a_invalid_packet_exact_correction":
            _package_a_prerequisites_intact(directory,state)
            fp_now=worktree_fingerprint(state["worktree"]["path"])
            if fp_now["digest"]!=recovery.get("fingerprint_digest"):
                raise ControllerError("Package A worktree fingerprint changed since invalid-packet correction was archived")
            archive_path=recovery.get("archive_path")
            archive_info=capped_regular_file_info(archive_path,os.path.join(directory,"package-a-corrections"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(archive_path,str) else None
            history=state.get("package_a_correction_history")
            if (prior.get("role")!="implementer" or prior.get("provider_session_id")!=recovery.get("provider_session_id") or
                    not archive_info or archive_info.get("sha256")!=recovery.get("archive_sha256") or not isinstance(history,list) or len(history)!=1 or
                    history[0].get("path")!=archive_info.get("path") or history[0].get("sha256")!=archive_info.get("sha256") or
                    recovery.get("intervention_sha256") not in {x.get("sha256") for x in state.get("interventions",[]) if isinstance(x,dict)}):
                raise ControllerError("Package A invalid-packet correction binding changed")
            try: archive=json.loads(Path(archive_info["path"]).read_text(encoding="utf-8"))
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A correction archive is unreadable") from exc
            if (archive.get("kind")!="package_a_invalid_packet_correction_archive" or
                    archive.get("attempt_id")!=prior.get("id") or
                    archive.get("provider_session_id")!=recovery.get("provider_session_id") or
                    archive.get("fingerprint_digest")!=recovery.get("fingerprint_digest") or
                    archive.get("intervention_sha256")!=recovery.get("intervention_sha256")):
                raise ControllerError("Package A invalid-packet correction archive binding changed")
            archive_core={k:v for k,v in archive.items() if k not in {"archive_id","issued_at"}}
            if archive.get("archive_id")!=digest_bytes(json.dumps(archive_core,sort_keys=True,separators=(",",":")).encode()):
                raise ControllerError("Package A invalid-packet correction archive identity changed")
            refs=archive.get("evidence_refs")
            if not isinstance(refs,list) or not refs: raise ControllerError("Package A invalid-packet correction archive evidence is missing")
            for row in refs:
                if not isinstance(row,dict) or set(row)!={"path","sha256","bytes"} or not isinstance(row.get("path"),str):
                    raise ControllerError("Package A invalid-packet correction archive evidence row is malformed")
                item=capped_regular_file_info(row["path"],directory,MAX_CANDIDATE_PATH_BYTES)
                if not item or item.get("sha256")!=row.get("sha256") or item.get("bytes")!=row.get("bytes"):
                    raise ControllerError("Package A archived invalid-packet correction evidence changed")
        elif recovery.get("kind")=="package_b_exact_correction":
            baseline=_package_b_prerequisites_intact(directory,state)
            candidate_state={**state,"attempt":{**prior,"started_at":recovery.get("original_attempt_started_at")}}
            _package_b_candidate_intact(directory,candidate_state,candidate,baseline)
            receipt_path=recovery.get("gate_receipt_path")
            receipt_info=capped_regular_file_info(receipt_path,os.path.join(directory,"package-b-gates"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(receipt_path,str) else None
            history=state.get("package_b_correction_history")
            if (prior.get("role")!="implementer" or prior.get("provider_session_id")!=recovery.get("provider_session_id") or
                    not receipt_info or receipt_info.get("sha256")!=recovery.get("gate_receipt_sha256") or
                    not isinstance(history,list) or len(history)!=1 or history[0].get("path")!=receipt_info.get("path") or
                    history[0].get("sha256")!=receipt_info.get("sha256")):
                raise ControllerError("Package B exact correction binding changed")
        elif recovery.get("kind")=="package_c_exact_correction":
            baseline=_package_c_prerequisites_intact(directory,state)
            candidate_state={**state,"attempt":{**prior,"started_at":recovery.get("original_attempt_started_at")}}
            _package_c_candidate_intact(directory,candidate_state,candidate,baseline)
            receipt_path=recovery.get("gate_receipt_path")
            receipt_info=capped_regular_file_info(receipt_path,os.path.join(directory,"package-c-gates"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(receipt_path,str) else None
            history=state.get("package_c_correction_history")
            if (prior.get("role")!="implementer" or prior.get("provider_session_id")!=recovery.get("provider_session_id") or
                    not receipt_info or receipt_info.get("sha256")!=recovery.get("gate_receipt_sha256") or
                    not isinstance(history,list) or len(history)!=1 or history[0].get("path")!=receipt_info.get("path") or
                    history[0].get("sha256")!=receipt_info.get("sha256")):
                raise ControllerError("Package C exact correction binding changed")
    if args.resume and not prior.get("provider_session_id"):
        raise ControllerError("cannot resume without an exact provider session id")
    pending = [x for x in state.get("interventions", []) if not x.get("consumed_at")]
    permitted = {"prepared", "failed", "cancelled", "paused"}
    if state.get("phase") == "awaiting_gate":
        raise ControllerError("candidate is awaiting deterministic gate adjudication")
    if state.get("phase") == "needs_authority":
        raise ControllerError("package needs an authority amendment token before another launch")
    if state.get("phase") == CAPACITY_WAITING:
        raise ControllerError("package is awaiting trusted plan capacity; resume-capacity is required after retry_after")
    elif state.get("phase") not in permitted:
        raise ControllerError("work package is not launchable from phase " + str(state.get("phase")))
    attempt_id = str(uuid.uuid4())
    session_id = recovery["provider_session_id"] if recovery and not recovery.get("consumed_at") else (prior.get("provider_session_id") if args.resume else str(uuid.uuid4()))
    logs = os.path.join(directory, "logs")
    os.makedirs(logs, mode=0o700, exist_ok=True)
    stdout_path, stderr_path = os.path.join(logs, attempt_id + ".stdout.log"), os.path.join(logs, attempt_id + ".stderr.log")
    executable = resolve_executable(args.claude_bin)
    prompt = launch_prompt(state, args.role, pending)
    permission = "auto" if args.role == "implementer" else "plan"
    outcome_schema=(PACKAGE_B_OUTCOME_SCHEMA if state.get("work_id")==PACKAGE_B_WORK_ID else
                    PACKAGE_C_OUTCOME_SCHEMA if _is_package_c(state) else
                    PACKAGE_A_OUTCOME_SCHEMA if _is_package_a(state) else OUTCOME_SCHEMA)
    argv = [executable, "-p", "--safe-mode", "--permission-mode", permission,
            "--disallowedTools", "Agent,Task", "--output-format", "stream-json",
            "--verbose", "--json-schema", json.dumps(outcome_schema, separators=(",", ":"))]
    argv += ["--resume", session_id] if args.resume else ["--session-id", session_id]
    if args.model:
        argv += ["--model", args.model]
    if args.effort:
        argv += ["--effort", args.effort]
    argv.append(prompt)
    state["phase"] = "starting"
    state["attempt"] = {"id": attempt_id, "role": args.role, "provider_session_id": session_id,
                        "resume": bool(args.resume), "pid": None, "pgid": None,
                        "started_at": utc(), "last_activity_at": utc(), "stdout": stdout_path,
                        "stderr": stderr_path, "argv_digest": digest_bytes(json.dumps(argv).encode()),
                        "backend": state["backend"]["kind"], "provider": "claude", "controller": "claude",
                        "model": args.model, "effort": args.effort, "policy": POLICY_ID}
    append_event(directory, "attempt_starting", attempt_id=attempt_id, role=args.role, resume=bool(args.resume))
    save(directory, state)
    try:
        child_pid, child_pgid = detached_spawn(argv, wt["path"], stdout_path, stderr_path)
    except (OSError, ControllerError) as exc:
        state["phase"] = "failed"
        state["attempt"]["spawn_error"] = type(exc).__name__
        if recovery and not recovery.get("consumed_at") and recovery.get("kind") in {"m0c_invalidated_plan_exact_correction", "m0c_preingest_plan_exact_correction", "package_a_exact_correction", "package_a_invalid_packet_exact_correction", "package_b_exact_correction"}:
            failures = recovery.setdefault("spawn_failures", [])
            failures.append({"at": utc(), "attempt_id": attempt_id, "error": type(exc).__name__})
        append_event(directory, "attempt_spawn_failed", attempt_id=attempt_id, error=type(exc).__name__)
        save(directory, state)
        raise ControllerError("controller spawn failed") from exc
    state["phase"] = "running"
    state["attempt"].update({"pid": child_pid, "pgid": child_pgid, "last_activity_at": utc()})
    for item in pending:
        item["consumed_at"] = utc()
        item["consumed_by_attempt"] = attempt_id
    append_event(directory, "attempt_running", attempt_id=attempt_id, pid=child_pid, session_id=session_id)
    if recovery and not recovery.get("consumed_at"):
        recovery["consumed_at"] = utc()
        recovery["resumed_attempt_id"] = attempt_id
        recovery["resumed_provider_session_id"] = session_id
        append_event(directory, "recovery_resumed", attempt_id=attempt_id,
                     original_attempt_id=recovery.get("original_attempt_id"), role=args.role,
                     candidate_id=recovery.get("candidate_id"), evidence_digest=recovery.get("evidence_digest"),
                     authority_amendment_sha256=recovery.get("authority_amendment_sha256"))
        if recovery.get("kind") in {"m0c_invalidated_plan_exact_correction", "m0c_preingest_plan_exact_correction"}:
            state["m0c_correction_used"] = {"at": recovery["consumed_at"], "attempt_id": attempt_id,
                                              "intervention_sha256": recovery.get("intervention_sha256")}
        elif recovery.get("kind")=="package_a_exact_correction":
            state["package_a_correction_used"]={"at":recovery["consumed_at"],"attempt_id":attempt_id,
                "original_attempt_id":recovery.get("original_attempt_id"),"intervention_sha256":recovery.get("intervention_sha256"),
                "archive_sha256":recovery.get("archive_sha256")}
            prior_gate=state.pop("package_a_gate_receipt",None)
            if prior_gate:
                history=state.get("package_a_gate_receipt_history",[])
                if not isinstance(history,list): raise ControllerError("Package A gate receipt history is malformed")
                state["package_a_gate_receipt_history"]=history+[prior_gate]
        elif recovery.get("kind")=="package_a_invalid_packet_exact_correction":
            state["package_a_correction_used"]={"at":recovery["consumed_at"],"attempt_id":attempt_id,
                "original_attempt_id":recovery.get("original_attempt_id"),"intervention_sha256":recovery.get("intervention_sha256"),
                "archive_sha256":recovery.get("archive_sha256")}
        elif recovery.get("kind")=="package_b_exact_correction":
            state["package_b_correction_used"]={"at":recovery["consumed_at"],"attempt_id":attempt_id,
                "original_attempt_id":recovery.get("original_attempt_id"),"gate_receipt_sha256":recovery.get("gate_receipt_sha256")}
            state.pop("package_b_gate_receipt",None)
            state.pop("gate",None)
            state.pop("candidate",None)
            state.pop("package_b_builder_delta",None)
            state.pop("package_b_collect",None)
            state.pop("package_b_verification",None)
            state.pop("package_b_review",None)
            state.pop("package_b_review_attempt",None)
            state.pop("package_b_review_retries",None)
            state.pop("package_b_review_capacity",None)
        elif recovery.get("kind")=="package_c_exact_correction":
            state["package_c_correction_used"]={"at":recovery["consumed_at"],"attempt_id":attempt_id,
                "original_attempt_id":recovery.get("original_attempt_id"),"gate_receipt_sha256":recovery.get("gate_receipt_sha256")}
            state.pop("package_c_gate_receipt",None)
            state.pop("gate",None)
            state.pop("candidate",None)
            state.pop("package_c_builder_delta",None)
            state.pop("package_c_collect",None)
            state.pop("package_c_verification",None)
            state.pop("package_c_review",None)
            state.pop("package_c_review_attempt",None)
            state.pop("package_c_review_retries",None)
            state.pop("package_c_review_capacity",None)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "launch", "work_id": state["work_id"],
            "phase": "running", "attempt_id": attempt_id, "provider_session_id": session_id}


def state_summary(state: Dict[str, Any]) -> Dict[str, Any]:
    attempt = state.get("attempt") or {}
    candidate = state.get("candidate") or {}
    alive = process_alive(attempt.get("pid"), attempt.get("pgid"))
    limitations = list(state.get("limitations", []))
    if _legacy_unsealed_alternate(state) and LEGACY_UNSEALED_ALTERNATE_ERROR not in limitations:
        limitations.append(LEGACY_UNSEALED_ALTERNATE_ERROR)
    return {"schema_version": SCHEMA, "work_id": state["work_id"], "phase": state["phase"],
            "revision": state["revision"], "backend": state["backend"]["kind"],
            "worktree": state["worktree"]["path"],
            "attempt": {k: attempt.get(k) for k in ("id", "role", "provider_session_id", "pid", "started_at", "last_activity_at")},
            "candidate": {k: candidate.get(k) for k in ("id", "evidence_digest", "packet_verified")},
            "capacity": ({k: state["capacity"].get(k) for k in ("failure_class", "retry_after", "reset_source", "wakeup_ref", "candidate_id")}
                         if isinstance(state.get("capacity"), dict) else None),
            "limitations": limitations,
            "alive": alive,
            "awaiting_gate": state["phase"] == "awaiting_gate",
            "awaiting_capacity": state["phase"] == CAPACITY_WAITING,
            "needs_authority": state["phase"] == "needs_authority",
            "quiescent_uncollected": not alive and state["phase"] in ACTIVE}


def command_status(args: argparse.Namespace) -> Dict[str, Any]:
    return state_summary(load(work_dir(real(args.state_root), args.work_id)))


def recent_events(directory: str) -> List[Dict[str, Any]]:
    path = os.path.join(directory, "events.jsonl")
    if not os.path.isfile(path) or os.path.islink(path):
        return []
    rows = []
    with open(path, encoding="utf-8") as src:
        for line in src:
            try:
                row = json.loads(line)
                if isinstance(row, dict): rows.append(row)
            except json.JSONDecodeError:
                rows.append({"kind": "malformed_event"})
    return rows[-MAX_EVENTS:]


def command_inspect(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory)
    wt = state["worktree"]["path"]
    changed = git(wt, ["status", "--porcelain=v1", "--untracked-files=all"]).splitlines()
    logs = []
    for p in sorted(Path(directory, "logs").glob("*.log"))[:MAX_PATHS]:
        info = file_info(str(p), directory)
        if info: logs.append(info)
    return {**state_summary(state), "events": recent_events(directory),
            "changed_paths": changed[:MAX_PATHS], "changed_paths_truncated": len(changed) > MAX_PATHS,
            "logs": logs, "logs_truncated": len(list(Path(directory, "logs").glob("*.log"))) > MAX_PATHS}


def _command_intervene(args: argparse.Namespace) -> Dict[str, Any]:
    text = args.instruction.strip()
    if not text or len(text.encode()) > MAX_INSTRUCTION:
        raise ControllerError("instruction must be non-empty and at most 4096 bytes")
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory)
    if _is_m0c_plan_work(state) and state.get("m0c_correction_used"):
        raise ControllerError("M0-C package has consumed its one bounded correction; create a new authorized package")
    recovery = state.get("recovery_constraint") if isinstance(state.get("recovery_constraint"), dict) else {}
    if recovery.get("kind") == "m0c_preingest_plan_exact_correction" and not recovery.get("consumed_at"):
        raise ControllerError("pre-ingest M0-C correction is already queued and permits only exact planner resume")
    if recovery.get("kind") == "package_a_invalid_packet_exact_correction" and not recovery.get("consumed_at"):
        raise ControllerError("Package A invalid-packet correction is already queued; no further intervention is permitted")
    # This is the sole correction escape hatch: never make needs_correction a
    # generally launchable phase.  It preserves the completed planner session
    # and the invalidated candidate as immutable recovery inputs.
    if state.get("phase") == "needs_correction":
        gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
        candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
        attempt = state.get("attempt") if isinstance(state.get("attempt"), dict) else {}
        rounds = state.get("correction_rounds", [])
        if (not _is_m0c_plan_work(state) or gate.get("kind") != "m0c_plan_evidence" or gate.get("verdict") != "invalidated" or
                not isinstance(gate.get("receipt_id"), str) or not candidate.get("id") or not candidate.get("evidence_digest") or
                attempt.get("role") != "planner" or not isinstance(attempt.get("provider_session_id"), str) or not attempt.get("provider_session_id") or
                not isinstance(rounds, list) or rounds):
            raise ControllerError("needs_correction permits only one invalidated M0-C planner correction")
        receipt_path = os.path.join(directory, "invalidations", gate["receipt_id"] + ".json")
        receipt = file_info(receipt_path, os.path.join(directory, "invalidations"))
        if not receipt or not candidate_intact(candidate, directory, state["worktree"]["path"]):
            raise ControllerError("correction candidate or invalidation receipt binding no longer matches")
        try: invalidation = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc: raise ControllerError("correction invalidation receipt is unreadable") from exc
        binding = invalidation.get("binding") if isinstance(invalidation, dict) else {}
        if (invalidation.get("kind") != "gate_invalidation_receipt" or invalidation.get("package_id") != state["work_id"] or
                binding.get("candidate_id") != candidate["id"] or binding.get("evidence_digest") != candidate["evidence_digest"] or
                binding.get("plan_sha256") != (state.get("planner_artifact") or {}).get("plan_sha256") or not binding.get("reasons")):
            raise ControllerError("correction invalidation receipt failed strict binding validation")
        item = {"id": str(uuid.uuid4()), "at": utc(), "text": text, "sha256": digest_bytes(text.encode()), "source": "invalidated_m0c_plan_gate"}
        state.setdefault("interventions", []).append(item)
        state["correction_rounds"] = [{"at": utc(), "intervention_id": item["id"], "intervention_sha256": item["sha256"], "receipt_id": gate["receipt_id"]}]
        state["recovery_constraint"] = {"kind": "m0c_invalidated_plan_exact_correction", "active_at": utc(),
            "original_attempt_id": attempt["id"], "role": "planner", "provider_session_id": attempt["provider_session_id"],
            "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"], "invalidation_receipt_path": receipt_path,
            "invalidation_receipt_sha256": receipt["sha256"], "invalidation_reasons": binding["reasons"], "intervention_sha256": item["sha256"], "consumed_at": None}
        state["phase"] = "prepared"
        append_event(directory, "m0c_gate_correction_queued", intervention_id=item["id"], receipt_id=gate["receipt_id"], candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"])
        save(directory, state)
        return {"schema_version": SCHEMA, "operation": "intervene", "work_id": state["work_id"], "intervention_id": item["id"], "delivery": "exact_planner_resume_required", "phase": "prepared"}
    gate_v=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if (_is_package_a(state) and state.get("phase")=="failed" and
            gate_v.get("reason")=="invalid_or_missing_worker_packet" and not state.get("candidate") and
            not state.get("package_a_correction_used") and not state.get("package_a_correction_history") and not recovery):
        attempt_v=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if attempt_v.get("role")!="implementer" or not attempt_v.get("provider_session_id"):
            raise ControllerError("Package A invalid-packet correction requires an implementer attempt with a provider session")
        _package_a_prerequisites_intact(directory,state)
        prereq=state["package_a_prerequisites"]
        log_path=attempt_v.get("stdout")
        log_info=file_info(log_path,os.path.join(directory,"logs")) if isinstance(log_path,str) else None
        if not log_info: raise ControllerError("Package A invalid-packet correction: original attempt log is unsafe or missing")
        generation=state.get("package_a_collect_generation",0)
        if generation==0:
            res_path=os.path.join(directory,"result.json"); res_info=file_info(res_path,directory)
        else:
            terminal_r=state.get("package_a_terminal_result") if isinstance(state.get("package_a_terminal_result"),dict) else {}
            res_path=terminal_r.get("path",""); res_info=file_info(res_path,directory) if res_path else None
        if not res_info: raise ControllerError("Package A invalid-packet correction: controller result is unsafe or missing")
        fp=worktree_fingerprint(state["worktree"]["path"])
        item_v={"id":str(uuid.uuid4()),"at":utc(),"text":text,"sha256":digest_bytes(text.encode()),"source":"package_a_invalid_packet_gate"}
        state.setdefault("interventions",[]).append(item_v)
        evidence_refs=[{"path":log_info["path"],"sha256":log_info["sha256"],"bytes":log_info["bytes"]},
                       {"path":res_info["path"],"sha256":res_info["sha256"],"bytes":res_info["bytes"]}]
        archive_core={"kind":"package_a_invalid_packet_correction_archive","candidate_id":None,"evidence_digest":None,
            "attempt_id":attempt_v["id"],"original_attempt_started_at":attempt_v.get("started_at"),
            "provider_session_id":attempt_v["provider_session_id"],"role":"implementer","fingerprint_digest":fp["digest"],
            "prerequisite_sha256":prereq.get("sha256"),"intervention_sha256":item_v["sha256"],"evidence_refs":evidence_refs}
        archive_id=digest_bytes(json.dumps(archive_core,sort_keys=True,separators=(",",":")).encode())
        archive={**archive_core,"archive_id":archive_id,"issued_at":utc()}
        corrections_dir=os.path.join(directory,"package-a-corrections")
        os.makedirs(corrections_dir,mode=0o700,exist_ok=True)
        archive_path=os.path.join(corrections_dir,archive_id+".invalid_packet.json")
        atomic_json(archive_path,archive)
        archive_info=capped_regular_file_info(archive_path,corrections_dir,MAX_PLAN_ARTIFACT_BYTES)
        if not archive_info: raise ControllerError("Package A invalid-packet correction archive write failed")
        state["package_a_correction_history"]=[{"path":archive_info["path"],"sha256":archive_info["sha256"],"archive_id":archive_id,"candidate_id":None,"evidence_digest":None}]
        state["recovery_constraint"]={"kind":"package_a_invalid_packet_exact_correction","active_at":utc(),
            "original_attempt_id":attempt_v["id"],"original_attempt_started_at":attempt_v.get("started_at"),
            "role":"implementer","provider_session_id":attempt_v["provider_session_id"],
            "archive_path":archive_info["path"],"archive_sha256":archive_info["sha256"],"archive_id":archive_id,
            "fingerprint_digest":fp["digest"],"prerequisite_sha256":prereq.get("sha256"),
            "intervention_sha256":item_v["sha256"],"consumed_at":None}
        state["package_a_collect_generation"]=1
        state["phase"]="prepared"
        append_event(directory,"package_a_invalid_packet_correction_queued",intervention_id=item_v["id"],attempt_id=attempt_v["id"],fingerprint_digest=fp["digest"])
        save(directory,state)
        return {"schema_version":SCHEMA,"operation":"intervene","work_id":state["work_id"],
                "intervention_id":item_v["id"],"delivery":"exact_implementer_resume_required","phase":"prepared"}
    item = {"id": str(uuid.uuid4()), "at": utc(), "text": text, "sha256": digest_bytes(text.encode())}
    state.setdefault("interventions", []).append(item)
    append_event(directory, "intervention_queued", intervention_id=item["id"], sha256=item["sha256"])
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "intervene", "work_id": state["work_id"],
            "intervention_id": item["id"], "delivery": "next_resume"}


def _command_cancel(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory); attempt = state.get("attempt") or {}
    if not process_alive(attempt.get("pid"), attempt.get("pgid")):
        return {"schema_version": SCHEMA, "operation": "cancel", "work_id": state["work_id"], "already_quiescent": True}
    state["phase"] = "cancelling"; append_event(directory, "cancel_requested", attempt_id=attempt.get("id")); save(directory, state)
    try: os.killpg(int(attempt["pgid"]), signal.SIGTERM)
    except (OSError, ValueError, KeyError): pass
    deadline = time.monotonic() + max(1, min(args.grace_seconds, 30))
    while time.monotonic() < deadline and process_alive(attempt.get("pid"), attempt.get("pgid")):
        time.sleep(0.1)
    killed = False
    if process_alive(attempt.get("pid"), attempt.get("pgid")):
        try: os.killpg(int(attempt["pgid"]), signal.SIGKILL); killed = True
        except (OSError, ValueError, KeyError): pass
    state["phase"] = "cancelled"; append_event(directory, "cancelled", attempt_id=attempt.get("id"), killed=killed); save(directory, state)
    return {"schema_version": SCHEMA, "operation": "cancel", "work_id": state["work_id"], "cancelled": True, "forced": killed}


def _controller_result_path(directory: str,state: Dict[str,Any],attempt: Dict[str,Any],classification: str) -> str:
    if _is_package_a(state) and state.get("package_a_collect_generation",0)>0:
        ident=_safe_identifier(attempt.get("id"),"Package A result attempt id")
        if not re.fullmatch(r"[a-z][a-z0-9_]{2,63}",classification): raise ControllerError("Package A result classification is malformed")
        root=os.path.join(directory,"package-a-results")
        if os.path.lexists(root) and (os.path.islink(root) or not os.path.isdir(root) or not inside(real(root),directory)):
            raise ControllerError("Package A result directory is unsafe")
        os.makedirs(root,mode=0o700,exist_ok=True)
        return os.path.join(root,ident+"."+classification+".json")
    return os.path.join(directory,"result.json")


def _package_a_correction_archive_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    history=state.get("package_a_correction_history")
    if not isinstance(history,list) or len(history)!=1 or not isinstance(history[0],dict): raise ControllerError("Package A correction archive history is malformed")
    bound=history[0]; path=bound.get("path")
    info=capped_regular_file_info(path,os.path.join(directory,"package-a-corrections"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(path,str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A correction archive changed")
    try: archive=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A correction archive is unreadable") from exc
    core={key:value for key,value in archive.items() if key not in {"archive_id","issued_at"}} if isinstance(archive,dict) else {}
    if (archive.get("archive_id")!=bound.get("archive_id") or archive.get("archive_id")!=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()) or
            archive.get("candidate_id")!=bound.get("candidate_id") or archive.get("evidence_digest")!=bound.get("evidence_digest")):
        raise ControllerError("Package A correction archive identity changed")
    refs=archive.get("evidence_refs")
    if not isinstance(refs,list) or not refs: raise ControllerError("Package A correction archive evidence is missing")
    for row in refs:
        if not isinstance(row,dict) or set(row)!={"path","sha256","bytes"} or not isinstance(row.get("path"),str): raise ControllerError("Package A correction archive evidence row is malformed")
        item=capped_regular_file_info(row["path"],directory,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=row.get("sha256") or item.get("bytes")!=row.get("bytes"): raise ControllerError("Package A archived correction evidence changed")
    return {"archive":archive,"info":info}


def _write_controller_result(directory: str,state: Dict[str,Any],attempt: Dict[str,Any],classification: str,result: Dict[str,Any]) -> Dict[str,Any]:
    path=_controller_result_path(directory,state,attempt,classification)
    if _is_package_a(state) and state.get("package_a_collect_generation",0)>0:
        result["result_path"]=path
        info=_package_a_adopt_json(path,os.path.dirname(path),result,"versioned controller result")
        state["package_a_terminal_result"]={"path":info["path"],"sha256":info["sha256"],"classification":classification,"attempt_id":attempt.get("id")}
        return info
    atomic_json(path,result)
    item=file_info(path,directory)
    if not item: raise ControllerError("controller result write failed")
    return item


def provider_capacity_wait(directory: str, state: Dict[str, Any], attempt: Dict[str, Any],
                           changed: List[str], artifacts: List[Dict[str, Any]], operation: str) -> Dict[str, Any]:
    """Persist a candidate-bound timed wait for trusted subscription capacity."""
    failure = provider_capacity_failure(directory, attempt)
    if not failure:
        raise ControllerError("no trusted resettable provider capacity result to reconcile")
    wt = state["worktree"]["path"]
    candidate = candidate_record(failure, changed, artifacts, wt, packet_verified=False,
                                 evidence_kind="provider_capacity_wait",
                                 failure_metadata={"failure_class": failure["failure_class"],
                                                   "source_log_path": str(attempt.get("stdout", "")),
                                                   "source_log_sha256": failure["source_log_sha256"],
                                                   "terminal_digest": failure["terminal_digest"]})
    candidate["id"] = "capacity-" + candidate["evidence_digest"][:32]
    capacity = {"path": failure["path"], "sha256": failure["sha256"], "failure_class": failure["failure_class"],
                "retry_after": failure["retry_after"], "reset_source": failure["reset_source"],
                "reset_evidence_digest": failure["reset_evidence_digest"], "provider": failure["provider"], "wakeup_ref": None, "lease_id": None,
                "wakeup_receipt_path": None, "wakeup_receipt_sha256": None, "lease_consumed_at": None,
                "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
                "original_attempt_id": attempt.get("id"), "role": attempt.get("role"),
                "provider_session_id": attempt.get("provider_session_id"), "resumed_at": None}
    state["candidate"] = candidate; state["capacity"] = capacity; state["escalation"] = None
    state["phase"] = CAPACITY_WAITING
    state["gate"] = {"verdict": CAPACITY_WAITING, "kind": "provider_capacity", "failure_class": failure["failure_class"],
                     "retry_after": failure["retry_after"], "candidate_id": candidate["id"],
                     "evidence_digest": candidate["evidence_digest"], "at": utc(), "policy": POLICY_ID}
    state["attempt"]["provider_failure"] = {"failure_class": failure["failure_class"], "packet_sha256": failure["sha256"],
                                                "source_log_sha256": failure["source_log_sha256"], "terminal_digest": failure["terminal_digest"]}
    result = {"schema_version": SCHEMA, "work_id": state["work_id"], "operation": operation, "phase": CAPACITY_WAITING,
              "gate": state["gate"], "capacity": {k: capacity[k] for k in ("failure_class", "retry_after", "reset_source", "reset_evidence_digest", "wakeup_ref", "lease_id", "candidate_id", "evidence_digest")},
              "provider_failure": {"failure_class": failure["failure_class"], "packet_sha256": failure["sha256"], "source_log_sha256": failure["source_log_sha256"], "terminal_digest": failure["terminal_digest"]},
              "limitations": ["no authority escalation is issued for trusted resettable plan capacity", "no automatic relaunch occurs before retry_after", "provider output text is never included in controller output"]}
    if _is_package_a(state) and state.get("package_a_collect_generation",0)>0:
        history=state.get("package_a_correction_history",[])
        if not isinstance(history,list) or len(history)!=1: raise ControllerError("Package A correction capacity lacks immutable archive")
        capacity["package_a_correction_archive_sha256"]=history[0].get("sha256")
    _write_controller_result(directory,state,attempt,"capacity_wait",result)
    append_event(directory, "provider_capacity_waiting", attempt_id=attempt.get("id"), role=attempt.get("role"),
                 provider_session_id=attempt.get("provider_session_id"), candidate_id=candidate["id"],
                 evidence_digest=candidate["evidence_digest"], retry_after=failure["retry_after"],
                 reset_source=failure["reset_source"], reset_evidence_digest=failure["reset_evidence_digest"],
                 worktree_fingerprint=candidate["evidence"]["worktree_fingerprint"]["digest"],
                 source_log_sha256=failure["source_log_sha256"], capacity_packet_sha256=failure["sha256"], policy=POLICY_ID)
    save(directory, state)
    return result


def provider_manual_capacity_wait(directory: str, state: Dict[str, Any], attempt: Dict[str, Any],
                                  changed: List[str], artifacts: List[Dict[str, Any]], operation: str) -> Dict[str, Any]:
    failure = provider_manual_capacity_failure(directory, attempt)
    if not failure:
        raise ControllerError("no provider quota terminal result is available for manual capacity wait")
    wt = state["worktree"]["path"]
    candidate = candidate_record(failure, changed, artifacts, wt, packet_verified=False,
                                 evidence_kind="provider_capacity_manual_signal",
                                 failure_metadata={"failure_class": failure["failure_class"], "source_log_path": str(attempt.get("stdout", "")),
                                                   "source_log_sha256": failure["source_log_sha256"], "terminal_digest": failure["terminal_digest"]})
    candidate["id"] = "capacity-" + candidate["evidence_digest"][:32]
    capacity = {"mode": "manual_signal", "path": failure["path"], "sha256": failure["sha256"],
                "failure_class": failure["failure_class"], "provider": failure["provider"], "candidate_id": candidate["id"],
                "evidence_digest": candidate["evidence_digest"], "original_attempt_id": attempt.get("id"),
                "role": attempt.get("role"), "provider_session_id": attempt.get("provider_session_id"), "signal": None, "resumed_at": None}
    state["candidate"] = candidate; state["capacity"] = capacity; state["escalation"] = None
    if not _is_package_a(state): state.pop("recovery_constraint", None)
    state["phase"] = CAPACITY_WAITING
    state["gate"] = {"verdict": CAPACITY_WAITING, "kind": "provider_capacity", "failure_class": failure["failure_class"],
                     "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"], "at": utc(), "policy": POLICY_ID}
    state["attempt"]["provider_failure"] = {"failure_class": failure["failure_class"], "packet_sha256": failure["sha256"],
                                                "source_log_sha256": failure["source_log_sha256"], "terminal_digest": failure["terminal_digest"]}
    result = {"schema_version": SCHEMA, "work_id": state["work_id"], "operation": operation, "phase": CAPACITY_WAITING,
              "gate": state["gate"], "capacity": {k: capacity[k] for k in ("mode", "failure_class", "candidate_id", "evidence_digest")},
              "limitations": ["no reset time was trusted", "an explicit human capacity-available signal is required before exact-session resume", "provider output text is never included in controller output"]}
    if _is_package_a(state) and state.get("package_a_collect_generation",0)>0:
        history=state.get("package_a_correction_history",[])
        if not isinstance(history,list) or len(history)!=1: raise ControllerError("Package A correction capacity lacks immutable archive")
        capacity["package_a_correction_archive_sha256"]=history[0].get("sha256")
    _write_controller_result(directory,state,attempt,"capacity_manual_wait",result)
    append_event(directory, "provider_capacity_manual_waiting", attempt_id=attempt.get("id"), candidate_id=candidate["id"],
                 evidence_digest=candidate["evidence_digest"], source_log_sha256=failure["source_log_sha256"], policy=POLICY_ID)
    save(directory, state)
    return result


def _package_a_reconcile_invalid_packet_generation(directory: str, state: Dict[str,Any], attempt: Dict[str,Any]) -> None:
    """Narrowly bounded, crash-safe, idempotent backward-compat reconciliation.

    Before the generation=1 fix landed, a consumed package_a_invalid_packet_exact_correction
    recovery left generation absent/0 in the persisted state.  On the very next collect the
    corrected packet is valid but generation=0 → result_path resolves to the root result.json
    which already exists, raising "cannot precede its durable intent".

    This function detects that exact pre-fix shape and sets generation=1 in one atomic
    save so the subsequent collect uses the attempt-specific path.  Any tampered, ambiguous,
    active, or structurally wrong state fails closed with a ControllerError.

    Already generation=1 is a silent no-op.  Future interventions already set generation=1
    before saving, so this path is never reached for newly created states.
    """
    if not _is_package_a(state):
        return
    generation = state.get("package_a_collect_generation", 0)
    if isinstance(generation, bool) or not isinstance(generation, int):
        raise ControllerError("Package A collect generation is invalid")
    if generation == 1:
        return
    if generation != 0:
        raise ControllerError("Package A collect generation is invalid")
    recovery = state.get("recovery_constraint") if isinstance(state.get("recovery_constraint"), dict) else None
    if not recovery or recovery.get("kind") != "package_a_invalid_packet_exact_correction" or not recovery.get("consumed_at"):
        return
    correction_used = state.get("package_a_correction_used")
    if not isinstance(correction_used, dict):
        raise ControllerError("Package A backward-compat reconciliation: correction_used is absent or malformed")
    if (correction_used.get("original_attempt_id") != recovery.get("original_attempt_id") or
            correction_used.get("intervention_sha256") != recovery.get("intervention_sha256") or
            correction_used.get("archive_sha256") != recovery.get("archive_sha256")):
        raise ControllerError("Package A backward-compat reconciliation: correction_used does not cross-bind with recovery")
    if attempt.get("role") != "implementer":
        raise ControllerError("Package A backward-compat reconciliation: current attempt role is not implementer")
    if attempt.get("provider_session_id") != recovery.get("provider_session_id"):
        raise ControllerError("Package A backward-compat reconciliation: attempt session does not match recovery")
    if attempt.get("policy") != POLICY_ID:
        raise ControllerError("Package A backward-compat reconciliation: attempt policy does not match current policy")
    if state.get("candidate") is not None:
        raise ControllerError("Package A backward-compat reconciliation: unexpected candidate present")
    if state.get("package_a_collect") is not None:
        raise ControllerError("Package A backward-compat reconciliation: unexpected collect evidence present")
    if state.get("package_a_builder_delta") is not None:
        raise ControllerError("Package A backward-compat reconciliation: unexpected builder delta present")
    history = state.get("package_a_correction_history")
    if not isinstance(history, list) or len(history) != 1 or not isinstance(history[0], dict):
        raise ControllerError("Package A backward-compat reconciliation: correction history is malformed")
    corrections_dir = os.path.join(directory, "package-a-corrections")
    archive_path = recovery.get("archive_path")
    archive_info = capped_regular_file_info(archive_path, corrections_dir, MAX_PLAN_ARTIFACT_BYTES) if isinstance(archive_path, str) else None
    if not archive_info or archive_info.get("sha256") != recovery.get("archive_sha256"):
        raise ControllerError("Package A backward-compat reconciliation: correction archive binding changed")
    if history[0].get("sha256") != archive_info["sha256"]:
        raise ControllerError("Package A backward-compat reconciliation: correction history sha256 does not match archive")
    try:
        archive = json.loads(Path(archive_info["path"]).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("Package A backward-compat reconciliation: correction archive is unreadable") from exc
    if archive.get("kind") != "package_a_invalid_packet_correction_archive":
        raise ControllerError("Package A backward-compat reconciliation: correction archive kind is wrong")
    if (archive.get("attempt_id") != recovery.get("original_attempt_id") or
            archive.get("provider_session_id") != recovery.get("provider_session_id") or
            archive.get("fingerprint_digest") != recovery.get("fingerprint_digest") or
            archive.get("intervention_sha256") != recovery.get("intervention_sha256")):
        raise ControllerError("Package A backward-compat reconciliation: correction archive bindings do not match recovery")
    archive_core = {k: v for k, v in archive.items() if k not in {"archive_id", "issued_at"}}
    if archive.get("archive_id") != digest_bytes(json.dumps(archive_core, sort_keys=True, separators=(",", ":")).encode()):
        raise ControllerError("Package A backward-compat reconciliation: correction archive identity changed")
    refs = archive.get("evidence_refs")
    if not isinstance(refs, list) or not refs:
        raise ControllerError("Package A backward-compat reconciliation: correction archive evidence is missing")
    root_result_path = real(os.path.join(directory, "result.json"))
    root_result_ref = None
    for row in refs:
        if not isinstance(row, dict) or set(row) != {"path", "sha256", "bytes"} or not isinstance(row.get("path"), str):
            raise ControllerError("Package A backward-compat reconciliation: correction archive evidence row is malformed")
        item = capped_regular_file_info(row["path"], directory, MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256") != row.get("sha256") or item.get("bytes") != row.get("bytes"):
            raise ControllerError("Package A backward-compat reconciliation: archived correction evidence changed")
        try:
            if real(row["path"]) == root_result_path:
                root_result_ref = row
        except OSError:
            pass
    if not root_result_ref:
        raise ControllerError("Package A backward-compat reconciliation: root result.json is not bound by archive evidence")
    _package_a_prerequisites_intact(directory, state)
    for subdir, label in (("package-a-collect", "collect"), ("package-a-delta", "delta")):
        p = os.path.join(directory, subdir)
        if os.path.lexists(p):
            if os.path.islink(p) or not os.path.isdir(p) or not inside(real(p), directory):
                raise ControllerError("Package A backward-compat reconciliation: %s directory is unsafe" % label)
            if os.listdir(p):
                raise ControllerError("Package A backward-compat reconciliation: %s directory has unexpected contents" % label)
    event_kind = "package_a_invalid_packet_generation_reconciled"
    already = any(row.get("kind") == event_kind and row.get("attempt_id") == attempt.get("id")
                  for row in recent_events(directory))
    state["package_a_collect_generation"] = 1
    if not already:
        append_event(directory, event_kind, attempt_id=attempt.get("id"),
                     archive_id=archive.get("archive_id"),
                     intervention_sha256=recovery.get("intervention_sha256"))
    save(directory, state)


def _command_collect(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory); attempt = state.get("attempt") or {}
    if state.get("work_id")==PACKAGE_B_WORK_ID and state.get("phase")=="awaiting_gate" and isinstance(state.get("package_b_collect"),dict):
        return _package_b_replay_collect(directory,state)
    if _is_package_c(state) and state.get("phase")=="awaiting_gate" and isinstance(state.get("package_c_collect"),dict):
        return _package_c_replay_collect(directory,state)
    if _is_package_a(state) and state.get("phase")=="awaiting_gate" and isinstance(state.get("package_a_collect"),dict):
        return _package_a_replay_collect(directory,state)
    if state.get("phase") not in {"starting", "running"}:
        raise ControllerError("collect requires a quiescent worker attempt awaiting evidence binding")
    if process_alive(attempt.get("pid"), attempt.get("pgid")):
        raise ControllerError("cannot collect while attempt is active")
    wt = state["worktree"]["path"]
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    if not registered_worktree(state["repo"]["root"], wt, state["worktree"]["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    changed = git(wt, ["status", "--porcelain=v1", "--untracked-files=all"]).splitlines()
    receipts = [x for x in (file_info(str(p), directory) for p in Path(directory).rglob("*.json")) if x]
    artifacts = []
    for record in declared_artifacts(wt):
        artifacts.append({"path": os.path.join(wt, record["name"]), "bytes": record["bytes"], "sha256": record["sha256"]})
    _package_a_reconcile_invalid_packet_generation(directory, state, attempt)
    if provider_capacity_failure(directory, attempt):
        return provider_capacity_wait(directory, state, attempt, changed, artifacts, "collect")
    if provider_manual_capacity_failure(directory, attempt):
        return provider_manual_capacity_wait(directory, state, attempt, changed, artifacts, "collect")
    guard = provider_terminal_failure(directory, attempt)
    if guard:
        result = {"schema_version": SCHEMA, "work_id": state["work_id"], "operation": "collect",
                  "phase_before_collect": state["phase"], "phase": "failed",
                  "gate": {"phase": "failed", "kind": "local_package_budget_guard", "verdict": "fail",
                           "failure_class": guard["failure_class"]},
                  "provider_failure": {"failure_class": guard["failure_class"],
                                       "packet_sha256": guard["sha256"], "source_log_sha256": guard["source_log_sha256"],
                                       "terminal_digest": guard["terminal_digest"]},
                  "limitations": ["local package budget exhaustion is terminal and cannot be resumed or amended",
                                  "it is not provider quota evidence and cannot enter awaiting_capacity",
                                  "provider output text is never included in controller output"]}
        _write_controller_result(directory,state,attempt,"local_guard_failure",result)
        state["candidate"] = None; state["escalation"] = None
        if not _is_package_a(state): state.pop("recovery_constraint", None)
        state["phase"] = "failed"
        state["gate"] = {"verdict": "fail", "kind": "local_package_budget_guard", "at": utc(),
                         "failure_class": guard["failure_class"], "policy": POLICY_ID}
        state["attempt"]["provider_failure"] = result["provider_failure"]
        append_event(directory, "local_package_budget_guard_terminal", attempt_id=attempt.get("id"), policy=POLICY_ID)
        save(directory, state)
        return result
    packet = final_structured_packet(directory, attempt)
    if not packet:
        result = {"schema_version": SCHEMA, "work_id": state["work_id"], "operation": "collect",
                  "gate": {"phase": "failed", "kind": "deterministic_validation", "verdict": "fail",
                           "reason": "invalid_or_missing_worker_packet"},
                  "phase_before_collect": state["phase"], "worker_packet": {"unverified": True},
                  "limitations": ["invalid structured output fails closed before supervisor adjudication", "bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated", "publishing remains unavailable in this bootstrap controller even when publish_external is requested"]}
        _write_controller_result(directory,state,attempt,"invalid_worker_packet",result)
        state["candidate"] = None
        state["escalation"] = None
        state["phase"] = "failed"
        state["gate"] = {"verdict": "fail", "kind": "deterministic_validation", "at": utc(),
                         "reason": "invalid_or_missing_worker_packet", "policy": POLICY_ID}
        append_event(directory, "candidate_validation_failed", attempt_id=attempt.get("id"), policy=POLICY_ID)
        save(directory, state)
        return result
    if state.get("work_id")==PACKAGE_B_WORK_ID:
        return _package_b_collect_verified(directory,state,attempt,packet,changed,receipts,artifacts)
    if _is_package_c(state):
        return _package_c_collect_verified(directory,state,attempt,packet,changed,receipts,artifacts)
    if _is_package_a(state):
        return _package_a_collect_verified(directory,state,attempt,packet,changed,receipts,artifacts)
    candidate = candidate_record(packet, changed, artifacts, wt)
    result = {"schema_version": SCHEMA, "work_id": state["work_id"], "operation": "collect",
              "gate": {"phase": "awaiting_gate", "kind": "evidence_bound_candidate",
                       "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
                       "packet_verified": candidate["packet_verified"]},
              "phase_before_collect": state["phase"], "attempt": {k: attempt.get(k) for k in ("id", "role", "provider_session_id", "pid")},
              "worktree": wt, "changed_paths": changed[:MAX_PATHS], "changed_paths_truncated": len(changed) > MAX_PATHS,
              "receipts": receipts[:MAX_PATHS], "artifacts": artifacts,
              "worker_packet": ({"path": packet["path"], "sha256": packet["sha256"],
                                  "outcome": packet["structured"]["outcome"],
                                  "summary": packet["structured"]["summary"],
                                  "next_action": packet["structured"]["next_action"]}
                                if packet else {"unverified": True}),
              "limitations": ["provider output is not proof of correctness", "no watcher or lease/fencing protocol is implemented", "detached provider exit code is not collected", "Cowork backend adapter is not implemented", "bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated", "publishing remains unavailable in this bootstrap controller even when publish_external is requested"]}
    atomic_json(os.path.join(directory, "result.json"), result)
    state["candidate"] = candidate
    state["escalation"] = None
    if state["phase"] not in {"cancelled", "failed"}:
        state["phase"] = "awaiting_gate"
    append_event(directory, "candidate_collected", attempt_id=attempt.get("id"),
                 candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"],
                 packet_verified=candidate["packet_verified"])
    save(directory, state)
    return result


def _command_ingest_plan_artifact(args: argparse.Namespace) -> Dict[str, Any]:
    """Copy one post-attempt Claude planner artifact and bind a strict M0-C plan gate.

    The source is evidence only: it is never referenced after this command and
    generic stream-json prose is deliberately not used as plan evidence.
    """
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    attempt = state.get("attempt") or {}
    if attempt.get("role") != "planner" or state.get("phase") not in {"awaiting_gate", "needs_correction"}:
        raise ControllerError("plan artifact ingestion requires a planner awaiting gate or correction")
    require_frozen_brief(state, directory); require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    source_root = real(args.claude_plans_root)
    source = os.path.abspath(os.path.expanduser(args.source_file))
    if not inside(source, source_root) or real(source) != source or os.path.islink(source):
        raise ControllerError("planner artifact source must be a direct file below the configured Claude plans root")
    configured = state.get("planner_artifact") if isinstance(state.get("planner_artifact"), dict) else {}
    if configured.get("source_root") and configured["source_root"] != source_root:
        raise ControllerError("Claude plans root is frozen for this package")
    try:
        before = os.stat(source, follow_symlinks=False)
        started = dt.datetime.fromisoformat(str(attempt["started_at"]).replace("Z", "+00:00")).timestamp()
        if not stat.S_ISREG(before.st_mode) or before.st_size <= 0 or before.st_size > MAX_PLAN_ARTIFACT_BYTES or before.st_mtime < started:
            raise ControllerError("planner artifact is unsafe, oversized, or predates this planner attempt")
        with open(source, "rb") as src: raw = src.read(MAX_PLAN_ARTIFACT_BYTES + 1)
        after = os.stat(source, follow_symlinks=False)
    except OSError as exc:
        raise ControllerError("planner artifact source is unreadable") from exc
    if len(raw) > MAX_PLAN_ARTIFACT_BYTES or (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise ControllerError("planner artifact changed while being ingested")
    provider = file_info(os.path.join(directory, "packets", str(attempt["id"]) + ".json"), os.path.join(directory, "packets"))
    if not provider:
        raise ControllerError("planner source requires a controller-owned structured provider packet")
    try:
        provider_packet = json.loads(Path(provider["path"]).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("planner provider packet is unreadable") from exc
    structured = provider_packet.get("structured") if isinstance(provider_packet, dict) else None
    if (provider_packet.get("attempt_id") != attempt.get("id") or provider_packet.get("work_id") != state["work_id"] or provider_packet.get("provider_session_id") != attempt.get("provider_session_id") or
            not isinstance(structured, dict) or structured.get("outcome") != "completed" or
            source not in structured.get("changed_paths", [])):
        raise ControllerError("planner source is not an exact changed path from this controller-owned planner attempt")
    plan = _extract_one_json_object(raw); _validate_m0c_plan(plan, state)
    packets = os.path.join(directory, "packets"); os.makedirs(packets, mode=0o700, exist_ok=True)
    raw_path = os.path.join(packets, str(attempt["id"]) + ".planner-artifact.md")
    existing = file_info(raw_path, packets)
    if existing and existing["sha256"] != digest_bytes(raw):
        raise ControllerError("planner artifact replay conflicts with controller-owned copy")
    if not existing:
        fd, temporary = tempfile.mkstemp(prefix=".tmp-", dir=packets)
        try:
            with os.fdopen(fd, "wb") as out: out.write(raw); out.flush(); os.fsync(out.fileno())
            os.replace(temporary, raw_path)
        finally:
            try: os.unlink(temporary)
            except FileNotFoundError: pass
    plan_path = os.path.join(packets, str(attempt["id"]) + ".plan.json")
    declared_package_id = _plan_declared_package_id(state)
    plan_packet = {"schema_version": SCHEMA, "kind": "m0c_planner_plan", "work_id": state["work_id"],
                   "declared_package_id": declared_package_id, "attempt_id": attempt["id"],
                   "source_artifact_sha256": digest_bytes(raw), "provider_packet_sha256": provider["sha256"],
                   "source_path": source, "source_snapshot_sha256": digest_bytes(raw), "plan": plan, "ingested_at": utc()}
    prior = file_info(plan_path, packets)
    if prior:
        try: existing_plan = json.loads(Path(plan_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc: raise ControllerError("controller-owned plan packet is unreadable") from exc
        if existing_plan.get("source_artifact_sha256") != plan_packet["source_artifact_sha256"] or existing_plan.get("plan") != plan:
            raise ControllerError("planner plan replay conflicts with controller-owned packet")
    else:
        atomic_json(plan_path, plan_packet)
    info = file_info(plan_path, packets)
    if not info: raise ControllerError("controller-owned plan packet was not written")
    packet_ref = {"path": plan_path, "sha256": info["sha256"]}
    prior_artifact = state.get("planner_artifact") if isinstance(state.get("planner_artifact"), dict) else {}
    prior_candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
    if (prior_artifact.get("source_root") == source_root and prior_artifact.get("plan_sha256") == info["sha256"] and
            (prior_candidate.get("evidence") or {}).get("packet_sha256") == info["sha256"] and state.get("phase") == "awaiting_gate"):
        return {"schema_version": SCHEMA, "operation": "ingest_plan_artifact", "phase": "awaiting_gate", "reused": True,
                "plan_packet": packet_ref, "candidate_id": prior_candidate.get("id"),
                "package_identity": {"controller_work_id": state["work_id"], "declared_package_id": declared_package_id}}
    candidate = _plan_candidate(packet_ref, state)
    state["candidate"] = candidate; state["escalation"] = None; state["phase"] = "awaiting_gate"
    state["planner_artifact"] = {"source_root": source_root, "source_artifact_sha256": digest_bytes(raw),
                                 "raw_path": raw_path, "raw_sha256": digest_bytes(raw), "plan_path": plan_path,
                                 "plan_sha256": info["sha256"], "attempt_id": attempt["id"],
                                 "provider_packet_sha256": provider["sha256"], "source_path": source,
                                 "source_snapshot_sha256": digest_bytes(raw), "declared_package_id": declared_package_id, "controller_work_id": state["work_id"]}
    state["gate"] = {"kind": "m0c_plan_evidence", "verdict": "awaiting_adjudication", "candidate_id": candidate["id"],
                     "evidence_digest": candidate["evidence_digest"], "plan_sha256": info["sha256"], "policy": POLICY_ID, "at": utc()}
    append_event(directory, "plan_artifact_ingested", attempt_id=attempt["id"], candidate_id=candidate["id"],
                 evidence_digest=candidate["evidence_digest"], plan_sha256=info["sha256"], declared_package_id=declared_package_id)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "ingest_plan_artifact", "phase": "awaiting_gate",
            "plan_packet": {"path": plan_path, "sha256": info["sha256"]}, "candidate_id": candidate["id"],
            "package_identity": {"controller_work_id": state["work_id"], "declared_package_id": declared_package_id}}


def _capacity_candidate_ready(directory: str, state: Dict[str, Any], require_lease: bool = False) -> Dict[str, Any]:
    if state.get("phase") != CAPACITY_WAITING:
        raise ControllerError("package is not awaiting capacity")
    capacity = state.get("capacity") if isinstance(state.get("capacity"), dict) else {}
    manual = capacity.get("mode") == "manual_signal"
    required = (("path", "sha256", "provider", "candidate_id", "evidence_digest", "role", "provider_session_id") if manual else
                ("path", "sha256", "retry_after", "reset_source", "reset_evidence_digest", "provider", "candidate_id", "evidence_digest", "role", "provider_session_id"))
    if any(not isinstance(capacity.get(key), str) or not capacity[key] for key in required):
        raise ControllerError("capacity state is incomplete")
    info = file_info(capacity["path"], os.path.join(directory, "packets"))
    if not info or info.get("sha256") != capacity["sha256"]:
        raise ControllerError("capacity packet binding no longer matches")
    try:
        with open(capacity["path"], encoding="utf-8") as src:
            packet = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("capacity packet is unreadable") from exc
    packet_keys = (("failure_class", "provider", "role", "provider_session_id") if manual else
                   ("failure_class", "retry_after", "reset_source", "reset_evidence_digest", "provider", "role", "provider_session_id"))
    for key in packet_keys:
        if packet.get(key) != capacity.get(key):
            raise ControllerError("capacity packet fields no longer match state")
    invocation = packet.get("invocation") if isinstance(packet.get("invocation"), dict) else {}
    if (invocation.get("backend") != "claude_direct" or invocation.get("provider") != "claude" or
            invocation.get("controller") != "claude" or invocation.get("policy") != POLICY_ID or
            packet.get("policy_digest") != digest_bytes(POLICY_ID.encode())):
        raise ControllerError("capacity invocation identity no longer matches policy")
    candidate = state.get("candidate") or {}
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    if candidate.get("id") != capacity["candidate_id"] or candidate.get("evidence_digest") != capacity["evidence_digest"] or not candidate_intact(candidate, directory, state["worktree"]["path"]):
        raise ControllerError("capacity candidate binding no longer matches")
    if require_lease:
        if manual:
            raise ControllerError("manual capacity waits require an explicit human capacity signal")
        receipt_path = capacity.get("wakeup_receipt_path"); receipt_sha = capacity.get("wakeup_receipt_sha256")
        lease_id = capacity.get("lease_id"); wakeup_ref = capacity.get("wakeup_ref")
        if not all(isinstance(x, str) and x for x in (receipt_path, receipt_sha, lease_id, wakeup_ref)):
            raise ControllerError("capacity wake lease is required before release")
        receipt_info = file_info(receipt_path, os.path.join(directory, "capacity-wakeups"))
        if not receipt_info or receipt_info.get("sha256") != receipt_sha:
            raise ControllerError("capacity wake receipt binding no longer matches")
        try:
            with open(receipt_path, encoding="utf-8") as src: receipt = json.load(src)
        except (OSError, json.JSONDecodeError) as exc:
            raise ControllerError("capacity wake receipt is unreadable") from exc
        expected = capacity_wake_expected(state, capacity, candidate, packet, lease_id, wakeup_ref)
        if not isinstance(receipt, dict) or receipt.get("kind") != "capacity_wakeup_lease" or any(receipt.get(k) != v for k, v in expected.items()):
            raise ControllerError("capacity wake receipt fields no longer match durable evidence")
    return capacity


def _command_ingest_plan_review(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if state.get("phase") != "awaiting_gate" or (state.get("gate") or {}).get("kind") != "m0c_plan_evidence":
        raise ControllerError("plan review requires an awaiting M0-C plan gate")
    candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
    artifact = state.get("planner_artifact") if isinstance(state.get("planner_artifact"), dict) else {}
    review_attempt = state.get("plan_review_attempt") if isinstance(state.get("plan_review_attempt"), dict) else {}
    if not review_attempt or review_attempt.get("consumed_at") or process_alive(review_attempt.get("pid"), review_attempt.get("pgid")):
        raise ControllerError("plan review requires a quiescent controller-launched review attempt")
    receipt = file_info(review_attempt.get("receipt_path"), os.path.join(directory, "review-attempts")) if isinstance(review_attempt.get("receipt_path"), str) else None
    if not receipt or (review_attempt.get("receipt_sha256") and receipt.get("sha256") != review_attempt.get("receipt_sha256")):
        raise ControllerError("plan review terminal receipt is missing or changed")
    try: terminal = json.loads(Path(receipt["path"]).read_text())
    except (OSError, json.JSONDecodeError) as exc: raise ControllerError("plan review terminal receipt is unreadable") from exc
    expected = {"schema_version":SCHEMA,"kind":"codex_plan_review_terminal","attempt_id":review_attempt.get("id"),"argv_digest":review_attempt.get("argv_digest"),"nonce":review_attempt.get("nonce")}
    if any(terminal.get(k) != v for k,v in expected.items()) or terminal.get("exit_code") != 0 or terminal.get("output_path") != review_attempt.get("output_path"):
        raise ControllerError("plan review terminal receipt failed strict binding validation")
    for label in ("stdout", "stderr"):
        item = capped_regular_file_info(review_attempt.get(label), os.path.join(directory, "logs"), MAX_PLAN_ARTIFACT_BYTES)
        if (not item or terminal.get(label + "_sha256") != item.get("sha256") or terminal.get(label + "_bytes") != item.get("bytes")):
            raise ControllerError("plan review terminal log binding no longer matches")
    source = require_regular(review_attempt.get("output_path"))
    raw = Path(source).read_bytes()
    if terminal.get("output_sha256") != digest_bytes(raw): raise ControllerError("plan review output no longer matches terminal receipt")
    if len(raw) > 64 * 1024: raise ControllerError("plan review exceeds bounded size")
    try: packet = json.loads(raw)
    except json.JSONDecodeError as exc: raise ControllerError("plan review must be JSON") from exc
    v2 = state.get("work_id") in {M0C_V2_WORK_ID, M0C_V3_WORK_ID}
    required = {"schema_version", "kind", "work_id", "attempt_id", "backend", "actor_id", "run_id", "review_nonce", "plan_sha256", "candidate_id", "verdict", "findings", "checks"}
    required.add("prerequisite_evidence_digests" if v2 else "upstream_evidence_digest")
    if (not isinstance(packet, dict) or set(packet) != required or packet.get("schema_version") != SCHEMA or
            packet.get("kind") != "m0c_plan_review" or packet.get("work_id") != state["work_id"] or
            packet.get("attempt_id") != artifact.get("attempt_id") or packet.get("backend") != ALTERNATE_BACKEND or
            not _safe_identifier(packet.get("actor_id"), "review actor id") or not _safe_identifier(packet.get("run_id"), "review run id") or
            packet.get("actor_id") != review_attempt.get("actor_id") or packet.get("run_id") != review_attempt.get("run_id") or packet.get("review_nonce") != review_attempt.get("nonce") or
            packet.get("actor_id") == "claude" or packet.get("plan_sha256") != artifact.get("plan_sha256") or
            (packet.get("prerequisite_evidence_digests") != [M0B_EVIDENCE_DIGEST, M0C0_EVIDENCE_DIGEST] if v2 else packet.get("upstream_evidence_digest") != M0B_EVIDENCE_DIGEST) or packet.get("candidate_id") != candidate.get("id") or
            packet.get("verdict") not in {"pass", "fail"} or not isinstance(packet.get("findings"), list) or not isinstance(packet.get("checks"), list) or
            len(packet["findings"]) > 20 or len(packet["checks"]) > 20):
        raise ControllerError("independent plan review packet failed strict binding validation")
    prior = state.get("plan_review") if isinstance(state.get("plan_review"), dict) else None
    if prior and (prior.get("sha256") != digest_bytes(raw) or prior.get("actor_id") != packet["actor_id"] or prior.get("run_id") != packet["run_id"]):
        raise ControllerError("plan review replay conflicts with controller-owned copy")
    destination = os.path.join(directory, "packets", str(artifact["attempt_id"]) + ".plan-review.json")
    if not prior:
        existing = file_info(destination, os.path.join(directory, "packets"))
        if existing and existing.get("sha256") != digest_bytes(raw):
            raise ControllerError("plan review recovery copy conflicts with controller-owned bytes")
        if existing:
            prior = {"sha256": existing["sha256"], "actor_id": packet["actor_id"], "run_id": packet["run_id"]}
        else:
        # Preserve the exact provider output bytes: the terminal wrapper receipt
        # binds this raw hash, while JSON parsing above supplies schema safety.
            fd, temporary = tempfile.mkstemp(prefix=".tmp-", dir=os.path.dirname(destination))
            try:
                with os.fdopen(fd, "wb") as out: out.write(raw); out.flush(); os.fsync(out.fileno())
                os.replace(temporary, destination)
            finally:
                try: os.unlink(temporary)
                except FileNotFoundError: pass
    info = file_info(destination, os.path.join(directory, "packets"))
    if not info or info["sha256"] != digest_bytes(raw): raise ControllerError("controller-owned plan review copy is invalid")
    state["plan_review"] = {"path": destination, "sha256": info["sha256"], "actor_id": packet["actor_id"], "run_id": packet["run_id"], "verdict": packet["verdict"], "plan_sha256": packet["plan_sha256"], "candidate_id": packet["candidate_id"]}
    review_attempt["consumed_at"] = utc(); review_attempt["packet_sha256"] = info["sha256"]; review_attempt["receipt_sha256"] = receipt["sha256"]
    append_event(directory, "plan_review_ingested", candidate_id=candidate["id"], packet_sha256=info["sha256"], actor_id=packet["actor_id"], run_id=packet["run_id"])
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "ingest_plan_review", "phase": state["phase"], "review_verdict": packet["verdict"], "packet_sha256": info["sha256"]}


def _plan_review_schema(state: Dict[str, Any], artifact: Dict[str, Any], candidate: Dict[str, Any],
                        actor: str, run: str, nonce: str) -> Dict[str, Any]:
    modern = state.get("work_id") in {M0C_V2_WORK_ID, M0C_V3_WORK_ID}
    evidence_key = "prerequisite_evidence_digests" if modern else "upstream_evidence_digest"
    evidence_schema = ({"type":"array","minItems":2,"maxItems":2,"items":{"type":"string"}} if modern else
                       {"type":"string","const":M0B_EVIDENCE_DIGEST})
    return {"type":"object","additionalProperties":False,"required":["schema_version","kind","work_id","attempt_id","backend","actor_id","run_id","review_nonce","plan_sha256",evidence_key,"candidate_id","verdict","findings","checks"],"properties":{
        "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"m0c_plan_review"},"work_id":{"type":"string","const":state["work_id"]},"attempt_id":{"type":"string","const":artifact.get("attempt_id")},"backend":{"type":"string","const":"codex_terra"},"actor_id":{"type":"string","const":actor},"run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"plan_sha256":{"type":"string","const":artifact.get("plan_sha256")},evidence_key:evidence_schema,"candidate_id":{"type":"string","const":candidate.get("id")},"verdict":{"type":"string","enum":["pass","fail"]},"findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},"checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}}}}


def _command_launch_plan_review(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if state.get("phase") != "awaiting_gate" or (state.get("gate") or {}).get("kind") != "m0c_plan_evidence":
        raise ControllerError("review launch requires an awaiting M0-C plan gate")
    artifact = state.get("planner_artifact") or {}; candidate = state.get("candidate") or {}
    _validate_m0c_plan(json.loads(Path(artifact["plan_path"]).read_text())["plan"], state)
    actor = "codex_terra_controller_v1"; run = str(uuid.uuid4())
    existing = state.get("plan_review_attempt") if isinstance(state.get("plan_review_attempt"), dict) else None
    if existing:
        raise ControllerError("independent review attempt already exists")
    review_dir = os.path.join(directory, "review-attempts"); os.makedirs(review_dir, mode=0o700, exist_ok=True)
    attempt_id = str(uuid.uuid4()); nonce = uuid.uuid4().hex; schema_path = os.path.join(review_dir, attempt_id + ".schema.json"); output_path = os.path.join(review_dir, attempt_id + ".output.json")
    v2 = state.get("work_id") in {M0C_V2_WORK_ID, M0C_V3_WORK_ID}
    schema = _plan_review_schema(state, artifact, candidate, actor, run, nonce)
    atomic_json(schema_path, schema)
    evidence = "prerequisite_evidence_digests=%s" % json.dumps([M0B_EVIDENCE_DIGEST, M0C0_EVIDENCE_DIGEST]) if v2 else "upstream_evidence_digest=%s" % M0B_EVIDENCE_DIGEST
    upstream = [os.path.join(os.path.dirname(directory), M0B_WORK_ID, "state.json"), os.path.join(os.path.dirname(directory), M0C0_WORK_ID, "state.json")] if v2 else [os.path.join(os.path.dirname(directory), M0B_WORK_ID, "state.json")]
    prompt = "Read-only independent M0-C review. Return only schema JSON and echo exactly: work_id=%s planner_attempt_id=%s review_attempt_id=%s actor_id=%s run_id=%s nonce=%s plan_sha256=%s candidate_id=%s %s. Read plan=%s and upstream controller evidence=%s." % (state["work_id"],artifact.get("attempt_id"),attempt_id,actor,run,nonce,artifact.get("plan_sha256"),candidate.get("id"),evidence,artifact["plan_path"],json.dumps(upstream))
    if len(prompt.encode()) > MAX_INSTRUCTION: raise ControllerError("review prompt exceeds bound")
    logs = os.path.join(directory, "logs"); os.makedirs(logs, mode=0o700, exist_ok=True); stdout=os.path.join(logs,attempt_id+".terra.stdout.log"); stderr=os.path.join(logs,attempt_id+".terra.stderr.log")
    codex_argv=[resolve_executable(args.codex_bin),"exec","--json","--model","gpt-5.6-terra","-c","model_reasoning_effort=\"medium\"","--sandbox","read-only","--cd",state["worktree"]["path"],"--output-schema",schema_path,"--output-last-message",output_path,prompt]
    digest=digest_bytes(json.dumps(codex_argv).encode()); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    argv=[sys.executable,os.path.abspath(__file__),"review-wrapper","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(codex_argv)]
    state["plan_review_attempt"] = {"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":utc(),"plan_sha256":artifact.get("plan_sha256"),"candidate_id":candidate.get("id"),"output_path":output_path,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"pid":None,"pgid":None,"consumed_at":None,"argv_digest":digest,"backend":"codex_terra"}
    save(directory,state)
    append_event(directory,"plan_review_starting",attempt_id=attempt_id)
    try: pid,pgid=detached_spawn(argv,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["plan_review_attempt"]["spawn_error"]=type(exc).__name__; state["plan_review_attempt"]["terminal_at"]=utc(); append_event(directory,"plan_review_spawn_failed",attempt_id=attempt_id); save(directory,state)
        raise ControllerError("review controller spawn failed") from exc
    state["plan_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"plan_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_plan_review","phase":state["phase"],"attempt_id":attempt_id,"run_id":run}


def _command_verify_m0b(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if state["work_id"] != M0B_WORK_ID or state.get("phase") != "completed": raise ControllerError("verify-m0b only accepts completed authoritative M0-B")
    candidate=state.get("candidate") or {}
    if candidate.get("id") != M0B_CANDIDATE_ID or candidate.get("evidence_digest") != M0B_EVIDENCE_DIGEST or not candidate_intact(candidate,directory,state["worktree"]["path"]): raise ControllerError("authoritative M0-B candidate binding no longer matches")
    receipts=state.get("verification_receipts") if isinstance(state.get("verification_receipts"),list) else []
    if receipts:
        if not _m0b_verification_receipts_valid(state, directory, candidate):
            raise ControllerError("existing M0-B verification receipts are malformed, incomplete, or changed")
        return {"schema_version":SCHEMA,"operation":"verify_m0b","reused":True,"receipts":receipts}
    root=state["worktree"]["path"]; out=[]; receipt_dir=os.path.join(directory,"receipts")
    # A prior verifier can time out after creating its owned receipt directory
    # but before publishing any receipt or state.  That empty directory is the
    # sole safe crash-recovery case.  Do not overwrite, adopt, or ignore any
    # other filesystem state while the state record has no receipt binding.
    try:
        if os.path.lexists(receipt_dir):
            if os.path.islink(receipt_dir) or not os.path.isdir(receipt_dir):
                raise ControllerError("M0-B verification receipt directory is unsafe")
            with os.scandir(receipt_dir) as entries:
                if any(True for _ in entries):
                    raise ControllerError("orphan M0-B verification receipts prevent recovery")
        else:
            os.makedirs(receipt_dir, mode=0o700, exist_ok=True)
        if os.path.islink(receipt_dir) or not os.path.isdir(receipt_dir):
            raise ControllerError("M0-B verification receipt directory is unsafe")
        with os.scandir(receipt_dir) as entries:
            if any(True for _ in entries):
                raise ControllerError("orphan M0-B verification receipts prevent recovery")
    except OSError as exc:
        raise ControllerError("M0-B verification receipt directory is unreadable") from exc
    pending=[]
    binding_before = _m0b_candidate_binding(candidate, root)
    for idx, spec in enumerate(_M0B_VERIFICATION_SPECS):
        argv = spec["argv"]
        try:
            proc=subprocess.run(argv,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=120)
        except subprocess.TimeoutExpired as exc:
            # Do not publish any partial receipt state; bounded error only.
            raise ControllerError("M0-B deterministic verification command timed out") from exc
        if proc.returncode != spec["expected_exit_code"]:
            raise ControllerError("M0-B deterministic verification command had an unexpected exit status")
        counters = _m0b_parse_verification_output(spec["classification"], proc.stdout)
        if counters is None:
            raise ControllerError("M0-B deterministic verification output did not match its exact bounded claim")
        if not candidate_intact(candidate, directory, root) or _m0b_candidate_binding(candidate, root) != binding_before:
            raise ControllerError("authoritative M0-B candidate changed during verification")
        pending.append((idx, spec, proc.stdout, counters))
    for idx, spec, stdout, counters in pending:
        binding_after = _m0b_candidate_binding(candidate, root)
        payload={"argv":spec["argv"],"cwd":root,"timeout_seconds":120,"expected_exit_code":spec["expected_exit_code"],
                 "actual_exit_code":spec["expected_exit_code"],"output_sha256":digest_bytes(stdout),"classification":spec["classification"],
                 "parsed_counters":counters,"candidate_binding_before":binding_before,"candidate_binding_after":binding_after}
        path=os.path.join(receipt_dir,str(idx)+".json"); atomic_json(path,payload)
        info=file_info(path,receipt_dir); out.append({"path":path,"sha256":info["sha256"],**payload})
    if not candidate_intact(candidate, directory, root) or _m0b_candidate_binding(candidate, root) != binding_before:
        raise ControllerError("authoritative M0-B candidate changed during verification")
    state["verification_receipts"]=out
    state["verification_disposition"]="known_baseline_failure"
    alternate = state.get("alternate_evidence") if isinstance(state.get("alternate_evidence"),dict) else {}
    state["historical_worker_assertions"]={"provenance":"historical_worker_assertion",
        "result": alternate.get("result"), "review": alternate.get("review")}
    append_event(directory,"m0b_verified",candidate_id=candidate["id"],verification_disposition="known_baseline_failure"); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_m0b","reused":False,"receipts":out}


def _historical_m0b_receipt(path: str, root: str) -> Optional[Dict[str, Any]]:
    """Validate a bounded legacy or scoped receipt shape, never its binding."""
    info = capped_regular_file_info(path, root, MAX_OUTPUT)
    if not info:
        return None
    try:
        payload = json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    argv = payload.get("argv") if isinstance(payload, dict) else None
    legacy = (isinstance(payload, dict) and set(payload) == {"argv", "cwd", "exit_code", "output_sha256"} and
              isinstance(argv, list) and bool(argv) and len(argv) <= 20 and
              all(isinstance(value, str) and bool(value) and len(value.encode()) <= 1024 for value in argv) and
              isinstance(payload.get("cwd"), str) and os.path.isabs(payload["cwd"]) and len(payload["cwd"].encode()) <= 4096 and
              not isinstance(payload.get("exit_code"), bool) and isinstance(payload.get("exit_code"), int) and
              _sha256_hex(payload.get("output_sha256")))
    if legacy:
        return info
    scoped_keys = {"argv", "cwd", "timeout_seconds", "expected_exit_code", "actual_exit_code", "output_sha256",
                   "classification", "parsed_counters", "candidate_binding_before", "candidate_binding_after"}
    if not isinstance(payload, dict) or set(payload) != scoped_keys:
        return None
    matching_specs = [spec for spec in _M0B_VERIFICATION_SPECS if payload.get("argv") == spec["argv"] and
                      payload.get("classification") == spec["classification"] and
                      payload.get("expected_exit_code") == spec["expected_exit_code"] and
                      payload.get("actual_exit_code") == spec["expected_exit_code"]]
    expected_counters = ({"ran": 32, "failures": 0, "errors": 0, "expected_failures": 3, "unexpected_successes": 0}
                         if payload.get("classification") == "candidate_characterization_pass" else
                         {"ran": 4, "failures": 1, "errors": 0, "expected_failures": 0, "unexpected_successes": 0})
    binding = payload.get("candidate_binding_before")
    if (len(matching_specs) != 1 or payload.get("timeout_seconds") != 120 or
            not isinstance(argv, list) or not argv or len(argv) > 20 or
            any(not isinstance(value, str) or not value or len(value.encode()) > 1024 for value in argv) or
            not isinstance(payload.get("cwd"), str) or not os.path.isabs(payload["cwd"]) or len(payload["cwd"].encode()) > 4096 or
            not _sha256_hex(payload.get("output_sha256")) or payload.get("parsed_counters") != expected_counters or
            not isinstance(binding, dict) or set(binding) != {"candidate_id", "evidence_digest", "worktree", "worktree_fingerprint_digest"} or
            binding != payload.get("candidate_binding_after") or not isinstance(binding.get("candidate_id"), str) or
            not _sha256_hex(binding.get("evidence_digest")) or not isinstance(binding.get("worktree"), str) or
            not os.path.isabs(binding["worktree"]) or not _sha256_hex(binding.get("worktree_fingerprint_digest"))):
        return None
    return info


def _prior_m0b_quarantine(directory: str) -> Optional[Dict[str, Any]]:
    """Return the one recoverable manifest; reject ambiguous crash debris."""
    root = os.path.join(directory, "receipts-quarantine")
    if not os.path.lexists(root):
        return None
    if os.path.islink(root) or not os.path.isdir(root):
        raise ControllerError("M0-B verification quarantine directory is unsafe")
    manifests = []
    try:
        with os.scandir(root) as entries:
            children = list(entries)
    except OSError as exc:
        raise ControllerError("M0-B verification quarantine directory is unreadable") from exc
    if len(children) > 2:
        raise ControllerError("M0-B verification quarantine exceeds bounded repair history")
    for entry in children:
        if (not re.fullmatch(r"[0-9a-f-]{36}", entry.name) or entry.is_symlink() or
                not entry.is_dir(follow_symlinks=False)):
            raise ControllerError("M0-B verification quarantine contains an unsafe entry")
        repair_dir = os.path.join(root, entry.name)
        try:
            names = {child.name for child in os.scandir(repair_dir)}
        except OSError as exc:
            raise ControllerError("M0-B verification quarantine repair is unreadable") from exc
        if "manifest.json" not in names or names - {"manifest.json", "0.json", "1.json"}:
            raise ControllerError("M0-B verification quarantine repair is incomplete")
        manifest = capped_regular_file_info(os.path.join(repair_dir, "manifest.json"), repair_dir, MAX_OUTPUT)
        if not manifest:
            raise ControllerError("M0-B verification quarantine manifest is unsafe")
        try:
            payload = json.loads(Path(manifest["path"]).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ControllerError("M0-B verification quarantine manifest is unreadable") from exc
        required = {"schema_version", "kind", "package_id", "repair_id", "created_at", "reason", "count", "receipts"}
        receipts = payload.get("receipts") if isinstance(payload, dict) else None
        if (not isinstance(payload, dict) or set(payload) != required or payload.get("schema_version") != SCHEMA or
                payload.get("kind") != "m0b_verification_orphan_quarantine" or payload.get("package_id") != M0B_WORK_ID or
                payload.get("repair_id") != entry.name or not isinstance(payload.get("created_at"), str) or
                payload.get("reason") != "unbound_historical_verifier_receipt" or not isinstance(payload.get("count"), int) or
                not isinstance(receipts, list) or payload["count"] != len(receipts) or not receipts or len(receipts) > 2):
            raise ControllerError("M0-B verification quarantine manifest is malformed")
        expected_names = set()
        for receipt in receipts:
            name = receipt.get("original_name") if isinstance(receipt, dict) else None
            if (not isinstance(receipt, dict) or set(receipt) != {"original_path", "original_name", "sha256", "reason"} or
                    not isinstance(receipt.get("original_path"), str) or name not in {"0.json", "1.json"} or
                    receipt["original_path"] != os.path.join(directory, "receipts", name) or not _sha256_hex(receipt.get("sha256")) or
                    receipt.get("reason") != "unbound_historical_verifier_receipt"):
                raise ControllerError("M0-B verification quarantine manifest receipt is malformed")
            if name in expected_names:
                raise ControllerError("M0-B verification quarantine manifest duplicates a receipt")
            expected_names.add(name)
            moved = capped_regular_file_info(os.path.join(repair_dir, name), repair_dir, MAX_OUTPUT)
            if not moved or moved["sha256"] != receipt["sha256"] or not _historical_m0b_receipt(moved["path"], repair_dir):
                raise ControllerError("M0-B verification quarantine receipt is unsafe")
        if names != expected_names | {"manifest.json"}:
            raise ControllerError("M0-B verification quarantine contents do not match manifest")
        manifests.append({"repair_id": entry.name, "manifest": manifest, "count": len(receipts)})
    if len(manifests) > 1:
        raise ControllerError("M0-B verification quarantine has ambiguous prior repairs")
    return manifests[0] if manifests else None


def _m0b_quarantine_intent(directory: str, state: Dict[str, Any], candidate: Dict[str, Any]) -> Optional[Tuple[str, Dict[str, Any], Dict[str, Any]]]:
    root = os.path.join(directory, "receipts-quarantine-intents")
    if not os.path.lexists(root):
        return None
    if os.path.islink(root) or not os.path.isdir(root):
        raise ControllerError("M0-B verification quarantine intent directory is unsafe")
    try:
        children = list(os.scandir(root))
    except OSError as exc:
        raise ControllerError("M0-B verification quarantine intent directory is unreadable") from exc
    if len(children) != 1 or children[0].is_symlink() or not children[0].is_file(follow_symlinks=False) or not re.fullmatch(r"[0-9a-f-]{36}\.json", children[0].name):
        raise ControllerError("M0-B verification quarantine intent is ambiguous or unsafe")
    info = capped_regular_file_info(children[0].path, root, MAX_OUTPUT)
    if not info:
        raise ControllerError("M0-B verification quarantine intent is unsafe")
    try:
        intent = json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ControllerError("M0-B verification quarantine intent is unreadable") from exc
    repair_id = children[0].name[:-5]; receipts = intent.get("receipts") if isinstance(intent, dict) else None
    required = {"schema_version", "kind", "package_id", "repair_id", "created_at", "candidate_id", "evidence_digest", "reason", "receipts", "applied_at"}
    if (not isinstance(intent, dict) or set(intent) != required or intent.get("schema_version") != SCHEMA or
            intent.get("kind") != "m0b_verification_orphan_quarantine_intent" or intent.get("package_id") != M0B_WORK_ID or
            intent.get("repair_id") != repair_id or not isinstance(intent.get("created_at"), str) or
            intent.get("candidate_id") != candidate.get("id") or intent.get("evidence_digest") != candidate.get("evidence_digest") or
            intent.get("reason") != "unbound_historical_verifier_receipt" or intent.get("applied_at") not in {None} and not isinstance(intent.get("applied_at"), str) or
            not isinstance(receipts, list) or not receipts or len(receipts) > 2):
        raise ControllerError("M0-B verification quarantine intent is malformed")
    names = set(); receipt_root = os.path.join(directory, "receipts"); repair_dir = os.path.join(directory, "receipts-quarantine", repair_id)
    for receipt in receipts:
        name = receipt.get("source_name") if isinstance(receipt, dict) else None
        if (not isinstance(receipt, dict) or set(receipt) != {"source_path", "source_name", "source_sha256", "source_bytes", "destination_path"} or
                name not in {"0.json", "1.json"} or name in names or receipt.get("source_path") != os.path.join(receipt_root, name) or
                receipt.get("destination_path") != os.path.join(repair_dir, name) or not _sha256_hex(receipt.get("source_sha256")) or
                isinstance(receipt.get("source_bytes"), bool) or not isinstance(receipt.get("source_bytes"), int) or receipt["source_bytes"] < 1 or receipt["source_bytes"] > MAX_OUTPUT):
            raise ControllerError("M0-B verification quarantine intent receipt is malformed")
        names.add(name)
    return info["path"], info, intent


def _quarantine_result(repair_id: str, manifest: Dict[str, Any], reused: bool) -> Dict[str, Any]:
    return {"schema_version": SCHEMA, "operation": "quarantine_m0b_verification_orphans", "reused": reused,
            "repair_id": repair_id, "manifest": {"path": manifest["path"], "sha256": manifest["sha256"]}, "count": manifest["count"]}


def _recover_m0b_quarantine_intent(directory: str, intent_path: str, intent: Dict[str, Any]) -> Dict[str, Any]:
    repair_id = intent["repair_id"]; receipt_dir = os.path.join(directory, "receipts"); repair_dir = os.path.join(directory, "receipts-quarantine", repair_id)
    root = os.path.dirname(repair_dir)
    if os.path.lexists(root) and (os.path.islink(root) or not os.path.isdir(root)):
        raise ControllerError("M0-B verification quarantine directory is unsafe")
    os.makedirs(root, mode=0o700, exist_ok=True)
    try:
        siblings = list(os.scandir(root))
    except OSError as exc:
        raise ControllerError("M0-B verification quarantine directory is unreadable") from exc
    if any(entry.name != repair_id or entry.is_symlink() or not entry.is_dir(follow_symlinks=False) for entry in siblings):
        raise ControllerError("M0-B verification quarantine recovery has unexpected sibling entries")
    if os.path.lexists(repair_dir) and (os.path.islink(repair_dir) or not os.path.isdir(repair_dir)):
        raise ControllerError("M0-B verification quarantine repair is unsafe")
    os.makedirs(repair_dir, mode=0o700, exist_ok=True)
    expected = {row["source_name"]: row for row in intent["receipts"]}
    try:
        source_names = {entry.name for entry in os.scandir(receipt_dir)}
        destination_names = {entry.name for entry in os.scandir(repair_dir)}
    except OSError as exc:
        raise ControllerError("M0-B verification quarantine recovery is unreadable") from exc
    if source_names - set(expected) or destination_names - (set(expected) | {"manifest.json"}):
        raise ControllerError("M0-B verification quarantine recovery contains unexpected entries")
    for name, row in expected.items():
        source = row["source_path"]; destination = row["destination_path"]
        source_info = capped_regular_file_info(source, receipt_dir, MAX_OUTPUT) if os.path.lexists(source) else None
        destination_info = capped_regular_file_info(destination, repair_dir, MAX_OUTPUT) if os.path.lexists(destination) else None
        if (os.path.lexists(source) and not source_info) or (os.path.lexists(destination) and not destination_info):
            raise ControllerError("M0-B verification quarantine recovery receipt is unsafe")
        valid_source = source_info and source_info["sha256"] == row["source_sha256"] and source_info["bytes"] == row["source_bytes"] and _historical_m0b_receipt(source_info["path"], receipt_dir)
        valid_destination = destination_info and destination_info["sha256"] == row["source_sha256"] and destination_info["bytes"] == row["source_bytes"] and _historical_m0b_receipt(destination_info["path"], repair_dir)
        if bool(valid_source) == bool(valid_destination):
            raise ControllerError("M0-B verification quarantine recovery receipt location is ambiguous or changed")
        if valid_source:
            os.replace(source, destination)
    manifest_path = os.path.join(repair_dir, "manifest.json")
    records = [{"original_path": row["source_path"], "original_name": row["source_name"], "sha256": row["source_sha256"], "reason": intent["reason"]} for row in intent["receipts"]]
    manifest_value = {"schema_version": SCHEMA, "kind": "m0b_verification_orphan_quarantine", "package_id": M0B_WORK_ID,
                      "repair_id": repair_id, "created_at": intent["created_at"], "reason": intent["reason"], "count": len(records), "receipts": records}
    existing = capped_regular_file_info(manifest_path, repair_dir, MAX_OUTPUT) if os.path.lexists(manifest_path) else None
    if os.path.lexists(manifest_path) and not existing:
        raise ControllerError("M0-B verification quarantine manifest is unsafe")
    if existing:
        try: prior_value = json.loads(Path(existing["path"]).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc: raise ControllerError("M0-B verification quarantine manifest is unreadable") from exc
        if prior_value != manifest_value: raise ControllerError("M0-B verification quarantine manifest conflicts with intent")
    else:
        atomic_json(manifest_path, manifest_value)
        existing = capped_regular_file_info(manifest_path, repair_dir, MAX_OUTPUT)
    if not existing: raise ControllerError("M0-B verification quarantine manifest was not written")
    manifest = {"path": existing["path"], "sha256": existing["sha256"], "count": len(records)}
    if not any(event.get("kind") == "m0b_verification_orphans_quarantined" and event.get("repair_id") == repair_id and event.get("manifest_sha256") == existing["sha256"] for event in recent_events(directory)):
        append_event(directory, "m0b_verification_orphans_quarantined", repair_id=repair_id, manifest_sha256=existing["sha256"], count=len(records))
    if intent.get("applied_at") is None:
        intent["applied_at"] = utc(); atomic_json(intent_path, intent)
    return manifest


def _command_quarantine_m0b_verification_orphans(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if state["work_id"] != M0B_WORK_ID or state.get("phase") != "completed":
        raise ControllerError("quarantine only accepts completed authoritative M0-B")
    if "verification_receipts" in state:
        raise ControllerError("quarantine requires M0-B state with no verification receipts")
    candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
    if (candidate.get("id") != M0B_CANDIDATE_ID or candidate.get("evidence_digest") != M0B_EVIDENCE_DIGEST or
            not candidate_intact(candidate, directory, state["worktree"]["path"])):
        raise ControllerError("authoritative M0-B candidate binding no longer matches")
    receipt_dir = os.path.join(directory, "receipts")
    if os.path.lexists(receipt_dir) and (os.path.islink(receipt_dir) or not os.path.isdir(receipt_dir)):
        raise ControllerError("M0-B verification receipt directory is unsafe")
    if not os.path.exists(receipt_dir):
        os.makedirs(receipt_dir, mode=0o700, exist_ok=True)
    try:
        with os.scandir(receipt_dir) as entries:
            entries = list(entries)
    except OSError as exc:
        raise ControllerError("M0-B verification receipt directory is unreadable") from exc
    pending = _m0b_quarantine_intent(directory, state, candidate)
    if pending:
        intent_path, _intent_info, intent = pending
        manifest = _recover_m0b_quarantine_intent(directory, intent_path, intent)
        return _quarantine_result(intent["repair_id"], manifest, True)
    prior = _prior_m0b_quarantine(directory)
    if not entries:
        if not prior:
            raise ControllerError("M0-B verification receipt directory has no orphan receipts to quarantine")
        if not any(event.get("kind") == "m0b_verification_orphans_quarantined" and event.get("repair_id") == prior["repair_id"] and event.get("manifest_sha256") == prior["manifest"]["sha256"] for event in recent_events(directory)):
            append_event(directory, "m0b_verification_orphans_quarantined", repair_id=prior["repair_id"], manifest_sha256=prior["manifest"]["sha256"], count=prior["count"])
        return _quarantine_result(prior["repair_id"], {"path": prior["manifest"]["path"], "sha256": prior["manifest"]["sha256"], "count": prior["count"]}, True)
    if prior:
        raise ControllerError("M0-B verification receipts conflict with an existing quarantine repair")
    by_name = {entry.name: entry for entry in entries}
    if set(by_name) - {"0.json", "1.json"} or not by_name:
        raise ControllerError("M0-B verification receipt directory contains unexpected orphan entries")
    sources = []
    for name in sorted(by_name):
        entry = by_name[name]
        if entry.is_symlink() or not entry.is_file(follow_symlinks=False):
            raise ControllerError("M0-B verification orphan receipt is unsafe")
        info = _historical_m0b_receipt(os.path.join(receipt_dir, name), receipt_dir)
        if not info:
            raise ControllerError("M0-B verification orphan receipt is malformed")
        sources.append((name, info))
    repair_id = str(uuid.uuid4()); repair_dir = os.path.join(directory, "receipts-quarantine", repair_id)
    intent = {"schema_version": SCHEMA, "kind": "m0b_verification_orphan_quarantine_intent", "package_id": M0B_WORK_ID,
              "repair_id": repair_id, "created_at": utc(), "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
              "reason": "unbound_historical_verifier_receipt", "applied_at": None,
              "receipts": [{"source_path": os.path.join(receipt_dir, name), "source_name": name, "source_sha256": info["sha256"],
                            "source_bytes": info["bytes"], "destination_path": os.path.join(repair_dir, name)} for name, info in sources]}
    intent_dir = os.path.join(directory, "receipts-quarantine-intents"); os.makedirs(intent_dir, mode=0o700, exist_ok=True)
    intent_path = os.path.join(intent_dir, repair_id + ".json"); atomic_json(intent_path, intent)
    manifest = _recover_m0b_quarantine_intent(directory, intent_path, intent)
    return _quarantine_result(repair_id, manifest, False)

def _codex_invalid_json_schema_events(lines: List[str]) -> bool:
    """Recognize only Codex's bounded, nested invalid-schema JSONL envelope."""
    for line in lines:
        try: event=json.loads(line)
        except json.JSONDecodeError: continue
        message=event.get("message") if isinstance(event,dict) else None
        if (event.get("type") not in {"turn.failed","error"} or not isinstance(message,str) or
                not message or len(message.encode())>4096):
            continue
        try: envelope=json.loads(message)
        except json.JSONDecodeError: continue
        error=envelope.get("error") if isinstance(envelope,dict) and isinstance(envelope.get("error"),dict) else {}
        if (envelope.get("type") in {"turn.failed","error"} and error.get("type")=="invalid_request_error" and
                error.get("code")=="invalid_json_schema" and envelope.get("status")==400):
            return True
    return False


def _command_retry_plan_review(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); attempt=state.get("plan_review_attempt") if isinstance(state.get("plan_review_attempt"),dict) else {}
    if not _is_m0c_plan_work(state) or state.get("phase") != "awaiting_gate" or not attempt or process_alive(attempt.get("pid"),attempt.get("pgid")):
        raise ControllerError("plan review retry requires a quiescent M0-C review attempt")
    retries=state.get("plan_review_retries",[])
    if not isinstance(retries,list) or retries: raise ControllerError("plan review retry is bounded to one attempt")
    artifact=state.get("planner_artifact") if isinstance(state.get("planner_artifact"),dict) else {}; candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if (attempt.get("plan_sha256") != artifact.get("plan_sha256") or attempt.get("candidate_id") != candidate.get("id") or
            attempt.get("actor_id") != "codex_terra_controller_v1" or not _safe_identifier(attempt.get("run_id"), "review run_id") or
            not isinstance(attempt.get("nonce"),str) or not attempt["nonce"] or
            not candidate_intact(candidate,directory,state["worktree"]["path"])):
        raise ControllerError("plan review retry candidate, plan, or controller identity is stale")
    plan_item=file_info(artifact.get("plan_path"),os.path.join(directory,"packets")) if isinstance(artifact.get("plan_path"),str) else None
    if (not plan_item or plan_item.get("sha256")!=artifact.get("plan_sha256") or
            plan_item.get("sha256")!=(candidate.get("evidence") or {}).get("packet_sha256")):
        raise ControllerError("plan review retry controller-owned plan packet binding changed")
    try: stored_plan=json.loads(Path(plan_item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("plan review retry controller-owned plan packet is unreadable") from exc
    planner_attempt=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
    if (not isinstance(stored_plan,dict) or stored_plan.get("kind")!="m0c_planner_plan" or
            stored_plan.get("work_id")!=state.get("work_id") or stored_plan.get("attempt_id")!=planner_attempt.get("id") or
            stored_plan.get("declared_package_id")!=_plan_declared_package_id(state)):
        raise ControllerError("plan review retry controller-owned plan packet identity changed")
    _validate_m0c_plan(stored_plan.get("plan"),state)
    schema_path=os.path.join(directory,"review-attempts",str(attempt.get("id"))+".schema.json")
    schema_item=capped_regular_file_info(schema_path,os.path.join(directory,"review-attempts"),64*1024)
    if not schema_item: raise ControllerError("plan review retry controller-owned schema is missing or unsafe")
    try: stored_schema=json.loads(Path(schema_item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("plan review retry controller-owned schema is unreadable") from exc
    expected_schema=_plan_review_schema(state,artifact,candidate,"codex_terra_controller_v1",attempt["run_id"],attempt["nonce"])
    schema_variant="current_supported"
    if stored_schema!=expected_schema:
        legacy_schema=json.loads(json.dumps(expected_schema))
        if "prerequisite_evidence_digests" in legacy_schema.get("properties",{}):
            legacy_schema["properties"]["prerequisite_evidence_digests"]={"type":"array","const":[M0B_EVIDENCE_DIGEST,M0C0_EVIDENCE_DIGEST]}
        if stored_schema==legacy_schema:
            schema_variant="legacy_array_const_rejected"
        else:
            raise ControllerError("plan review retry controller-owned schema binding changed")
    if schema_variant=="legacy_array_const_rejected" and state.get("work_id") not in {M0C_V2_WORK_ID,M0C_V3_WORK_ID}:
        raise ControllerError("plan review retry controller-owned schema binding changed")
    infrastructure_failure=False; retry_evidence={}
    if attempt.get("spawn_error"):
        if schema_variant!="current_supported":
            raise ControllerError("legacy rejected review schema requires typed invalid_json_schema terminal evidence")
        infrastructure_failure = bool(attempt.get("terminal_at")) and attempt.get("pid") is None and attempt.get("pgid") is None
        spawn_class=str(attempt.get("spawn_error"))
        retry_evidence={"disposition":"spawn_failure","terminal_receipt_sha256":None,"exit_code":None,"output_null":True,
                        "spawn_error_class":spawn_class,"spawn_error_sha256":digest_bytes(spawn_class.encode())}
    else:
        receipt=file_info(attempt.get("receipt_path"),os.path.join(directory,"review-attempts")) if isinstance(attempt.get("receipt_path"),str) else None
        if not receipt: raise ControllerError("plan review retry terminal receipt is missing or unsafe")
        try: terminal=json.loads(Path(receipt["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("plan review retry terminal receipt is unreadable") from exc
        expected={"schema_version":SCHEMA,"kind":"codex_plan_review_terminal","attempt_id":attempt.get("id"),"argv_digest":attempt.get("argv_digest"),"nonce":attempt.get("nonce")}
        if any(terminal.get(k)!=v for k,v in expected.items()) or terminal.get("output_path")!=attempt.get("output_path"):
            raise ControllerError("plan review retry terminal receipt binding changed")
        logs={}
        for label in ("stdout","stderr"):
            item=capped_regular_file_info(attempt.get(label),os.path.join(directory,"logs"),MAX_PLAN_ARTIFACT_BYTES)
            if not item or terminal.get(label+"_sha256")!=item.get("sha256") or terminal.get(label+"_bytes")!=item.get("bytes"):
                raise ControllerError("plan review retry terminal log binding changed")
            logs[label]=item
        output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"review-attempts"),64*1024)
        sealed_no_output = terminal.get("output_sha256") is None and isinstance(attempt.get("output_path"),str) and not os.path.lexists(attempt["output_path"])
        exit_code=terminal.get("exit_code")
        if isinstance(exit_code,bool) or not isinstance(exit_code,int) or exit_code==0:
            raise ControllerError("successful plan review attempts cannot be retried")
        if not sealed_no_output:
            raise ControllerError("nonzero plan review with any output is not retryable")
        try: stdout_lines=Path(logs["stdout"]["path"]).read_text(encoding="utf-8").splitlines()
        except (OSError,UnicodeDecodeError) as exc: raise ControllerError("plan review retry stdout is unreadable") from exc
        typed_failure=_codex_invalid_json_schema_events(stdout_lines)
        if not typed_failure:
            raise ControllerError("nonzero plan review is not a typed retryable infrastructure failure")
        infrastructure_failure=True
        retry_evidence={"disposition":"invalid_json_schema","terminal_receipt_sha256":receipt["sha256"],
                        "exit_code":exit_code,"output_null":True,"spawn_error_class":None,"spawn_error_sha256":None}
    retry_evidence["schema_variant"]=schema_variant
    retry_evidence["schema_sha256"]=schema_item["sha256"]
    if not infrastructure_failure: raise ControllerError("plan review retry lacks sealed infrastructure failure evidence")
    state["plan_review_retries"]=[{"at":utc(),"prior_attempt_id":attempt.get("id"),"prior_argv_digest":attempt.get("argv_digest"),"reason":"terminal_or_spawn_failure","evidence":retry_evidence}]
    history=state.get("plan_review_attempt_history") or []
    if not isinstance(history,list): raise ControllerError("plan review attempt history is malformed")
    archived=dict(attempt); archived["retry_evidence"]=retry_evidence
    state["plan_review_attempt_history"]=history+[archived]
    state["plan_review_attempt"]=None; append_event(directory,"plan_review_retry_released",attempt_id=attempt.get("id")); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_plan_review","phase":"awaiting_gate"}


def _command_review_wrapper(args: argparse.Namespace) -> Dict[str, Any]:
    """Private detached runner: no shell, receipt is the only exit authority."""
    try: argv=json.loads(args.codex_argv_json)
    except json.JSONDecodeError as exc: raise ControllerError("wrapper argv is malformed") from exc
    if not isinstance(argv,list) or not argv or any(not isinstance(x,str) for x in argv): raise ControllerError("wrapper argv is malformed")
    if digest_bytes(json.dumps(argv).encode()) != args.argv_digest: raise ControllerError("wrapper argv digest mismatch")
    started=utc(); code=127
    if args.terminal_kind=="claude_package_a_review_terminal":
        run=_bounded_run(argv,os.getcwd(),300,PACKAGE_A_CLAUDE_REVIEW_LOG_CAP); code=run["exit_code"]
        stdout_bytes=run["output"]
        for path,value in ((args.stdout_path,stdout_bytes),(args.stderr_path,b"")):
            with open(path,"wb") as out: out.write(value); out.flush(); os.fsync(out.fileno())
        for line in stdout_bytes.decode("utf-8","replace").splitlines():
            try: event=json.loads(line)
            except json.JSONDecodeError: continue
            if isinstance(event,dict) and event.get("type")=="result" and isinstance(event.get("structured_output"),dict):
                output_dir=os.path.dirname(args.output_path)
                fd,temp=tempfile.mkstemp(prefix=".tmp-",dir=output_dir)
                try:
                    with os.fdopen(fd,"w",encoding="utf-8") as f:
                        json.dump(event["structured_output"],f,sort_keys=True,indent=2); f.write("\n"); f.flush(); os.fsync(f.fileno())
                    os.replace(temp,args.output_path)
                except Exception:
                    with contextlib.suppress(FileNotFoundError): os.unlink(temp)
                break
    elif args.terminal_kind==PACKAGE_C_RR_TERMINAL_KIND:
        run=_bounded_run(argv,os.getcwd(),PACKAGE_C_RR_REVIEW_TIMEOUT,PACKAGE_C_RR_REVIEW_LOG_CAP); code=run["exit_code"]
        stdout_bytes=run["output"]
        for path,value in ((args.stdout_path,stdout_bytes),(args.stderr_path,b"")):
            with open(path,"wb") as out: out.write(value); out.flush(); os.fsync(out.fileno())
        for line in stdout_bytes.decode("utf-8","replace").splitlines():
            try: event=json.loads(line)
            except json.JSONDecodeError: continue
            if isinstance(event,dict) and event.get("type")=="result" and isinstance(event.get("structured_output"),dict):
                output_dir=os.path.dirname(args.output_path)
                fd,temp=tempfile.mkstemp(prefix=".tmp-",dir=output_dir)
                try:
                    with os.fdopen(fd,"w",encoding="utf-8") as f:
                        json.dump(event["structured_output"],f,sort_keys=True,indent=2); f.write("\n"); f.flush(); os.fsync(f.fileno())
                    os.replace(temp,args.output_path)
                except Exception:
                    with contextlib.suppress(FileNotFoundError): os.unlink(temp)
                break
    elif args.terminal_kind=="codex_package_a_review_terminal":
        run=_bounded_run(argv,os.getcwd(),300,MAX_PLAN_ARTIFACT_BYTES); code=run["exit_code"]
        for path,value in ((args.stdout_path,run["output"]),(args.stderr_path,b"")):
            with open(path,"wb") as out: out.write(value); out.flush(); os.fsync(out.fileno())
    else:
        try:
            with open(args.stdout_path,"wb") as out, open(args.stderr_path,"wb") as err:
                code=subprocess.run(argv,stdout=out,stderr=err).returncode
        except OSError: code=127
    output=capped_regular_file_info(args.output_path,os.path.dirname(args.receipt),64*1024) if os.path.lexists(args.output_path) else None
    _log_cap=(PACKAGE_C_RR_REVIEW_LOG_CAP if args.terminal_kind==PACKAGE_C_RR_TERMINAL_KIND else (PACKAGE_A_CLAUDE_REVIEW_LOG_CAP if args.terminal_kind=="claude_package_a_review_terminal" else MAX_PLAN_ARTIFACT_BYTES))
    stdout=capped_regular_file_info(args.stdout_path,os.path.dirname(args.stdout_path),_log_cap)
    stderr=capped_regular_file_info(args.stderr_path,os.path.dirname(args.stderr_path),_log_cap)
    terminal={"schema_version":SCHEMA,"kind":args.terminal_kind,"attempt_id":args.attempt_id,"argv_digest":args.argv_digest,"nonce":args.nonce,"started_at":started,"finished_at":utc(),"exit_code":code,"output_path":args.output_path,"output_sha256":output.get("sha256") if output else None,"stdout_sha256":stdout.get("sha256") if stdout else None,"stdout_bytes":stdout.get("bytes") if stdout else 0,"stderr_sha256":stderr.get("sha256") if stderr else None,"stderr_bytes":stderr.get("bytes") if stderr else 0}
    if args.terminal_kind in {"codex_package_a_review_terminal","claude_package_a_review_terminal",PACKAGE_C_RR_TERMINAL_KIND}: terminal["policy"]=POLICY_ID; terminal["timed_out"]=run["timed_out"]; terminal["output_limit_exceeded"]=bool(run["output_limit_exceeded"] or run.get("cleanup_error") or (os.path.lexists(args.output_path) and output is None)); terminal["output_bytes"]=output.get("bytes") if output else 0
    atomic_json(args.receipt,terminal)
    return {"schema_version":SCHEMA,"operation":"review_wrapper","exit_code":code}


def _command_invalidate_gate(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}; gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
    reasons = sorted(set(args.reason_code or [])); findings = sorted(set(args.finding_id or []))
    if state.get("phase") not in {"completed", "needs_correction"} or not reasons or len(reasons) > 10 or any(not re.fullmatch(r"[a-z][a-z0-9_]{2,79}", x) for x in reasons) or any(not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,159}", x) for x in findings):
        raise ControllerError("gate invalidation requires completed gate and bounded reason/finding IDs")
    if state.get("phase") == "needs_correction" and gate.get("verdict") == "invalidated":
        receipt_id = gate.get("receipt_id"); path = os.path.join(directory, "invalidations", str(receipt_id) + ".json")
        info = file_info(path, os.path.join(directory, "invalidations"))
        try: prior = json.loads(Path(path).read_text()) if info else None
        except (OSError, json.JSONDecodeError) as exc: raise ControllerError("invalidation receipt is unreadable") from exc
        binding = prior.get("binding") if isinstance(prior, dict) else {}
        if (not info or prior.get("receipt_id") != receipt_id or binding.get("reasons") != reasons or binding.get("finding_ids") != findings or
                binding.get("candidate_id") != candidate.get("id") or binding.get("evidence_digest") != candidate.get("evidence_digest")):
            raise ControllerError("invalidation replay conflicts with immutable receipt")
        if not any(x.get("kind") == "gate_invalidation_applied" and x.get("receipt_id") == receipt_id for x in recent_events(directory)):
            append_event(directory, "gate_invalidation_applied", receipt_id=receipt_id, candidate_id=candidate["id"])
        return {"schema_version": SCHEMA, "operation": "invalidate_gate", "phase": "needs_correction", "receipt": {"path": path, "sha256": info["sha256"]}, "reused": True}
    if (gate.get("verdict") not in {"pass", "invalidated"} or not candidate.get("id") or not candidate.get("evidence_digest") or
            (state.get("phase") == "needs_correction" and gate.get("verdict") != "invalidated")):
        raise ControllerError("only a completed candidate-bound passing gate may be invalidated")
    prior_state = Path(state_path(directory)).read_bytes()
    binding = {"prior_revision": state["revision"], "prior_state_sha256": digest_bytes(prior_state), "prior_gate": gate,
               "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"], "gate_sha256": digest_bytes(json.dumps(gate, sort_keys=True, separators=(",", ":")).encode()), "plan_sha256": (state.get("planner_artifact") or {}).get("plan_sha256"), "reasons": reasons, "finding_ids": findings}
    if not isinstance(binding["plan_sha256"], str): raise ControllerError("gate invalidation requires a bound plan")
    receipt_id = digest_bytes(json.dumps(binding, sort_keys=True, separators=(",", ":")).encode())
    receipts = os.path.join(directory, "invalidations"); os.makedirs(receipts, mode=0o700, exist_ok=True); path = os.path.join(receipts, receipt_id + ".json")
    receipt = {"schema_version": SCHEMA, "kind": "gate_invalidation_receipt", "package_id": state["work_id"], "receipt_id": receipt_id, "binding": binding, "issued_at": utc()}
    existing = file_info(path, receipts)
    if existing:
        try: prior = json.loads(Path(path).read_text())
        except (OSError, json.JSONDecodeError) as exc: raise ControllerError("invalidation receipt is unreadable") from exc
        if prior.get("binding") != binding or prior.get("receipt_id") != receipt_id: raise ControllerError("invalidation receipt conflicts")
    else: atomic_json(path, receipt)
    events = recent_events(directory)
    if not any(x.get("kind") == "gate_invalidation_intent" and x.get("receipt_id") == receipt_id for x in events):
        append_event(directory, "gate_invalidation_intent", receipt_id=receipt_id, candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"])
    if state.get("phase") == "completed":
        state["phase"] = "needs_correction"; state["gate"] = {"kind": "m0c_plan_evidence", "verdict": "invalidated", "receipt_id": receipt_id, "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"], "policy": POLICY_ID, "at": utc()}; save(directory, state)
    if not any(x.get("kind") == "gate_invalidation_applied" and x.get("receipt_id") == receipt_id for x in recent_events(directory)):
        append_event(directory, "gate_invalidation_applied", receipt_id=receipt_id, candidate_id=candidate["id"])
    return {"schema_version": SCHEMA, "operation": "invalidate_gate", "phase": "needs_correction", "receipt": {"path": path, "sha256": (file_info(path, receipts) or {}).get("sha256")}, "reused": bool(existing)}


def capacity_wake_expected(state: Dict[str, Any], capacity: Dict[str, Any], candidate: Dict[str, Any],
                           packet: Dict[str, Any], lease_id: str, wakeup_ref: str) -> Dict[str, Any]:
    return {"capacity_packet_sha256": capacity["sha256"], "capacity_packet_path": capacity["path"],
            "failure_class": capacity["failure_class"], "retry_after": capacity["retry_after"],
            "reset_source": capacity["reset_source"], "reset_evidence_digest": capacity["reset_evidence_digest"], "provider": capacity["provider"],
            "role": capacity["role"], "provider_session_id": capacity["provider_session_id"],
            "lease_id": lease_id, "wakeup_ref": wakeup_ref, "wakeup_ref_sha256": digest_bytes(wakeup_ref.encode()),
            "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
            "worktree_fingerprint": candidate["evidence"]["worktree_fingerprint"], "declared_artifacts": candidate["evidence"]["declared_artifacts"],
            "base": {"repo_root": state["repo"]["root"], "head": state["repo"]["head"], "worktree_branch": state["worktree"]["branch"], "brief_sha256": state["brief"]["sha256"]},
            "invocation": packet.get("invocation"), "policy": POLICY_ID, "policy_digest": digest_bytes(POLICY_ID.encode())}


def _command_register_capacity_wakeup(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    ref = args.wakeup_ref.strip()
    if not ref or len(ref.encode()) > 500:
        raise ControllerError("wakeup reference is required and at most 500 bytes")
    capacity = _capacity_candidate_ready(directory, state)
    if (capacity.get("mode") == "manual_signal" or
            any(not isinstance(capacity.get(key), str) or not capacity[key]
                for key in ("retry_after", "reset_source", "reset_evidence_digest"))):
        raise ControllerError("manual capacity waits cannot register a scheduled wakeup; an authenticated external authority adapter is required")
    if capacity.get("lease_id"):
        if capacity.get("wakeup_ref") != ref:
            raise ControllerError("capacity wake lease already exists for a different wakeup reference")
        _capacity_candidate_ready(directory, state, require_lease=True)
        return {"schema_version": SCHEMA, "operation": "register_capacity_wakeup", "phase": CAPACITY_WAITING,
                "retry_after": capacity["retry_after"], "wakeup_ref": ref, "lease_id": capacity["lease_id"], "reused": True}
    receipts = os.path.join(directory, "capacity-wakeups"); os.makedirs(receipts, mode=0o700, exist_ok=True)
    candidate = state["candidate"]
    try:
        with open(capacity["path"], encoding="utf-8") as src: failure_packet = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("capacity packet is unreadable") from exc
    # A receipt may have survived a crash after its atomic write and before
    # state publication.  The package-local receipt directory has no other
    # producer, so any malformed/conflicting entry fails closed.
    orphans = []
    for path in sorted(Path(receipts).glob("*.json")):
        item = file_info(str(path), receipts)
        if not item:
            raise ControllerError("capacity wake receipt is unsafe")
        try:
            with open(path, encoding="utf-8") as src: receipt = json.load(src)
        except (OSError, json.JSONDecodeError) as exc:
            raise ControllerError("capacity wake receipt is unreadable") from exc
        lease = receipt.get("lease_id") if isinstance(receipt, dict) else None
        receipt_ref = receipt.get("wakeup_ref") if isinstance(receipt, dict) else None
        if not isinstance(lease, str) or not re.fullmatch(r"[0-9a-f-]{36}", lease) or not isinstance(receipt_ref, str):
            raise ControllerError("capacity wake receipt is malformed")
        expected = capacity_wake_expected(state, capacity, candidate, failure_packet, lease, receipt_ref)
        expected_keys = set(expected) | {"schema_version", "kind", "package_id", "issued_at"}
        if (set(receipt) != expected_keys or receipt.get("schema_version") != SCHEMA or receipt.get("kind") != "capacity_wakeup_lease" or
                receipt.get("package_id") != state["work_id"] or not isinstance(receipt.get("issued_at"), str) or
                len(receipt["issued_at"].encode()) > 64 or any(receipt.get(k) != v for k, v in expected.items())):
            raise ControllerError("capacity wake receipt failed full binding validation")
        orphans.append((lease, receipt_ref, str(path), item["sha256"]))
    if len(orphans) > 1:
        raise ControllerError("conflicting capacity wake receipts prevent recovery")
    if orphans:
        lease_id, receipt_ref, receipt_path, receipt_sha = orphans[0]
        if receipt_ref != ref:
            raise ControllerError("capacity wake lease already exists for a different wakeup reference")
        capacity.update({"wakeup_ref": ref, "lease_id": lease_id, "wakeup_receipt_path": receipt_path,
                         "wakeup_receipt_sha256": receipt_sha})
        save(directory, state)
        return {"schema_version": SCHEMA, "operation": "register_capacity_wakeup", "phase": CAPACITY_WAITING,
                "retry_after": capacity["retry_after"], "wakeup_ref": ref, "lease_id": lease_id, "reused": True}
    lease_id = str(uuid.uuid4())
    receipt = {"schema_version": SCHEMA, "kind": "capacity_wakeup_lease", "package_id": state["work_id"],
               **capacity_wake_expected(state, capacity, candidate, failure_packet, lease_id, ref), "issued_at": utc()}
    receipt_path = os.path.join(receipts, lease_id + ".json"); atomic_json(receipt_path, receipt)
    receipt_info = file_info(receipt_path, receipts)
    capacity.update({"wakeup_ref": ref, "lease_id": lease_id, "wakeup_receipt_path": receipt_path,
                     "wakeup_receipt_sha256": (receipt_info or {}).get("sha256")})
    append_event(directory, "capacity_wakeup_registered", candidate_id=capacity["candidate_id"], retry_after=capacity["retry_after"], lease_id=lease_id, wakeup_ref_sha256=receipt["wakeup_ref_sha256"], receipt_sha256=capacity["wakeup_receipt_sha256"])
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "register_capacity_wakeup", "phase": CAPACITY_WAITING,
            "retry_after": capacity["retry_after"], "wakeup_ref": ref, "lease_id": lease_id, "reused": False}


def _command_resume_capacity(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if state.get("phase") == "prepared" and isinstance(state.get("capacity"), dict) and state["capacity"].get("resumed_at"):
        capacity = state["capacity"]; recovery = state.get("recovery_constraint") or {}
        if recovery.get("kind") == "provider_plan_capacity_exact_resume" and recovery.get("candidate_id") == capacity.get("candidate_id"):
            return {"schema_version": SCHEMA, "operation": "resume_capacity", "phase": "prepared", "delivery": "exact_resume_required",
                    "role": capacity.get("role"), "provider_session_id": capacity.get("provider_session_id"), "reused": True}
    capacity = _capacity_candidate_ready(directory, state, require_lease=True)
    # Stored instant is intentionally allowed to become past; parser is only
    # for strict format validation at ingestion, so parse it directly here.
    try:
        due = dt.datetime.fromisoformat(capacity["retry_after"].replace("Z", "+00:00"))
    except ValueError as exc:
        raise ControllerError("capacity retry_after is malformed") from exc
    if due > dt.datetime.now(dt.timezone.utc):
        raise ControllerError("capacity retry_after has not elapsed")
    if capacity.get("resumed_at") or capacity.get("lease_consumed_at"):
        raise ControllerError("capacity wake lease has already been consumed")
    state["recovery_constraint"] = {"kind": "provider_plan_capacity_exact_resume", "active_at": utc(),
        "original_attempt_id": capacity.get("original_attempt_id"), "role": capacity["role"], "provider_session_id": capacity["provider_session_id"],
        "candidate_id": capacity["candidate_id"], "evidence_digest": capacity["evidence_digest"], "capacity_packet_sha256": capacity["sha256"], "consumed_at": None}
    capacity["resumed_at"] = utc(); capacity["lease_consumed_at"] = capacity["resumed_at"]; state["phase"] = "prepared"
    append_event(directory, "capacity_recovery_released", candidate_id=capacity["candidate_id"], retry_after=capacity["retry_after"], lease_id=capacity["lease_id"], wakeup_ref_sha256=digest_bytes(capacity["wakeup_ref"].encode()))
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "resume_capacity", "phase": "prepared", "delivery": "exact_resume_required",
            "role": capacity["role"], "provider_session_id": capacity["provider_session_id"]}


def _command_reconcile_provider_capacity(args: argparse.Namespace) -> Dict[str, Any]:
    """Recover an uncollected legacy attempt only when trusted reset metadata exists."""
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory); attempt = state.get("attempt") or {}
    gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
    legacy = state.get("phase") == "failed" and gate.get("reason") == "invalid_or_missing_worker_packet" and not state.get("candidate")
    uncollected = state.get("phase") in {"starting", "running"} and not state.get("candidate")
    if not (legacy or uncollected) or process_alive(attempt.get("pid"), attempt.get("pgid")):
        raise ControllerError("capacity reconcile only accepts a quiescent unreconciled attempt")
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"]); wt = state["worktree"]["path"]
    if not registered_worktree(state["repo"]["root"], wt, state["worktree"]["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    changed = git(wt, ["status", "--porcelain=v1"]).splitlines()
    artifacts = [{"path": os.path.join(wt, x["name"]), "bytes": x["bytes"], "sha256": x["sha256"]} for x in declared_artifacts(wt)]
    return provider_capacity_wait(directory, state, attempt, changed, artifacts, "reconcile_provider_capacity")


def _command_adjudicate(args: argparse.Namespace) -> Dict[str, Any]:
    """Record a supervisor's policy-bounded, JSON-only gate disposition."""
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory)
    if _is_package_a(state):
        raise ControllerError("Package A dispositions require the fixed package-specific controller gate")
    if state.get("work_id") == PACKAGE_B_WORK_ID:
        raise ControllerError("Package B dispositions require the fixed adjudicate-package-b controller gate")
    if _is_package_c(state):
        raise ControllerError("Package C dispositions require the fixed adjudicate-package-c controller gate")
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    attempt = state.get("attempt") or {}
    require_frozen_brief(state, directory)
    if state.get("phase") != "awaiting_gate":
        raise ControllerError("adjudication requires an awaiting_gate candidate")
    candidate = state.get("candidate") or {}
    if not candidate.get("id") or not candidate.get("evidence_digest"):
        raise ControllerError("candidate binding is missing")
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    if not candidate_intact(candidate, directory, state["worktree"]["path"]):
        raise ControllerError("candidate evidence binding no longer matches durable packet")
    rationale = args.rationale.strip()
    if not rationale or len(rationale.encode()) > 2000:
        raise ControllerError("rationale is required and at most 2000 bytes")
    adjudicator = args.adjudicator_principal.strip()
    if not adjudicator or len(adjudicator.encode()) > 300:
        raise ControllerError("bounded adjudicator principal is required")
    gate_common = {"candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
                   "at": utc(), "rationale": rationale, "adjudicator_principal": adjudicator,
                   "policy": POLICY_ID}
    if args.verdict == "pass":
        if not candidate.get("packet_verified"):
            raise ControllerError("unverified candidate cannot pass the deterministic gate")
        if (state.get("gate") or {}).get("kind") == "m0c_plan_evidence":
            if adjudicator != "orchestrator-plan-gate/v1":
                raise ControllerError("M0-C plan gate requires the fixed controller adjudicator principal")
            artifact = state.get("planner_artifact") if isinstance(state.get("planner_artifact"), dict) else {}
            packet_path = artifact.get("plan_path")
            item = file_info(packet_path, os.path.join(directory, "packets")) if isinstance(packet_path, str) else None
            if not item or item.get("sha256") != artifact.get("plan_sha256") or item.get("sha256") != (candidate.get("evidence") or {}).get("packet_sha256"):
                raise ControllerError("planner plan packet binding no longer matches")
            try:
                stored = json.loads(Path(packet_path).read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as exc:
                raise ControllerError("planner plan packet is unreadable") from exc
            if (not isinstance(stored, dict) or stored.get("kind") != "m0c_planner_plan" or stored.get("attempt_id") != attempt.get("id") or
                    stored.get("work_id") != state["work_id"] or stored.get("declared_package_id") != _plan_declared_package_id(state)):
                raise ControllerError("planner plan packet identity is invalid")
            _validate_m0c_plan(stored.get("plan"), state)
            review = state.get("plan_review") if isinstance(state.get("plan_review"), dict) else {}
            review_item = file_info(review.get("path"), os.path.join(directory, "packets")) if isinstance(review.get("path"), str) else None
            if (not review_item or review_item.get("sha256") != review.get("sha256") or review.get("verdict") != "pass" or
                    review.get("plan_sha256") != artifact.get("plan_sha256") or review.get("candidate_id") != candidate.get("id") or
                    review.get("actor_id") in {"claude", attempt.get("provider_session_id")}):
                raise ControllerError("M0-C plan pass requires a distinct controller-owned independent review receipt")
        alternate = state.get("alternate_evidence") if isinstance(state.get("alternate_evidence"), dict) else None
        if isinstance((candidate.get("evidence") or {}).get("alternate_attempt_id"), str):
            _alternate_gate_packets_intact(state, directory, candidate)
        state["phase"] = "completed"
        state["gate"] = {"verdict": "pass", **gate_common}
        append_event(directory, "gate_passed", candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"], adjudicator_principal=adjudicator, policy=POLICY_ID)
    elif args.verdict == "fail":
        state["phase"] = "failed"
        state["gate"] = {"verdict": "fail", **gate_common}
        append_event(directory, "gate_failed", candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"], adjudicator_principal=adjudicator, policy=POLICY_ID)
    elif args.verdict == "revise":
        instruction = (args.instruction or "").strip()
        if not instruction or len(instruction.encode()) > MAX_INSTRUCTION:
            raise ControllerError("revision instruction is required and at most 4096 bytes")
        gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
        preingest = (_is_m0c_plan_work(state) and not state.get("planner_artifact") and
                     (candidate.get("evidence") or {}).get("evidence_kind") == "worker_packet" and
                     gate.get("kind") in {None, "evidence_bound_candidate"})
        if preingest:
            if adjudicator != "orchestrator-plan-gate/v1":
                raise ControllerError("M0-C plan correction requires the fixed controller adjudicator principal")
            rounds = state.get("correction_rounds", [])
            if (state.get("m0c_correction_used") or not isinstance(rounds, list) or rounds or attempt.get("role") != "planner" or
                    not isinstance(attempt.get("provider_session_id"), str) or not attempt["provider_session_id"] or
                    not candidate.get("packet_verified") or not candidate_intact(candidate, directory, state["worktree"]["path"])):
                raise ControllerError("pre-ingest M0-C revision requires one intact verified planner candidate")
            item = {"id": str(uuid.uuid4()), "at": utc(), "text": instruction,
                    "sha256": digest_bytes(instruction.encode()), "source": "preingest_m0c_plan_gate"}
            state.setdefault("interventions", []).append(item)
            state["correction_rounds"] = [{"at": utc(), "intervention_id": item["id"], "intervention_sha256": item["sha256"], "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"]}]
            state["recovery_constraint"] = {"kind": "m0c_preingest_plan_exact_correction", "active_at": utc(),
                "original_attempt_id": attempt["id"], "role": "planner", "provider_session_id": attempt["provider_session_id"],
                "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
                "intervention_sha256": item["sha256"], "consumed_at": None}
            state["phase"] = "prepared"
            state["gate"] = {"verdict": "revise", **gate_common}
            append_event(directory, "m0c_preingest_correction_queued", candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"], intervention_id=item["id"], adjudicator_principal=adjudicator, policy=POLICY_ID)
            save(directory, state)
            return {"schema_version": SCHEMA, "operation": "adjudicate", "phase": "prepared", "gate": state["gate"], "delivery": "exact_planner_resume_required"}
        item = {"id": str(uuid.uuid4()), "at": utc(), "text": instruction,
                "sha256": digest_bytes(instruction.encode()), "source": "gate_revision"}
        state.setdefault("interventions", []).append(item)
        state["phase"] = "prepared"
        state["gate"] = {"verdict": "revise", **gate_common}
        append_event(directory, "gate_revision_requested", candidate_id=candidate["id"], intervention_id=item["id"], adjudicator_principal=adjudicator, policy=POLICY_ID)
    else:
        escalation = bounded_authority(state, directory, args.capability_required or "", args.target_authority_role or "", args.target_authority_principal or "", candidate, rationale)
        state["phase"] = "needs_authority"
        state["gate"] = {"verdict": "needs_authority", **gate_common}
        state["escalation"] = {"path": escalation["path"], "sha256": escalation["sha256"],
                               "token_sha256": escalation["token_sha256"], "used_at": None,
                               "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"],
                               "causal_fingerprint": escalation["causal_fingerprint"]}
        append_event(directory, "authority_escalated", candidate_id=candidate["id"],
                     capability_required=args.capability_required, target_authority_role=args.target_authority_role,
                     target_authority_principal=args.target_authority_principal, adjudicator_principal=adjudicator, policy=POLICY_ID,
                     causal_fingerprint=escalation["causal_fingerprint"])
        save(directory, state)
        return {"schema_version": SCHEMA, "operation": "adjudicate", "phase": "needs_authority",
                "escalation": escalation["packet"]}
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "adjudicate", "phase": state["phase"],
            "gate": state["gate"]}


def _command_amend(args: argparse.Namespace) -> Dict[str, Any]:
    """Consume one authority-issued token and return the package to automated work."""
    directory = work_dir(real(args.state_root), args.work_id)
    state = load(directory)
    escalation = state.get("escalation") or {}
    token = args.resume_token.strip()
    instruction = args.instruction.strip()
    if not escalation:
        raise ControllerError("no authority escalation is awaiting amendment")
    if escalation.get("used_at") or digest_bytes(token.encode()) != escalation.get("token_sha256"):
        raise ControllerError("invalid or already-used authority resume token")
    if state.get("phase") != "needs_authority":
        raise ControllerError("no authority escalation is awaiting amendment")
    path = escalation.get("path")
    if not isinstance(path, str) or not inside(path, os.path.join(directory, "escalations")) or os.path.islink(path):
        raise ControllerError("authority escalation packet is unsafe")
    info = file_info(path, os.path.join(directory, "escalations"))
    if not info or info.get("sha256") != escalation.get("sha256"):
        raise ControllerError("authority escalation packet binding no longer matches")
    try:
        with open(path, encoding="utf-8") as src:
            packet = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("authority escalation packet is unreadable") from exc
    if packet.get("capability_required") == "increase_budget":
        raise ControllerError("legacy increase_budget authority tokens are retired and cannot be amended or replayed")
    target = packet.get("target_authority") if isinstance(packet.get("target_authority"), dict) else {}
    if packet.get("causal_fingerprint") != escalation.get("causal_fingerprint"):
        raise ControllerError("authority escalation causal binding no longer matches")
    if packet.get("resume_token") != token or packet.get("capability_required") != args.granted_capability:
        raise ControllerError("authority token or granted capability does not match escalation")
    if target.get("principal") != args.acting_authority_principal:
        raise ControllerError("acting authority principal does not match escalation target")
    candidate = state.get("candidate") or {}
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    if not candidate_intact(candidate, directory, state["worktree"]["path"]):
        raise ControllerError("candidate evidence binding no longer matches durable packet")
    if not instruction or len(instruction.encode()) > MAX_INSTRUCTION:
        raise ControllerError("amendment instruction is required and at most 4096 bytes")
    item = {"id": str(uuid.uuid4()), "at": utc(), "text": instruction,
            "sha256": digest_bytes(instruction.encode()), "source": "authority_amendment"}
    state.setdefault("interventions", []).append(item)
    escalation["used_at"] = utc()
    escalation["amendment_sha256"] = item["sha256"]
    state["authority_amendment"] = {"at": escalation["used_at"], "acting_authority_principal": args.acting_authority_principal,
                                    "granted_capability": args.granted_capability, "instruction_sha256": item["sha256"],
                                    "candidate_id": candidate.get("id"), "evidence_digest": candidate.get("evidence_digest"),
                                    "policy": POLICY_ID}
    state["phase"] = "prepared"
    append_event(directory, "authority_amended", intervention_id=item["id"],
                 candidate_id=candidate.get("id"), acting_authority_principal=args.acting_authority_principal,
                 granted_capability=args.granted_capability, policy=POLICY_ID)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "amend", "phase": "prepared",
            "amendment_id": item["id"], "delivery": "next_resume", "authority_amendment": state["authority_amendment"],
            "limitations": ["bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated", "publishing remains unavailable in this bootstrap controller even when publish_external is requested"]}


def _validate_legacy_budget_retirement(directory: str, state: Dict[str, Any], escalation: Dict[str, Any],
                                       packet: Dict[str, Any]) -> None:
    """Validate the one historical ``budget_exhausted`` controller schema."""
    candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
    gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
    attempt = state.get("attempt") if isinstance(state.get("attempt"), dict) else {}
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    failure = evidence.get("provider_failure") if isinstance(evidence.get("provider_failure"), dict) else {}
    if (gate.get("kind") != "provider_failure" or gate.get("failure_class") != "budget_exhausted" or
            escalation.get("failure_class") != "budget_exhausted" or evidence.get("evidence_kind") != "provider_terminal_failure" or
            failure.get("failure_class") != "budget_exhausted" or not candidate_intact(candidate, directory, state["worktree"]["path"])):
        raise ControllerError("legacy budget retirement evidence is not the recognized controller schema")
    if (gate.get("candidate_id") != candidate.get("id") or gate.get("evidence_digest") != candidate.get("evidence_digest") or
            escalation.get("candidate_id") != candidate.get("id") or escalation.get("evidence_digest") != candidate.get("evidence_digest")):
        raise ControllerError("legacy budget retirement candidate binding no longer matches")
    provider_path = evidence.get("packet_path"); provider_info = file_info(provider_path, os.path.join(directory, "packets")) if isinstance(provider_path, str) else None
    log_path = failure.get("source_log_path"); log_info = file_info(log_path, os.path.join(directory, "logs")) if isinstance(log_path, str) else None
    if (not provider_info or provider_info.get("sha256") != evidence.get("packet_sha256") or not log_info or
            log_info.get("sha256") != failure.get("source_log_sha256") or attempt.get("stdout") != log_path):
        raise ControllerError("legacy provider-failure packet or log binding no longer matches")
    try:
        with open(provider_path, encoding="utf-8") as src: provider_packet = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("legacy provider-failure packet is unreadable") from exc
    terminal = {"type": "result", "subtype": "error_max_budget_usd", "is_error": True}
    terminal_digest = digest_bytes(json.dumps(terminal, sort_keys=True, separators=(",", ":")).encode())
    provider_keys = {"schema_version", "kind", "work_id", "attempt_id", "provider_session_id", "failure_class",
                     "terminal", "source_log_sha256", "terminal_digest", "parsed_at"}
    if (not isinstance(provider_packet, dict) or set(provider_packet) != provider_keys or provider_packet.get("schema_version") != SCHEMA or
            provider_packet.get("kind") != "provider_terminal_failure" or provider_packet.get("work_id") != state["work_id"] or
            provider_packet.get("attempt_id") != attempt.get("id") or provider_packet.get("provider_session_id") != attempt.get("provider_session_id") or
            provider_packet.get("failure_class") != "budget_exhausted" or provider_packet.get("terminal") != terminal or
            provider_packet.get("source_log_sha256") != log_info["sha256"] or provider_packet.get("terminal_digest") != terminal_digest or
            failure.get("terminal_digest") != terminal_digest):
        raise ControllerError("legacy provider-failure packet is not the recognized typed local guard")
    found_terminal = False
    try:
        with open(log_path, encoding="utf-8", errors="replace") as src:
            for line in src:
                try: event = json.loads(line)
                except json.JSONDecodeError: continue
                if (isinstance(event, dict) and event.get("type") == "result" and event.get("subtype") == "error_max_budget_usd" and event.get("is_error") is True):
                    found_terminal = True
    except OSError as exc:
        raise ControllerError("legacy provider log is unreadable") from exc
    if not found_terminal:
        raise ControllerError("legacy provider log lacks the typed local budget terminal")
    binding = packet.get("candidate_binding") if isinstance(packet.get("candidate_binding"), dict) else {}
    candidate_digest = (evidence.get("worktree_fingerprint") or {}).get("digest")
    base = {"repo_root": state["repo"]["root"], "head": state["repo"]["head"], "worktree_branch": state["worktree"]["branch"], "brief_sha256": state["brief"]["sha256"]}
    expected_binding = {"base_digest": digest_bytes(json.dumps(base, sort_keys=True, separators=(",", ":")).encode()),
                        "candidate_digest": candidate_digest,
                        "artifact_hashes": {x["name"]: x["sha256"] for x in evidence.get("declared_artifacts", [])},
                        "finding_ids": [], "base": base, "candidate_id": candidate.get("id"), "evidence_digest": candidate.get("evidence_digest")}
    expected_refs = [{"kind": "provider_terminal_failure", "path": provider_path, "sha256": provider_info["sha256"]},
                     {"kind": "worktree_fingerprint", "sha256": candidate_digest},
                     {"kind": "provider_failure_log", "path": log_path, "sha256": log_info["sha256"], "terminal_digest": terminal_digest}]
    token = packet.get("resume_token")
    token_free = {k: v for k, v in packet.items() if k not in {"resume_token", "causal_fingerprint"}}
    causal = digest_bytes(json.dumps({"package_id": state["work_id"], "policy_version": POLICY_ID,
                                      "candidate_digest": candidate_digest, "capability_required": "increase_budget",
                                      "packet_without_token": token_free}, sort_keys=True, separators=(",", ":")).encode())
    if (packet.get("kind") != "authority_escalation" or packet.get("package_id") != state["work_id"] or
            packet.get("capability_required") != "increase_budget" or packet.get("policy_version") != POLICY_ID or
            packet.get("policy_digest") != digest_bytes(POLICY_ID.encode()) or packet.get("candidate_binding") != expected_binding or
            packet.get("evidence_refs") != expected_refs or not isinstance(token, str) or packet.get("resume_token_sha256") != digest_bytes(token.encode()) or
            escalation.get("token_sha256") != digest_bytes(token.encode()) or packet.get("causal_fingerprint") != causal or
            escalation.get("causal_fingerprint") != causal):
        raise ControllerError("legacy authority escalation failed full binding validation")
    event_ok = any(row.get("kind") == "provider_budget_exhausted" and row.get("attempt_id") == attempt.get("id") and
                   row.get("candidate_id") == candidate.get("id") and row.get("evidence_digest") == candidate.get("evidence_digest") and
                   row.get("causal_fingerprint") == causal and row.get("policy") == POLICY_ID for row in recent_events(directory))
    if not event_ok:
        raise ControllerError("legacy controller event record is missing or does not match")


def _command_retire_local_budget_guard(args: argparse.Namespace) -> Dict[str, Any]:
    """Make pre-policy local-budget escalations permanently unusable without resuming work."""
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    escalation = state.get("escalation") if isinstance(state.get("escalation"), dict) else {}
    if state.get("phase") != "needs_authority" or not escalation:
        raise ControllerError("no legacy local budget authority state is awaiting retirement")
    path = escalation.get("path")
    info = file_info(path, os.path.join(directory, "escalations")) if isinstance(path, str) else None
    if not info or info.get("sha256") != escalation.get("sha256"):
        raise ControllerError("legacy escalation packet binding no longer matches")
    try:
        with open(path, encoding="utf-8") as src: packet = json.load(src)
    except (OSError, json.JSONDecodeError) as exc:
        raise ControllerError("legacy escalation packet is unreadable") from exc
    if packet.get("capability_required") != "increase_budget":
        raise ControllerError("retirement only accepts a legacy local budget guard escalation")
    if escalation.get("failure_class") == "budget_exhausted":
        _validate_legacy_budget_retirement(directory, state, escalation, packet)
    elif escalation.get("failure_class") != "local_package_budget_guard":
        raise ControllerError("retirement only accepts a legacy local budget guard escalation")
    state["retired_authority"] = {"at": utc(), "kind": "local_package_budget_guard", "packet_sha256": info["sha256"],
                                  "candidate_id": escalation.get("candidate_id"), "evidence_digest": escalation.get("evidence_digest")}
    escalation["used_at"] = utc(); escalation["retired_at"] = escalation["used_at"]
    state["escalation"] = None; state.pop("recovery_constraint", None); state["phase"] = "failed"
    state["gate"] = {"verdict": "fail", "kind": "local_package_budget_guard_retired", "at": utc(), "policy": POLICY_ID}
    append_event(directory, "legacy_local_budget_guard_retired", packet_sha256=info["sha256"], policy=POLICY_ID)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "retire_local_budget_guard", "phase": "failed", "retired": True,
            "limitations": ["the prior increase_budget token remains invalid", "no resume or spending-limit amendment is permitted"]}


def _command_prepare_alternate_evidence(args: argparse.Namespace) -> Dict[str, Any]:
    """Open a new, non-launching evidence route after a retired local guard."""
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    require_frozen_brief(state, directory)
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    gate = state.get("gate") if isinstance(state.get("gate"), dict) else {}
    if state.get("alternate_evidence"):
        prior = state["alternate_evidence"]
        requested = (args.model, args.effort, args.worker_actor_id, args.worker_run_id, args.reviewer_actor_id, args.reviewer_run_id)
        existing = tuple(prior.get(x) for x in ("model", "effort", "worker_actor_id", "worker_run_id", "reviewer_actor_id", "reviewer_run_id"))
        if requested != existing:
            raise ControllerError("alternate evidence attempt already exists with different identity")
        current = _alternate_binding(state, state["worktree"]["path"])
        if prior.get("binding") != current:
            raise ControllerError("alternate evidence candidate changed; prepare a new attempt")
        _validate_alternate_config(directory, state, prior)
        return {"schema_version": SCHEMA, "operation": "prepare_alternate_evidence", "phase": state["phase"], "attempt_id": prior["id"],
                "candidate_digest": (prior.get("binding") or {}).get("candidate_digest"), "candidate_binding": prior.get("binding"), "reused": True}
    if state.get("phase") != "failed" or gate.get("kind") not in {"local_package_budget_guard", "local_package_budget_guard_retired"}:
        raise ControllerError("alternate evidence requires a terminal local package budget guard")
    for value, label in ((args.worker_actor_id, "worker actor id"), (args.worker_run_id, "worker run id"), (args.reviewer_actor_id, "reviewer actor id"), (args.reviewer_run_id, "reviewer run id")):
        _safe_identifier(value, label)
    if args.worker_actor_id == args.reviewer_actor_id or args.worker_run_id == args.reviewer_run_id:
        raise ControllerError("alternate worker and reviewer identities must be distinct")
    if not args.model or len(args.model.encode()) > 160 or not args.effort or len(args.effort.encode()) > 40:
        raise ControllerError("alternate model and effort are required and bounded")
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"]); wt = state["worktree"]["path"]
    if not registered_worktree(state["repo"]["root"], wt, state["worktree"]["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    attempt = {"id": str(uuid.uuid4()), "backend": ALTERNATE_BACKEND, "route": ALTERNATE_ROUTE_LOCAL_GUARD,
               "controller": "codex", "model": args.model,
               "effort": args.effort, "worker_actor_id": args.worker_actor_id, "worker_run_id": args.worker_run_id,
               "reviewer_actor_id": args.reviewer_actor_id, "reviewer_run_id": args.reviewer_run_id,
               "prepared_at": utc(), "binding": _alternate_binding(state, wt), "result": None, "review": None}
    attempt["config"] = _seal_alternate_config(directory, state, attempt)
    state["alternate_evidence"] = attempt; state["candidate"] = None; state["escalation"] = None
    state["phase"] = "awaiting_evidence"
    state["gate"] = {"verdict": "awaiting_evidence", "kind": "alternate_evidence", "attempt_id": attempt["id"], "policy": POLICY_ID, "at": utc()}
    append_event(directory, "alternate_evidence_prepared", attempt_id=attempt["id"], route=attempt["route"], backend=ALTERNATE_BACKEND,
                 controller="codex", model=args.model, effort=args.effort, worker_actor_id=args.worker_actor_id,
                 worker_run_id=args.worker_run_id, reviewer_actor_id=args.reviewer_actor_id, reviewer_run_id=args.reviewer_run_id)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "prepare_alternate_evidence", "phase": state["phase"],
            "attempt_id": attempt["id"], "backend": ALTERNATE_BACKEND, "controller": "codex", "model": args.model,
            "effort": args.effort, "candidate_digest": attempt["binding"]["candidate_digest"], "candidate_binding": attempt["binding"],
            "limitations": ["this command does not launch a provider", "the retired local guard remains terminal", "packet transcripts are not accepted"]}


def _command_prepare_provider_neutral_evidence(args: argparse.Namespace) -> Dict[str, Any]:
    """Freeze a prepared candidate for a non-provider Codex Terra evidence route.

    This route intentionally has no relationship to a local guard or a provider
    failure.  A receipt must still bind to a regular file within the frozen
    candidate; a clean worktree can use a pre-existing tracked file as that
    receipt, while an otherwise empty clean candidate cannot satisfy the shared
    receipt schema.
    """
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    require_frozen_brief(state, directory)
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    prior = state.get("alternate_evidence") if isinstance(state.get("alternate_evidence"), dict) else None
    if prior:
        requested = (args.model, args.effort, args.worker_actor_id, args.worker_run_id, args.reviewer_actor_id, args.reviewer_run_id)
        existing = tuple(prior.get(x) for x in ("model", "effort", "worker_actor_id", "worker_run_id", "reviewer_actor_id", "reviewer_run_id"))
        if prior.get("route") != ALTERNATE_ROUTE_PROVIDER_NEUTRAL or requested != existing:
            raise ControllerError("provider-neutral evidence attempt already exists with different identity or route")
        current = _alternate_binding(state, state["worktree"]["path"])
        if prior.get("binding") != current:
            raise ControllerError("provider-neutral evidence candidate changed; prepare a new attempt")
        _validate_alternate_config(directory, state, prior)
        if state.get("phase") not in {"awaiting_evidence", "awaiting_review", "awaiting_gate"}:
            raise ControllerError("provider-neutral evidence phase is invalid")
        return {"schema_version": SCHEMA, "operation": "prepare_provider_neutral_evidence", "phase": state["phase"],
                "attempt_id": prior["id"], "route": prior["route"], "candidate_digest": current["candidate_digest"],
                "candidate_binding": current, "reused": True}
    if state.get("attempt") or state.get("candidate"):
        raise ControllerError("provider-neutral evidence requires no provider attempt, alternate evidence, or candidate")
    if state.get("phase") != "prepared":
        raise ControllerError("provider-neutral evidence requires a prepared package")
    for value, label in ((args.worker_actor_id, "worker actor id"), (args.worker_run_id, "worker run id"),
                         (args.reviewer_actor_id, "reviewer actor id"), (args.reviewer_run_id, "reviewer run id")):
        _safe_identifier(value, label)
    if args.worker_actor_id == args.reviewer_actor_id or args.worker_run_id == args.reviewer_run_id:
        raise ControllerError("alternate worker and reviewer identities must be distinct")
    if not args.model or len(args.model.encode()) > 160 or not args.effort or len(args.effort.encode()) > 40:
        raise ControllerError("alternate model and effort are required and bounded")
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"]); wt = state["worktree"]["path"]
    if not registered_worktree(state["repo"]["root"], wt, state["worktree"]["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    attempt = {"id": str(uuid.uuid4()), "backend": ALTERNATE_BACKEND, "route": ALTERNATE_ROUTE_PROVIDER_NEUTRAL,
               "controller": "codex", "model": args.model, "effort": args.effort,
               "worker_actor_id": args.worker_actor_id, "worker_run_id": args.worker_run_id,
               "reviewer_actor_id": args.reviewer_actor_id, "reviewer_run_id": args.reviewer_run_id,
               "prepared_at": utc(), "binding": _alternate_binding(state, wt), "result": None, "review": None}
    attempt["config"] = _seal_alternate_config(directory, state, attempt)
    state["alternate_evidence"] = attempt; state["phase"] = "awaiting_evidence"
    state["gate"] = {"verdict": "awaiting_evidence", "kind": "alternate_evidence", "route": attempt["route"],
                     "attempt_id": attempt["id"], "policy": POLICY_ID, "at": utc()}
    append_event(directory, "provider_neutral_evidence_prepared", attempt_id=attempt["id"], route=attempt["route"],
                 backend=ALTERNATE_BACKEND, controller="codex", model=args.model, effort=args.effort,
                 worker_actor_id=args.worker_actor_id, worker_run_id=args.worker_run_id,
                 reviewer_actor_id=args.reviewer_actor_id, reviewer_run_id=args.reviewer_run_id)
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "prepare_provider_neutral_evidence", "phase": state["phase"],
            "attempt_id": attempt["id"], "route": attempt["route"], "backend": ALTERNATE_BACKEND,
            "controller": "codex", "model": args.model, "effort": args.effort,
            "candidate_digest": attempt["binding"]["candidate_digest"], "candidate_binding": attempt["binding"],
            "limitations": ["this command does not launch a provider", "packet transcripts are not accepted",
                            "a shared receipt must bind to a regular frozen candidate artifact"]}


def _alternate_current(state: Dict[str, Any], directory: str) -> Tuple[Dict[str, Any], str, Dict[str, Any]]:
    attempt = state.get("alternate_evidence") if isinstance(state.get("alternate_evidence"), dict) else None
    if not attempt or attempt.get("backend") != ALTERNATE_BACKEND:
        raise ControllerError("alternate evidence attempt is missing")
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    route = attempt.get("route", ALTERNATE_ROUTE_LOCAL_GUARD)
    if route not in ALTERNATE_ROUTES:
        raise ControllerError("alternate evidence route is invalid")
    if state.get("phase") not in {"awaiting_evidence", "awaiting_review", "awaiting_gate"}:
        raise ControllerError("alternate evidence phase is invalid")
    require_frozen_brief(state, directory)
    wt = state["worktree"]["path"]
    require_unchanged_base(state["repo"]["root"], state["repo"]["head"])
    if not registered_worktree(state["repo"]["root"], wt, state["worktree"]["branch"]):
        raise ControllerError("recorded worktree registration is invalid")
    binding = _alternate_binding(state, wt)
    if attempt.get("binding") != binding:
        raise ControllerError("alternate evidence candidate changed; prepare a new attempt")
    config = _validate_alternate_config(directory, state, attempt)
    if config.get("candidate_binding") != binding or config.get("route") != route:
        raise ControllerError("alternate evidence config receipt candidate or route binding is invalid")
    return attempt, wt, binding


def _command_ingest_alternate_result(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    if state.get("phase") not in {"awaiting_evidence", "awaiting_review", "awaiting_gate"}:
        raise ControllerError("alternate result ingestion requires an awaiting evidence attempt")
    attempt, wt, binding = _alternate_current(state, directory)
    packet = _read_alternate_packet(args.packet_file)
    _validate_alternate_result(packet, state, attempt, binding, wt)
    if packet["actor_id"] != attempt["worker_actor_id"] or packet["run_id"] != attempt["worker_run_id"]:
        raise ControllerError("alternate result actor identity does not match prepared attempt")
    copied = _copy_alternate_packet(directory, attempt["id"], "result", packet)
    prior = attempt.get("result")
    record = {"path": copied["path"], "sha256": copied["sha256"], "actor_id": packet["actor_id"], "run_id": packet["run_id"]}
    if prior and prior != record:
        raise ControllerError("alternate result already ingested with different evidence")
    if prior == record and state.get("phase") == "awaiting_review":
        return {"schema_version": SCHEMA, "operation": "ingest_alternate_result", "phase": state["phase"],
                "attempt_id": attempt["id"], "packet_sha256": copied["sha256"], "reused": True}
    if state.get("phase") == "awaiting_gate":
        return {"schema_version": SCHEMA, "operation": "ingest_alternate_result", "phase": state["phase"], "attempt_id": attempt["id"], "packet_sha256": copied["sha256"], "reused": True}
    attempt["result"] = record; state["phase"] = "awaiting_review"
    state["gate"] = {"verdict": "awaiting_review", "kind": "alternate_evidence", "route": attempt.get("route", ALTERNATE_ROUTE_LOCAL_GUARD), "attempt_id": attempt["id"], "policy": POLICY_ID, "at": utc()}
    append_event(directory, "alternate_result_ingested", attempt_id=attempt["id"], route=attempt.get("route", ALTERNATE_ROUTE_LOCAL_GUARD), packet_sha256=copied["sha256"], actor_id=packet["actor_id"], run_id=packet["run_id"], candidate_digest=binding["candidate_digest"])
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "ingest_alternate_result", "phase": state["phase"], "attempt_id": attempt["id"], "packet_sha256": copied["sha256"]}


def _command_ingest_alternate_review(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id); state = load(directory)
    if _legacy_unsealed_alternate(state):
        raise ControllerError(LEGACY_UNSEALED_ALTERNATE_ERROR)
    if state.get("phase") not in {"awaiting_review", "awaiting_gate"}:
        raise ControllerError("alternate review ingestion requires an ingested alternate result")
    attempt, wt, binding = _alternate_current(state, directory); result = attempt.get("result") if isinstance(attempt.get("result"), dict) else None
    if not result:
        raise ControllerError("alternate review requires an ingested result")
    packet = _read_alternate_packet(args.packet_file)
    _validate_alternate_review(packet, state, attempt, binding, result["actor_id"], result["run_id"])
    if packet["actor_id"] != attempt["reviewer_actor_id"] or packet["run_id"] != attempt["reviewer_run_id"]:
        raise ControllerError("alternate review actor identity does not match prepared attempt")
    copied = _copy_alternate_packet(directory, attempt["id"], "review", packet)
    record = {"path": copied["path"], "sha256": copied["sha256"], "actor_id": packet["actor_id"], "run_id": packet["run_id"], "verdict": packet["verdict"]}
    prior = attempt.get("review")
    if prior and prior != record:
        raise ControllerError("alternate review already ingested with different evidence")
    if state.get("phase") == "awaiting_gate" and prior == record:
        candidate = state.get("candidate") if isinstance(state.get("candidate"), dict) else {}
        evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
        if (evidence.get("alternate_attempt_id") != attempt["id"] or
                evidence.get("alternate_route") != attempt.get("route", ALTERNATE_ROUTE_LOCAL_GUARD) or
                not candidate_intact(candidate, directory, wt)):
            raise ControllerError("alternate review replay candidate binding no longer matches")
        return {"schema_version": SCHEMA, "operation": "ingest_alternate_review", "phase": state["phase"],
                "attempt_id": attempt["id"], "candidate_id": candidate["id"], "review_verdict": packet["verdict"],
                "packet_sha256": copied["sha256"], "reused": True}
    attempt["review"] = record
    changed = binding["changed_paths"]
    artifacts = [{"path": os.path.join(wt, x["name"]), "bytes": x["bytes"], "sha256": x["sha256"]} for x in declared_artifacts(wt)]
    candidate = candidate_record({"path": result["path"], "sha256": result["sha256"]}, changed, artifacts, wt)
    candidate["evidence"]["alternate_review"] = {"path": copied["path"], "sha256": copied["sha256"]}
    candidate["evidence"]["alternate_attempt_id"] = attempt["id"]
    candidate["evidence"]["alternate_route"] = attempt.get("route", ALTERNATE_ROUTE_LOCAL_GUARD)
    candidate["evidence"]["alternate_config"] = dict(attempt["config"])
    candidate["evidence_digest"] = digest_bytes(json.dumps(candidate["evidence"], sort_keys=True, separators=(",", ":")).encode())
    state["candidate"] = candidate; state["phase"] = "awaiting_gate"
    state["gate"] = {"verdict": "awaiting_gate", "kind": "alternate_evidence_bound_candidate", "route": candidate["evidence"]["alternate_route"], "attempt_id": attempt["id"], "candidate_id": candidate["id"], "evidence_digest": candidate["evidence_digest"], "review_verdict": packet["verdict"], "policy": POLICY_ID, "at": utc()}
    append_event(directory, "alternate_review_ingested", attempt_id=attempt["id"], route=candidate["evidence"]["alternate_route"], packet_sha256=copied["sha256"], actor_id=packet["actor_id"], run_id=packet["run_id"], candidate_id=candidate["id"], evidence_digest=candidate["evidence_digest"])
    save(directory, state)
    return {"schema_version": SCHEMA, "operation": "ingest_alternate_review", "phase": state["phase"], "attempt_id": attempt["id"], "candidate_id": candidate["id"], "review_verdict": packet["verdict"], "packet_sha256": copied["sha256"], "limitations": ["ingestion never completes a package", "adjudicate rechecks packet and candidate bindings"]}


def _alternate_gate_packets_intact(state: Dict[str, Any], directory: str, candidate: Dict[str, Any]) -> None:
    """Re-validate sealed alternate config and durable result/review at pass time."""
    attempt, wt, binding = _alternate_current(state, directory)
    evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), dict) else {}
    config = attempt.get("config") if isinstance(attempt.get("config"), dict) else {}
    if (evidence.get("alternate_attempt_id") != attempt["id"] or evidence.get("alternate_route") != attempt.get("route") or
            evidence.get("alternate_config") != config or (state.get("gate") or {}).get("route") != attempt.get("route")):
        raise ControllerError("alternate evidence route or config binding no longer matches")
    result, review = attempt.get("result"), attempt.get("review")
    if not isinstance(result, dict) or not isinstance(review, dict):
        raise ControllerError("alternate evidence result or review receipt is missing")
    result_item = file_info(result.get("path"), os.path.join(directory, "packets", "alternate")) if isinstance(result.get("path"), str) else None
    review_item = file_info(review.get("path"), os.path.join(directory, "packets", "alternate")) if isinstance(review.get("path"), str) else None
    if not result_item or result_item.get("sha256") != result.get("sha256") or not review_item or review_item.get("sha256") != review.get("sha256"):
        raise ControllerError("alternate evidence durable packet binding no longer matches")
    result_packet, review_packet = _read_alternate_packet(result["path"]), _read_alternate_packet(review["path"])
    _validate_alternate_result(result_packet, state, attempt, binding, wt)
    _validate_alternate_review(review_packet, state, attempt, binding, result_packet["actor_id"], result_packet["run_id"])
    if (result_packet["actor_id"] != attempt["worker_actor_id"] or result_packet["run_id"] != attempt["worker_run_id"] or
            review_packet["actor_id"] != attempt["reviewer_actor_id"] or review_packet["run_id"] != attempt["reviewer_run_id"] or
            review_packet.get("verdict") != "pass"):
        raise ControllerError("alternate independent review must pass before completion")


def command_prepare(args: argparse.Namespace) -> Dict[str, Any]:
    if not args.work_id:
        args.work_id = "work-" + uuid.uuid4().hex[:12]
    directory = work_dir(real(args.state_root or default_root(real(args.repo))), args.work_id)
    with package_lock(directory):
        return _command_prepare(args)


