def command_ingest_alternate_review(args: argparse.Namespace) -> Dict[str, Any]:
    directory = work_dir(real(args.state_root), args.work_id)
    with package_lock(directory):
        return _command_ingest_alternate_review(args)


def _package_a_prerequisites_intact(directory: str, state: Dict[str, Any]) -> Dict[str, Any]:
    bound=state.get("package_a_prerequisites") if isinstance(state.get("package_a_prerequisites"),dict) else {}
    path=bound.get("path"); info=file_info(path,os.path.join(directory,"prerequisites")) if isinstance(path,str) else None
    if not info or info.get("sha256")!=bound.get("sha256"):
        raise ControllerError("Package A prerequisite baseline receipt is missing or changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A prerequisite baseline receipt is unreadable") from exc
    if (receipt.get("kind")!="package_a_prerequisite_baseline" or receipt.get("work_id")!=state["work_id"] or
            receipt.get("base_head")!=state["repo"]["head"] or receipt.get("outcome_id")!=_package_a_identity(state["work_id"])["outcome_id"]):
        raise ControllerError("Package A prerequisite baseline identity changed")
    files=receipt.get("files") if isinstance(receipt.get("files"),list) else []
    if {x.get("path"):x.get("sha256") for x in files if isinstance(x,dict)}!=PACKAGE_A_PREREQUISITE_FILES:
        raise ControllerError("Package A prerequisite baseline file manifest changed")
    for row in files:
        item=capped_regular_file_info(os.path.join(state["worktree"]["path"],row["path"]),state["worktree"]["path"],MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=row["sha256"]:
            # test_cowork is the sole prerequisite file later writable by the builder.
            if not (state.get("attempt") and row["path"]=="scripts/test_cowork.py"):
                raise ControllerError("Package A immutable prerequisite file changed")
    return receipt


def _command_materialize_package_a_prerequisites(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state) or state.get("phase")!="prepared" or state.get("attempt"):
        raise ControllerError("Package A materialization requires a fresh prepared package with no attempt")
    require_frozen_brief(state,directory); require_unchanged_base(state["repo"]["root"],state["repo"]["head"])
    if (state["repo"]["head"]!=PACKAGE_A_BASE_HEAD or state["brief"]["sha256"]!=_package_a_identity(state["work_id"])["brief_sha256"] or
            not registered_worktree(state["repo"]["root"],state["worktree"]["path"],state["worktree"]["branch"])):
        raise ControllerError("Package A frozen base, brief, or worktree authority is invalid")
    if state.get("package_a_prerequisites"):
        receipt=_package_a_prerequisites_intact(directory,state)
        return {"schema_version":SCHEMA,"operation":"materialize_package_a_prerequisites","reused":True,"receipt":state["package_a_prerequisites"],"fingerprint":receipt["post_materialization_fingerprint"]}
    root=os.path.dirname(directory)
    pre_status=git(state["worktree"]["path"],["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    if any(len(line)<4 or line[3:] not in PACKAGE_A_PREREQUISITE_FILES for line in pre_status):
        raise ControllerError("Package A worktree has unauthorized pre-materialization edits")
    _validate_m0c_v2_prerequisites(_m0c_v2_expected_prerequisites(root),state)
    v3_dir=work_dir(root,M0C_V3_WORK_ID); v3=load(v3_dir); vc=v3.get("candidate") if isinstance(v3.get("candidate"),dict) else {}; review=v3.get("plan_review") if isinstance(v3.get("plan_review"),dict) else {}
    review_file=file_info(review.get("path"),os.path.join(v3_dir,"packets")) if isinstance(review.get("path"),str) else None
    if (v3.get("phase")!="completed" or (v3.get("gate") or {}).get("verdict")!="pass" or (v3.get("gate") or {}).get("adjudicator_principal")!="orchestrator-plan-gate/v1" or
            vc.get("id")!=PACKAGE_A_V3_CANDIDATE_ID or vc.get("evidence_digest")!=PACKAGE_A_V3_EVIDENCE_DIGEST or
            not candidate_intact(vc,v3_dir,v3["worktree"]["path"]) or not review_file or review_file.get("sha256")!=PACKAGE_A_V3_REVIEW_SHA256 or review.get("sha256")!=PACKAGE_A_V3_REVIEW_SHA256 or review.get("verdict")!="pass" or review.get("actor_id")!="codex_terra_controller_v1" or review.get("candidate_id")!=vc.get("id") or review.get("plan_sha256")!=PACKAGE_A_V3_PLAN_SHA256):
        raise ControllerError("Package A v3 plan authority is not intact")
    sources={}
    for package in (M0B_WORK_ID,M0C0_WORK_ID):
        upstream=load(work_dir(root,package)); wt=upstream["worktree"]["path"]
        for rel,sha in PACKAGE_A_PREREQUISITE_FILES.items():
            item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
            if item and item.get("sha256")==sha: sources[rel]=item["path"]
    if set(sources)!=set(PACKAGE_A_PREREQUISITE_FILES): raise ControllerError("Package A canonical prerequisite source is missing")
    wt=state["worktree"]["path"]
    for rel,sha in PACKAGE_A_PREREQUISITE_FILES.items():
        destination=os.path.join(wt,rel); existing=capped_regular_file_info(destination,wt,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(destination) else None
        if existing and existing.get("sha256")==sha: continue
        if os.path.lexists(destination) and not (rel=="scripts/test_cowork.py" and existing and existing.get("sha256")==PACKAGE_A_BASE_TEST_COWORK_SHA256): raise ControllerError("Package A partial materialization conflicts with canonical bytes")
        os.makedirs(os.path.dirname(destination),exist_ok=True); fd,tmp=tempfile.mkstemp(prefix=".package-a-",dir=os.path.dirname(destination))
        try:
            with os.fdopen(fd,"wb") as out, open(sources[rel],"rb") as src: shutil.copyfileobj(src,out); out.flush(); os.fsync(out.fileno())
            if digest_bytes(Path(tmp).read_bytes())!=sha: raise ControllerError("Package A materialized prerequisite hash mismatch")
            os.replace(tmp,destination)
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    fingerprint=worktree_fingerprint(wt); files=[{"path":rel,"sha256":sha,"source":sources[rel]} for rel,sha in sorted(PACKAGE_A_PREREQUISITE_FILES.items())]
    receipt={"schema_version":SCHEMA,"kind":"package_a_prerequisite_baseline","work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"base_head":state["repo"]["head"],"v3_candidate_id":vc["id"],"v3_evidence_digest":vc["evidence_digest"],"v3_plan_sha256":PACKAGE_A_V3_PLAN_SHA256,"v3_review_sha256":PACKAGE_A_V3_REVIEW_SHA256,"files":files,"post_materialization_fingerprint":fingerprint,"created_at":utc()}
    receipts=os.path.join(directory,"prerequisites"); os.makedirs(receipts,mode=0o700,exist_ok=True); path=os.path.join(receipts,"baseline.json"); atomic_json(path,receipt); info=file_info(path,receipts)
    state["package_a_prerequisites"]={"path":path,"sha256":info["sha256"],"fingerprint_digest":fingerprint["digest"]}; append_event(directory,"package_a_prerequisites_materialized",receipt_sha256=info["sha256"],fingerprint_digest=fingerprint["digest"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"materialize_package_a_prerequisites","reused":False,"receipt":state["package_a_prerequisites"],"fingerprint":fingerprint}


def command_materialize_package_a_prerequisites(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_materialize_package_a_prerequisites(args)


def _command_verify_package_a(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate" or not candidate.get("packet_verified") or not candidate_intact(candidate,directory,state["worktree"]["path"]):
        raise ControllerError("Package A verification requires an intact collected candidate")
    baseline=_package_a_prerequisites_intact(directory,state); delta=_package_a_builder_delta(directory,state,candidate); wt=state["worktree"]["path"]
    changed=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines(); paths={line[3:] for line in changed if len(line)>=4}
    expected=set(PACKAGE_A_PREREQUISITE_FILES)|{"scripts/cowork_dispatch.py"}
    if not paths.issubset(expected) or "scripts/cowork_dispatch.py" not in paths:
        raise ControllerError("Package A builder delta escaped the exact allowlist")
    for rel in ("scripts/test_dispatch_contract_characterization.py","scripts/fixtures/dispatch_contract_characterization_sources.json"):
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item["sha256"]!=PACKAGE_A_PREREQUISITE_FILES[rel]: raise ControllerError("Package A M0-B prerequisite changed")
    probe=("import importlib.util,json,pathlib; p=pathlib.Path('scripts/cowork_dispatch.py'); "
           "s=importlib.util.spec_from_file_location('cowork_dispatch',p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); "
           "[getattr(m,n) for n in ('validate_dispatch_contract','validate_dispatch_decision','validate_attempt_link','decide')]; json.dumps({'ok':True})")
    specs=[(["python3","-m","unittest","scripts/test_cowork.py"],240,"test_cowork"),
           (["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],180,"characterization"),
           (["git","diff","--check"],60,"diff_check"),(["python3","-c",probe],30,"json_probe")]
    receipts=[]; receipt_dir=os.path.join(directory,"package-a-verification"); os.makedirs(receipt_dir,mode=0o700,exist_ok=True)
    for index,(argv,timeout,label) in enumerate(specs):
        try: proc=subprocess.run(argv,cwd=wt,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=timeout)
        except subprocess.TimeoutExpired as exc: raise ControllerError("Package A deterministic verification timed out") from exc
        payload={"schema_version":SCHEMA,"kind":"package_a_verification_receipt","label":label,"argv":argv,"cwd":wt,"exit_code":proc.returncode,"output_sha256":digest_bytes(proc.stdout),"output_bytes":len(proc.stdout),"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"]}
        path=os.path.join(receipt_dir,str(index)+".json"); atomic_json(path,payload); item=file_info(path,receipt_dir); receipts.append({"path":path,"sha256":item["sha256"],**payload})
        if proc.returncode!=0: raise ControllerError("Package A deterministic verification failed: "+label)
    state["package_a_verification"]={"at":utc(),"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"changed_paths":changed,"builder_delta":delta,"receipts":receipts,"verified":True}
    append_event(directory,"package_a_verified",candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],receipt_count=len(receipts)); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_package_a","phase":state["phase"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"receipts":receipts,"baseline_fingerprint":baseline["post_materialization_fingerprint"]["digest"]}


def command_verify_package_a(args: argparse.Namespace) -> Dict[str, Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_verify_package_a(args)


# Package-A baseline transaction v2.  These definitions intentionally replace
# the bootstrap drafts above while retaining their command wrappers.
def _package_a_validate_v3_authority(root: str) -> Dict[str, Any]:
    directory=work_dir(root,M0C_V3_WORK_ID); state=load(directory)
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    artifact=state.get("planner_artifact") if isinstance(state.get("planner_artifact"),dict) else {}
    review=state.get("plan_review") if isinstance(state.get("plan_review"),dict) else {}
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    packets=os.path.join(directory,"packets")
    plan_info=capped_regular_file_info(artifact.get("plan_path"),packets,MAX_PLAN_ARTIFACT_BYTES) if isinstance(artifact.get("plan_path"),str) else None
    review_info=capped_regular_file_info(review.get("path"),packets,MAX_PLAN_ARTIFACT_BYTES) if isinstance(review.get("path"),str) else None
    if (state.get("phase")!="completed" or gate.get("verdict")!="pass" or gate.get("adjudicator_principal")!="orchestrator-plan-gate/v1" or
            candidate.get("id")!=PACKAGE_A_V3_CANDIDATE_ID or candidate.get("evidence_digest")!=PACKAGE_A_V3_EVIDENCE_DIGEST or
            not candidate_intact(candidate,directory,state["worktree"]["path"]) or
            artifact.get("plan_sha256")!=PACKAGE_A_V3_PLAN_SHA256 or (candidate.get("evidence") or {}).get("packet_sha256")!=PACKAGE_A_V3_PLAN_SHA256 or
            not plan_info or plan_info.get("sha256")!=PACKAGE_A_V3_PLAN_SHA256 or
            not review_info or review_info.get("sha256")!=PACKAGE_A_V3_REVIEW_SHA256 or review.get("sha256")!=PACKAGE_A_V3_REVIEW_SHA256 or
            review.get("candidate_id")!=candidate.get("id") or review.get("actor_id")!="codex_terra_controller_v1" or
            not _safe_identifier(review.get("run_id"),"Package A v3 review run id") or review.get("verdict")!="pass" or
            review.get("plan_sha256")!=PACKAGE_A_V3_PLAN_SHA256):
        raise ControllerError("Package A v3 plan/review authority changed")
    try:
        plan_packet=json.loads(Path(plan_info["path"]).read_text(encoding="utf-8"))
        review_packet=json.loads(Path(review_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc:
        raise ControllerError("Package A v3 plan/review authority is unreadable") from exc
    if (not isinstance(plan_packet,dict) or plan_packet.get("kind")!="m0c_planner_plan" or
            plan_packet.get("work_id")!=M0C_V3_WORK_ID or plan_packet.get("declared_package_id")!=M0C_V3_PLAN_PACKAGE_ID or
            plan_packet.get("attempt_id")!=artifact.get("attempt_id") or not isinstance(plan_packet.get("plan"),dict)):
        raise ControllerError("Package A v3 plan packet identity changed")
    required={"schema_version","kind","work_id","attempt_id","backend","actor_id","run_id","review_nonce","plan_sha256","prerequisite_evidence_digests","candidate_id","verdict","findings","checks"}
    if (not isinstance(review_packet,dict) or set(review_packet)!=required or review_packet.get("schema_version")!=SCHEMA or
            review_packet.get("kind")!="m0c_plan_review" or review_packet.get("work_id")!=M0C_V3_WORK_ID or
            review_packet.get("attempt_id")!=artifact.get("attempt_id") or review_packet.get("backend")!=ALTERNATE_BACKEND or
            review_packet.get("actor_id")!=review.get("actor_id") or review_packet.get("run_id")!=review.get("run_id") or
            review_packet.get("plan_sha256")!=PACKAGE_A_V3_PLAN_SHA256 or
            review_packet.get("prerequisite_evidence_digests")!=[M0B_EVIDENCE_DIGEST,M0C0_EVIDENCE_DIGEST] or
            review_packet.get("candidate_id")!=candidate.get("id") or review_packet.get("verdict")!="pass"):
        raise ControllerError("Package A v3 review packet identity changed")
    return state


def _package_a_source_specs(root: str) -> List[Dict[str, Any]]:
    specs=[]
    mapping=((M0B_WORK_ID,"scripts/test_dispatch_contract_characterization.py",None),
             (M0B_WORK_ID,"scripts/fixtures/dispatch_contract_characterization_sources.json",None),
             (M0C0_WORK_ID,"scripts/test_cowork.py",PACKAGE_A_BASE_TEST_COWORK_SHA256))
    for package,rel,base_sha in mapping:
        directory=work_dir(root,package); state=load(directory); candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
        source=os.path.join(state["worktree"]["path"],rel); sha=PACKAGE_A_PREREQUISITE_FILES[rel]
        item=capped_regular_file_info(source,state["worktree"]["path"],MAX_CANDIDATE_PATH_BYTES)
        if (state.get("phase")!="completed" or (state.get("gate") or {}).get("verdict")!="pass" or
                not candidate_intact(candidate,directory,state["worktree"]["path"]) or not item or item.get("sha256")!=sha):
            raise ControllerError("Package A canonical prerequisite source authority changed")
        specs.append({"source_package":package,"source_candidate_id":candidate["id"],"source_evidence_digest":candidate["evidence_digest"],
                      "source_path":source,"path":rel,"sha256":sha,"base_expected_sha256":base_sha})
    return specs


def _package_a_validate_receipt(directory: str,state: Dict[str,Any],receipt: Dict[str,Any],info: Dict[str,Any]) -> Dict[str,Any]:
    keys={"schema_version","kind","work_id","outcome_id","base_head","worktree","branch","intent_sha256","v3_candidate_id","v3_evidence_digest","v3_plan_sha256","v3_review_sha256","files","post_materialization_fingerprint","created_at"}
    rows=receipt.get("files") if isinstance(receipt,dict) else None
    row_keys={"source_package","source_candidate_id","source_evidence_digest","source_path","path","sha256","base_expected_sha256","destination"}
    if (not isinstance(receipt,dict) or set(receipt)!=keys or receipt.get("schema_version")!=SCHEMA or receipt.get("kind")!="package_a_prerequisite_baseline" or
            receipt.get("work_id")!=state["work_id"] or receipt.get("outcome_id")!=_package_a_identity(state["work_id"])["outcome_id"] or receipt.get("base_head")!=PACKAGE_A_BASE_HEAD or
            receipt.get("worktree")!=state["worktree"]["path"] or receipt.get("branch")!=state["worktree"]["branch"] or
            receipt.get("v3_candidate_id")!=PACKAGE_A_V3_CANDIDATE_ID or receipt.get("v3_evidence_digest")!=PACKAGE_A_V3_EVIDENCE_DIGEST or
            receipt.get("v3_plan_sha256")!=PACKAGE_A_V3_PLAN_SHA256 or receipt.get("v3_review_sha256")!=PACKAGE_A_V3_REVIEW_SHA256 or
            not isinstance(rows,list) or len(rows)!=3 or any(not isinstance(x,dict) or set(x)!=row_keys for x in rows)):
        raise ControllerError("Package A prerequisite baseline receipt is malformed")
    if [x["path"] for x in rows]!=list(PACKAGE_A_PREREQUISITE_FILES) or len({x["path"] for x in rows})!=3:
        raise ControllerError("Package A prerequisite baseline rows are duplicated, reordered, or incomplete")
    created=receipt.get("created_at")
    if not isinstance(created,str) or not created or len(created.encode())>64:
        raise ControllerError("Package A prerequisite baseline timestamp is malformed")
    intent_path=os.path.join(directory,"prerequisites","materialization-intent.json")
    intent_info=capped_regular_file_info(intent_path,os.path.join(directory,"prerequisites"),MAX_PLAN_ARTIFACT_BYTES)
    if not intent_info or intent_info.get("sha256")!=receipt.get("intent_sha256"):
        raise ControllerError("Package A prerequisite intent binding changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A prerequisite intent is unreadable") from exc
    expected_intent={"schema_version":SCHEMA,"kind":"package_a_materialization_intent","work_id":state["work_id"],"base_head":PACKAGE_A_BASE_HEAD,"worktree":state["worktree"]["path"],"branch":state["worktree"]["branch"],"planned_receipt":info["path"],"files":rows}
    if intent!=expected_intent: raise ControllerError("Package A prerequisite intent schema or rows changed")
    bound=state.get("package_a_prerequisites") if isinstance(state.get("package_a_prerequisites"),dict) else {}
    if bound and bound.get("intent_path")!=intent_path:
        raise ControllerError("Package A state and intent path binding disagree")
    if bound and bound.get("intent_sha256")!=intent_info["sha256"]:
        raise ControllerError("Package A state and intent hash binding disagree")
    if bound and bound.get("fingerprint_digest")!=(receipt.get("post_materialization_fingerprint") or {}).get("digest"):
        raise ControllerError("Package A state and fingerprint binding disagree")
    root=os.path.dirname(directory); expected=_package_a_source_specs(root)
    for row,spec in zip(rows,expected):
        expected_row={**spec,"destination":os.path.join(state["worktree"]["path"],spec["path"])}
        if row!=expected_row: raise ControllerError("Package A prerequisite source binding changed")
        item=capped_regular_file_info(row["destination"],state["worktree"]["path"],MAX_CANDIDATE_PATH_BYTES)
        _adoption_intent_exists=os.path.lexists(os.path.join(directory,"package-a-adoption","intent.json"))
        _has_builder=(state.get("attempt") or state.get("package_a_adoption") or _adoption_intent_exists)
        if (not item or item.get("sha256")!=row["sha256"]) and not (_has_builder and row["path"]=="scripts/test_cowork.py"):
            raise ControllerError("Package A prerequisite destination changed")
    fp=worktree_fingerprint(state["worktree"]["path"])
    _adoption_intent_active=os.path.lexists(os.path.join(directory,"package-a-adoption","intent.json"))
    if not state.get("attempt") and not state.get("package_a_adoption") and not _adoption_intent_active and fp!=receipt.get("post_materialization_fingerprint"): raise ControllerError("Package A current worktree differs from sealed baseline")
    return receipt


def _package_a_prerequisites_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    directory=real(directory)
    require_frozen_brief(state,directory)
    if (state.get("brief") or {}).get("sha256")!=_package_a_identity(state["work_id"])["brief_sha256"] or git(state["worktree"]["path"],["rev-parse","HEAD"]).strip()!=PACKAGE_A_BASE_HEAD:
        raise ControllerError("Package A frozen brief or worktree HEAD authority changed")
    root=os.path.dirname(directory)
    _validate_m0c_v2_prerequisites(_m0c_v2_expected_prerequisites(root),state)
    _package_a_validate_v3_authority(root)
    bound=state.get("package_a_prerequisites") if isinstance(state.get("package_a_prerequisites"),dict) else {}
    if set(bound)!={"path","sha256","fingerprint_digest","intent_path","intent_sha256"}:
        raise ControllerError("Package A prerequisite state binding is malformed")
    path=bound.get("path"); info=capped_regular_file_info(path,os.path.join(directory,"prerequisites"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(path,str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A prerequisite baseline receipt is missing or changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A prerequisite baseline receipt is unreadable") from exc
    return _package_a_validate_receipt(directory,state,receipt,info)


def _command_materialize_package_a_prerequisites(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); wt=state["worktree"]["path"]
    if not _is_package_a(state) or state.get("phase")!="prepared" or state.get("attempt"): raise ControllerError("Package A materialization requires fresh prepared state")
    require_frozen_brief(state,directory); require_unchanged_base(state["repo"]["root"],PACKAGE_A_BASE_HEAD)
    if (state["repo"]["head"]!=PACKAGE_A_BASE_HEAD or state["brief"]["sha256"]!=_package_a_identity(state["work_id"])["brief_sha256"] or
            not registered_worktree(state["repo"]["root"],wt,state["worktree"]["branch"]) or git(wt,["rev-parse","HEAD"]).strip()!=PACKAGE_A_BASE_HEAD):
        raise ControllerError("Package A base, brief, or worktree authority is invalid")
    if state.get("package_a_prerequisites"):
        receipt=_package_a_prerequisites_intact(directory,state)
        if not any(x.get("kind")=="package_a_prerequisites_materialized" and x.get("receipt_sha256")==state["package_a_prerequisites"]["sha256"] for x in recent_events(directory)):
            append_event(directory,"package_a_prerequisites_materialized",receipt_sha256=state["package_a_prerequisites"]["sha256"],fingerprint_digest=state["package_a_prerequisites"]["fingerprint_digest"])
        return {"schema_version":SCHEMA,"operation":"materialize_package_a_prerequisites","reused":True,"receipt":state["package_a_prerequisites"],"fingerprint":receipt["post_materialization_fingerprint"]}
    root=os.path.dirname(directory); _validate_m0c_v2_prerequisites(_m0c_v2_expected_prerequisites(root),state)
    _package_a_validate_v3_authority(root)
    specs=_package_a_source_specs(root); prereq=os.path.join(directory,"prerequisites")
    if os.path.lexists(prereq) and (os.path.islink(prereq) or not os.path.isdir(prereq)): raise ControllerError("Package A prerequisite transaction directory is unsafe")
    os.makedirs(prereq,mode=0o700,exist_ok=True)
    pre_status=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    permitted_status={"?? scripts/test_dispatch_contract_characterization.py","?? scripts/fixtures/dispatch_contract_characterization_sources.json"," M scripts/test_cowork.py"}
    if any(line not in permitted_status for line in pre_status):
        raise ControllerError("Package A worktree has unauthorized pre-materialization edits")
    names={x.name for x in Path(prereq).iterdir()}; allowed={"materialization-intent.json","baseline.json","copy-0.tmp","copy-1.tmp","copy-2.tmp"}
    if names-allowed: raise ControllerError("Package A prerequisite transaction contains unexpected entries")
    intent_path=os.path.join(prereq,"materialization-intent.json"); receipt_path=os.path.join(prereq,"baseline.json")
    if any(name.startswith("copy-") for name in names) and "materialization-intent.json" not in names:
        raise ControllerError("Package A transaction temp exists without durable intent")
    if "baseline.json" in names and "materialization-intent.json" not in names:
        raise ControllerError("Package A baseline receipt cannot precede its durable intent")
    if pre_status and "materialization-intent.json" not in names:
        raise ControllerError("Package A dirty prerequisite bytes cannot be adopted without exact durable intent")
    rows=[{**spec,"destination":os.path.join(wt,spec["path"])} for spec in specs]
    intent={"schema_version":SCHEMA,"kind":"package_a_materialization_intent","work_id":state["work_id"],"base_head":PACKAGE_A_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"planned_receipt":receipt_path,"files":rows}
    prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not prior: raise ControllerError("Package A materialization intent is unsafe")
    prior_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(receipt_path) else None
    if os.path.lexists(receipt_path) and not prior_receipt: raise ControllerError("Package A baseline receipt is unsafe")
    if prior:
        try: prior_value=json.loads(Path(prior["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A materialization intent is unreadable") from exc
        if prior_value!=intent: raise ControllerError("Package A materialization intent conflicts with recovery")
    else: atomic_json(intent_path,intent); prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    for index,row in enumerate(rows):
        dest=row["destination"]
        if os.path.islink(dest): raise ControllerError("Package A destination symlink is unsafe")
        existing=capped_regular_file_info(dest,wt,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(dest) else None
        if existing and existing.get("sha256")==row["sha256"]: continue
        if row["base_expected_sha256"] is None:
            if os.path.lexists(dest): raise ControllerError("Package A absent-base destination conflicts")
        elif not existing or existing.get("sha256")!=row["base_expected_sha256"]: raise ControllerError("Package A tracked base destination conflicts")
        os.makedirs(os.path.dirname(dest),exist_ok=True); tmp=os.path.join(prereq,"copy-%d.tmp"%index)
        try:
            temp_info=capped_regular_file_info(tmp,prereq,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(tmp) else None
            if os.path.lexists(tmp) and not temp_info: raise ControllerError("Package A transaction temp is unsafe")
            if not temp_info or temp_info.get("sha256")!=row["sha256"]:
                flags=os.O_WRONLY|os.O_CREAT|(os.O_TRUNC if temp_info else os.O_EXCL)
                fd=os.open(tmp,flags,0o600)
                with os.fdopen(fd,"wb") as out,open(row["source_path"],"rb") as src: shutil.copyfileobj(src,out);out.flush();os.fsync(out.fileno())
            if digest_bytes(Path(tmp).read_bytes())!=row["sha256"]: raise ControllerError("Package A prerequisite copy hash mismatch")
            os.replace(tmp,dest)
            dir_fd=os.open(os.path.dirname(dest),os.O_RDONLY)
            try: os.fsync(dir_fd)
            finally: os.close(dir_fd)
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    final_status=set(git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines())
    if final_status!=permitted_status: raise ControllerError("Package A materialized status is not the exact canonical baseline")
    fp=worktree_fingerprint(wt); receipt={"schema_version":SCHEMA,"kind":"package_a_prerequisite_baseline","work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"base_head":PACKAGE_A_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"intent_sha256":prior["sha256"],"v3_candidate_id":PACKAGE_A_V3_CANDIDATE_ID,"v3_evidence_digest":PACKAGE_A_V3_EVIDENCE_DIGEST,"v3_plan_sha256":PACKAGE_A_V3_PLAN_SHA256,"v3_review_sha256":PACKAGE_A_V3_REVIEW_SHA256,"files":rows,"post_materialization_fingerprint":fp,"created_at":utc()}
    existing_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(receipt_path) else None; reused=bool(existing_receipt)
    if os.path.lexists(receipt_path) and not existing_receipt: raise ControllerError("Package A baseline receipt is unsafe")
    if existing_receipt:
        try: old=json.loads(Path(existing_receipt["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A orphan baseline receipt is unreadable") from exc
        # created_at is immutable from the orphan; all other bytes must match.
        receipt["created_at"]=old.get("created_at")
        if old!=receipt: raise ControllerError("Package A orphan baseline receipt conflicts with recovery")
    else: atomic_json(receipt_path,receipt); existing_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    _package_a_validate_receipt(directory,state,receipt,existing_receipt)
    state["package_a_prerequisites"]={"path":receipt_path,"sha256":existing_receipt["sha256"],"fingerprint_digest":fp["digest"],"intent_path":intent_path,"intent_sha256":prior["sha256"]}
    if not any(x.get("kind")=="package_a_prerequisites_materialized" and x.get("receipt_sha256")==existing_receipt["sha256"] for x in recent_events(directory)):
        append_event(directory,"package_a_prerequisites_materialized",receipt_sha256=existing_receipt["sha256"],fingerprint_digest=fp["digest"])
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"materialize_package_a_prerequisites","reused":reused,"receipt":state["package_a_prerequisites"],"fingerprint":fp}


def _package_a_builder_delta(directory: str,state: Dict[str,Any],candidate: Dict[str,Any]) -> Dict[str,Any]:
    receipt=_package_a_prerequisites_intact(directory,state); wt=state["worktree"]["path"]
    status=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines(); paths=[x[3:] for x in status if len(x)>=4]
    allowed=set(PACKAGE_A_PREREQUISITE_FILES)|{"scripts/cowork_dispatch.py"}
    exact_status={"?? scripts/test_dispatch_contract_characterization.py","?? scripts/fixtures/dispatch_contract_characterization_sources.json","?? scripts/cowork_dispatch.py"," M scripts/test_cowork.py"}
    for rel in ("scripts/test_dispatch_contract_characterization.py","scripts/fixtures/dispatch_contract_characterization_sources.json"):
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item["sha256"]!=PACKAGE_A_PREREQUISITE_FILES[rel]: raise ControllerError("Package A immutable M0-B artifact changed")
    delta=[]
    for rel in ("scripts/cowork_dispatch.py","scripts/test_cowork.py"):
        path=os.path.join(wt,rel)
        if os.path.lexists(path):
            item=capped_regular_file_info(path,wt,MAX_CANDIDATE_PATH_BYTES)
            if not item: raise ControllerError("Package A builder delta path is not a safe regular file")
            baseline=PACKAGE_A_PREREQUISITE_FILES.get(rel); changed=item["sha256"]!=baseline
            if changed: delta.append({"path":rel,"sha256":item["sha256"],"baseline_sha256":baseline})
    if not any(x["path"]=="scripts/cowork_dispatch.py" for x in delta): raise ControllerError("Package A builder did not create cowork_dispatch.py")
    if not any(x["path"]=="scripts/test_cowork.py" for x in delta): raise ControllerError("Package A builder did not provide its required test_cowork delta")
    if len(status)!=len(set(status)) or set(status)!=exact_status or len(paths)!=len(set(paths)) or set(paths)!=allowed:
        raise ControllerError("Package A builder delta escaped baseline allowlist or exact unstaged modes")
    value={"candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"files":delta}
    value["sha256"]=digest_bytes(json.dumps(value,sort_keys=True,separators=(",",":")).encode())
    bound=state.get("package_a_builder_delta") if isinstance(state.get("package_a_builder_delta"),dict) else {}
    if bound:
        if (set(bound)!={"path","sha256","candidate_id","evidence_digest","delta_sha256"} or
                bound.get("candidate_id")!=candidate.get("id") or bound.get("evidence_digest")!=candidate.get("evidence_digest") or
                bound.get("delta_sha256")!=value["sha256"]):
            raise ControllerError("Package A builder delta state binding is malformed")
        item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-a-delta"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
        if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A builder delta receipt changed")
        try: stored=json.loads(Path(item["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A builder delta receipt is unreadable") from exc
        if stored!=value: raise ControllerError("Package A builder delta no longer rederives from candidate")
    return value


def _package_a_json_sha256(value: Dict[str,Any]) -> str:
    encoded=(json.dumps(value,sort_keys=True,indent=2)+"\n").encode()
    return digest_bytes(encoded)


def _package_a_adopt_json(path: str,parent: str,value: Dict[str,Any],label: str) -> Dict[str,Any]:
    info=capped_regular_file_info(path,parent,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(path) else None
    if os.path.lexists(path) and not info: raise ControllerError("Package A %s recovery path is unsafe"%label)
    if info:
        try: prior=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A %s recovery copy is unreadable"%label) from exc
        if prior!=value or info.get("sha256")!=_package_a_json_sha256(value):
            raise ControllerError("Package A %s recovery copy conflicts with sealed evidence"%label)
        return info
    atomic_json(path,value)
    info=capped_regular_file_info(path,parent,MAX_PLAN_ARTIFACT_BYTES)
    if not info or info.get("sha256")!=_package_a_json_sha256(value): raise ControllerError("Package A %s could not be sealed"%label)
    return info


def _package_a_adopt_bytes(path: str,parent: str,value: bytes,label: str) -> Dict[str,Any]:
    info=capped_regular_file_info(path,parent,PACKAGE_A_MAX_GATE_OUTPUT) if os.path.lexists(path) else None
    if os.path.lexists(path) and not info: raise ControllerError("Package A %s recovery path is unsafe"%label)
    if info:
        if info.get("sha256")!=digest_bytes(value) or info.get("bytes")!=len(value): raise ControllerError("Package A %s recovery bytes conflict"%label)
        return info
    fd,temp=tempfile.mkstemp(prefix=".tmp-",dir=os.path.dirname(path))
    try:
        with os.fdopen(fd,"wb") as out: out.write(value); out.flush(); os.fsync(out.fileno())
        os.replace(temp,path)
    finally:
        try: os.unlink(temp)
        except FileNotFoundError: pass
    info=capped_regular_file_info(path,parent,PACKAGE_A_MAX_GATE_OUTPUT)
    if not info or info.get("sha256")!=digest_bytes(value): raise ControllerError("Package A %s could not be sealed"%label)
    return info


def _package_a_claimed_delta(packet: Dict[str,Any]) -> List[str]:
    normalized=[]
    for item in packet["structured"].get("changed_paths",[]):
        if not isinstance(item,str): raise ControllerError("Package A worker changed_paths is malformed")
        rel=item[3:] if item.startswith(("?? "," M ")) else item
        if (not rel or os.path.isabs(rel) or "\\" in rel or os.path.normpath(rel)!=rel or rel.startswith("../") or "/../" in rel):
            raise ControllerError("Package A worker changed_paths contains an unsafe alias")
        normalized.append(rel)
    if len(normalized)!=len(set(normalized)):
        raise ControllerError("Package A worker changed_paths contains duplicates after normalization")
    return normalized


def _package_a_collect_result(state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],candidate: Dict[str,Any],
                              changed: List[str],artifacts: List[Dict[str,Any]],delta: Dict[str,Any],delta_path: str,
                              delta_receipt_sha256: str,baseline_info: Dict[str,Any],phase_before_collect: str) -> Dict[str,Any]:
    return {"schema_version":SCHEMA,"work_id":state["work_id"],"operation":"collect",
            "gate":{"phase":"awaiting_gate","kind":"evidence_bound_candidate","candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"packet_verified":True},
            "phase_before_collect":phase_before_collect,"attempt":{k:attempt.get(k) for k in ("id","role","provider_session_id","pid")},
            "worktree":state["worktree"]["path"],"changed_paths":changed[:MAX_PATHS],"changed_paths_truncated":len(changed)>MAX_PATHS,
            "receipts":[baseline_info],"artifacts":artifacts,
            "worker_packet":{"path":packet["path"],"sha256":packet["sha256"],"outcome":packet["structured"]["outcome"],"summary":packet["structured"]["summary"],"next_action":packet["structured"]["next_action"]},
            "limitations":["provider output is not proof of correctness","no watcher or lease/fencing protocol is implemented","detached provider exit code is not collected","Cowork backend adapter is not implemented","bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated","publishing remains unavailable in this bootstrap controller even when publish_external is requested"],
            "package_a_builder_delta":{**delta,"receipt_path":delta_path,"receipt_sha256":delta_receipt_sha256}}


def _package_a_candidate_intact(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> None:
    candidate_keys={"schema_version","id","evidence_digest","evidence","packet_verified","created_at"}
    evidence_keys={"packet_sha256","packet_path","evidence_kind","changed_paths","declared_artifacts","worktree_fingerprint","package_a_baseline_receipt_sha256","package_a_baseline_fingerprint_digest"}
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    created=candidate.get("created_at")
    digest=digest_bytes(json.dumps(evidence,sort_keys=True,separators=(",",":")).encode())
    current_status=git(state["worktree"]["path"],["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    current_fingerprint=worktree_fingerprint(state["worktree"]["path"])
    if (not isinstance(candidate,dict) or set(candidate)!=candidate_keys or candidate.get("schema_version")!=SCHEMA or candidate.get("packet_verified") is not True or
            not isinstance(created,str) or created!=(state.get("attempt") or {}).get("started_at") or len(created.encode())>64 or set(evidence)!=evidence_keys or evidence.get("evidence_kind")!="worker_packet" or
            evidence.get("package_a_baseline_receipt_sha256")!=state["package_a_prerequisites"]["sha256"] or
            evidence.get("package_a_baseline_fingerprint_digest")!=baseline["post_materialization_fingerprint"]["digest"] or
            evidence.get("changed_paths")!=current_status or evidence.get("worktree_fingerprint")!=current_fingerprint or candidate.get("evidence_digest")!=digest or candidate.get("id")!="package-a-"+digest[:32] or
            not candidate_intact(candidate,directory,state["worktree"]["path"])):
        raise ControllerError("Package A candidate deterministic evidence binding changed")


def _package_a_attempt_intact(attempt: Dict[str,Any]) -> None:
    expected={"role":"implementer","backend":"claude_direct","provider":"claude","controller":"claude","model":"sonnet","effort":"medium","policy":POLICY_ID}
    if not isinstance(attempt,dict) or any(attempt.get(key)!=value for key,value in expected.items()) or not _safe_identifier(attempt.get("id"),"Package A attempt id") or not _safe_identifier(attempt.get("provider_session_id"),"Package A provider session id"):
        raise ControllerError("Package A implementer attempt identity changed")


def _package_a_collect_verified(directory: str,state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],
                                changed: List[str],receipts: List[Dict[str,Any]],artifacts: List[Dict[str,Any]]) -> Dict[str,Any]:
    _package_a_attempt_intact(attempt)
    wt=state["worktree"]["path"]; baseline=_package_a_prerequisites_intact(directory,state)
    structured=packet.get("structured") if isinstance(packet.get("structured"),dict) else {}
    # The controller independently executes all five gates and never trusts worker claims.
    # The worker must declare the three canonical checks as its exact ordered prefix; additional
    # advisory rows (e.g. M0-B hash check, JSON probe) are permitted up to the schema's maxItems=20
    # because they carry no elevated trust and do not affect gate execution.
    required_commands=["python3 -m unittest scripts/test_cowork.py","python3 -m unittest scripts/test_dispatch_contract_characterization.py","git diff --check"]
    worker_checks=structured.get("checks") if isinstance(structured.get("checks"),list) else []
    if (structured.get("outcome")!="completed" or
            len(worker_checks)<len(required_commands) or
            [row.get("command") for row in worker_checks[:len(required_commands)]]!=required_commands or
            any(row.get("cwd")!=wt or row.get("receipt_refs")!=[] for row in worker_checks)):
        raise ControllerError("Package A worker command claims are not the exact advisory gate list")
    candidate=candidate_record(packet,changed,artifacts,wt)
    candidate["evidence"]["package_a_baseline_receipt_sha256"]=state["package_a_prerequisites"]["sha256"]
    candidate["evidence"]["package_a_baseline_fingerprint_digest"]=baseline["post_materialization_fingerprint"]["digest"]
    candidate["evidence_digest"]=digest_bytes(json.dumps(candidate["evidence"],sort_keys=True,separators=(",",":")).encode())
    candidate["id"]="package-a-"+candidate["evidence_digest"][:32]
    candidate["created_at"]=attempt.get("started_at")
    _package_a_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); expected=[x["path"] for x in delta["files"]]
    claimed=_package_a_claimed_delta(packet)
    if claimed!=expected: raise ControllerError("Package A worker changed_paths does not match derived builder delta")
    delta_dir=os.path.join(directory,"package-a-delta"); collect_dir=os.path.join(directory,"package-a-collect")
    for path,label in ((delta_dir,"delta directory"),(collect_dir,"collect directory")):
        if os.path.lexists(path) and (os.path.islink(path) or not os.path.isdir(path)):
            raise ControllerError("Package A %s is unsafe"%label)
        os.makedirs(path,mode=0o700,exist_ok=True)
    generation=state.get("package_a_collect_generation",0)
    if isinstance(generation,bool) or not isinstance(generation,int) or generation not in {0,1}: raise ControllerError("Package A collect generation is invalid")
    delta_path=os.path.join(delta_dir,candidate["id"]+".json"); result_path=(os.path.join(directory,"result.json") if generation==0 else os.path.join(collect_dir,str(attempt.get("id"))+".result.json"))
    intent_path=os.path.join(collect_dir,str(attempt.get("id"))+".intent.json")
    delta_sha=_package_a_json_sha256(delta)
    baseline_bound=state["package_a_prerequisites"]
    baseline_info=capped_regular_file_info(baseline_bound["path"],os.path.join(directory,"prerequisites"),MAX_PLAN_ARTIFACT_BYTES)
    if not baseline_info or baseline_info.get("sha256")!=baseline_bound["sha256"]: raise ControllerError("Package A baseline receipt changed during collection")
    phase_before_collect=state["phase"]
    result=_package_a_collect_result(state,attempt,packet,candidate,changed,artifacts,delta,delta_path,delta_sha,baseline_info,phase_before_collect)
    result_sha=_package_a_json_sha256(result)
    intent={"schema_version":SCHEMA,"kind":"package_a_collect_intent","work_id":state["work_id"],"attempt_id":attempt.get("id"),
            "provider_packet_path":packet["path"],"provider_packet_sha256":packet["sha256"],"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],"phase_before_collect":phase_before_collect,"generation":generation,"candidate":candidate,
            "delta_path":delta_path,"delta_receipt_sha256":delta_sha,"delta_sha256":delta["sha256"],
            "result_path":result_path,"result_sha256":result_sha}
    if not os.path.lexists(intent_path) and (os.path.lexists(delta_path) or os.path.lexists(result_path)):
        raise ControllerError("Package A collect output cannot precede its durable intent")
    intent_info=_package_a_adopt_json(intent_path,collect_dir,intent,"collect intent")
    delta_info=_package_a_adopt_json(delta_path,delta_dir,delta,"builder delta receipt")
    if delta_info["sha256"]!=delta_sha: raise ControllerError("Package A builder delta receipt hash changed")
    result_info=_package_a_adopt_json(result_path,directory,result,"collect result")
    if result_info["sha256"]!=result_sha: raise ControllerError("Package A collect result hash changed")
    state["candidate"]=candidate; state["escalation"]=None; state["phase"]="awaiting_gate"
    state["package_a_builder_delta"]={"path":delta_path,"sha256":delta_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"delta_sha256":delta["sha256"]}
    state["package_a_collect"]={"intent_path":intent_path,"intent_sha256":intent_info["sha256"],"result_path":result_path,"result_sha256":result_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="candidate_collected" and row.get("candidate_id")==candidate["id"] and row.get("evidence_digest")==candidate["evidence_digest"] for row in recent_events(directory)):
        append_event(directory,"candidate_collected",attempt_id=attempt.get("id"),candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],packet_verified=True)
    save(directory,state)
    return result


def _package_a_replay_collect(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_collect") if isinstance(state.get("package_a_collect"),dict) else {}
    keys={"intent_path","intent_sha256","result_path","result_sha256","candidate_id","evidence_digest"}
    if set(bound)!=keys: raise ControllerError("Package A collected state binding is malformed")
    collect_dir=os.path.join(directory,"package-a-collect")
    if not all(isinstance(bound.get(key),str) for key in keys): raise ControllerError("Package A collected state binding types are malformed")
    intent_info=capped_regular_file_info(bound["intent_path"],collect_dir,MAX_PLAN_ARTIFACT_BYTES)
    result_info=capped_regular_file_info(bound["result_path"],directory,MAX_PLAN_ARTIFACT_BYTES)
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not result_info or result_info.get("sha256")!=bound.get("result_sha256"):
        raise ControllerError("Package A collected intent or result binding changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text(encoding="utf-8")); result=json.loads(Path(result_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A collected intent or result is unreadable") from exc
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}; attempt=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
    _package_a_attempt_intact(attempt)
    baseline=_package_a_prerequisites_intact(directory,state); baseline_bound=state["package_a_prerequisites"]
    intent_keys={"schema_version","kind","work_id","attempt_id","provider_packet_path","provider_packet_sha256","baseline_receipt_sha256","baseline_fingerprint_digest","phase_before_collect","generation","candidate","delta_path","delta_receipt_sha256","delta_sha256","result_path","result_sha256"}
    expected_delta_path=os.path.join(directory,"package-a-delta",str(candidate.get("id"))+".json")
    generation=state.get("package_a_collect_generation",0); expected_result_path=(os.path.join(directory,"result.json") if generation==0 else os.path.join(directory,"package-a-collect",str(attempt.get("id"))+".result.json"))
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    if (not isinstance(intent,dict) or set(intent)!=intent_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_a_collect_intent" or
            intent.get("work_id")!=state["work_id"] or intent.get("attempt_id")!=attempt.get("id") or
            intent.get("provider_packet_path")!=evidence.get("packet_path") or intent.get("provider_packet_sha256")!=evidence.get("packet_sha256") or
            intent.get("baseline_receipt_sha256")!=baseline_bound.get("sha256") or intent.get("baseline_fingerprint_digest")!=baseline["post_materialization_fingerprint"]["digest"] or
            intent.get("phase_before_collect") not in {"starting","running"} or intent.get("generation")!=generation or
            intent.get("candidate")!=candidate or intent.get("delta_path")!=expected_delta_path or intent.get("result_path")!=expected_result_path or
            intent.get("result_sha256")!=bound.get("result_sha256") or candidate.get("id")!=bound.get("candidate_id") or candidate.get("evidence_digest")!=bound.get("evidence_digest")):
        raise ControllerError("Package A collected candidate binding changed")
    _package_a_candidate_intact(directory,state,candidate,baseline)
    packet_info=capped_regular_file_info(intent["provider_packet_path"],os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES)
    if not packet_info or packet_info.get("sha256")!=intent["provider_packet_sha256"]: raise ControllerError("Package A collected provider packet binding changed")
    try: provider_packet=json.loads(Path(packet_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A collected provider packet is unreadable") from exc
    structured=normalize_package_a_structured(provider_packet.get("structured") if isinstance(provider_packet,dict) else None)
    provider_keys={"schema_version","work_id","attempt_id","provider_session_id","structured","source_log_sha256","parsed_at"}
    if (not isinstance(provider_packet,dict) or set(provider_packet)!=provider_keys or provider_packet.get("schema_version")!=SCHEMA or
            not isinstance(provider_packet.get("parsed_at"),str) or not provider_packet["parsed_at"] or len(provider_packet["parsed_at"].encode())>64 or
            not structured or provider_packet.get("work_id")!=state["work_id"] or provider_packet.get("attempt_id")!=attempt.get("id") or
            provider_packet.get("provider_session_id")!=attempt.get("provider_session_id") or provider_packet.get("source_log_sha256")!=(file_info(attempt.get("stdout"),os.path.join(directory,"logs")) or {}).get("sha256")):
        raise ControllerError("Package A collected provider packet identity changed")
    delta=_package_a_builder_delta(directory,state,candidate)
    delta_info=capped_regular_file_info(expected_delta_path,os.path.join(directory,"package-a-delta"),MAX_PLAN_ARTIFACT_BYTES)
    if (not delta_info or delta_info.get("sha256")!=intent.get("delta_receipt_sha256") or intent.get("delta_sha256")!=delta.get("sha256")):
        raise ControllerError("Package A collected builder delta binding changed")
    try: stored_delta=json.loads(Path(delta_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A collected builder delta is unreadable") from exc
    if stored_delta!=delta: raise ControllerError("Package A collected builder delta changed")
    baseline_info=capped_regular_file_info(baseline_bound["path"],os.path.join(directory,"prerequisites"),MAX_PLAN_ARTIFACT_BYTES)
    packet={"path":packet_info["path"],"sha256":packet_info["sha256"],"structured":structured}
    expected_result=_package_a_collect_result(state,attempt,packet,candidate,evidence.get("changed_paths",[]),evidence.get("declared_artifacts",[]),delta,expected_delta_path,delta_info["sha256"],baseline_info,intent["phase_before_collect"])
    if result!=expected_result or result_info.get("sha256")!=_package_a_json_sha256(expected_result):
        raise ControllerError("Package A collected result binding changed")
    return result


def _bounded_run(argv: List[str],cwd: str,timeout_seconds: int,limit: int=PACKAGE_A_MAX_GATE_OUTPUT) -> Dict[str,Any]:
    started=time.monotonic(); retained=bytearray(); total_seen=0; timed_out=False; overflow=False; cleanup_error=None
    try:
        proc=subprocess.Popen(argv,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL,start_new_session=True)
    except OSError as exc:
        return {"exit_code":127,"timed_out":False,"output_limit_exceeded":False,"output_sha256":digest_bytes(b""),"output_bytes":0,
                "output_total_seen":0,"output":b"","spawn_error":type(exc).__name__,"cleanup_error":None}
    def terminate_group() -> None:
        nonlocal cleanup_error
        try: os.killpg(proc.pid,signal.SIGTERM)
        except ProcessLookupError: return
        except PermissionError: cleanup_error="permission_denied"; return
        deadline=time.monotonic()+0.5
        while time.monotonic()<deadline:
            try: os.killpg(proc.pid,0)
            except ProcessLookupError: return
            except PermissionError: cleanup_error="permission_denied"; return
            time.sleep(0.02)
        try: os.killpg(proc.pid,signal.SIGKILL)
        except ProcessLookupError: pass
        except PermissionError: cleanup_error="permission_denied"
    selector=selectors.DefaultSelector()
    try:
        assert proc.stdout is not None
        os.set_blocking(proc.stdout.fileno(),False); selector.register(proc.stdout,selectors.EVENT_READ)
        deadline=started+timeout_seconds
        while True:
            remaining=deadline-time.monotonic()
            if remaining<=0 and proc.poll() is None:
                timed_out=True; terminate_group()
            events=selector.select(max(0,min(0.2,remaining)) if proc.poll() is None and not timed_out else 0)
            for key,_ in events:
                try: chunk=os.read(key.fileobj.fileno(),65536)
                except BlockingIOError: chunk=b""
                if chunk:
                    total_seen+=len(chunk)
                    available=max(0,limit-len(retained)); retained.extend(chunk[:available])
                    if len(chunk)>available: overflow=True; terminate_group()
                elif proc.poll() is not None:
                    try: selector.unregister(key.fileobj)
                    except Exception: pass
            if proc.poll() is not None:
                while True:
                    try: chunk=os.read(proc.stdout.fileno(),65536)
                    except (BlockingIOError,OSError): break
                    if not chunk: break
                    total_seen+=len(chunk)
                    available=max(0,limit-len(retained)); retained.extend(chunk[:available])
                    if len(chunk)>available: overflow=True
                break
        code=proc.wait()
        # A successful leader may have left background descendants in its
        # process group.  Terminate the entire group before fingerprinting.
        terminate_group()
    finally:
        selector.close()
        if proc.poll() is None: terminate_group(); proc.wait()
        if proc.stdout is not None: proc.stdout.close()
    output=bytes(retained)
    return {"exit_code":code,"timed_out":timed_out,"output_limit_exceeded":overflow,"output_sha256":digest_bytes(output),
            "output_bytes":len(output),"output_total_seen":total_seen,"output":output,"spawn_error":None,"cleanup_error":cleanup_error}


def _package_a_unittest_counters(raw: bytes) -> Dict[str,int]:
    text=raw.decode("utf-8","replace")
    ran=re.findall(r"Ran\s+(\d+)\s+tests?\b",text)
    if len(ran)!=1: raise ControllerError("Package A unittest output lacks one exact test counter")
    def count(label: str) -> int:
        prefix=r"(?<!expected )" if label=="failures" else ""
        values=re.findall(prefix+r"\b"+re.escape(label)+r"=(\d+)",text)
        return int(values[-1]) if values else 0
    return {"tests":int(ran[0]),"failures":count("failures"),"errors":count("errors"),
            "skipped":count("skipped"),"expected_failures":count("expected failures"),
            "unexpected_successes":count("unexpected successes")}


def _package_a_probe_code(builder_name: str) -> str:
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,119}",builder_name): raise ControllerError("Package A idempotency builder name is unsafe")
    # The values are fixed controller fixtures.  The probe imports only the
    # candidate module, constructs all three v1 records, validates and JSON
    # round-trips them, exercises allow/refuse reduction, and checks key
    # determinism without touching state or a provider.
    return """import importlib.util,json,uuid
spec=importlib.util.spec_from_file_location('cowork_dispatch','scripts/cowork_dispatch.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
cid='11111111-1111-4111-8111-111111111111'
contract={'schema_version':1,'record':'DispatchContract','contract_id':cid,'role':'builder','phase':'build','controller':'claude','kind':'dispatch','purpose':'launch','site':'controller.package_a_probe','resume_session_id':None,'created':1.0}
contract=m.validate_dispatch_contract(contract)
allow=m.validate_dispatch_decision(m.decide(contract),contract)
fact={'allowed':False,'refusal_code':'controller_not_allowed','refusal_message':'denied','source':'policy_guard'}
refuse=m.validate_dispatch_decision(m.decide(contract,policy_result=fact),contract)
source={'kind':'trace_event','event_id':'event-1','event_name':'role.send.start','session_id':None,'prompt_sha256':None,'created':1.0}
delivery={'prompt_kind':'pending_replay','prompt_sha256':'%s','prompt_bytes':7}
keyfn=getattr(m,%s)
key1=keyfn('builder','pending_replay',source,1);key2=keyfn('builder','pending_replay',source,1);key3=keyfn('builder','pending_replay',source,2)
link={'schema_version':1,'record':'AttemptLink','attempt_id':'22222222-2222-4222-8222-222222222222','role':'builder','phase':'build','kind':'pending_replay','source_ref':source,'delivery_ref':delivery,'idempotency_key':key1,'created':2.0}
link=m.validate_attempt_link(link)
records=[contract,allow,link]
contract_keys={'schema_version','record','contract_id','role','phase','controller','kind','purpose','site','resume_session_id','created'}
decision_keys={'schema_version','record','decision_id','contract_id','outcome','refusal_code','refusal_message','source','spawned','trace_event_id'}
link_keys={'schema_version','record','attempt_id','role','phase','kind','source_ref','delivery_ref','idempotency_key','created'}
assert set(contract)==contract_keys and contract['record']=='DispatchContract' and contract['contract_id']==cid and contract['kind']=='dispatch' and contract['purpose']=='launch'
assert set(allow)==decision_keys and set(refuse)==decision_keys
uuid.UUID(allow['decision_id']);uuid.UUID(refuse['decision_id'])
assert allow['record']=='DispatchDecision' and allow['contract_id']==cid and allow['outcome']=='allow'
assert allow['refusal_code'] is None and allow['refusal_message'] is None and allow['source'] is None and allow['spawned'] is False and allow['trace_event_id'] is None
assert refuse['record']=='DispatchDecision' and refuse['contract_id']==cid and refuse['outcome']=='refuse'
assert refuse['refusal_code']=='controller_not_allowed' and refuse['refusal_message']=='denied' and refuse['source']=='policy_guard' and refuse['spawned'] is False and refuse['trace_event_id'] is None
assert set(link)==link_keys and link['record']=='AttemptLink' and link['source_ref']==source and link['delivery_ref']==delivery and link['idempotency_key']==key1
uuid.UUID(link['attempt_id'])
assert key1==key2 and key1.startswith('builder:pending_replay:') and key1.endswith(':1')
assert key3.startswith('builder:pending_replay:') and key3.endswith(':2') and key1.rsplit(':',1)[0]==key3.rsplit(':',1)[0]
assert [json.loads(json.dumps(x,sort_keys=True)) for x in records]==records
print(json.dumps({'records':3,'allow':True,'refuse':True,'key':True},sort_keys=True))
""" % ("a"*64,json.dumps(builder_name))


def _package_a_worker_packet(directory: str,candidate: Dict[str,Any]) -> Dict[str,Any]:
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    item=capped_regular_file_info(evidence.get("packet_path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(evidence.get("packet_path"),str) else None
    if not item or item.get("sha256")!=evidence.get("packet_sha256"): raise ControllerError("Package A worker packet binding changed")
    try: packet=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A worker packet is unreadable") from exc
    structured=normalize_package_a_structured(packet.get("structured") if isinstance(packet,dict) else None)
    if not structured or structured.get("outcome")!="completed": raise ControllerError("Package A candidate requires a completed strict worker packet")
    return {"path":item["path"],"sha256":item["sha256"],"structured":structured}


def _package_a_verification_specs(worker: Dict[str,Any]) -> List[Dict[str,Any]]:
    if worker["structured"]["record_api_summary"]["idempotency_key_builder"]!="build_attempt_link_idempotency_key(role, kind, source_ref, ordinal)":
        raise ControllerError("Package A worker API summary changed")
    builder="build_attempt_link_idempotency_key"
    return [
        {"label":"test_cowork","argv":["python3","-m","unittest","scripts/test_cowork.py"],"timeout":300,"kind":"unittest"},
        {"label":"characterization","argv":["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],"timeout":180,"kind":"characterization"},
        {"label":"diff_check","argv":["git","diff","--check"],"timeout":60,"kind":"empty"},
        {"label":"candidate_delta","argv":["controller","package-a-delta"],"timeout":0,"kind":"controller"},
        {"label":"json_probe","argv":["python3","-c",_package_a_probe_code(builder)],"timeout":30,"kind":"probe"},
    ]


def _package_b_structural_migration_passes(wt: str) -> bool:
    # Inspect definitions and decorators, not incidental prose mentioning a
    # retired witness name.
    import ast
    char_path=os.path.join(wt,"scripts/test_dispatch_contract_characterization.py")
    try: tree=ast.parse(Path(char_path).read_text(encoding="utf-8"),filename=char_path)
    except (OSError,SyntaxError,UnicodeError): return False
    target=None
    for node in tree.body:
        if isinstance(node,ast.ClassDef) and node.name=="MissingDispatchContractTest":
            if target is not None: return False
            target=node
    if target is None: return False
    methods={node.name:node for node in target.body if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef))}
    if (PACKAGE_B_RETIRED_WITNESS in methods or PACKAGE_B_UNIFORM_REFUSAL_METHOD not in methods or
            any(name not in methods for name in PACKAGE_B_PACKAGE_C_MARKERS)):
        return False
    def expected_failure(node: Any) -> bool:
        for decorator in node.decorator_list:
            if isinstance(decorator,ast.Attribute) and isinstance(decorator.value,ast.Name) and decorator.value.id=="unittest" and decorator.attr=="expectedFailure":
                return True
            if isinstance(decorator,ast.Name) and decorator.id=="expectedFailure": return True
        return False
    return (not expected_failure(methods[PACKAGE_B_UNIFORM_REFUSAL_METHOD]) and
            all(expected_failure(methods[name]) for name in PACKAGE_B_PACKAGE_C_MARKERS))


def _package_c_structural_migration_passes(wt: str) -> bool:
    # Both contract methods must be ordinary passes (no expectedFailure
    # decorator anywhere in the module), and both retired witness methods
    # must no longer exist under any class.
    import ast
    char_path=os.path.join(wt,"scripts/test_dispatch_contract_characterization.py")
    try: tree=ast.parse(Path(char_path).read_text(encoding="utf-8"),filename=char_path)
    except (OSError,SyntaxError,UnicodeError): return False
    def expected_failure(node: Any) -> bool:
        for decorator in node.decorator_list:
            if isinstance(decorator,ast.Attribute) and isinstance(decorator.value,ast.Name) and decorator.value.id=="unittest" and decorator.attr=="expectedFailure":
                return True
            if isinstance(decorator,ast.Name) and decorator.id=="expectedFailure": return True
        return False
    classes={}; all_method_names=set(); any_expected_failure=False
    for node in tree.body:
        if isinstance(node,ast.ClassDef):
            classes.setdefault(node.name,[]).append(node)
            for method in node.body:
                if isinstance(method,(ast.FunctionDef,ast.AsyncFunctionDef)):
                    all_method_names.add(method.name)
                    if expected_failure(method): any_expected_failure=True
    if any_expected_failure: return False
    target_defs=classes.get("MissingDispatchContractTest")
    if not target_defs or len(target_defs)!=1: return False
    methods={node.name:node for node in target_defs[0].body if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef))}
    for dotted in PACKAGE_C_CONTRACT_TESTS:
        _mod,cls,method=dotted.rsplit(".",2)
        if cls!="MissingDispatchContractTest" or method not in methods: return False
    for method in PACKAGE_C_RETIRED_WITNESSES:
        if method in all_method_names: return False
    return True


def _package_a_gate_result(spec: Dict[str,Any],wt: str) -> Dict[str,Any]:
    if spec["kind"]=="controller":
        return {"exit_code":0,"timed_out":False,"output_limit_exceeded":False,"output_sha256":digest_bytes(b""),"output_bytes":0,
                "output_total_seen":0,"output":b"","spawn_error":None,"cleanup_error":None,"counters":{},"passed":True}
    if spec["kind"]=="package_b_structural":
        passed=_package_b_structural_migration_passes(wt)
        output=b"" if passed else b"structural_migration_check_failed"
        return {"exit_code":0 if passed else 1,"timed_out":False,"output_limit_exceeded":False,
                "output_sha256":digest_bytes(output),"output_bytes":len(output),"output_total_seen":len(output),
                "output":output,"spawn_error":None,"cleanup_error":None,"counters":{},"passed":passed}
    if spec["kind"]=="package_c_structural":
        passed=_package_c_structural_migration_passes(wt)
        output=b"" if passed else b"structural_migration_check_failed"
        return {"exit_code":0 if passed else 1,"timed_out":False,"output_limit_exceeded":False,
                "output_sha256":digest_bytes(output),"output_bytes":len(output),"output_total_seen":len(output),
                "output":output,"spawn_error":None,"cleanup_error":None,"counters":{},"passed":passed}
    if spec["kind"]=="characterization_c":
        run=_bounded_run(spec["argv"],wt,spec["timeout"])
        passed=(run["exit_code"]==0 and not run["timed_out"] and not run["output_limit_exceeded"] and run.get("spawn_error") is None and run.get("cleanup_error") is None)
        try: counters=_package_a_unittest_counters(run["output"])
        except ControllerError: counters={"parse_error":1}; passed=False
        if passed:
            passed=(counters.get("failures",1)==0 and counters.get("errors",1)==0 and counters.get("unexpected_successes",1)==0
                    and counters.get("tests",0)>=1 and counters.get("expected_failures",-1)==PACKAGE_C_CHAR_EXPECTED_FAILURES)
        return {**{key:run[key] for key in ("exit_code","timed_out","output_limit_exceeded","output_sha256","output_bytes","output_total_seen","output","spawn_error","cleanup_error")},"counters":counters,"passed":passed}
    if spec["kind"]=="focused_unittest":
        run=_bounded_run(spec["argv"],wt,spec["timeout"])
        passed=(run["exit_code"]==0 and not run["timed_out"] and not run["output_limit_exceeded"] and run.get("spawn_error") is None and run.get("cleanup_error") is None)
        try: counters=_package_a_unittest_counters(run["output"])
        except ControllerError: counters={"parse_error":1}; passed=False
        if passed:
            passed=(counters.get("failures",1)==0 and counters.get("errors",1)==0 and counters.get("unexpected_successes",1)==0
                    and counters.get("expected_failures",1)==0 and counters.get("tests",0)>=1)
        return {**{key:run[key] for key in ("exit_code","timed_out","output_limit_exceeded","output_sha256","output_bytes","output_total_seen","output","spawn_error","cleanup_error")},"counters":counters,"passed":passed}
    if spec["kind"]=="characterization_b":
        run=_bounded_run(spec["argv"],wt,spec["timeout"])
        passed=(run["exit_code"]==0 and not run["timed_out"] and not run["output_limit_exceeded"] and run.get("spawn_error") is None and run.get("cleanup_error") is None)
        try: counters=_package_a_unittest_counters(run["output"])
        except ControllerError: counters={"parse_error":1}; passed=False
        if passed:
            passed=(counters.get("failures",1)==0 and counters.get("errors",1)==0 and counters.get("unexpected_successes",1)==0
                    and counters.get("tests",0)>=1 and counters.get("expected_failures",-1)==PACKAGE_B_CHAR_EXPECTED_FAILURES)
        return {**{key:run[key] for key in ("exit_code","timed_out","output_limit_exceeded","output_sha256","output_bytes","output_total_seen","output","spawn_error","cleanup_error")},"counters":counters,"passed":passed}
    run=_bounded_run(spec["argv"],wt,spec["timeout"])
    counters={}; passed=(run["exit_code"]==0 and not run["timed_out"] and not run["output_limit_exceeded"] and run.get("spawn_error") is None and run.get("cleanup_error") is None)
    if spec["kind"] in {"unittest","characterization"}:
        try: counters=_package_a_unittest_counters(run["output"])
        except ControllerError: counters={"parse_error":1}; passed=False
        if passed:
            passed=(counters["failures"]==0 and counters["errors"]==0 and counters["unexpected_successes"]==0 and counters["tests"]>0)
            if spec["kind"]=="characterization": passed=passed and counters["tests"]==32 and counters["expected_failures"]==3
    elif passed and spec["kind"]=="empty": passed=run["output_bytes"]==0
    elif passed and spec["kind"]=="probe":
        try: probe=json.loads(run["output"].decode("utf-8").strip())
        except (UnicodeDecodeError,json.JSONDecodeError): probe=None
        passed=probe=={"allow":True,"key":True,"records":3,"refuse":True}
    elif passed and spec["kind"]=="package_b_probe": passed=_package_b_probe_passes(run["output"])
    elif passed and spec["kind"]=="package_c_probe": passed=_package_c_probe_passes(run["output"])
    return {**{key:run[key] for key in ("exit_code","timed_out","output_limit_exceeded","output_sha256","output_bytes","output_total_seen","output","spawn_error","cleanup_error")},"counters":counters,"passed":passed}


def _package_a_write_gate_terminal(path: str,header: Dict[str,Any],raw: bytes) -> None:
    parent=os.path.dirname(path)
    if os.path.lexists(path): raise ControllerError("Package A gate terminal already exists")
    os.makedirs(parent,mode=0o700,exist_ok=True); fd,temp=tempfile.mkstemp(prefix=".tmp-gate-",dir=parent)
    try:
        with os.fdopen(fd,"wb") as out:
            out.write(json.dumps(header,sort_keys=True,separators=(",",":")).encode()+b"\n"+raw); out.flush(); os.fsync(out.fileno())
        os.replace(temp,path)
    finally:
        try: os.unlink(temp)
        except FileNotFoundError: pass


def _command_package_a_gate_wrapper(args: argparse.Namespace) -> Dict[str,Any]:
    try: spec=json.loads(args.spec_json)
    except json.JSONDecodeError as exc: raise ControllerError("Package A gate wrapper spec is malformed") from exc
    if not isinstance(spec,dict) or digest_bytes(json.dumps(spec,sort_keys=True,separators=(",",":")).encode())!=args.spec_sha256:
        raise ControllerError("Package A gate wrapper spec binding changed")
    claim={"schema_version":SCHEMA,"kind":"package_a_gate_wrapper_start","index":args.index,"spec_sha256":args.spec_sha256,
        "static_sha256":args.static_sha256,"wrapper_nonce":args.wrapper_nonce,"wrapper_argv_sha256":args.wrapper_digest,
        "pid":os.getpid(),"pgid":os.getpgrp(),"started_at":utc(),"deadline":args.deadline}
    try:
        fd=os.open(args.start_path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    except FileExistsError as exc:
        raise ControllerError("Package A gate wrapper start is already claimed") from exc
    try:
        with os.fdopen(fd,"w",encoding="utf-8") as out: json.dump(claim,out,sort_keys=True,separators=(",",":")); out.write("\n"); out.flush(); os.fsync(out.fileno())
    except Exception:
        try: os.close(fd)
        except OSError: pass
        raise
    result=_package_a_gate_result(spec,args.cwd); raw=result.pop("output")
    header={"schema_version":SCHEMA,"kind":"package_a_gate_terminal","index":args.index,"label":spec.get("label"),"spec_sha256":args.spec_sha256,
        "static_sha256":args.static_sha256,"result":result}
    _package_a_write_gate_terminal(args.terminal_path,header,raw)
    return {"schema_version":SCHEMA,"operation":"package_a_gate_wrapper","passed":result["passed"]}


def _package_a_read_gate_terminal(path: str,verify_dir: str,spec: Dict[str,Any],index: int,static_sha: str) -> Tuple[Dict[str,Any],bytes,Dict[str,Any]]:
    info=capped_regular_file_info(path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT+64*1024)
    if not info: raise ControllerError("Package A gate terminal is missing or unsafe")
    try: blob=Path(info["path"]).read_bytes(); first,raw=blob.split(b"\n",1); header=json.loads(first)
    except (OSError,ValueError,json.JSONDecodeError) as exc: raise ControllerError("Package A gate terminal is malformed") from exc
    result=header.get("result") if isinstance(header,dict) else None
    result_keys={"exit_code","timed_out","output_limit_exceeded","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
    if (not isinstance(header,dict) or set(header)!={"schema_version","kind","index","label","spec_sha256","static_sha256","result"} or
            header.get("schema_version")!=SCHEMA or header.get("kind")!="package_a_gate_terminal" or header.get("index")!=index or
            header.get("label")!=spec.get("label") or header.get("spec_sha256")!=digest_bytes(json.dumps(spec,sort_keys=True,separators=(",",":")).encode()) or
            header.get("static_sha256")!=static_sha or not isinstance(result,dict) or set(result)!=result_keys or
            result.get("output_sha256")!=digest_bytes(raw) or result.get("output_bytes")!=len(raw)):
        raise ControllerError("Package A gate terminal binding changed")
    return result,raw,info


def _package_a_execute_gate(spec: Dict[str,Any],index: int,wt: str,verify_dir: str,terminal_path: str,start_path: str,static: Dict[str,Any],wrapper_nonce: str,deadline_text: str,env: Optional[Dict[str,str]]=None) -> Tuple[Dict[str,Any],bytes,Dict[str,Any]]:
    static_sha=digest_bytes(json.dumps(static,sort_keys=True,separators=(",",":")).encode()); spec_sha=digest_bytes(json.dumps(spec,sort_keys=True,separators=(",",":")).encode())
    wrapper_core={"terminal_path":terminal_path,"start_path":start_path,"index":index,"cwd":wt,"spec_sha256":spec_sha,"static_sha256":static_sha,"wrapper_nonce":wrapper_nonce,"deadline":deadline_text}
    wrapper_digest=digest_bytes(json.dumps(wrapper_core,sort_keys=True,separators=(",",":")).encode())
    if os.path.lexists(terminal_path): return _package_a_read_gate_terminal(terminal_path,verify_dir,spec,index,static_sha)
    start=None; proc=None
    if os.path.lexists(start_path):
        item=capped_regular_file_info(start_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        try: start=json.loads(Path(item["path"]).read_text()) if item else None
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A gate start receipt is unreadable") from exc
        if (not isinstance(start,dict) or set(start)!={"schema_version","kind","index","spec_sha256","static_sha256","wrapper_nonce","wrapper_argv_sha256","pid","pgid","started_at","deadline"} or
                start.get("schema_version")!=SCHEMA or start.get("kind")!="package_a_gate_wrapper_start" or start.get("index")!=index or
                start.get("spec_sha256")!=spec_sha or start.get("static_sha256")!=static_sha or start.get("wrapper_nonce")!=wrapper_nonce or
                start.get("wrapper_argv_sha256")!=wrapper_digest or start.get("deadline")!=deadline_text or not isinstance(start.get("pid"),int) or not isinstance(start.get("pgid"),int)):
            raise ControllerError("Package A gate start receipt binding changed")
        _parse_utc_instant(start.get("started_at")); _parse_utc_instant(start.get("deadline"))
        pid,pgid=start["pid"],start["pgid"]
    else:
        argv=[sys.executable,os.path.abspath(__file__),"package-a-gate-wrapper","--terminal-path",terminal_path,"--index",str(index),"--cwd",wt,
              "--spec-json",json.dumps(spec,separators=(",",":")),"--spec-sha256",spec_sha,"--static-sha256",static_sha,"--start-path",start_path,
              "--wrapper-nonce",wrapper_nonce,"--wrapper-digest",wrapper_digest,"--deadline",deadline_text]
        try:
            proc=subprocess.Popen(argv,cwd=wt,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,stdin=subprocess.DEVNULL,start_new_session=True,close_fds=True,env=env)
        except OSError as exc: raise ControllerError("Package A gate wrapper spawn failed") from exc
        pid=proc.pid; pgid=proc.pid
    deadline=_parse_utc_instant(deadline_text)
    while dt.datetime.now(dt.timezone.utc)<deadline:
        if os.path.lexists(terminal_path):
            if proc:
                try: proc.wait(timeout=2)
                except subprocess.TimeoutExpired: pass
            return _package_a_read_gate_terminal(terminal_path,verify_dir,spec,index,static_sha)
        if not process_alive(pid,pgid): break
        time.sleep(.05)
    if os.path.lexists(terminal_path):
        if proc:
            try: proc.wait(timeout=2)
            except subprocess.TimeoutExpired: pass
        return _package_a_read_gate_terminal(terminal_path,verify_dir,spec,index,static_sha)
    if os.path.lexists(start_path) and not process_alive(pid,pgid):
        counters={"parse_error":1} if spec["kind"] in {"unittest","characterization","characterization_b","characterization_c","focused_unittest"} else {}
        result={"exit_code":127,"timed_out":False,"output_limit_exceeded":False,"output_sha256":digest_bytes(b""),"output_bytes":0,
            "output_total_seen":0,"spawn_error":"PackageAGateWrapperLost","cleanup_error":None,"counters":counters,"passed":False}
        header={"schema_version":SCHEMA,"kind":"package_a_gate_terminal","index":index,"label":spec.get("label"),"spec_sha256":spec_sha,
            "static_sha256":static_sha,"result":result}
        _package_a_write_gate_terminal(terminal_path,header,b"")
        return _package_a_read_gate_terminal(terminal_path,verify_dir,spec,index,static_sha)
    raise ControllerError("Package A gate wrapper remains ambiguous without terminal evidence")


def _package_a_gate_start_intact(path: str,verify_dir: str,spec: Dict[str,Any],index: int,wt: str,static: Dict[str,Any],wrapper_nonce: str,deadline_text: str) -> Dict[str,Any]:
    info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
    if not info: raise ControllerError("Package A gate start receipt is missing or unsafe")
    try: start=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A gate start receipt is unreadable") from exc
    spec_sha=digest_bytes(json.dumps(spec,sort_keys=True,separators=(",",":")).encode()); static_sha=digest_bytes(json.dumps(static,sort_keys=True,separators=(",",":")).encode())
    wrapper_core={"terminal_path":os.path.join(verify_dir,"%d-%s.terminal.bin"%(index,spec["label"])),"start_path":path,"index":index,"cwd":wt,
        "spec_sha256":spec_sha,"static_sha256":static_sha,"wrapper_nonce":wrapper_nonce,"deadline":deadline_text}
    wrapper_digest=digest_bytes(json.dumps(wrapper_core,sort_keys=True,separators=(",",":")).encode())
    keys={"schema_version","kind","index","spec_sha256","static_sha256","wrapper_nonce","wrapper_argv_sha256","pid","pgid","started_at","deadline"}
    if (not isinstance(start,dict) or set(start)!=keys or start.get("schema_version")!=SCHEMA or start.get("kind")!="package_a_gate_wrapper_start" or
            start.get("index")!=index or start.get("spec_sha256")!=spec_sha or start.get("static_sha256")!=static_sha or start.get("wrapper_nonce")!=wrapper_nonce or
            start.get("wrapper_argv_sha256")!=wrapper_digest or start.get("deadline")!=deadline_text or isinstance(start.get("pid"),bool) or not isinstance(start.get("pid"),int) or
            isinstance(start.get("pgid"),bool) or not isinstance(start.get("pgid"),int)):
        raise ControllerError("Package A gate start receipt binding changed")
    _parse_utc_instant(start.get("started_at")); _parse_utc_instant(start.get("deadline"))
    return info


def _package_a_receipt_passes(spec: Dict[str,Any],receipt: Dict[str,Any],raw: bytes) -> bool:
    if (receipt.get("exit_code")!=0 or receipt.get("timed_out") is not False or
            receipt.get("output_limit_exceeded") is not False or receipt.get("spawn_error") is not None or receipt.get("cleanup_error") is not None or not _sha256_hex(receipt.get("output_sha256")) or
            isinstance(receipt.get("output_bytes"),bool) or not isinstance(receipt.get("output_bytes"),int) or receipt["output_bytes"]<0): return False
    counters=receipt.get("counters")
    if spec["kind"] in {"unittest","characterization"}:
        keys={"tests","failures","errors","skipped","expected_failures","unexpected_successes"}
        if not isinstance(counters,dict) or set(counters)!=keys or any(isinstance(counters[k],bool) or not isinstance(counters[k],int) or counters[k]<0 for k in keys): return False
        try: parsed=_package_a_unittest_counters(raw)
        except ControllerError: return False
        if counters!=parsed: return False
        if counters["tests"]<1 or counters["failures"] or counters["errors"] or counters["unexpected_successes"]: return False
        if spec["kind"]=="characterization" and (counters["tests"]!=32 or counters["expected_failures"]!=3): return False
    elif spec["kind"]=="focused_unittest":
        keys={"tests","failures","errors","skipped","expected_failures","unexpected_successes"}
        if not isinstance(counters,dict) or set(counters)!=keys or any(isinstance(counters[k],bool) or not isinstance(counters[k],int) or counters[k]<0 for k in keys): return False
        try: parsed=_package_a_unittest_counters(raw)
        except ControllerError: return False
        if counters!=parsed: return False
        if counters["tests"]<1 or counters["failures"] or counters["errors"] or counters["unexpected_successes"] or counters["expected_failures"]!=0: return False
    elif spec["kind"]=="characterization_b":
        keys={"tests","failures","errors","skipped","expected_failures","unexpected_successes"}
        if not isinstance(counters,dict) or set(counters)!=keys or any(isinstance(counters[k],bool) or not isinstance(counters[k],int) or counters[k]<0 for k in keys): return False
        try: parsed=_package_a_unittest_counters(raw)
        except ControllerError: return False
        if counters!=parsed: return False
        if counters["tests"]<1 or counters["failures"] or counters["errors"] or counters["unexpected_successes"]: return False
        if counters["expected_failures"]!=PACKAGE_B_CHAR_EXPECTED_FAILURES: return False
    elif spec["kind"]=="characterization_c":
        keys={"tests","failures","errors","skipped","expected_failures","unexpected_successes"}
        if not isinstance(counters,dict) or set(counters)!=keys or any(isinstance(counters[k],bool) or not isinstance(counters[k],int) or counters[k]<0 for k in keys): return False
        try: parsed=_package_a_unittest_counters(raw)
        except ControllerError: return False
        if counters!=parsed: return False
        if counters["tests"]<1 or counters["failures"] or counters["errors"] or counters["unexpected_successes"]: return False
        if counters["expected_failures"]!=PACKAGE_C_CHAR_EXPECTED_FAILURES: return False
    elif counters!={}: return False
    if spec["kind"] in {"empty","controller","package_b_structural","package_c_structural"} and receipt["output_bytes"]!=0: return False
    if spec["kind"]=="probe":
        try: probe=json.loads(raw.decode("utf-8").strip())
        except (UnicodeDecodeError,json.JSONDecodeError): return False
        if probe!={"allow":True,"key":True,"records":3,"refuse":True}: return False
    if spec["kind"]=="package_b_probe" and not _package_b_probe_passes(raw): return False
    if spec["kind"]=="package_c_probe" and not _package_c_probe_passes(raw): return False
    return True


def _package_a_receipt_consistent(spec: Dict[str,Any],receipt: Dict[str,Any],output_info: Dict[str,Any],raw: bytes) -> bool:
    if (isinstance(receipt.get("exit_code"),bool) or not isinstance(receipt.get("exit_code"),int) or
            not isinstance(receipt.get("timed_out"),bool) or not isinstance(receipt.get("output_limit_exceeded"),bool) or
            (receipt.get("spawn_error") is not None and (not isinstance(receipt.get("spawn_error"),str) or len(receipt["spawn_error"].encode())>120)) or
            (receipt.get("cleanup_error") is not None and receipt.get("cleanup_error")!="permission_denied") or
            not _sha256_hex(receipt.get("output_sha256")) or isinstance(receipt.get("output_bytes"),bool) or
            not isinstance(receipt.get("output_bytes"),int) or receipt["output_bytes"]<0 or receipt["output_bytes"]>PACKAGE_A_MAX_GATE_OUTPUT+65536 or
            isinstance(receipt.get("output_total_seen"),bool) or not isinstance(receipt.get("output_total_seen"),int) or
            receipt["output_total_seen"]<receipt["output_bytes"] or receipt["output_total_seen"]>PACKAGE_A_MAX_GATE_OUTPUT+65536 or
            not isinstance(receipt.get("counters"),dict) or not isinstance(receipt.get("passed"),bool) or
            receipt.get("output_path")!=output_info.get("path") or receipt.get("output_sha256")!=output_info.get("sha256") or receipt.get("output_bytes")!=output_info.get("bytes")):
        return False
    if receipt["output_limit_exceeded"]:
        if receipt["output_bytes"]!=PACKAGE_A_MAX_GATE_OUTPUT or receipt["output_total_seen"]<=receipt["output_bytes"]: return False
    elif receipt["output_total_seen"]!=receipt["output_bytes"]:
        return False
    if spec["kind"] in {"unittest","characterization","focused_unittest","characterization_b","characterization_c"}:
        try: expected_counters=_package_a_unittest_counters(raw)
        except ControllerError: expected_counters={"parse_error":1}
        if receipt.get("counters")!=expected_counters: return False
    elif receipt.get("counters")!={}: return False
    derived=_package_a_receipt_passes(spec,receipt,raw)
    if receipt["passed"]!=derived: return False
    if not derived and not (receipt["exit_code"]!=0 or receipt["timed_out"] or receipt["output_limit_exceeded"] or receipt.get("spawn_error") or receipt.get("cleanup_error") or spec["kind"] in {"unittest","characterization","focused_unittest","characterization_b","characterization_c","empty","probe","package_b_probe","package_c_probe"}):
        return False
    return True


def _package_a_verification_static(state: Dict[str,Any],candidate: Dict[str,Any],delta: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    return {"work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
            "implementer_attempt_id":state["attempt"]["id"],"implementer_session_id":state["attempt"]["provider_session_id"],
            "model":"sonnet","effort":"medium","policy":POLICY_ID,"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],"delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],
            "delta_sha256":delta["sha256"],"candidate_fingerprint_digest":candidate["evidence"]["worktree_fingerprint"]["digest"]}


def _package_a_verification_dir(directory: str,candidate: Dict[str,Any]) -> str:
    ident=candidate.get("id")
    if not isinstance(ident,str) or not re.fullmatch(r"package-a-[0-9a-f]{32}",ident): raise ControllerError("Package A verification candidate id is unsafe")
    return os.path.join(directory,"package-a-verification",ident)


def _package_a_validate_verification(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_verification") if isinstance(state.get("package_a_verification"),dict) else {}
    if set(bound)!={"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"}: raise ControllerError("Package A verification state binding is malformed")
    verify_dir=_package_a_verification_dir(directory,candidate); intent_info=capped_regular_file_info(bound.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("intent_path"),str) else None
    aggregate_info=capped_regular_file_info(bound.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("aggregate_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not aggregate_info or aggregate_info.get("sha256")!=bound.get("aggregate_sha256"): raise ControllerError("Package A verification intent or aggregate changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text()); aggregate=json.loads(Path(aggregate_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification evidence is unreadable") from exc
    static=_package_a_verification_static(state,candidate,delta,baseline); specs=_package_a_verification_specs(_package_a_worker_packet(directory,candidate))
    expected_intent_keys={"schema_version","kind","created_at","static","specs","receipt_paths","output_paths","terminal_paths","start_paths","aggregate_path"}
    if (not isinstance(intent,dict) or set(intent)!=expected_intent_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_a_verification_intent" or
            not isinstance(intent.get("created_at"),str) or intent.get("static")!=static or intent.get("specs")!=specs or
            intent.get("receipt_paths")!=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("output_paths")!=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)] or intent.get("aggregate_path")!=aggregate_info["path"]):
        raise ControllerError("Package A verification intent binding changed")
    if (intent.get("terminal_paths")!=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("start_paths")!=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]):
        raise ControllerError("Package A verification execution intent binding changed")
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,intent["receipt_paths"],intent["output_paths"],intent["terminal_paths"],intent["start_paths"])):
        info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT)
        if not info or not output_info: raise ControllerError("Package A verification receipt or output is missing or unsafe")
        try: raw=Path(output_info["path"]).read_bytes()
        except OSError as exc: raise ControllerError("Package A verification output is unreadable") from exc
        try: receipt=json.loads(Path(info["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification receipt is unreadable") from exc
        terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT+64*1024)
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
        receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
        structurally_bound=(isinstance(receipt,dict) and set(receipt)==receipt_keys and receipt.get("schema_version")==SCHEMA and receipt.get("kind")=="package_a_verification_receipt" and
                receipt.get("index")==index and receipt.get("label")==spec["label"] and receipt.get("argv")==spec["argv"] and receipt.get("cwd")==state["worktree"]["path"] and
                receipt.get("timeout_seconds")==spec["timeout"] and receipt.get("static")==static and bool(terminal_info) and
                receipt.get("start_path")==start_info["path"] and receipt.get("start_sha256")==start_info["sha256"] and
                receipt.get("terminal_path")==terminal_info["path"] and receipt.get("terminal_sha256")==terminal_info["sha256"])
        if not structurally_bound: raise ControllerError("Package A verification receipt structure changed")
        if not _package_a_receipt_consistent(spec,receipt,output_info,raw): raise ControllerError("Package A verification receipt semantics changed: "+spec["label"])
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
    aggregate_keys={"schema_version","kind","created_at","static","receipts","all_passed","post_fingerprint"}
    if (not isinstance(aggregate,dict) or set(aggregate)!=aggregate_keys or aggregate.get("schema_version")!=SCHEMA or aggregate.get("kind")!="package_a_verification_aggregate" or
            aggregate.get("created_at")!=intent["created_at"] or aggregate.get("static")!=static or aggregate.get("receipts")!=refs or aggregate.get("all_passed") is not all(row["passed"] for row in refs) or
            aggregate.get("post_fingerprint")!=candidate["evidence"]["worktree_fingerprint"] or bound.get("candidate_id")!=candidate["id"] or bound.get("evidence_digest")!=candidate["evidence_digest"]):
        raise ControllerError("Package A verification aggregate binding changed")
    return {"intent":intent,"aggregate":aggregate,"aggregate_info":aggregate_info,"refs":refs}


def _command_verify_package_a(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A verification requires its canonical awaiting gate")
    baseline=_package_a_prerequisites_intact(directory,state)
    if _is_package_a_v4(state): return _command_verify_package_a_v4(directory,state,candidate,baseline)
    if _is_package_a_v5(state): return _command_verify_package_a_v5(directory,state,candidate,baseline)
    _package_a_attempt_intact(state.get("attempt")); _package_a_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); _package_a_worker_packet(directory,candidate)
    if state.get("package_a_verification"):
        verified=_package_a_validate_verification(directory,state,candidate,baseline,delta)
        return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":True,"aggregate_path":verified["aggregate_info"]["path"],"aggregate_sha256":verified["aggregate_info"]["sha256"],"all_passed":verified["aggregate"]["all_passed"]}
    _top_verify=os.path.join(directory,"package-a-verification")
    if os.path.lexists(_top_verify) and (os.path.islink(_top_verify) or not os.path.isdir(_top_verify) or not inside(os.path.realpath(_top_verify),directory)): raise ControllerError("Package A verification top-level directory is unsafe")
    static=_package_a_verification_static(state,candidate,delta,baseline); specs=_package_a_verification_specs(_package_a_worker_packet(directory,candidate)); verify_dir=_package_a_verification_dir(directory,candidate)
    if os.path.lexists(verify_dir) and (os.path.islink(verify_dir) or not os.path.isdir(verify_dir)): raise ControllerError("Package A verification directory is unsafe")
    os.makedirs(verify_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(verify_dir,"intent.json"); aggregate_path=os.path.join(verify_dir,"aggregate.json"); receipt_paths=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)]; output_paths=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    terminal_paths=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)]; start_paths=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]
    base_intent={"schema_version":SCHEMA,"kind":"package_a_verification_intent","static":static,"specs":specs,"receipt_paths":receipt_paths,"output_paths":output_paths,
                 "terminal_paths":terminal_paths,"start_paths":start_paths,"aggregate_path":aggregate_path}
    existing_intent=capped_regular_file_info(intent_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not existing_intent: raise ControllerError("Package A verification intent is unsafe")
    if existing_intent:
        try: intent=json.loads(Path(existing_intent["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification intent is unreadable") from exc
        if set(intent)!=(set(base_intent)|{"created_at"}) or {k:v for k,v in intent.items() if k!="created_at"}!=base_intent or not isinstance(intent.get("created_at"),str): raise ControllerError("Package A verification orphan intent conflicts")
    else:
        if os.path.lexists(aggregate_path) or any(os.path.lexists(path) for path in receipt_paths+output_paths+terminal_paths+start_paths): raise ControllerError("Package A verification output cannot precede durable intent")
        intent={**base_intent,"created_at":utc()}; existing_intent=_package_a_adopt_json(intent_path,verify_dir,intent,"verification intent")
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,receipt_paths,output_paths,terminal_paths,start_paths)):
        before=worktree_fingerprint(state["worktree"]["path"])
        if before!=candidate["evidence"]["worktree_fingerprint"]: raise ControllerError("Package A candidate changed before deterministic gate")
        prior=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(path) else None
        if os.path.lexists(path) and not prior: raise ControllerError("Package A verification orphan receipt is unsafe")
        if prior:
            try: old=json.loads(Path(prior["path"]).read_text())
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification orphan receipt is unreadable") from exc
            receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
            output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT)
            terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT+64*1024)
            wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
            cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
            raw=Path(output_info["path"]).read_bytes() if output_info else b""
            if (not isinstance(old,dict) or set(old)!=receipt_keys or old.get("schema_version")!=SCHEMA or old.get("kind")!="package_a_verification_receipt" or old.get("index")!=index or old.get("label")!=spec["label"] or old.get("argv")!=spec["argv"] or old.get("cwd")!=state["worktree"]["path"] or old.get("timeout_seconds")!=spec["timeout"] or old.get("static")!=static or
                    not output_info or not terminal_info or old.get("start_path")!=start_info["path"] or old.get("start_sha256")!=start_info["sha256"] or
                    old.get("terminal_path")!=terminal_info["path"] or old.get("terminal_sha256")!=terminal_info["sha256"] or not _package_a_receipt_consistent(spec,old,output_info,raw)):
                raise ControllerError("Package A verification orphan receipt conflicts")
            info=prior; payload=old
        else:
            wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
            cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1])
            wrapper_deadline=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
            result,raw,terminal_info=_package_a_execute_gate(spec,index,state["worktree"]["path"],verify_dir,terminal_path,start_path,static,wrapper_nonce,wrapper_deadline)
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,wrapper_deadline)
            if spec["kind"]=="controller": _package_a_builder_delta(directory,state,candidate)
            after=worktree_fingerprint(state["worktree"]["path"])
            if after!=before: result["passed"]=False
            output_info=_package_a_adopt_bytes(output_path,verify_dir,raw,"verification output")
            result["output_path"]=output_info["path"]
            payload={"schema_version":SCHEMA,"kind":"package_a_verification_receipt","index":index,"label":spec["label"],"argv":spec["argv"],"cwd":state["worktree"]["path"],"timeout_seconds":spec["timeout"],"static":static,
                     "start_path":start_info["path"],"start_sha256":start_info["sha256"],"terminal_path":terminal_info["path"],"terminal_sha256":terminal_info["sha256"],**result}
            info=_package_a_adopt_json(path,verify_dir,payload,"verification receipt")
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":payload["counters"],"passed":payload["passed"]})
    all_passed=all(row["passed"] for row in refs)
    aggregate={"schema_version":SCHEMA,"kind":"package_a_verification_aggregate","created_at":intent["created_at"],"static":static,"receipts":refs,"all_passed":all_passed,"post_fingerprint":worktree_fingerprint(state["worktree"]["path"])}
    if aggregate["post_fingerprint"]!=candidate["evidence"]["worktree_fingerprint"]: raise ControllerError("Package A verification changed candidate")
    aggregate_info=_package_a_adopt_json(aggregate_path,verify_dir,aggregate,"verification aggregate")
    state["package_a_verification"]={"intent_path":intent_path,"intent_sha256":existing_intent["sha256"],"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    event_kind="package_a_verification_passed" if all_passed else "package_a_verification_failed"
    if not any(row.get("kind")==event_kind and row.get("aggregate_sha256")==aggregate_info["sha256"] for row in recent_events(directory)):
        append_event(directory,event_kind,candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],aggregate_sha256=aggregate_info["sha256"],
            gate_name="package-a-deterministic-verification/v1",policy=POLICY_ID,
            input_hashes={"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],"candidate_evidence_digest":candidate["evidence_digest"]},
            disposition="pass" if all_passed else "nonpass",next_state="awaiting_gate",all_passed=all_passed)
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":False,"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"all_passed":all_passed,"receipts":refs}


def _package_a_review_context(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_attempt_intact(state.get("attempt")); _package_a_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_validate_verification(directory,state,candidate,baseline,delta)
    changed=[row["path"] for row in delta["files"]]
    if changed!=["scripts/cowork_dispatch.py","scripts/test_cowork.py"]: raise ControllerError("Package A review changed-path binding is invalid")
    return {"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":changed}


def _package_a_review_schema(state: Dict[str,Any],context: Dict[str,Any],attempt_id: str,run: str,nonce: str) -> Dict[str,Any]:
    candidate=context["candidate"]; verification=context["verification"]
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","work_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce","candidate_id","evidence_digest","baseline_receipt_sha256","baseline_fingerprint_digest","delta_receipt_sha256","delta_sha256","verification_aggregate_sha256","verification_receipt_sha256s","implementer_attempt_id","implementer_session_id","implementer_model","implementer_effort","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_a_review"},"work_id":{"type":"string","const":state["work_id"]},
            "policy":{"type":"string","const":POLICY_ID},
            "review_attempt_id":{"type":"string","const":attempt_id},"backend":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"candidate_id":{"type":"string","const":candidate["id"]},
            "evidence_digest":{"type":"string","const":candidate["evidence_digest"]},"baseline_receipt_sha256":{"type":"string","const":state["package_a_prerequisites"]["sha256"]},
            "baseline_fingerprint_digest":{"type":"string","const":context["baseline"]["post_materialization_fingerprint"]["digest"]},
            "delta_receipt_sha256":{"type":"string","const":state["package_a_builder_delta"]["sha256"]},"delta_sha256":{"type":"string","const":context["delta"]["sha256"]},
            "verification_aggregate_sha256":{"type":"string","const":verification["aggregate_info"]["sha256"]},
            "verification_receipt_sha256s":{"type":"array","minItems":5,"maxItems":5,"items":{"type":"string"}},
            "implementer_attempt_id":{"type":"string","const":state["attempt"]["id"]},"implementer_session_id":{"type":"string","const":state["attempt"]["provider_session_id"]},
            "implementer_model":{"type":"string","const":"sonnet"},"implementer_effort":{"type":"string","const":"medium"},
            "changed_paths":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_a_review_expected(state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    verification=context["verification"]
    return {"schema_version":SCHEMA,"kind":"package_a_review","work_id":state["work_id"],"policy":POLICY_ID,"review_attempt_id":attempt["id"],"backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,
            "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_nonce":attempt["nonce"],"candidate_id":context["candidate"]["id"],
            "evidence_digest":context["candidate"]["evidence_digest"],"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":context["baseline"]["post_materialization_fingerprint"]["digest"],"delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],
            "delta_sha256":context["delta"]["sha256"],"verification_aggregate_sha256":verification["aggregate_info"]["sha256"],
            "verification_receipt_sha256s":[row["sha256"] for row in verification["refs"]],"implementer_attempt_id":state["attempt"]["id"],
            "implementer_session_id":state["attempt"]["provider_session_id"],"implementer_model":"sonnet","implementer_effort":"medium","changed_paths":context["changed_paths"]}


def _package_a_review_attempt_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package A review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"review attempt id"),(attempt.get("run_id"),"review run id"),(attempt.get("nonce"),"review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(directory,"package-a-review-attempts"); expected_schema=_package_a_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_a_review_expected(state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package A review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_A_CLAUDE_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=context["candidate"]["id"] or attempt.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(directory,"logs")),("stderr",os.path.join(directory,"logs"))))):
        raise ControllerError("Package A review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A review schema binding changed")
    return attempt


def _package_a_claude_session(stdout_path: str,directory: str,reviewer_session_id: str) -> str:
    info=capped_regular_file_info(stdout_path,os.path.join(directory,"logs"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP)
    if not info: raise ControllerError("Package A reviewer stdout is missing")
    try:
        for line in Path(info["path"]).read_text(encoding="utf-8").splitlines():
            try: row=json.loads(line)
            except json.JSONDecodeError: continue
            if isinstance(row,dict) and row.get("type")=="result" and isinstance(row.get("session_id"),str):
                if row["session_id"]!=reviewer_session_id: raise ControllerError("Package A reviewer session identity mismatch")
                return reviewer_session_id
    except ControllerError: raise
    except (OSError,UnicodeDecodeError) as exc: raise ControllerError("Package A reviewer stdout is unreadable") from exc
    raise ControllerError("Package A reviewer did not emit a typed result event")


def _package_a_claude_optional_session(stdout_path: str,directory: str,reviewer_session_id: str) -> Optional[str]:
    info=capped_regular_file_info(stdout_path,os.path.join(directory,"logs"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP)
    if not info: raise ControllerError("Package A reviewer stdout is missing")
    try:
        for line in Path(info["path"]).read_text(encoding="utf-8").splitlines():
            try: row=json.loads(line)
            except json.JSONDecodeError: continue
            if isinstance(row,dict) and row.get("type")=="result" and isinstance(row.get("session_id"),str):
                if row["session_id"]!=reviewer_session_id: raise ControllerError("Package A reviewer session identity mismatch")
                return reviewer_session_id
    except ControllerError: raise
    except (OSError,UnicodeDecodeError) as exc: raise ControllerError("Package A reviewer stdout is unreadable") from exc
    return None


def _command_launch_package_a_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A review requires its awaiting gate")
    if _is_package_a_v4(state): return _command_launch_package_a_v4_review(args,directory,state)
    if _is_package_a_v5(state): return _command_launch_package_a_v5_review(args,directory,state)
    context=_package_a_review_context(directory,state)
    if context["verification"]["aggregate"].get("all_passed") is not True: raise ControllerError("Package A review requires all deterministic gates to pass")
    if state.get("package_a_review"): raise ControllerError("Package A candidate already has an ingested independent review")
    existing=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
    if existing:
        _package_a_review_attempt_intact(directory,state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _package_a_review_terminal(directory,existing)
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            append_event(directory,"package_a_review_launch_lost",attempt_id=existing["id"],classification=classification); save(directory,state)
        raise ControllerError("Package A independent review attempt already exists")
    retries=state.get("package_a_review_retries",[])
    if not isinstance(retries,list) or len(retries)>1: raise ControllerError("Package A review retry history is malformed")
    actor=PACKAGE_A_CLAUDE_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(directory,"package-a-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package A review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_a_review_schema(state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"review schema")
    receipt_refs=[row["path"] for row in context["verification"]["refs"]]
    prompt=("Read-only independent Package-A review. Return only the required schema JSON. "
            "Inspect only: the small production module scripts/cowork_dispatch.py, bounded additions in the candidate delta %s, and sealed controller receipts=%s. "
            "Do not read or run scripts/test_cowork.py in full; do not run tests or broad shell commands. Use bounded file reads only. "
            "Check the three pure record validators, fixed public APIs, negative controls, reducer allow/refuse purity, JSON round trips, exact path scope in %s, and no Package B/C/D call-site behavior against baseline=%s and verification aggregate=%s. "
            "Echo the controller bindings exactly; worker check claims and receipt_refs are advisory and must not be used as evidence." %
            (state["package_a_builder_delta"]["path"],json.dumps(receipt_refs),json.dumps(context["changed_paths"]),state["package_a_prerequisites"]["path"],context["verification"]["aggregate_info"]["path"]))
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package A review prompt exceeds bound")
    logs=os.path.join(directory,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-a-claude.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-a-claude.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind","claude_package_a_review_terminal","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    expected=_package_a_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=305)).isoformat().replace("+00:00","Z")
    state["package_a_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save(directory,state); append_event(directory,"package_a_review_starting",attempt_id=attempt_id,candidate_id=context["candidate"]["id"])
    try: pid,pgid=detached_spawn(wrapper,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["package_a_review_attempt"]["spawn_error"]=type(exc).__name__; state["package_a_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); state["package_a_review_attempt"]["terminal_at"]=utc()
        append_event(directory,"package_a_review_spawn_failed",attempt_id=attempt_id); save(directory,state); raise ControllerError("Package A review controller spawn failed") from exc
    state["package_a_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"package_a_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":attempt_id,"run_id":run,"phase":state["phase"]}


def _review_terminal(directory: str,attempt: Dict[str,Any],review_subdir: str) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    receipt=capped_regular_file_info(attempt.get("receipt_path"),os.path.join(directory,review_subdir),MAX_PLAN_ARTIFACT_BYTES) if isinstance(attempt.get("receipt_path"),str) else None
    if not receipt: raise ControllerError("review terminal receipt is missing or unsafe")
    try: terminal=json.loads(Path(receipt["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("review terminal receipt is unreadable") from exc
    keys={"schema_version","kind","policy","attempt_id","argv_digest","nonce","started_at","finished_at","exit_code","output_path","output_sha256","output_bytes","stdout_sha256","stdout_bytes","stderr_sha256","stderr_bytes","timed_out","output_limit_exceeded"}
    expected={"schema_version":SCHEMA,"kind":"claude_package_a_review_terminal","policy":POLICY_ID,"attempt_id":attempt.get("id"),"argv_digest":attempt.get("argv_digest"),"nonce":attempt.get("nonce"),"output_path":attempt.get("output_path")}
    if (not isinstance(terminal,dict) or set(terminal)!=keys or any(terminal.get(k)!=v for k,v in expected.items()) or
            not isinstance(terminal.get("started_at"),str) or not isinstance(terminal.get("finished_at"),str) or
            isinstance(terminal.get("exit_code"),bool) or not isinstance(terminal.get("exit_code"),int) or
            isinstance(terminal.get("output_bytes"),bool) or not isinstance(terminal.get("output_bytes"),int) or terminal["output_bytes"]<0 or
            not isinstance(terminal.get("timed_out"),bool) or not isinstance(terminal.get("output_limit_exceeded"),bool) or
            (terminal.get("output_sha256") is not None and not _sha256_hex(terminal.get("output_sha256")))):
        raise ControllerError("review terminal binding changed")
    for label in ("stdout","stderr"):
        item=capped_regular_file_info(attempt.get(label),os.path.join(directory,"logs"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get(label),str) else None
        if not item or terminal.get(label+"_sha256")!=item["sha256"] or terminal.get(label+"_bytes")!=item["bytes"]: raise ControllerError("review terminal log binding changed")
    return terminal,receipt


def _package_a_review_terminal(directory: str,attempt: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    return _review_terminal(directory,attempt,"package-a-review-attempts")


def _package_a_claude_capacity_event(stdout_path: str,directory: str,reviewer_session_id: str) -> Optional[Dict[str,Any]]:
    info=capped_regular_file_info(stdout_path,os.path.join(directory,"logs"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP)
    if not info: return None
    matches=[]
    try: lines=Path(info["path"]).read_text(encoding="utf-8").splitlines()
    except (OSError,UnicodeDecodeError): return None
    for line in lines:
        try: row=json.loads(line)
        except json.JSONDecodeError: continue
        if not isinstance(row,dict) or row.get("session_id")!=reviewer_session_id: continue
        if row.get("type")=="rate_limit_event":
            info_block=row.get("rate_limit_info") if isinstance(row.get("rate_limit_info"),dict) else {}
            if info_block.get("isUsingOverage") is False and info_block.get("status")=="rejected":
                reset=parse_provider_reset_epoch(info_block.get("resetsAt"))
                matches.append({"code":"subscription_quota_exhausted","retry_after":reset})
        elif row.get("type")=="result" and row.get("is_error") is True and row.get("subtype")=="error_plan_quota_exhausted":
            matches.append({"code":"subscription_quota_exhausted","retry_after":None})
    if not matches: return None
    if len(matches)!=1: raise ControllerError("Package A review capacity evidence is ambiguous")
    return {**matches[0],"stdout_sha256":info["sha256"]}


def _claude_schema_failure_events(lines: List[str]) -> bool:
    """Detect a Claude typed schema-validation failure in reviewer stdout JSONL."""
    schema_subtypes={"error_schema_validation","error_invalid_schema","error_schema_invalid"}
    for line in lines:
        try: row=json.loads(line)
        except json.JSONDecodeError: continue
        if isinstance(row,dict) and row.get("type")=="result" and row.get("is_error") is True and row.get("subtype") in schema_subtypes:
            return True
    return False


def _package_a_review_capacity_wait(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any],
                                    terminal: Dict[str,Any],receipt: Dict[str,Any],event: Dict[str,Any]) -> Dict[str,Any]:
    if state.get("package_a_review_capacity_history") or state.get("package_a_review_capacity"):
        raise ControllerError("Package A review capacity continuation is already consumed or active")
    provider_session=_package_a_claude_optional_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    mode="scheduled" if event.get("retry_after") else "manual_signal"
    packet={"schema_version":SCHEMA,"kind":"package_a_review_capacity","work_id":state["work_id"],"policy":POLICY_ID,
        "failure_class":"subscription_quota_exhausted","capacity_code":event["code"],"mode":mode,"retry_after":event.get("retry_after"),
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],
        "run_id":attempt["run_id"],"nonce":attempt["nonce"],"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"provider_session_id":provider_session,
        "terminal_receipt_sha256":receipt["sha256"],"stdout_sha256":event["stdout_sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],
        "issued_at":attempt["prepared_at"],"wakeup":None,"consumed_at":None}
    root=os.path.join(directory,"package-a-review-capacity")
    if os.path.lexists(root) and (os.path.islink(root) or not os.path.isdir(root) or not inside(real(root),directory)): raise ControllerError("Package A review capacity directory is unsafe")
    os.makedirs(root,mode=0o700,exist_ok=True); path=os.path.join(root,attempt["id"]+".json")
    info=_package_a_adopt_json(path,root,packet,"review capacity packet")
    state["package_a_review_capacity"]={"path":info["path"],"sha256":info["sha256"],"mode":mode,"retry_after":event.get("retry_after"),
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],"provider_session_id":provider_session,
        "wakeup":None,"consumed_at":None}
    state["phase"]=CAPACITY_WAITING
    state["gate"]={"kind":"package_a_review_capacity","verdict":CAPACITY_WAITING,"candidate_id":context["candidate"]["id"],
        "evidence_digest":context["candidate"]["evidence_digest"],"mode":mode,"policy":POLICY_ID}
    append_event(directory,"package_a_review_capacity_waiting",candidate_id=context["candidate"]["id"],review_attempt_id=attempt["id"],mode=mode,
        retry_after=event.get("retry_after"),policy=POLICY_ID); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_a_review","phase":CAPACITY_WAITING,"capacity":{"mode":mode,"retry_after":event.get("retry_after"),
        "failure_class":"subscription_quota_exhausted"},"limitations":["subscription_only","no refill, paid overage, or monetary-limit authority","manual mode requires an authenticated outer adapter signal"]}


def _command_ingest_package_a_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A review ingest requires its awaiting gate")
    if _is_package_a_v4(state): return _command_ingest_package_a_v4_review(directory,state)
    if _is_package_a_v5(state): return _command_ingest_package_a_v5_review(directory,state)
    context=_package_a_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A review requires a quiescent controller-owned attempt")
    _package_a_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            return _package_a_review_capacity_wait(directory,state,context,attempt,terminal,receipt,capacity_event)
        raise ControllerError("Package A independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-a-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package A review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    prior_sessions={row.get("provider_session_id") for row in state.get("package_a_review_attempt_history",[]) if isinstance(row,dict)}
    if provider_session==state["attempt"].get("provider_session_id") or provider_session in prior_sessions:
        raise ControllerError("Package A reviewer provider session is not fresh and distinct")
    expected=_package_a_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A independent review packet failed strict binding validation")
    packets=os.path.join(directory,"packets"); destination=os.path.join(packets,context["candidate"]["id"]+".package-a-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    envelope={"schema_version":SCHEMA,"kind":"package_a_review_envelope","work_id":state["work_id"],"policy":POLICY_ID,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,
        "run_id":attempt["run_id"],"review_attempt_id":attempt["id"],"reviewer_session_id":provider_session,
        "terminal_receipt_sha256":receipt["sha256"],"model_packet_sha256":model_packet_sha256,"model_packet":packet}
    copied=_package_a_adopt_json(destination,packets,envelope,"independent review envelope")
    state["package_a_review"]={"path":destination,"sha256":copied["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,"verdict":packet["verdict"],
        "model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    attempt["consumed_at"]=utc(); attempt["receipt_sha256"]=receipt["sha256"]; attempt["packet_sha256"]=copied["sha256"]; attempt["provider_session_id"]=provider_session
    append_event(directory,"package_a_review_ingested",candidate_id=context["candidate"]["id"],packet_sha256=copied["sha256"],verdict=packet["verdict"],actor_id=PACKAGE_A_CLAUDE_REVIEW_ACTOR); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_a_review","verdict":packet["verdict"],"packet_sha256":copied["sha256"],"phase":state["phase"]}


def _command_retry_package_a_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate" or state.get("package_a_review"): raise ControllerError("Package A review retry requires an unconsumed awaiting review")
    if _is_package_a_v4(state): return _command_retry_package_a_v4_review(directory,state)
    if _is_package_a_v5(state): return _command_retry_package_a_v5_review(directory,state)
    context=_package_a_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    retries=state.get("package_a_review_retries",[])
    if not attempt or attempt.get("consumed_at") or not isinstance(retries,list) or retries or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A review infrastructure retry is unavailable")
    _package_a_review_attempt_intact(directory,state,context,attempt)
    schema_info=capped_regular_file_info(attempt.get("schema_path"),os.path.join(directory,"package-a-review-attempts"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_schema=_package_a_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    if not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256"):
        raise ControllerError("Package A review retry schema binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A review retry schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A review retry schema changed")
    evidence={}
    if attempt.get("spawn_error"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("spawn_error_sha256")!=digest_bytes(str(attempt["spawn_error"]).encode()): raise ControllerError("Package A review spawn failure binding changed")
        evidence={"classification":"spawn_failure","receipt_sha256":None,"spawn_error_sha256":attempt["spawn_error_sha256"]}
    elif attempt.get("launch_lost"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("launch_lost")!="prepared_launch_lost" or attempt.get("launch_lost_sha256")!=digest_bytes(b"prepared_launch_lost"):
            raise ControllerError("Package A review launch-lost binding changed")
        evidence={"classification":"prepared_launch_lost","receipt_sha256":None,"spawn_error_sha256":attempt["launch_lost_sha256"]}
    else:
        terminal,receipt=_package_a_review_terminal(directory,attempt)
        output_exists=isinstance(attempt.get("output_path"),str) and os.path.lexists(attempt["output_path"])
        if terminal.get("exit_code")==0 or terminal.get("output_sha256") is not None or output_exists: raise ControllerError("Package A review application result is not infrastructure-retryable")
        if not terminal.get("output_limit_exceeded") or terminal.get("timed_out"): raise ControllerError("Package A review failure is not the bounded stream overflow infrastructure class")
        capacity_check=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_check: raise ControllerError("Package A review overflow concurrent with capacity event is not retryable")
        evidence={"classification":"bounded_stream_overflow","receipt_sha256":receipt["sha256"],"reviewer_session_id":attempt.get("reviewer_session_id"),"spawn_error_sha256":None}
    archived={**attempt,"retry_evidence":evidence,"schema_sha256":schema_info["sha256"]}
    history=state.get("package_a_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package A review history is malformed")
    state["package_a_review_attempt_history"]=history+[archived]; state["package_a_review_retries"]=[{"at":utc(),"prior_attempt_id":attempt["id"],"evidence":evidence}]; state["package_a_review_attempt"]=None
    append_event(directory,"package_a_review_retry_released",attempt_id=attempt["id"],classification=evidence["classification"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_package_a_review","phase":state["phase"],"retry_released":True}


def _package_a_review_capacity_intact(directory: str,state: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    bound=state.get("package_a_review_capacity") if isinstance(state.get("package_a_review_capacity"),dict) else {}
    keys={"path","sha256","mode","retry_after","candidate_id","evidence_digest","review_attempt_id","provider_session_id","wakeup","consumed_at"}
    if set(bound)!=keys or state.get("phase")!=CAPACITY_WAITING: raise ControllerError("Package A review capacity state is malformed")
    info=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-a-review-capacity"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A review capacity packet changed")
    try: packet=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A review capacity packet is unreadable") from exc
    if (packet.get("kind")!="package_a_review_capacity" or packet.get("policy")!=POLICY_ID or packet.get("candidate_id")!=bound.get("candidate_id") or
            packet.get("evidence_digest")!=bound.get("evidence_digest") or packet.get("review_attempt_id")!=bound.get("review_attempt_id") or
            packet.get("provider_session_id")!=bound.get("provider_session_id") or packet.get("mode")!=bound.get("mode") or packet.get("retry_after")!=bound.get("retry_after")):
        raise ControllerError("Package A review capacity binding changed")
    state_for_context={**state,"phase":"awaiting_gate"}; context=_package_a_review_context(directory,state_for_context)
    attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    _package_a_review_attempt_intact(directory,state_for_context,context,attempt); terminal,receipt=_package_a_review_terminal(directory,attempt)
    if (attempt.get("id")!=bound.get("review_attempt_id") or receipt.get("sha256")!=packet.get("terminal_receipt_sha256") or
            context["candidate"].get("id")!=bound.get("candidate_id") or context["candidate"].get("evidence_digest")!=bound.get("evidence_digest") or
            context["verification"]["aggregate_info"]["sha256"]!=packet.get("verification_aggregate_sha256")):
        raise ControllerError("Package A review capacity attempt binding changed")
    return packet,info


def _command_register_package_a_review_capacity_wakeup(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_a_review_capacity_intact(directory,state)
    bound=state["package_a_review_capacity"]
    if bound.get("mode")!="scheduled" or not isinstance(bound.get("retry_after"),str): raise ControllerError("Package A manual review capacity cannot register an agent wakeup")
    ref=args.wakeup_ref.strip()
    if not ref or len(ref.encode())>500: raise ControllerError("Package A review wakeup reference is required and bounded")
    receipt_core={"schema_version":SCHEMA,"kind":"package_a_review_capacity_wakeup","work_id":state["work_id"],"policy":POLICY_ID,
        "capacity_packet_sha256":packet_info["sha256"],"candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],
        "review_attempt_id":bound["review_attempt_id"],"retry_after":bound["retry_after"],"wakeup_ref_sha256":digest_bytes(ref.encode())}
    lease_id=digest_bytes(json.dumps(receipt_core,sort_keys=True,separators=(",",":")).encode()); receipt={**receipt_core,"lease_id":lease_id,"issued_at":packet["issued_at"]}
    root=os.path.join(directory,"package-a-review-capacity-wakeups"); os.makedirs(root,mode=0o700,exist_ok=True); path=os.path.join(root,lease_id+".json")
    info=_package_a_adopt_json(path,root,receipt,"review capacity wakeup")
    expected={"path":info["path"],"sha256":info["sha256"],"lease_id":lease_id,"wakeup_ref":ref,"consumed_at":None}
    if bound.get("wakeup") and bound["wakeup"]!=expected: raise ControllerError("Package A review capacity has a different wakeup")
    bound["wakeup"]=expected; append_event(directory,"package_a_review_capacity_wakeup_registered",lease_id=lease_id,candidate_id=bound["candidate_id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"register_package_a_review_capacity_wakeup","phase":CAPACITY_WAITING,"lease_id":lease_id,"retry_after":bound["retry_after"],"reused":False}


def _command_resume_package_a_review_capacity(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_a_review_capacity_intact(directory,state); bound=state["package_a_review_capacity"]
    if bound.get("mode")!="scheduled": raise ControllerError("Package A manual review capacity requires an authenticated outer adapter signal")
    due=_parse_utc_instant(bound.get("retry_after"))
    if due>dt.datetime.now(dt.timezone.utc): raise ControllerError("Package A review capacity retry time has not elapsed")
    wake=bound.get("wakeup") if isinstance(bound.get("wakeup"),dict) else {}
    item=capped_regular_file_info(wake.get("path"),os.path.join(directory,"package-a-review-capacity-wakeups"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(wake.get("path"),str) else None
    if not item or item.get("sha256")!=wake.get("sha256") or wake.get("consumed_at") or bound.get("consumed_at"): raise ControllerError("Package A review capacity wakeup lease is missing or consumed")
    attempt=state["package_a_review_attempt"]; archived={**attempt,"capacity_packet_sha256":packet_info["sha256"],"capacity_disposition":"scheduled_continuation"}
    history=state.get("package_a_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package A review history is malformed")
    history=history+[archived]; consumed=utc(); wake["consumed_at"]=consumed; bound["consumed_at"]=consumed
    state["package_a_review_attempt_history"]=history; state["package_a_review_capacity_history"]=[{**bound}]
    state["package_a_review_attempt"]=None; state["package_a_review_capacity"]=None; state["phase"]="awaiting_gate"
    state["gate"]={"kind":"package_a_review_capacity_released","verdict":"awaiting_review","candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],"policy":POLICY_ID}
    append_event(directory,"package_a_review_capacity_released",lease_id=wake["lease_id"],candidate_id=bound["candidate_id"],next_state="awaiting_gate"); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"resume_package_a_review_capacity","phase":"awaiting_gate","delivery":"fresh_controller_review_continuation"}


def _package_a_review_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_review") if isinstance(state.get("package_a_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict",
          "model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package A independent review state binding is malformed")
    item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A independent review envelope changed")
    try: envelope=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A independent review envelope is unreadable") from exc
    attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    _package_a_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    packet=envelope.get("model_packet") if isinstance(envelope,dict) else None
    expected=_package_a_review_expected(state,context,attempt); packet_keys=set(expected)|{"verdict","findings","checks"}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id",
                   "reviewer_session_id","terminal_receipt_sha256","model_packet_sha256","model_packet"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or
            envelope.get("kind")!="package_a_review_envelope" or envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or
            envelope.get("candidate_id")!=context["candidate"]["id"] or envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            envelope.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or envelope.get("run_id")!=attempt.get("run_id") or envelope.get("review_attempt_id")!=attempt.get("id") or
            envelope.get("reviewer_session_id")!=attempt.get("provider_session_id") or envelope.get("terminal_receipt_sha256")!=receipt["sha256"] or
            not isinstance(packet,dict) or set(packet)!=packet_keys or any(packet.get(k)!=v for k,v in expected.items()) or
            envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded")):
        raise ControllerError("Package A independent review envelope binding changed")
    if (packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A independent review verdict packet is malformed")
    expected_bound={"path":item["path"],"sha256":item["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":attempt["provider_session_id"],"policy":POLICY_ID,
        "verdict":packet["verdict"],"model_packet_sha256":envelope["model_packet_sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    if bound!=expected_bound or attempt.get("packet_sha256")!=item["sha256"] or not isinstance(attempt.get("consumed_at"),str):
        raise ControllerError("Package A independent review state no longer matches its envelope")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":receipt}


def _package_a_archive_correction(directory: str,state: Dict[str,Any],context: Dict[str,Any],instruction: str) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    candidate=context["candidate"]; attempt=state["attempt"]
    history=state.get("package_a_correction_history",[])
    if not isinstance(history,list) or history or state.get("package_a_correction_used"): raise ControllerError("Package A has exhausted its one bounded builder correction")
    review=None
    if isinstance(state.get("package_a_review"),dict): review=_package_a_review_intact(directory,state,context)
    archive_dir=os.path.join(directory,"package-a-corrections")
    if os.path.lexists(archive_dir) and (os.path.islink(archive_dir) or not os.path.isdir(archive_dir)): raise ControllerError("Package A correction archive directory is unsafe")
    os.makedirs(archive_dir,mode=0o700,exist_ok=True)
    intervention={"id":str(uuid.uuid4()),"at":utc(),"text":instruction,"sha256":digest_bytes(instruction.encode()),"source":"package_a_fixed_gate"}
    archive={"schema_version":SCHEMA,"kind":"package_a_correction_archive","work_id":state["work_id"],"policy":POLICY_ID,"archived_at":utc(),
        "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"attempt_id":attempt["id"],"provider_session_id":attempt["provider_session_id"],"attempt_started_at":attempt["started_at"],
        "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"delta_receipt_path":state["package_a_builder_delta"]["path"],
        "delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],"delta_sha256":context["delta"]["sha256"],
        "collect":state.get("package_a_collect"),"verification":state.get("package_a_verification"),"review":state.get("package_a_review"),
        "review_envelope_sha256":review["info"]["sha256"] if review else None,"intervention_id":intervention["id"],"intervention_sha256":intervention["sha256"]}
    path=os.path.join(archive_dir,candidate["id"]+".json"); info=_package_a_adopt_json(path,archive_dir,archive,"correction archive")
    state.setdefault("interventions",[]).append(intervention)
    state["package_a_correction_history"]=[{"path":info["path"],"sha256":info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"intervention_sha256":intervention["sha256"]}]
    state["recovery_constraint"]={"kind":"package_a_exact_correction","active_at":utc(),"original_attempt_id":attempt["id"],"role":"implementer",
        "provider_session_id":attempt["provider_session_id"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
        "original_attempt_started_at":attempt["started_at"],"delta_sha256":context["delta"]["sha256"],"archive_path":info["path"],"archive_sha256":info["sha256"],"intervention_sha256":intervention["sha256"],"consumed_at":None}
    state["package_a_collect_generation"]=1
    for key in ("package_a_collect","package_a_builder_delta","package_a_verification","package_a_review","package_a_review_attempt"):
        state.pop(key,None)
    state["package_a_review_retries"]=[]
    return intervention,info


def _command_adjudicate_package_a(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A fixed gate requires its awaiting candidate")
    if args.adjudicator_principal!=PACKAGE_A_GATE_PRINCIPAL: raise ControllerError("Package A gate requires the fixed controller principal")
    rationale=args.rationale.strip()
    if not rationale or len(rationale.encode())>2000: raise ControllerError("Package A gate rationale is required and bounded")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_attempt_intact(state.get("attempt")); _package_a_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_validate_verification(directory,state,candidate,baseline,delta)
    all_passed=verification["aggregate"]["all_passed"] is True
    context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":[row["path"] for row in delta["files"]]}
    review=None
    if isinstance(state.get("package_a_review"),dict): review=_package_a_review_intact(directory,state,context)
    verdict=args.verdict
    if verdict=="pass":
        if not all_passed or not review or review["packet"]["verdict"]!="pass": raise ControllerError("Package A pass requires all deterministic gates and an independent pass review")
        state["phase"]="completed"; disposition="pass"; event_kind="package_a_gate_passed"
    elif verdict=="revise":
        if all_passed and (not review or review["packet"]["verdict"]=="pass"): raise ControllerError("Package A correction requires deterministic or independent review dissent")
        instruction=(args.instruction or "").strip()
        if not instruction or len(instruction.encode())>MAX_INSTRUCTION: raise ControllerError("Package A revision instruction is required and bounded")
        intervention,archive=_package_a_archive_correction(directory,state,context,instruction)
        state["phase"]="prepared"; disposition="revise"; event_kind="package_a_correction_queued"
    elif verdict=="fail":
        state["phase"]="failed"; disposition="fail"; event_kind="package_a_gate_failed"
    else:
        raise ControllerError("Package A fixed gate does not delegate an authority expansion path")
    gate={"kind":"package_a_fixed_gate","gate_name":"orchestrator-package-a-gate/v1","verdict":disposition,"at":utc(),"rationale":rationale,
          "adjudicator_principal":PACKAGE_A_GATE_PRINCIPAL,"policy":POLICY_ID,"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
          "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],"review_sha256":review["info"]["sha256"] if review else None}
    state["gate"]=gate
    append_event(directory,event_kind,gate_name=gate["gate_name"],policy=POLICY_ID,candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],
        input_hashes={"verification_aggregate_sha256":gate["verification_aggregate_sha256"],"review_sha256":gate["review_sha256"],"delta_receipt_sha256":verification["aggregate"]["static"]["delta_receipt_sha256"]},
        adjudicator_identity=PACKAGE_A_GATE_PRINCIPAL,disposition=disposition,next_state=state["phase"])
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":state["phase"],"gate":gate,
            "delivery":"exact_implementer_resume_required" if verdict=="revise" else None}


def _package_a_archived_evidence_refs(directory: str,state: Dict[str,Any],extra: Iterable[Dict[str,Any]]=()) -> List[Dict[str,Any]]:
    """Seal every controller artifact the correction leaves behind."""
    values=[state.get("candidate"),state.get("attempt")]+[state.get(key) for key in ("package_a_prerequisites","package_a_collect","package_a_builder_delta","package_a_verification",
            "package_a_review","package_a_review_attempt","package_a_review_attempt_history","package_a_review_retries")]
    paths=[]
    def visit(value: Any) -> None:
        if isinstance(value,dict):
            for key,item in value.items():
                if key in {"path","packet_path","provider_packet_path","intent_path","result_path","aggregate_path","schema_path","output_path","receipt_path","stdout","stderr"} and isinstance(item,str):
                    paths.append(item)
                elif key in {"receipt_paths","output_paths","terminal_paths","start_paths"} and isinstance(item,list):
                    paths.extend(x for x in item if isinstance(x,str))
                else: visit(item)
        elif isinstance(value,list):
            for item in value: visit(item)
    for value in values: visit(value)
    for row in extra:
        if isinstance(row,dict) and isinstance(row.get("path"),str): paths.append(row["path"])
    refs=[]; seen=set()
    for path in sorted(paths):
        if path in seen: continue
        seen.add(path)
        item=capped_regular_file_info(path,directory,MAX_CANDIDATE_PATH_BYTES)
        if not item: raise ControllerError("Package A correction evidence path is missing or unsafe")
        refs.append({"path":item["path"],"sha256":item["sha256"],"bytes":item["bytes"]})
    return refs


def _package_a_gate_receipt_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_gate_receipt") if isinstance(state.get("package_a_gate_receipt"),dict) else {}
    if set(bound)!={"path","sha256","receipt_id","candidate_id","evidence_digest","disposition"}: raise ControllerError("Package A gate receipt state binding is malformed")
    info=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-a-gates"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A fixed gate receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A fixed gate receipt is unreadable") from exc
    keys={"schema_version","kind","receipt_id","work_id","policy","gate_name","adjudicator_principal","candidate_id","evidence_digest",
          "verification_aggregate_sha256","review_sha256","correction_already_used","disposition","reason_code","issued_at"}
    if (not isinstance(receipt,dict) or set(receipt)!=keys or receipt.get("schema_version")!=SCHEMA or receipt.get("kind")!="package_a_gate_receipt" or
            receipt.get("work_id")!=state["work_id"] or receipt.get("policy")!=POLICY_ID or receipt.get("gate_name")!="orchestrator-package-a-gate/v1" or
            receipt.get("adjudicator_principal")!=PACKAGE_A_GATE_PRINCIPAL or receipt.get("receipt_id")!=bound.get("receipt_id") or
            receipt.get("candidate_id")!=bound.get("candidate_id") or receipt.get("evidence_digest")!=bound.get("evidence_digest") or
            receipt.get("disposition")!=bound.get("disposition") or receipt.get("receipt_id")!=digest_bytes(json.dumps({k:v for k,v in receipt.items() if k not in {"receipt_id","issued_at"}},sort_keys=True,separators=(",",":")).encode())):
        raise ControllerError("Package A fixed gate receipt binding changed")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if receipt.get("issued_at")!=(candidate.get("created_at") or state.get("created_at")):
        raise ControllerError("Package A fixed gate receipt time binding changed")
    return {"receipt":receipt,"info":info}


def _package_a_gate_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    if not isinstance(state.get("package_a_gate_receipt"),dict): return None
    sealed=_package_a_gate_receipt_intact(directory,state); receipt=sealed["receipt"]
    expected_phase={"pass":"completed","revise":"prepared","fail":"failed"}[receipt["disposition"]]
    if state.get("phase")!=expected_phase: raise ControllerError("Package A fixed gate phase binding changed")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if (gate.get("kind")!="package_a_fixed_gate" or gate.get("gate_name")!=PACKAGE_A_GATE_PRINCIPAL or gate.get("verdict")!=receipt["disposition"] or
            gate.get("receipt_id")!=receipt["receipt_id"] or gate.get("receipt_sha256")!=sealed["info"]["sha256"] or gate.get("candidate_id")!=receipt["candidate_id"] or
            gate.get("evidence_digest")!=receipt["evidence_digest"] or gate.get("reason_code")!=receipt["reason_code"] or gate.get("policy")!=POLICY_ID):
        raise ControllerError("Package A fixed gate state binding changed")
    if receipt["disposition"]=="pass":
        context=_package_a_review_context(directory,state); review=_package_a_review_intact(directory,state,context)
        if (context["verification"]["aggregate"].get("all_passed") is not True or review["packet"].get("verdict")!="pass" or
                context["verification"]["aggregate_info"]["sha256"]!=receipt.get("verification_aggregate_sha256") or review["info"]["sha256"]!=receipt.get("review_sha256")):
            raise ControllerError("Package A passing gate evidence changed")
    elif receipt["disposition"]=="revise":
        recovery=state.get("recovery_constraint") if isinstance(state.get("recovery_constraint"),dict) else {}
        archive=capped_regular_file_info(recovery.get("archive_path"),os.path.join(directory,"package-a-corrections"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(recovery.get("archive_path"),str) else None
        if recovery.get("kind")!="package_a_exact_correction" or not archive or archive.get("sha256")!=recovery.get("archive_sha256"):
            raise ControllerError("Package A correction gate archive changed")
    event_kind={"pass":"package_a_gate_passed","revise":"package_a_correction_queued","fail":"package_a_gate_failed"}[receipt["disposition"]]
    if not any(row.get("kind")==event_kind and row.get("receipt_id")==receipt["receipt_id"] for row in recent_events(directory)):
        append_event(directory,event_kind,receipt_id=receipt["receipt_id"],gate_name=receipt["gate_name"],policy=POLICY_ID,
            candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],disposition=receipt["disposition"],next_state=expected_phase)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":expected_phase,"disposition":receipt["disposition"],
            "receipt":{"path":sealed["info"]["path"],"sha256":sealed["info"]["sha256"]},"reused":True,
            "delivery":"exact_implementer_resume_required" if receipt["disposition"]=="revise" else None}


def _package_a_derived_instruction(verification: Dict[str,Any],review: Optional[Dict[str,Any]]) -> str:
    failed=[row["label"] for row in verification["refs"] if row.get("passed") is not True]
    findings=(review or {}).get("packet",{}).get("findings",[]) if review else []
    text=("Correct Package A in the exact existing implementer session. Failed controller gates: %s. Independent findings: %s. "
          "Stay within scripts/cowork_dispatch.py and scripts/test_cowork.py; return the strict Package-A outcome packet." %
          (", ".join(failed) if failed else "none", "; ".join(findings) if findings else "none"))
    return text[:MAX_INSTRUCTION]


def _package_a_prepare_automatic_correction(directory: str,state: Dict[str,Any],context: Dict[str,Any],instruction: str,
                                             gate_ref: Dict[str,Any]) -> Dict[str,Any]:
    candidate=context["candidate"]; attempt=state["attempt"]
    if state.get("package_a_correction_used") or state.get("package_a_correction_history"):
        raise ControllerError("Package A correction is already consumed")
    intervention_sha=digest_bytes(instruction.encode()); intervention_id="package-a-correction-"+intervention_sha[:32]
    extra=[gate_ref]+list(context["verification"]["refs"])
    for row in context["verification"]["refs"]:
        try: payload=json.loads(Path(row["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification receipt cannot be archived") from exc
        if isinstance(payload.get("output_path"),str): extra.append({"path":payload["output_path"]})
    refs=_package_a_archived_evidence_refs(directory,state,extra)
    archive_core={"schema_version":SCHEMA,"kind":"package_a_correction_archive","work_id":state["work_id"],"policy":POLICY_ID,
        "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"attempt_id":attempt["id"],"provider_session_id":attempt["provider_session_id"],
        "attempt_started_at":attempt["started_at"],"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
        "delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],"delta_sha256":context["delta"]["sha256"],
        "gate_receipt_sha256":gate_ref["sha256"],"intervention_id":intervention_id,"intervention_sha256":intervention_sha,"evidence_refs":refs,
        "archived_state":{"candidate":candidate,"attempt":attempt,"collect":state.get("package_a_collect"),"builder_delta":state.get("package_a_builder_delta"),
            "verification":state.get("package_a_verification"),"review":state.get("package_a_review"),"review_attempt":state.get("package_a_review_attempt"),
            "review_attempt_history":state.get("package_a_review_attempt_history",[]),"review_retries":state.get("package_a_review_retries",[])}}
    archive_id=digest_bytes(json.dumps(archive_core,sort_keys=True,separators=(",",":")).encode()); archive={**archive_core,"archive_id":archive_id,"issued_at":candidate["created_at"]}
    archive_dir=os.path.join(directory,"package-a-corrections")
    if os.path.lexists(archive_dir) and (os.path.islink(archive_dir) or not os.path.isdir(archive_dir) or not inside(real(archive_dir),directory)):
        raise ControllerError("Package A correction archive directory is unsafe")
    os.makedirs(archive_dir,mode=0o700,exist_ok=True)
    archive_info=_package_a_adopt_json(os.path.join(archive_dir,archive_id+".json"),archive_dir,archive,"correction archive")
    intervention={"id":intervention_id,"at":candidate["created_at"],"text":instruction,"sha256":intervention_sha,"source":"package_a_fixed_gate"}
    if not any(row.get("id")==intervention_id for row in state.get("interventions",[]) if isinstance(row,dict)): state.setdefault("interventions",[]).append(intervention)
    state["package_a_correction_history"]=[{"path":archive_info["path"],"sha256":archive_info["sha256"],"archive_id":archive_id,
        "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"intervention_sha256":intervention_sha}]
    state["recovery_constraint"]={"kind":"package_a_exact_correction","active_at":candidate["created_at"],"original_attempt_id":attempt["id"],"role":"implementer",
        "provider_session_id":attempt["provider_session_id"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
        "original_attempt_started_at":attempt["started_at"],"delta_sha256":context["delta"]["sha256"],"archive_path":archive_info["path"],
        "archive_sha256":archive_info["sha256"],"intervention_sha256":intervention_sha,"consumed_at":None}
    state["package_a_collect_generation"]=1
    active_review_attempt=state.get("package_a_review_attempt")
    if isinstance(active_review_attempt,dict):
        review_history=state.get("package_a_review_attempt_history",[])
        if not isinstance(review_history,list): raise ControllerError("Package A review attempt history is malformed")
        if not any(row.get("id")==active_review_attempt.get("id") for row in review_history if isinstance(row,dict)):
            state["package_a_review_attempt_history"]=review_history+[active_review_attempt]
    for key in ("package_a_collect","package_a_builder_delta","package_a_verification","package_a_review","package_a_review_attempt"):
        state.pop(key,None)
    state["package_a_review_retries"]=[]
    return archive_info


def _command_adjudicate_package_a(args: argparse.Namespace) -> Dict[str,Any]:
    """Derive the fixed Package-A disposition; callers cannot choose it."""
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a(state): raise ControllerError("Package A fixed gate requires its canonical identity")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if _is_package_a_v4(state): return _command_adjudicate_package_a_v4(directory,state,candidate)
    if _is_package_a_v5(state): return _command_adjudicate_package_a_v5(directory,state,candidate)
    replay=_package_a_gate_replay(directory,state)
    if replay: return replay
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package A fixed gate requires its awaiting candidate")
    try:
        baseline=_package_a_prerequisites_intact(directory,state); _package_a_attempt_intact(state.get("attempt")); _package_a_candidate_intact(directory,state,candidate,baseline)
        delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_validate_verification(directory,state,candidate,baseline,delta)
        context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":[row["path"] for row in delta["files"]]}
        review=_package_a_review_intact(directory,state,context) if isinstance(state.get("package_a_review"),dict) else None
        all_passed=verification["aggregate"]["all_passed"] is True
        review_verdict=(review or {}).get("packet",{}).get("verdict")
        review_infrastructure_exhausted=False; exhausted_review_receipt=None
        active_review=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
        review_retries=state.get("package_a_review_retries")
        if all_passed and review_verdict is None and active_review and isinstance(review_retries,list) and len(review_retries)==1:
            if process_alive(active_review.get("pid"),active_review.get("pgid")):
                raise ControllerError("Package A independent review is still running")
            _package_a_review_attempt_intact(directory,state,context,active_review)
            terminal,terminal_receipt=_package_a_review_terminal(directory,active_review)
            output_exists=isinstance(active_review.get("output_path"),str) and os.path.lexists(active_review["output_path"])
            capacity_event=_package_a_claude_capacity_event(active_review["stdout"],directory,active_review.get("reviewer_session_id",""))
            review_infrastructure_exhausted=(
                terminal.get("exit_code")!=0 and
                (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and
                terminal.get("output_sha256") is None and not output_exists and capacity_event is None)
            if review_infrastructure_exhausted: exhausted_review_receipt=terminal_receipt
        if all_passed and review_verdict=="pass": disposition,reason="pass","all_evidence_passed"
        elif review_verdict=="fail": disposition,reason="fail","independent_review_failed"
        elif review_infrastructure_exhausted: disposition,reason="fail","review_infrastructure_exhausted"
        elif state.get("package_a_correction_used") or state.get("package_a_correction_history"):
            disposition,reason="fail","correction_exhausted"
        else: disposition,reason="revise","deterministic_or_review_dissent"
        verification_sha=verification["aggregate_info"]["sha256"]
        review_sha=review["info"]["sha256"] if review else (exhausted_review_receipt or {}).get("sha256")
    except ControllerError:
        # Once verification was sealed, a later candidate/evidence mutation is
        # a typed terminal failure, never an opportunity to rewrite evidence.
        if not isinstance(state.get("package_a_verification"),dict): raise
        disposition,reason="fail","candidate_or_evidence_invalid"; verification_sha=state["package_a_verification"].get("aggregate_sha256")
        review_sha=(state.get("package_a_review") or {}).get("sha256"); context=None
    if context is not None and all_passed and review_verdict is None and not review_infrastructure_exhausted:
        return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":"awaiting_gate","disposition":"awaiting_review","reused":False}
    core={"schema_version":SCHEMA,"kind":"package_a_gate_receipt","work_id":state["work_id"],"policy":POLICY_ID,
        "gate_name":"orchestrator-package-a-gate/v1","adjudicator_principal":PACKAGE_A_GATE_PRINCIPAL,"candidate_id":candidate.get("id"),
        "evidence_digest":candidate.get("evidence_digest"),"verification_aggregate_sha256":verification_sha,"review_sha256":review_sha,
        "correction_already_used":bool(state.get("package_a_correction_used") or state.get("package_a_correction_history")),"disposition":disposition,"reason_code":reason}
    receipt_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"receipt_id":receipt_id,"issued_at":candidate.get("created_at") or state.get("created_at")}
    gate_dir=os.path.join(directory,"package-a-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir) or not inside(real(gate_dir),directory)):
        raise ControllerError("Package A fixed gate directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    receipt_info=_package_a_adopt_json(os.path.join(gate_dir,receipt_id+".json"),gate_dir,receipt,"fixed gate receipt")
    if disposition=="revise":
        assert context is not None
        instruction=_package_a_derived_instruction(context["verification"],review)
        _package_a_prepare_automatic_correction(directory,state,context,instruction,receipt_info); state["phase"]="prepared"
    elif disposition=="pass": state["phase"]="completed"
    else: state["phase"]="failed"
    state["gate"]={"kind":"package_a_fixed_gate","gate_name":PACKAGE_A_GATE_PRINCIPAL,"verdict":disposition,"reason_code":reason,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"receipt_id":receipt_id,"receipt_sha256":receipt_info["sha256"],"policy":POLICY_ID}
    state["package_a_gate_receipt"]={"path":receipt_info["path"],"sha256":receipt_info["sha256"],"receipt_id":receipt_id,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"disposition":disposition}
    save(directory,state)
    result=_package_a_gate_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


# ---------------------------------------------------------------------------
# Package A v4 — controller-adopted-candidate route
# ---------------------------------------------------------------------------

def _is_package_a_v4(state: Dict[str,Any]) -> bool:
    return state.get("work_id")==PACKAGE_A_V4_WORK_ID


def _package_a_v4_source_intact(root: str) -> Dict[str,Any]:
    """Validate and return the immutable v3 source package state for v4 adoption."""
    source_dir=work_dir(root,PACKAGE_A_V4_SOURCE_WORK_ID); state=load(source_dir)
    if state.get("phase")!="failed" or state.get("work_id")!=PACKAGE_A_V4_SOURCE_WORK_ID:
        raise ControllerError("Package A v4 source package identity or phase changed")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_A_V4_SOURCE_CANDIDATE_ID or candidate.get("evidence_digest")!=PACKAGE_A_V4_SOURCE_EVIDENCE_DIGEST:
        raise ControllerError("Package A v4 source candidate identity changed")
    gate_bound=state.get("package_a_gate_receipt") if isinstance(state.get("package_a_gate_receipt"),dict) else {}
    gates_dir=os.path.join(source_dir,"package-a-gates")
    gate_info=capped_regular_file_info(gate_bound.get("path"),gates_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(gate_bound.get("path"),str) else None
    if not gate_info or gate_info.get("sha256")!=PACKAGE_A_V4_SOURCE_GATE_RECEIPT_SHA256:
        raise ControllerError("Package A v4 source gate receipt changed")
    try: gate_receipt=json.loads(Path(gate_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v4 source gate receipt is unreadable") from exc
    if gate_receipt.get("reason_code")!=PACKAGE_A_V4_SOURCE_GATE_REASON:
        raise ControllerError("Package A v4 source gate reason changed")
    source_wt=(state.get("worktree") or {}).get("path")
    if not isinstance(source_wt,str): raise ControllerError("Package A v4 source worktree path is missing")
    for rel,expected_sha in (("scripts/cowork_dispatch.py",PACKAGE_A_V4_SOURCE_MODULE_SHA256),("scripts/test_cowork.py",PACKAGE_A_V4_SOURCE_TEST_SHA256)):
        item=capped_regular_file_info(os.path.join(source_wt,rel),source_wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=expected_sha: raise ControllerError("Package A v4 source file %s has wrong hash"%rel)
    review_dir=os.path.join(source_dir,"package-a-review-attempts")
    history=state.get("package_a_review_attempt_history") if isinstance(state.get("package_a_review_attempt_history"),list) else []
    current_attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
    all_attempts=list(history)+([current_attempt] if current_attempt else [])
    found_first=found_second=False
    for attempt in all_attempts:
        if not isinstance(attempt,dict): continue
        rpath=attempt.get("receipt_path")
        rinfo=capped_regular_file_info(rpath,review_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(rpath,str) else None
        if not rinfo: continue
        if rinfo.get("sha256")==PACKAGE_A_V4_SOURCE_FIRST_REVIEW_SHA256: found_first=True
        if rinfo.get("sha256")==PACKAGE_A_V4_SOURCE_SECOND_REVIEW_SHA256: found_second=True
    if not found_first: raise ControllerError("Package A v4 source first review terminal receipt changed")
    if not found_second: raise ControllerError("Package A v4 source second review terminal receipt changed")
    return {"state":state,"source_wt":source_wt,"gate_receipt":gate_receipt}


def _package_a_v4_candidate_intact(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> None:
    candidate_keys={"schema_version","id","evidence_digest","evidence","packet_verified","created_at"}
    evidence_keys={"evidence_kind","route","adoption_receipt_path","adoption_receipt_sha256","changed_paths","declared_artifacts","worktree_fingerprint","package_a_baseline_receipt_sha256","package_a_baseline_fingerprint_digest"}
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    created=candidate.get("created_at")
    digest=digest_bytes(json.dumps(evidence,sort_keys=True,separators=(",",":")).encode())
    current_status=git(state["worktree"]["path"],["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    current_fingerprint=worktree_fingerprint(state["worktree"]["path"])
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    if (not isinstance(candidate,dict) or set(candidate)!=candidate_keys or candidate.get("schema_version")!=SCHEMA or candidate.get("packet_verified") is not True or
            not isinstance(created,str) or not created or len(created.encode())>64 or set(evidence)!=evidence_keys or
            evidence.get("evidence_kind")!="controller_adopted_candidate" or evidence.get("route")!=PACKAGE_A_V4_ROUTE or
            evidence.get("adoption_receipt_sha256")!=adopt_bound.get("receipt_sha256") or
            evidence.get("package_a_baseline_receipt_sha256")!=state["package_a_prerequisites"]["sha256"] or
            evidence.get("package_a_baseline_fingerprint_digest")!=baseline["post_materialization_fingerprint"]["digest"] or
            evidence.get("changed_paths")!=current_status or evidence.get("worktree_fingerprint")!=current_fingerprint or
            candidate.get("evidence_digest")!=digest or candidate.get("id")!="package-a-"+digest[:32] or
            evidence.get("declared_artifacts")!=declared_artifacts(state["worktree"]["path"])):
        raise ControllerError("Package A v4 candidate deterministic evidence binding changed")


def _command_adopt_package_a_candidate(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if state.get("work_id") not in (PACKAGE_A_V4_WORK_ID,PACKAGE_A_V5_WORK_ID): raise ControllerError("Package A adoption requires v4 or v5 identity")
    if not state.get("package_a_prerequisites"): raise ControllerError("Package A adoption requires materialized prerequisites")
    if state.get("package_a_adoption"):
        adopt_bound=state["package_a_adoption"]
        adopt_dir=os.path.join(directory,"package-a-adoption")
        intent_info=capped_regular_file_info(adopt_bound.get("intent_path"),adopt_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(adopt_bound.get("intent_path"),str) else None
        receipt_info=capped_regular_file_info(adopt_bound.get("receipt_path"),adopt_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(adopt_bound.get("receipt_path"),str) else None
        if not intent_info or not receipt_info or intent_info.get("sha256")!=adopt_bound.get("intent_sha256") or receipt_info.get("sha256")!=adopt_bound.get("receipt_sha256"):
            raise ControllerError("Package A adoption state binding changed")
        return {"schema_version":SCHEMA,"operation":"adopt_package_a_candidate","reused":True,"candidate_id":adopt_bound["candidate_id"],"evidence_digest":adopt_bound["evidence_digest"],"adoption_receipt":{"path":receipt_info["path"],"sha256":receipt_info["sha256"]},"route":PACKAGE_A_V4_ROUTE}
    if state.get("phase")!="prepared" or state.get("attempt"): raise ControllerError("Package A adoption requires a fresh prepared package with no attempt")
    baseline=_package_a_prerequisites_intact(directory,state)
    require_unchanged_base(state["repo"]["root"],PACKAGE_A_BASE_HEAD)
    root=os.path.dirname(directory); source=(_package_a_v5_source_intact(root) if _is_package_a_v5(state) else _package_a_v4_source_intact(root)); source_wt=source["source_wt"]; wt=state["worktree"]["path"]
    FILES_TO_ADOPT=[("scripts/cowork_dispatch.py",PACKAGE_A_V4_SOURCE_MODULE_SHA256),("scripts/test_cowork.py",PACKAGE_A_V4_SOURCE_TEST_SHA256)]
    adopt_dir=os.path.join(directory,"package-a-adoption")
    if os.path.lexists(adopt_dir) and (os.path.islink(adopt_dir) or not os.path.isdir(adopt_dir)): raise ControllerError("Package A adoption directory is unsafe")
    os.makedirs(adopt_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(adopt_dir,"intent.json")
    if not os.path.lexists(intent_path):
        staged=git(wt,["diff","--cached","--name-only"]).strip()
        if staged: raise ControllerError("Package A adoption requires no staged state in destination worktree")
        pre_status=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines()
        permitted_pre={"?? scripts/test_dispatch_contract_characterization.py","?? scripts/fixtures/dispatch_contract_characterization_sources.json"," M scripts/test_cowork.py"}
        if set(pre_status)!=permitted_pre: raise ControllerError("Package A destination worktree has unexpected pre-adoption state")
    before_fp=worktree_fingerprint(wt)
    files_info=[]
    for rel,expected_sha in FILES_TO_ADOPT:
        src=os.path.join(source_wt,rel); dst=os.path.join(wt,rel)
        src_item=capped_regular_file_info(src,source_wt,MAX_CANDIDATE_PATH_BYTES)
        if not src_item or src_item.get("sha256")!=expected_sha: raise ControllerError("Package A adoption source file %s hash mismatch"%rel)
        if os.path.islink(dst): raise ControllerError("Package A adoption destination %s is a symlink"%rel)
        files_info.append({"path":rel,"source_sha256":expected_sha,"source_path":src,"destination":dst})
    intent={"schema_version":SCHEMA,"kind":"package_a_adoption_intent","work_id":state["work_id"],"source_work_id":PACKAGE_A_V4_SOURCE_WORK_ID,
            "source_candidate_id":PACKAGE_A_V4_SOURCE_CANDIDATE_ID,"source_evidence_digest":PACKAGE_A_V4_SOURCE_EVIDENCE_DIGEST,
            "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],
            "before_fingerprint":before_fp,"files":files_info}
    prior_intent=capped_regular_file_info(intent_path,adopt_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not prior_intent: raise ControllerError("Package A adoption intent is unsafe")
    if prior_intent:
        try: prior_value=json.loads(Path(prior_intent["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A adoption intent is unreadable") from exc
        if {k:v for k,v in prior_value.items() if k!="before_fingerprint"}!={k:v for k,v in intent.items() if k!="before_fingerprint"}:
            raise ControllerError("Package A adoption intent conflicts with recovery")
    else:
        atomic_json(intent_path,intent); prior_intent=capped_regular_file_info(intent_path,adopt_dir,MAX_PLAN_ARTIFACT_BYTES)
    for fi in files_info:
        dst=fi["destination"]; rel=fi["path"]
        if os.path.islink(dst): raise ControllerError("Package A adoption destination %s is a symlink"%rel)
        existing=capped_regular_file_info(dst,wt,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(dst) else None
        if existing and existing.get("sha256")==fi["source_sha256"]: continue
        tmp_name="copy-"+rel.replace("/","-")+".tmp"; tmp=os.path.join(adopt_dir,tmp_name)
        try:
            tmp_item=capped_regular_file_info(tmp,adopt_dir,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(tmp) else None
            if not tmp_item or tmp_item.get("sha256")!=fi["source_sha256"]:
                flags=os.O_WRONLY|os.O_CREAT|(os.O_TRUNC if tmp_item else os.O_EXCL)
                fd=os.open(tmp,flags,0o600)
                with os.fdopen(fd,"wb") as out,open(fi["source_path"],"rb") as src: shutil.copyfileobj(src,out);out.flush();os.fsync(out.fileno())
            if digest_bytes(Path(tmp).read_bytes())!=fi["source_sha256"]: raise ControllerError("Package A adoption copy hash mismatch for %s"%rel)
            os.makedirs(os.path.dirname(dst),exist_ok=True); os.replace(tmp,dst)
            dir_fd=os.open(os.path.dirname(dst),os.O_RDONLY)
            try: os.fsync(dir_fd)
            finally: os.close(dir_fd)
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    after_fp=worktree_fingerprint(wt); dest_file_info=[]
    for fi in files_info:
        item=capped_regular_file_info(fi["destination"],wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=fi["source_sha256"]: raise ControllerError("Package A adoption destination verification failed for %s"%fi["path"])
        if os.path.islink(fi["destination"]): raise ControllerError("Package A adoption destination %s is a symlink"%fi["path"])
        dest_file_info.append({"path":fi["path"],"source_sha256":fi["source_sha256"],"destination_sha256":item["sha256"]})
    receipt={"schema_version":SCHEMA,"kind":"package_a_adoption_receipt","work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],
             "route":PACKAGE_A_V4_ROUTE,"policy":POLICY_ID,"source_work_id":PACKAGE_A_V4_SOURCE_WORK_ID,
             "source_candidate_id":PACKAGE_A_V4_SOURCE_CANDIDATE_ID,"source_evidence_digest":PACKAGE_A_V4_SOURCE_EVIDENCE_DIGEST,
             "source_fingerprint_digest":PACKAGE_A_V4_SOURCE_FINGERPRINT,"source_gate_receipt_sha256":PACKAGE_A_V4_SOURCE_GATE_RECEIPT_SHA256,
             "source_gate_reason":PACKAGE_A_V4_SOURCE_GATE_REASON,"source_module_sha256":PACKAGE_A_V4_SOURCE_MODULE_SHA256,
             "source_test_sha256":PACKAGE_A_V4_SOURCE_TEST_SHA256,"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
             "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],"before_fingerprint":before_fp,
             "after_fingerprint":after_fp,"intent_sha256":prior_intent["sha256"],"files":dest_file_info,"created_at":utc()}
    receipt_path=os.path.join(adopt_dir,"receipt.json"); receipt_info=_package_a_adopt_json(receipt_path,adopt_dir,receipt,"adoption receipt")
    changed_paths=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines(); current_fp=worktree_fingerprint(wt)
    evidence={"evidence_kind":"controller_adopted_candidate","route":PACKAGE_A_V4_ROUTE,
              "adoption_receipt_path":receipt_path,"adoption_receipt_sha256":receipt_info["sha256"],
              "changed_paths":changed_paths,"worktree_fingerprint":current_fp,"declared_artifacts":[],
              "package_a_baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
              "package_a_baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"]}
    evidence_digest=digest_bytes(json.dumps(evidence,sort_keys=True,separators=(",",":")).encode())
    candidate_id="package-a-"+evidence_digest[:32]
    candidate={"schema_version":SCHEMA,"id":candidate_id,"evidence_digest":evidence_digest,"evidence":evidence,"packet_verified":True,"created_at":utc()}
    delta_files=[]
    for fi in dest_file_info:
        baseline_sha=PACKAGE_A_PREREQUISITE_FILES.get(fi["path"]); delta_files.append({"path":fi["path"],"sha256":fi["source_sha256"],"baseline_sha256":baseline_sha})
    delta={"candidate_id":candidate_id,"evidence_digest":evidence_digest,"baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],"files":delta_files}
    delta["sha256"]=digest_bytes(json.dumps(delta,sort_keys=True,separators=(",",":")).encode())
    delta_dir=os.path.join(directory,"package-a-delta"); os.makedirs(delta_dir,mode=0o700,exist_ok=True)
    delta_path=os.path.join(delta_dir,candidate_id+".json"); delta_info=_package_a_adopt_json(delta_path,delta_dir,delta,"adoption delta receipt")
    state["candidate"]=candidate; state["phase"]="awaiting_gate"
    state["package_a_adoption"]={"intent_path":intent_path,"intent_sha256":prior_intent["sha256"],"receipt_path":receipt_path,"receipt_sha256":receipt_info["sha256"],"candidate_id":candidate_id,"evidence_digest":evidence_digest,"route":PACKAGE_A_V4_ROUTE}
    state["package_a_builder_delta"]={"path":delta_path,"sha256":delta_info["sha256"],"candidate_id":candidate_id,"evidence_digest":evidence_digest,"delta_sha256":delta["sha256"]}
    if not any(row.get("kind")=="package_a_candidate_adopted" and row.get("candidate_id")==candidate_id for row in recent_events(directory)):
        append_event(directory,"package_a_candidate_adopted",candidate_id=candidate_id,evidence_digest=evidence_digest,route=PACKAGE_A_V4_ROUTE,adoption_receipt_sha256=receipt_info["sha256"])
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"adopt_package_a_candidate","reused":False,"candidate_id":candidate_id,"evidence_digest":evidence_digest,"adoption_receipt":{"path":receipt_path,"sha256":receipt_info["sha256"]},"route":PACKAGE_A_V4_ROUTE}


def command_adopt_package_a_candidate(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_adopt_package_a_candidate(args)


def _package_a_v4_verification_static(state: Dict[str,Any],candidate: Dict[str,Any],delta: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"route":PACKAGE_A_V4_ROUTE,
            "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
            "adoption_receipt_sha256":adopt_bound.get("receipt_sha256"),"policy":POLICY_ID,
            "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],
            "delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],"delta_sha256":delta["sha256"],
            "candidate_fingerprint_digest":candidate["evidence"]["worktree_fingerprint"]["digest"]}


def _package_a_v4_verification_specs() -> List[Dict[str,Any]]:
    builder=PACKAGE_A_V4_BUILDER_NAME
    return [
        {"label":"test_cowork","argv":["python3","-m","unittest","scripts/test_cowork.py"],"timeout":300,"kind":"unittest"},
        {"label":"characterization","argv":["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],"timeout":180,"kind":"characterization"},
        {"label":"diff_check","argv":["git","diff","--check"],"timeout":60,"kind":"empty"},
        {"label":"candidate_delta","argv":["controller","package-a-delta"],"timeout":0,"kind":"controller"},
        {"label":"json_probe","argv":["python3","-c",_package_a_probe_code(builder)],"timeout":30,"kind":"probe"},
    ]


def _package_a_v4_validate_verification(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_verification") if isinstance(state.get("package_a_verification"),dict) else {}
    if set(bound)!={"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"}: raise ControllerError("Package A verification state binding is malformed")
    verify_dir=_package_a_verification_dir(directory,candidate); intent_info=capped_regular_file_info(bound.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("intent_path"),str) else None
    aggregate_info=capped_regular_file_info(bound.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("aggregate_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not aggregate_info or aggregate_info.get("sha256")!=bound.get("aggregate_sha256"): raise ControllerError("Package A verification intent or aggregate changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text()); aggregate=json.loads(Path(aggregate_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification evidence is unreadable") from exc
    static=_package_a_v4_verification_static(state,candidate,delta,baseline); specs=_package_a_v4_verification_specs()
    expected_intent_keys={"schema_version","kind","created_at","static","specs","receipt_paths","output_paths","terminal_paths","start_paths","aggregate_path"}
    if (not isinstance(intent,dict) or set(intent)!=expected_intent_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_a_verification_intent" or
            not isinstance(intent.get("created_at"),str) or intent.get("static")!=static or intent.get("specs")!=specs or
            intent.get("receipt_paths")!=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("output_paths")!=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)] or intent.get("aggregate_path")!=aggregate_info["path"]):
        raise ControllerError("Package A verification intent binding changed")
    if (intent.get("terminal_paths")!=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("start_paths")!=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]):
        raise ControllerError("Package A verification execution intent binding changed")
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,intent["receipt_paths"],intent["output_paths"],intent["terminal_paths"],intent["start_paths"])):
        info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT)
        if not info or not output_info: raise ControllerError("Package A verification receipt or output is missing or unsafe")
        try: raw=Path(output_info["path"]).read_bytes()
        except OSError as exc: raise ControllerError("Package A verification output is unreadable") from exc
        try: receipt=json.loads(Path(info["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification receipt is unreadable") from exc
        terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT+64*1024)
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
        receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
        structurally_bound=(isinstance(receipt,dict) and set(receipt)==receipt_keys and receipt.get("schema_version")==SCHEMA and receipt.get("kind")=="package_a_verification_receipt" and
                receipt.get("index")==index and receipt.get("label")==spec["label"] and receipt.get("argv")==spec["argv"] and receipt.get("cwd")==state["worktree"]["path"] and
                receipt.get("timeout_seconds")==spec["timeout"] and receipt.get("static")==static and bool(terminal_info) and
                receipt.get("start_path")==start_info["path"] and receipt.get("start_sha256")==start_info["sha256"] and
                receipt.get("terminal_path")==terminal_info["path"] and receipt.get("terminal_sha256")==terminal_info["sha256"])
        if not structurally_bound: raise ControllerError("Package A verification receipt structure changed")
        if not _package_a_receipt_consistent(spec,receipt,output_info,raw): raise ControllerError("Package A verification receipt semantics changed: "+spec["label"])
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
    aggregate_keys={"schema_version","kind","created_at","static","receipts","all_passed","post_fingerprint"}
    if (not isinstance(aggregate,dict) or set(aggregate)!=aggregate_keys or aggregate.get("schema_version")!=SCHEMA or aggregate.get("kind")!="package_a_verification_aggregate" or
            aggregate.get("created_at")!=intent["created_at"] or aggregate.get("static")!=static or aggregate.get("receipts")!=refs or aggregate.get("all_passed") is not all(row["passed"] for row in refs) or
            aggregate.get("post_fingerprint")!=candidate["evidence"]["worktree_fingerprint"] or bound.get("candidate_id")!=candidate["id"] or bound.get("evidence_digest")!=candidate["evidence_digest"]):
        raise ControllerError("Package A verification aggregate binding changed")
    return {"intent":intent,"aggregate":aggregate,"aggregate_info":aggregate_info,"refs":refs}


def _command_verify_package_a_v4(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    """v4 verification: adopted candidate, no worker packet, no implementer attempt."""
    _package_a_v4_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate)
    if state.get("package_a_verification"):
        verified=_package_a_v4_validate_verification(directory,state,candidate,baseline,delta)
        return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":True,"aggregate_path":verified["aggregate_info"]["path"],"aggregate_sha256":verified["aggregate_info"]["sha256"],"all_passed":verified["aggregate"]["all_passed"]}
    _top_verify=os.path.join(directory,"package-a-verification")
    if os.path.lexists(_top_verify) and (os.path.islink(_top_verify) or not os.path.isdir(_top_verify) or not inside(os.path.realpath(_top_verify),directory)): raise ControllerError("Package A verification top-level directory is unsafe")
    static=_package_a_v4_verification_static(state,candidate,delta,baseline); specs=_package_a_v4_verification_specs(); verify_dir=_package_a_verification_dir(directory,candidate)
    if os.path.lexists(verify_dir) and (os.path.islink(verify_dir) or not os.path.isdir(verify_dir)): raise ControllerError("Package A verification directory is unsafe")
    os.makedirs(verify_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(verify_dir,"intent.json"); aggregate_path=os.path.join(verify_dir,"aggregate.json"); receipt_paths=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)]; output_paths=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    terminal_paths=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)]; start_paths=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]
    base_intent={"schema_version":SCHEMA,"kind":"package_a_verification_intent","static":static,"specs":specs,"receipt_paths":receipt_paths,"output_paths":output_paths,"terminal_paths":terminal_paths,"start_paths":start_paths,"aggregate_path":aggregate_path}
    existing_intent=capped_regular_file_info(intent_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not existing_intent: raise ControllerError("Package A verification intent is unsafe")
    if existing_intent:
        try: intent=json.loads(Path(existing_intent["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification intent is unreadable") from exc
        if set(intent)!=(set(base_intent)|{"created_at"}) or {k:v for k,v in intent.items() if k!="created_at"}!=base_intent or not isinstance(intent.get("created_at"),str): raise ControllerError("Package A verification orphan intent conflicts")
    else:
        if os.path.lexists(aggregate_path) or any(os.path.lexists(path) for path in receipt_paths+output_paths+terminal_paths+start_paths): raise ControllerError("Package A verification output cannot precede durable intent")
        intent={**base_intent,"created_at":utc()}; existing_intent=_package_a_adopt_json(intent_path,verify_dir,intent,"verification intent")
    wt=state["worktree"]["path"]; refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,receipt_paths,output_paths,terminal_paths,start_paths)):
        before=worktree_fingerprint(wt)
        if before!=candidate["evidence"]["worktree_fingerprint"]: raise ControllerError("Package A candidate changed before deterministic gate")
        prior=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(path) else None
        if os.path.lexists(path) and not prior: raise ControllerError("Package A verification orphan receipt is unsafe")
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(dt.datetime.fromisoformat(intent["created_at"].replace("Z","+00:00"))+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        result,raw,terminal_info=_package_a_execute_gate(spec,index,wt,verify_dir,terminal_path,start_path,static,wrapper_nonce,deadline_text)
        output_info=_package_a_adopt_bytes(output_path,verify_dir,raw,"gate output")
        result["output_path"]=output_info["path"]
        if prior:
            try: old=json.loads(Path(prior["path"]).read_text())
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A verification orphan receipt is unreadable") from exc
            receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            if (not isinstance(old,dict) or set(old)!=receipt_keys or old.get("schema_version")!=SCHEMA or old.get("kind")!="package_a_verification_receipt" or old.get("index")!=index or old.get("label")!=spec["label"] or old.get("argv")!=spec["argv"] or old.get("cwd")!=wt or old.get("timeout_seconds")!=spec["timeout"] or old.get("static")!=static or not output_info or not terminal_info or old.get("start_path")!=start_info["path"] or old.get("start_sha256")!=start_info["sha256"] or old.get("terminal_path")!=terminal_info["path"] or old.get("terminal_sha256")!=terminal_info["sha256"] or not _package_a_receipt_consistent(spec,old,output_info,raw)):
                raise ControllerError("Package A verification orphan receipt conflicts")
            refs.append({"index":index,"label":spec["label"],"path":prior["path"],"sha256":prior["sha256"],"counters":old["counters"],"passed":old["passed"]})
        else:
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            receipt={"schema_version":SCHEMA,"kind":"package_a_verification_receipt","index":index,"label":spec["label"],"argv":spec["argv"],"cwd":wt,"timeout_seconds":spec["timeout"],"static":static,
                     "start_path":start_info["path"],"start_sha256":start_info["sha256"],"terminal_path":terminal_info["path"],"terminal_sha256":terminal_info["sha256"],
                     **{k:result[k] for k in ("exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed")}}
            receipt_info=_package_a_adopt_json(path,verify_dir,receipt,"verification receipt")
            refs.append({"index":index,"label":spec["label"],"path":receipt_info["path"],"sha256":receipt_info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
        if not refs[-1]["passed"]: break
    all_passed=all(row["passed"] for row in refs) and len(refs)==len(specs)
    post_fp=worktree_fingerprint(wt)
    aggregate={"schema_version":SCHEMA,"kind":"package_a_verification_aggregate","created_at":intent["created_at"],"static":static,"receipts":refs,"all_passed":all_passed,"post_fingerprint":post_fp}
    aggregate_info=_package_a_adopt_json(aggregate_path,verify_dir,aggregate,"verification aggregate")
    state["package_a_verification"]={"intent_path":intent_path,"intent_sha256":existing_intent["sha256"],"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="package_a_verified" and row.get("candidate_id")==candidate["id"] for row in recent_events(directory)):
        append_event(directory,"package_a_verified",candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],all_passed=all_passed)
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":False,"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"all_passed":all_passed}


def _package_a_v4_dossier_content(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any],verification: Dict[str,Any]) -> Dict[str,Any]:
    adopt_bound=state["package_a_adoption"]; wt=state["worktree"]["path"]
    module_path=os.path.join(wt,"scripts/cowork_dispatch.py")
    module_item=capped_regular_file_info(module_path,wt,MAX_CANDIDATE_PATH_BYTES)
    if not module_item or module_item.get("sha256")!=PACKAGE_A_V4_SOURCE_MODULE_SHA256:
        raise ControllerError("Package A v4 dossier production module hash mismatch")
    try: module_text=Path(module_item["path"]).read_text(encoding="utf-8")
    except (OSError,UnicodeDecodeError) as exc: raise ControllerError("Package A v4 dossier production module is unreadable") from exc
    try: diff_result=subprocess.run(["git","diff","HEAD","--","scripts/test_cowork.py"],cwd=wt,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
    except subprocess.TimeoutExpired as exc: raise ControllerError("Package A v4 dossier test delta timed out") from exc
    if diff_result.returncode not in (0,1): raise ControllerError("Package A v4 dossier test delta command failed")
    try: delta_text=diff_result.stdout.decode("utf-8","replace")
    except Exception as exc: raise ControllerError("Package A v4 dossier test delta is not decodable") from exc
    gate_summaries=[]
    for ref in verification["refs"]:
        gate_summaries.append({"index":ref["index"],"label":ref["label"],"sha256":ref["sha256"],"counters":ref["counters"],"passed":ref["passed"]})
    dossier={"schema_version":SCHEMA,"kind":"package_a_v4_review_dossier","work_id":PACKAGE_A_V4_WORK_ID,"outcome_id":PACKAGE_A_V4_OUTCOME_ID,
             "policy":POLICY_ID,"route":PACKAGE_A_V4_ROUTE,"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
             "adoption_receipt_sha256":adopt_bound["receipt_sha256"],"source_work_id":PACKAGE_A_V4_SOURCE_WORK_ID,
             "source_candidate_id":PACKAGE_A_V4_SOURCE_CANDIDATE_ID,"source_evidence_digest":PACKAGE_A_V4_SOURCE_EVIDENCE_DIGEST,
             "source_gate_receipt_sha256":PACKAGE_A_V4_SOURCE_GATE_RECEIPT_SHA256,"source_gate_reason":PACKAGE_A_V4_SOURCE_GATE_REASON,
             "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
             "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],"gate_summaries":gate_summaries,
             "changed_paths":["scripts/cowork_dispatch.py","scripts/test_cowork.py"],
             "authority_statement":("Package A v4 review-rescue. Route: controller_adopted_candidate. Adjudicator: orchestrator-package-a-gate/v1. "
                                    "This package reviews the already-verified v3 candidate adopted without modification. "
                                    "No new implementation. No provider attempt. No builder correction authorized. Review-only."),
             "record_api":{"records":["DispatchContract","DispatchDecision","AttemptLink"],
                           "validators":["validate_dispatch_contract(record)","validate_dispatch_decision(record, contract)","validate_attempt_link(record)"],
                           "reducer":"decide(contract, policy_result=None, preflight_result=None, probe_result=None)",
                           "idempotency_key_builder":"build_attempt_link_idempotency_key(role, kind, source_ref, ordinal)"},
             "contracts":sorted(M0C_CONTRACTS),"production_module":module_text,"test_cowork_delta":delta_text,"created_at":utc()}
    return dossier


def _command_build_package_a_v4_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a_v4(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A v4 dossier requires v4 awaiting gate")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_v4_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate)
    if not state.get("package_a_verification"): raise ControllerError("Package A v4 dossier requires verified candidate")
    verification=_package_a_v4_validate_verification(directory,state,candidate,baseline,delta)
    if verification["aggregate"].get("all_passed") is not True: raise ControllerError("Package A v4 dossier requires all gates passed")
    dossier_dir=os.path.join(directory,"package-a-v4-dossier")
    if state.get("package_a_v4_dossier"):
        bound=state["package_a_v4_dossier"]
        dossier_info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_A_V4_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
        if not dossier_info or dossier_info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A v4 dossier changed")
        return {"schema_version":SCHEMA,"operation":"build_package_a_v4_dossier","reused":True,"path":dossier_info["path"],"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"]}
    if os.path.lexists(dossier_dir) and (os.path.islink(dossier_dir) or not os.path.isdir(dossier_dir)): raise ControllerError("Package A v4 dossier directory is unsafe")
    os.makedirs(dossier_dir,mode=0o700,exist_ok=True)
    dossier=_package_a_v4_dossier_content(directory,state,candidate,baseline,delta,verification)
    encoded=(json.dumps(dossier,sort_keys=True,indent=2)+"\n").encode("utf-8")
    if len(encoded)>PACKAGE_A_V4_DOSSIER_CAP: raise ControllerError("Package A v4 dossier exceeds 128 KiB cap (%d bytes)"%len(encoded))
    dossier_path=os.path.join(dossier_dir,candidate["id"]+".dossier.json")
    dossier_info=_package_a_adopt_bytes(dossier_path,dossier_dir,encoded,"v4 dossier")
    state["package_a_v4_dossier"]={"path":dossier_path,"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    append_event(directory,"package_a_v4_dossier_built",candidate_id=candidate["id"],sha256=dossier_info["sha256"],bytes=dossier_info["bytes"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"build_package_a_v4_dossier","reused":False,"path":dossier_path,"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"]}


def command_build_package_a_v4_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_build_package_a_v4_dossier(args)


def _package_a_v4_dossier_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_v4_dossier") if isinstance(state.get("package_a_v4_dossier"),dict) else {}
    if set(bound)!={"path","sha256","bytes","candidate_id","evidence_digest"}: raise ControllerError("Package A v4 dossier state binding is malformed")
    dossier_dir=os.path.join(directory,"package-a-v4-dossier")
    info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_A_V4_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256") or info.get("bytes")!=bound.get("bytes"): raise ControllerError("Package A v4 dossier changed")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if bound.get("candidate_id")!=candidate.get("id") or bound.get("evidence_digest")!=candidate.get("evidence_digest"):
        raise ControllerError("Package A v4 dossier candidate binding changed")
    return {"path":info["path"],"sha256":info["sha256"],"bytes":info["bytes"]}


def _package_a_v4_review_context(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_v4_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_v4_validate_verification(directory,state,candidate,baseline,delta)
    dossier=_package_a_v4_dossier_intact(directory,state)
    changed=[row["path"] for row in delta["files"]]
    if changed!=["scripts/cowork_dispatch.py","scripts/test_cowork.py"]: raise ControllerError("Package A v4 review changed-path binding is invalid")
    return {"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"dossier":dossier,"changed_paths":changed}


def _package_a_v4_review_schema(state: Dict[str,Any],context: Dict[str,Any],attempt_id: str,run: str,nonce: str) -> Dict[str,Any]:
    candidate=context["candidate"]; verification=context["verification"]; dossier=context["dossier"]
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","work_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce","candidate_id","evidence_digest","adoption_receipt_sha256","dossier_sha256","verification_aggregate_sha256","verification_receipt_sha256s","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_a_v4_review"},"work_id":{"type":"string","const":state["work_id"]},
            "policy":{"type":"string","const":POLICY_ID},"review_attempt_id":{"type":"string","const":attempt_id},
            "backend":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"candidate_id":{"type":"string","const":candidate["id"]},
            "evidence_digest":{"type":"string","const":candidate["evidence_digest"]},"adoption_receipt_sha256":{"type":"string","const":adopt_bound.get("receipt_sha256")},
            "dossier_sha256":{"type":"string","const":dossier["sha256"]},"verification_aggregate_sha256":{"type":"string","const":verification["aggregate_info"]["sha256"]},
            "verification_receipt_sha256s":{"type":"array","minItems":5,"maxItems":5,"items":{"type":"string"}},
            "changed_paths":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_a_v4_review_expected(state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    verification=context["verification"]; dossier=context["dossier"]
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"schema_version":SCHEMA,"kind":"package_a_v4_review","work_id":state["work_id"],"policy":POLICY_ID,"review_attempt_id":attempt["id"],
            "backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_nonce":attempt["nonce"],
            "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
            "adoption_receipt_sha256":adopt_bound.get("receipt_sha256"),"dossier_sha256":dossier["sha256"],
            "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],
            "verification_receipt_sha256s":[row["sha256"] for row in verification["refs"]],"changed_paths":context["changed_paths"]}


def _package_a_v4_review_attempt_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package A v4 review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"review attempt id"),(attempt.get("run_id"),"review run id"),(attempt.get("nonce"),"review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(directory,"package-a-review-attempts"); expected_schema=_package_a_v4_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_a_v4_review_expected(state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package A v4 review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_A_CLAUDE_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=context["candidate"]["id"] or attempt.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(directory,"logs")),("stderr",os.path.join(directory,"logs"))))):
        raise ControllerError("Package A v4 review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v4 review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A v4 review schema binding changed")
    return attempt


def _package_a_v4_review_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_review") if isinstance(state.get("package_a_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict","model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package A v4 independent review state binding is malformed")
    item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A v4 independent review envelope changed")
    try: envelope=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v4 independent review envelope is unreadable") from exc
    attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    _package_a_v4_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    packet=envelope.get("model_packet") if isinstance(envelope,dict) else None
    expected=_package_a_v4_review_expected(state,context,attempt); packet_keys=set(expected)|{"verdict","findings","checks"}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id","reviewer_session_id","terminal_receipt_sha256","model_packet_sha256","model_packet"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or
            envelope.get("kind")!="package_a_v4_review_envelope" or envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or
            envelope.get("candidate_id")!=context["candidate"]["id"] or envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            envelope.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or envelope.get("run_id")!=attempt.get("run_id") or envelope.get("review_attempt_id")!=attempt.get("id") or
            envelope.get("reviewer_session_id")!=attempt.get("provider_session_id") or envelope.get("terminal_receipt_sha256")!=receipt["sha256"] or
            not isinstance(packet,dict) or set(packet)!=packet_keys or any(packet.get(k)!=v for k,v in expected.items()) or
            envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded")):
        raise ControllerError("Package A v4 independent review envelope binding changed")
    if (packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A v4 independent review verdict packet is malformed")
    expected_bound={"path":item["path"],"sha256":item["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":attempt["provider_session_id"],"policy":POLICY_ID,
        "verdict":packet["verdict"],"model_packet_sha256":envelope["model_packet_sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    if bound!=expected_bound or attempt.get("packet_sha256")!=item["sha256"] or not isinstance(attempt.get("consumed_at"),str):
        raise ControllerError("Package A v4 independent review state no longer matches its envelope")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":receipt}


def _package_a_v4_gate_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    if not isinstance(state.get("package_a_gate_receipt"),dict): return None
    sealed=_package_a_gate_receipt_intact(directory,state); receipt=sealed["receipt"]
    expected_phase={"pass":"completed","revise":"prepared","fail":"failed"}[receipt["disposition"]]
    if state.get("phase")!=expected_phase: raise ControllerError("Package A v4 fixed gate phase binding changed")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if (gate.get("kind")!="package_a_fixed_gate" or gate.get("gate_name")!=PACKAGE_A_GATE_PRINCIPAL or gate.get("verdict")!=receipt["disposition"] or
            gate.get("receipt_id")!=receipt["receipt_id"] or gate.get("receipt_sha256")!=sealed["info"]["sha256"] or gate.get("candidate_id")!=receipt["candidate_id"] or
            gate.get("evidence_digest")!=receipt["evidence_digest"] or gate.get("reason_code")!=receipt["reason_code"] or gate.get("policy")!=POLICY_ID):
        raise ControllerError("Package A v4 fixed gate state binding changed")
    if receipt["disposition"]=="pass":
        context=_package_a_v4_review_context(directory,state); review=_package_a_v4_review_intact(directory,state,context)
        if (context["verification"]["aggregate"].get("all_passed") is not True or review["packet"].get("verdict")!="pass" or
                context["verification"]["aggregate_info"]["sha256"]!=receipt.get("verification_aggregate_sha256") or review["info"]["sha256"]!=receipt.get("review_sha256")):
            raise ControllerError("Package A v4 passing gate evidence changed")
    event_kind={"pass":"package_a_gate_passed","revise":"package_a_correction_queued","fail":"package_a_gate_failed"}[receipt["disposition"]]
    if not any(row.get("kind")==event_kind and row.get("receipt_id")==receipt["receipt_id"] for row in recent_events(directory)):
        append_event(directory,event_kind,receipt_id=receipt["receipt_id"],gate_name=receipt["gate_name"],policy=POLICY_ID,candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],disposition=receipt["disposition"],next_state=expected_phase)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":expected_phase,"disposition":receipt["disposition"],
            "receipt":{"path":sealed["info"]["path"],"sha256":sealed["info"]["sha256"]},"reused":True,"delivery":None}


def _command_launch_package_a_v4_review(args: argparse.Namespace,directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    context=_package_a_v4_review_context(directory,state)
    dossier=context["dossier"]
    if state.get("package_a_review"): raise ControllerError("Package A v4 candidate already has an ingested independent review")
    existing=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
    if existing:
        _package_a_v4_review_attempt_intact(directory,state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _package_a_review_terminal(directory,existing)
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            append_event(directory,"package_a_review_launch_lost",attempt_id=existing["id"],classification=classification); save(directory,state)
        raise ControllerError("Package A v4 independent review attempt already exists")
    retries=state.get("package_a_review_retries",[])
    if not isinstance(retries,list) or len(retries)>1: raise ControllerError("Package A v4 review retry history is malformed")
    actor=PACKAGE_A_CLAUDE_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(directory,"package-a-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package A v4 review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_a_v4_review_schema(state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"v4 review schema")
    prompt=("Package A v4 review-rescue. Read ONLY the sealed review dossier at: %s. "
            "Do not read any other file, run tests, execute shell commands, spawn agents, or explore the repository. "
            "The dossier contains the full production module, bounded test diff, gate summaries, and exact controller bindings. "
            "Review the three pure record validators, fixed public APIs, reducer allow/refuse purity, JSON round trips, and negative controls. "
            "Return only the required schema JSON packet bound to the exact candidate_id, evidence_digest, adoption_receipt_sha256, dossier_sha256, and verification_aggregate_sha256 provided in the dossier." % dossier["path"])
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package A v4 review prompt exceeds bound")
    logs=os.path.join(directory,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-a-claude.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-a-claude.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind","claude_package_a_review_terminal","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    expected=_package_a_v4_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=305)).isoformat().replace("+00:00","Z")
    state["package_a_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save(directory,state); append_event(directory,"package_a_review_starting",attempt_id=attempt_id,candidate_id=context["candidate"]["id"])
    try: pid,pgid=detached_spawn(wrapper,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["package_a_review_attempt"]["spawn_error"]=type(exc).__name__; state["package_a_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); state["package_a_review_attempt"]["terminal_at"]=utc()
        append_event(directory,"package_a_review_spawn_failed",attempt_id=attempt_id); save(directory,state); raise ControllerError("Package A v4 review controller spawn failed") from exc
    state["package_a_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"package_a_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":attempt_id,"run_id":run,"phase":state["phase"]}


def _command_ingest_package_a_v4_review(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    context=_package_a_v4_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A v4 review requires a quiescent controller-owned attempt")
    _package_a_v4_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            return _package_a_review_capacity_wait(directory,state,context,attempt,terminal,receipt,capacity_event)
        if terminal.get("timed_out"): raise ControllerError("Package A v4 review timed out; timeout is terminal for this package")
        raise ControllerError("Package A v4 independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-a-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package A v4 review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v4 review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    prior_sessions={row.get("provider_session_id") for row in state.get("package_a_review_attempt_history",[]) if isinstance(row,dict)}
    if provider_session in prior_sessions: raise ControllerError("Package A v4 reviewer provider session is not distinct from prior attempts")
    expected=_package_a_v4_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A v4 independent review packet failed strict binding validation")
    packets=os.path.join(directory,"packets"); destination=os.path.join(packets,context["candidate"]["id"]+".package-a-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    envelope={"schema_version":SCHEMA,"kind":"package_a_v4_review_envelope","work_id":state["work_id"],"policy":POLICY_ID,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,
        "run_id":attempt["run_id"],"review_attempt_id":attempt["id"],"reviewer_session_id":provider_session,
        "terminal_receipt_sha256":receipt["sha256"],"model_packet_sha256":model_packet_sha256,"model_packet":packet}
    copied=_package_a_adopt_json(destination,packets,envelope,"v4 independent review envelope")
    state["package_a_review"]={"path":destination,"sha256":copied["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,"verdict":packet["verdict"],
        "model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    attempt["consumed_at"]=utc(); attempt["receipt_sha256"]=receipt["sha256"]; attempt["packet_sha256"]=copied["sha256"]; attempt["provider_session_id"]=provider_session
    append_event(directory,"package_a_review_ingested",candidate_id=context["candidate"]["id"],packet_sha256=copied["sha256"],verdict=packet["verdict"],actor_id=PACKAGE_A_CLAUDE_REVIEW_ACTOR); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_a_review","verdict":packet["verdict"],"packet_sha256":copied["sha256"],"phase":state["phase"]}


def _command_retry_package_a_v4_review(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    if state.get("package_a_review"): raise ControllerError("Package A v4 review retry requires an unconsumed awaiting review")
    context=_package_a_v4_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    retries=state.get("package_a_review_retries",[])
    if not attempt or attempt.get("consumed_at") or not isinstance(retries,list) or retries or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A v4 review infrastructure retry is unavailable")
    _package_a_v4_review_attempt_intact(directory,state,context,attempt)
    schema_info=capped_regular_file_info(attempt.get("schema_path"),os.path.join(directory,"package-a-review-attempts"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_schema=_package_a_v4_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    if not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256"): raise ControllerError("Package A v4 review retry schema binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v4 review retry schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A v4 review retry schema changed")
    evidence={}
    if attempt.get("spawn_error"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("spawn_error_sha256")!=digest_bytes(str(attempt["spawn_error"]).encode()): raise ControllerError("Package A v4 review spawn failure binding changed")
        evidence={"classification":"spawn_failure","receipt_sha256":None,"spawn_error_sha256":attempt["spawn_error_sha256"]}
    elif attempt.get("launch_lost"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("launch_lost")!="prepared_launch_lost" or attempt.get("launch_lost_sha256")!=digest_bytes(b"prepared_launch_lost"):
            raise ControllerError("Package A v4 review launch-lost binding changed")
        evidence={"classification":"prepared_launch_lost","receipt_sha256":None,"spawn_error_sha256":attempt["launch_lost_sha256"]}
    else:
        terminal,receipt=_package_a_review_terminal(directory,attempt)
        output_exists=isinstance(attempt.get("output_path"),str) and os.path.lexists(attempt["output_path"])
        if terminal.get("exit_code")==0 or terminal.get("output_sha256") is not None or output_exists: raise ControllerError("Package A v4 review application result is not infrastructure-retryable")
        if terminal.get("timed_out"): raise ControllerError("Package A v4 review timeout is terminal; not retryable")
        if not terminal.get("output_limit_exceeded"): raise ControllerError("Package A v4 review failure is not the bounded stream overflow infrastructure class")
        capacity_check=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_check: raise ControllerError("Package A v4 review overflow concurrent with capacity event is not retryable")
        evidence={"classification":"bounded_stream_overflow","receipt_sha256":receipt["sha256"],"reviewer_session_id":attempt.get("reviewer_session_id"),"spawn_error_sha256":None}
    archived={**attempt,"retry_evidence":evidence,"schema_sha256":schema_info["sha256"]}
    history=state.get("package_a_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package A v4 review history is malformed")
    state["package_a_review_attempt_history"]=history+[archived]; state["package_a_review_retries"]=[{"at":utc(),"prior_attempt_id":attempt["id"],"evidence":evidence}]; state["package_a_review_attempt"]=None
    append_event(directory,"package_a_review_retry_released",attempt_id=attempt["id"],classification=evidence["classification"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_package_a_review","phase":state["phase"],"retry_released":True}


def _command_adjudicate_package_a_v4(directory: str,state: Dict[str,Any],candidate: Dict[str,Any]) -> Dict[str,Any]:
    """Derive the fixed v4 Package-A disposition: no revise path, needs_correction treated as fail."""
    replay=_package_a_v4_gate_replay(directory,state)
    if replay: return replay
    context=None; review=None; all_passed=False; review_verdict=None; review_infrastructure_exhausted=False; exhausted_review_receipt=None
    try:
        baseline=_package_a_prerequisites_intact(directory,state); _package_a_v4_candidate_intact(directory,state,candidate,baseline)
        delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_v4_validate_verification(directory,state,candidate,baseline,delta)
        dossier=_package_a_v4_dossier_intact(directory,state)
        context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"dossier":dossier,"changed_paths":[row["path"] for row in delta["files"]]}
        review=_package_a_v4_review_intact(directory,state,context) if isinstance(state.get("package_a_review"),dict) else None
        all_passed=verification["aggregate"]["all_passed"] is True
        review_verdict=(review or {}).get("packet",{}).get("verdict")
        active_review=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
        review_retries=state.get("package_a_review_retries")
        if all_passed and review_verdict is None and active_review and isinstance(review_retries,list) and len(review_retries)==1:
            if process_alive(active_review.get("pid"),active_review.get("pgid")): raise ControllerError("Package A v4 independent review is still running")
            _package_a_v4_review_attempt_intact(directory,state,context,active_review)
            terminal,terminal_receipt=_package_a_review_terminal(directory,active_review)
            output_exists=isinstance(active_review.get("output_path"),str) and os.path.lexists(active_review["output_path"])
            capacity_event=_package_a_claude_capacity_event(active_review["stdout"],directory,active_review.get("reviewer_session_id",""))
            review_infrastructure_exhausted=(
                terminal.get("exit_code")!=0 and
                (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and
                terminal.get("output_sha256") is None and not output_exists and capacity_event is None)
            if review_infrastructure_exhausted: exhausted_review_receipt=terminal_receipt
        if all_passed and review_verdict=="pass": disposition,reason="pass","all_evidence_passed"
        elif review_verdict in {"fail","needs_correction"}: disposition,reason="fail","independent_review_failed"
        elif review_infrastructure_exhausted: disposition,reason="fail","review_infrastructure_exhausted"
        else: disposition,reason="fail","deterministic_or_review_dissent"
        verification_sha=verification["aggregate_info"]["sha256"]
        review_sha=review["info"]["sha256"] if review else (exhausted_review_receipt or {}).get("sha256")
    except ControllerError:
        if not isinstance(state.get("package_a_verification"),dict): raise
        disposition,reason="fail","candidate_or_evidence_invalid"; verification_sha=state["package_a_verification"].get("aggregate_sha256")
        review_sha=(state.get("package_a_review") or {}).get("sha256"); context=None
    if context is not None and all_passed and review_verdict is None and not review_infrastructure_exhausted:
        return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":"awaiting_gate","disposition":"awaiting_review","reused":False}
    core={"schema_version":SCHEMA,"kind":"package_a_gate_receipt","work_id":state["work_id"],"policy":POLICY_ID,
        "gate_name":"orchestrator-package-a-gate/v1","adjudicator_principal":PACKAGE_A_GATE_PRINCIPAL,"candidate_id":candidate.get("id"),
        "evidence_digest":candidate.get("evidence_digest"),"verification_aggregate_sha256":verification_sha,"review_sha256":review_sha,
        "correction_already_used":False,"disposition":disposition,"reason_code":reason}
    receipt_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"receipt_id":receipt_id,"issued_at":candidate.get("created_at") or state.get("created_at")}
    gate_dir=os.path.join(directory,"package-a-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir) or not inside(real(gate_dir),directory)):
        raise ControllerError("Package A v4 fixed gate directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    receipt_info=_package_a_adopt_json(os.path.join(gate_dir,receipt_id+".json"),gate_dir,receipt,"v4 fixed gate receipt")
    if disposition=="pass": state["phase"]="completed"
    else: state["phase"]="failed"
    state["gate"]={"kind":"package_a_fixed_gate","gate_name":PACKAGE_A_GATE_PRINCIPAL,"verdict":disposition,"reason_code":reason,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"receipt_id":receipt_id,"receipt_sha256":receipt_info["sha256"],"policy":POLICY_ID}
    state["package_a_gate_receipt"]={"path":receipt_info["path"],"sha256":receipt_info["sha256"],"receipt_id":receipt_id,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"disposition":disposition}
    save(directory,state)
    result=_package_a_v4_gate_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


# ---------------------------------------------------------------------------
# Package A v5 — hermetic controller-adopted-candidate rescue
# ---------------------------------------------------------------------------

def _is_package_a_v5(state: Dict[str,Any]) -> bool:
    return state.get("work_id")==PACKAGE_A_V5_WORK_ID


def _package_a_v5_source_intact(root: str) -> Dict[str,Any]:
    """Validate v4 terminal state then return the immutable v3 source for v5 adoption."""
    v4_dir=work_dir(root,PACKAGE_A_V4_WORK_ID); v4_state=load(v4_dir)
    if v4_state.get("phase")!="failed" or v4_state.get("work_id")!=PACKAGE_A_V4_WORK_ID:
        raise ControllerError("Package A v5 source v4 prerequisite identity or phase changed")
    v4_gate_bound=v4_state.get("package_a_gate_receipt") if isinstance(v4_state.get("package_a_gate_receipt"),dict) else {}
    v4_gates_dir=os.path.join(v4_dir,"package-a-gates")
    v4_gate_info=capped_regular_file_info(v4_gate_bound.get("path"),v4_gates_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(v4_gate_bound.get("path"),str) else None
    if not v4_gate_info or v4_gate_info.get("sha256")!=PACKAGE_A_V5_SOURCE_V4_GATE_SHA256:
        raise ControllerError("Package A v5 source v4 terminal gate receipt changed")
    return _package_a_v4_source_intact(root)


def _package_a_v5_hermetic_env() -> Dict[str,str]:
    """Build a hermetic child env appending git command-scope config overrides."""
    env=dict(os.environ)
    raw=os.environ.get("GIT_CONFIG_COUNT","")
    if raw:
        try: start=int(raw)
        except ValueError: raise ControllerError("Package A v5 gate GIT_CONFIG_COUNT is malformed")
        if start<0 or start>256: raise ControllerError("Package A v5 gate GIT_CONFIG_COUNT is excessive")
        for i in range(start):
            if ("GIT_CONFIG_KEY_%d"%i) not in os.environ or ("GIT_CONFIG_VALUE_%d"%i) not in os.environ:
                raise ControllerError("Package A v5 gate GIT_CONFIG_COUNT entry %d is missing"%i)
    else:
        start=0
    for j,(key,value) in enumerate(PACKAGE_A_V5_HERMETIC_GIT_OVERRIDES):
        env["GIT_CONFIG_KEY_%d"%(start+j)]=key
        env["GIT_CONFIG_VALUE_%d"%(start+j)]=value
    env["GIT_CONFIG_COUNT"]=str(start+len(PACKAGE_A_V5_HERMETIC_GIT_OVERRIDES))
    return env


def _package_a_v5_candidate_intact(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> None:
    return _package_a_v4_candidate_intact(directory,state,candidate,baseline)


def _package_a_v5_verification_static(state: Dict[str,Any],candidate: Dict[str,Any],delta: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"work_id":state["work_id"],"outcome_id":_package_a_identity(state["work_id"])["outcome_id"],"route":PACKAGE_A_V5_ROUTE,
            "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
            "adoption_receipt_sha256":adopt_bound.get("receipt_sha256"),"policy":POLICY_ID,
            "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],
            "delta_receipt_sha256":state["package_a_builder_delta"]["sha256"],"delta_sha256":delta["sha256"],
            "candidate_fingerprint_digest":candidate["evidence"]["worktree_fingerprint"]["digest"],
            "env_policy_digest":PACKAGE_A_V5_ENV_POLICY_DIGEST}


def _package_a_v5_verification_specs() -> List[Dict[str,Any]]:
    builder=PACKAGE_A_V5_BUILDER_NAME
    return [
        {"label":"test_cowork","argv":["python3","-m","unittest","scripts/test_cowork.py"],"timeout":PACKAGE_A_V5_TEST_TIMEOUT,"kind":"unittest"},
        {"label":"characterization","argv":["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],"timeout":180,"kind":"characterization"},
        {"label":"diff_check","argv":["git","diff","--check"],"timeout":60,"kind":"empty"},
        {"label":"candidate_delta","argv":["controller","package-a-delta"],"timeout":0,"kind":"controller"},
        {"label":"json_probe","argv":["python3","-c",_package_a_probe_code(builder)],"timeout":30,"kind":"probe"},
    ]


def _package_a_v5_validate_verification(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_verification") if isinstance(state.get("package_a_verification"),dict) else {}
    if set(bound)!={"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"}: raise ControllerError("Package A v5 verification state binding is malformed")
    verify_dir=_package_a_verification_dir(directory,candidate); intent_info=capped_regular_file_info(bound.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("intent_path"),str) else None
    aggregate_info=capped_regular_file_info(bound.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("aggregate_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not aggregate_info or aggregate_info.get("sha256")!=bound.get("aggregate_sha256"): raise ControllerError("Package A v5 verification intent or aggregate changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text()); aggregate=json.loads(Path(aggregate_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 verification evidence is unreadable") from exc
    static=_package_a_v5_verification_static(state,candidate,delta,baseline); specs=_package_a_v5_verification_specs()
    expected_intent_keys={"schema_version","kind","created_at","static","specs","receipt_paths","output_paths","terminal_paths","start_paths","aggregate_path"}
    if (not isinstance(intent,dict) or set(intent)!=expected_intent_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_a_verification_intent" or
            not isinstance(intent.get("created_at"),str) or intent.get("static")!=static or intent.get("specs")!=specs or
            intent.get("receipt_paths")!=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("output_paths")!=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)] or intent.get("aggregate_path")!=aggregate_info["path"]):
        raise ControllerError("Package A v5 verification intent binding changed")
    if (intent.get("terminal_paths")!=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)] or
            intent.get("start_paths")!=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]):
        raise ControllerError("Package A v5 verification execution intent binding changed")
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,intent["receipt_paths"],intent["output_paths"],intent["terminal_paths"],intent["start_paths"])):
        info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT)
        if not info or not output_info: raise ControllerError("Package A v5 verification receipt or output is missing or unsafe")
        try: raw=Path(output_info["path"]).read_bytes()
        except OSError as exc: raise ControllerError("Package A v5 verification output is unreadable") from exc
        try: receipt=json.loads(Path(info["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 verification receipt is unreadable") from exc
        terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_A_MAX_GATE_OUTPUT+64*1024)
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
        receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
        structurally_bound=(isinstance(receipt,dict) and set(receipt)==receipt_keys and receipt.get("schema_version")==SCHEMA and receipt.get("kind")=="package_a_verification_receipt" and
                receipt.get("index")==index and receipt.get("label")==spec["label"] and receipt.get("argv")==spec["argv"] and receipt.get("cwd")==state["worktree"]["path"] and
                receipt.get("timeout_seconds")==spec["timeout"] and receipt.get("static")==static and bool(terminal_info) and
                receipt.get("start_path")==start_info["path"] and receipt.get("start_sha256")==start_info["sha256"] and
                receipt.get("terminal_path")==terminal_info["path"] and receipt.get("terminal_sha256")==terminal_info["sha256"])
        if not structurally_bound: raise ControllerError("Package A v5 verification receipt structure changed")
        if not _package_a_receipt_consistent(spec,receipt,output_info,raw): raise ControllerError("Package A v5 verification receipt semantics changed: "+spec["label"])
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
    aggregate_keys={"schema_version","kind","created_at","static","receipts","all_passed","post_fingerprint"}
    if (not isinstance(aggregate,dict) or set(aggregate)!=aggregate_keys or aggregate.get("schema_version")!=SCHEMA or aggregate.get("kind")!="package_a_verification_aggregate" or
            aggregate.get("created_at")!=intent["created_at"] or aggregate.get("static")!=static or aggregate.get("receipts")!=refs or aggregate.get("all_passed") is not all(row["passed"] for row in refs) or
            aggregate.get("post_fingerprint")!=candidate["evidence"]["worktree_fingerprint"] or bound.get("candidate_id")!=candidate["id"] or bound.get("evidence_digest")!=candidate["evidence_digest"]):
        raise ControllerError("Package A v5 verification aggregate binding changed")
    return {"intent":intent,"aggregate":aggregate,"aggregate_info":aggregate_info,"refs":refs}


def _command_verify_package_a_v5(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    """v5 verification: adopted candidate with hermetic git gate environment."""
    _package_a_v5_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate)
    if state.get("package_a_verification"):
        verified=_package_a_v5_validate_verification(directory,state,candidate,baseline,delta)
        return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":True,"aggregate_path":verified["aggregate_info"]["path"],"aggregate_sha256":verified["aggregate_info"]["sha256"],"all_passed":verified["aggregate"]["all_passed"]}
    _top_verify=os.path.join(directory,"package-a-verification")
    if os.path.lexists(_top_verify) and (os.path.islink(_top_verify) or not os.path.isdir(_top_verify) or not inside(os.path.realpath(_top_verify),directory)): raise ControllerError("Package A v5 verification top-level directory is unsafe")
    static=_package_a_v5_verification_static(state,candidate,delta,baseline); specs=_package_a_v5_verification_specs(); verify_dir=_package_a_verification_dir(directory,candidate)
    if os.path.lexists(verify_dir) and (os.path.islink(verify_dir) or not os.path.isdir(verify_dir)): raise ControllerError("Package A v5 verification directory is unsafe")
    os.makedirs(verify_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(verify_dir,"intent.json"); aggregate_path=os.path.join(verify_dir,"aggregate.json"); receipt_paths=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)]; output_paths=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    terminal_paths=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)]; start_paths=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]
    base_intent={"schema_version":SCHEMA,"kind":"package_a_verification_intent","static":static,"specs":specs,"receipt_paths":receipt_paths,"output_paths":output_paths,"terminal_paths":terminal_paths,"start_paths":start_paths,"aggregate_path":aggregate_path}
    existing_intent=capped_regular_file_info(intent_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not existing_intent: raise ControllerError("Package A v5 verification intent is unsafe")
    if existing_intent:
        try: intent=json.loads(Path(existing_intent["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 verification intent is unreadable") from exc
        if set(intent)!=(set(base_intent)|{"created_at"}) or {k:v for k,v in intent.items() if k!="created_at"}!=base_intent or not isinstance(intent.get("created_at"),str): raise ControllerError("Package A v5 verification orphan intent conflicts")
    else:
        if os.path.lexists(aggregate_path) or any(os.path.lexists(path) for path in receipt_paths+output_paths+terminal_paths+start_paths): raise ControllerError("Package A v5 verification output cannot precede durable intent")
        intent={**base_intent,"created_at":utc()}; existing_intent=_package_a_adopt_json(intent_path,verify_dir,intent,"v5 verification intent")
    wt=state["worktree"]["path"]; refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,receipt_paths,output_paths,terminal_paths,start_paths)):
        before=worktree_fingerprint(wt)
        if before!=candidate["evidence"]["worktree_fingerprint"]: raise ControllerError("Package A v5 candidate changed before deterministic gate")
        prior=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(path) else None
        if os.path.lexists(path) and not prior: raise ControllerError("Package A v5 verification orphan receipt is unsafe")
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(dt.datetime.fromisoformat(intent["created_at"].replace("Z","+00:00"))+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        hermetic_env=_package_a_v5_hermetic_env()
        result,raw,terminal_info=_package_a_execute_gate(spec,index,wt,verify_dir,terminal_path,start_path,static,wrapper_nonce,deadline_text,env=hermetic_env)
        output_info=_package_a_adopt_bytes(output_path,verify_dir,raw,"v5 gate output")
        result["output_path"]=output_info["path"]
        if prior:
            try: old=json.loads(Path(prior["path"]).read_text())
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 verification orphan receipt is unreadable") from exc
            receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            if (not isinstance(old,dict) or set(old)!=receipt_keys or old.get("schema_version")!=SCHEMA or old.get("kind")!="package_a_verification_receipt" or old.get("index")!=index or old.get("label")!=spec["label"] or old.get("argv")!=spec["argv"] or old.get("cwd")!=wt or old.get("timeout_seconds")!=spec["timeout"] or old.get("static")!=static or not output_info or not terminal_info or old.get("start_path")!=start_info["path"] or old.get("start_sha256")!=start_info["sha256"] or old.get("terminal_path")!=terminal_info["path"] or old.get("terminal_sha256")!=terminal_info["sha256"] or not _package_a_receipt_consistent(spec,old,output_info,raw)):
                raise ControllerError("Package A v5 verification orphan receipt conflicts")
            refs.append({"index":index,"label":spec["label"],"path":prior["path"],"sha256":prior["sha256"],"counters":old["counters"],"passed":old["passed"]})
        else:
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            receipt={"schema_version":SCHEMA,"kind":"package_a_verification_receipt","index":index,"label":spec["label"],"argv":spec["argv"],"cwd":wt,"timeout_seconds":spec["timeout"],"static":static,
                     "start_path":start_info["path"],"start_sha256":start_info["sha256"],"terminal_path":terminal_info["path"],"terminal_sha256":terminal_info["sha256"],
                     **{k:result[k] for k in ("exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed")}}
            receipt_info=_package_a_adopt_json(path,verify_dir,receipt,"v5 verification receipt")
            refs.append({"index":index,"label":spec["label"],"path":receipt_info["path"],"sha256":receipt_info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
        if not refs[-1]["passed"]: break
    all_passed=all(row["passed"] for row in refs) and len(refs)==len(specs)
    post_fp=worktree_fingerprint(wt)
    aggregate={"schema_version":SCHEMA,"kind":"package_a_verification_aggregate","created_at":intent["created_at"],"static":static,"receipts":refs,"all_passed":all_passed,"post_fingerprint":post_fp}
    aggregate_info=_package_a_adopt_json(aggregate_path,verify_dir,aggregate,"v5 verification aggregate")
    state["package_a_verification"]={"intent_path":intent_path,"intent_sha256":existing_intent["sha256"],"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="package_a_verified" and row.get("candidate_id")==candidate["id"] for row in recent_events(directory)):
        append_event(directory,"package_a_verified",candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],all_passed=all_passed)
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_package_a","reused":False,"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"all_passed":all_passed}


def _package_a_v5_dossier_content(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any],verification: Dict[str,Any]) -> Dict[str,Any]:
    adopt_bound=state["package_a_adoption"]; wt=state["worktree"]["path"]
    module_path=os.path.join(wt,"scripts/cowork_dispatch.py")
    module_item=capped_regular_file_info(module_path,wt,MAX_CANDIDATE_PATH_BYTES)
    if not module_item or module_item.get("sha256")!=PACKAGE_A_V4_SOURCE_MODULE_SHA256:
        raise ControllerError("Package A v5 dossier production module hash mismatch")
    try: module_text=Path(module_item["path"]).read_text(encoding="utf-8")
    except (OSError,UnicodeDecodeError) as exc: raise ControllerError("Package A v5 dossier production module is unreadable") from exc
    try: diff_result=subprocess.run(["git","diff","HEAD","--","scripts/test_cowork.py"],cwd=wt,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
    except subprocess.TimeoutExpired as exc: raise ControllerError("Package A v5 dossier test delta timed out") from exc
    if diff_result.returncode not in (0,1): raise ControllerError("Package A v5 dossier test delta command failed")
    try: delta_text=diff_result.stdout.decode("utf-8","replace")
    except Exception as exc: raise ControllerError("Package A v5 dossier test delta is not decodable") from exc
    gate_summaries=[]
    for ref in verification["refs"]:
        gate_summaries.append({"index":ref["index"],"label":ref["label"],"sha256":ref["sha256"],"counters":ref["counters"],"passed":ref["passed"]})
    dossier={"schema_version":SCHEMA,"kind":"package_a_v5_review_dossier","work_id":PACKAGE_A_V5_WORK_ID,"outcome_id":PACKAGE_A_V5_OUTCOME_ID,
             "policy":POLICY_ID,"route":PACKAGE_A_V5_ROUTE,"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
             "adoption_receipt_sha256":adopt_bound["receipt_sha256"],"source_work_id":PACKAGE_A_V5_SOURCE_WORK_ID,
             "source_candidate_id":PACKAGE_A_V4_SOURCE_CANDIDATE_ID,"source_evidence_digest":PACKAGE_A_V4_SOURCE_EVIDENCE_DIGEST,
             "source_gate_receipt_sha256":PACKAGE_A_V4_SOURCE_GATE_RECEIPT_SHA256,"source_gate_reason":PACKAGE_A_V5_SOURCE_GATE_REASON,
             "baseline_receipt_sha256":state["package_a_prerequisites"]["sha256"],
             "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],"gate_summaries":gate_summaries,
             "changed_paths":["scripts/cowork_dispatch.py","scripts/test_cowork.py"],
             "env_policy_digest":PACKAGE_A_V5_ENV_POLICY_DIGEST,
             "authority_statement":("Package A v5 hermetic review-rescue. Route: controller_adopted_candidate. Adjudicator: orchestrator-package-a-gate/v1. "
                                    "This package reviews the already-verified v3 candidate adopted without modification. "
                                    "No new implementation. No provider attempt. No builder correction authorized. Hermetic git gate environment."),
             "record_api":{"records":["DispatchContract","DispatchDecision","AttemptLink"],
                           "validators":["validate_dispatch_contract(record)","validate_dispatch_decision(record, contract)","validate_attempt_link(record)"],
                           "reducer":"decide(contract, policy_result=None, preflight_result=None, probe_result=None)",
                           "idempotency_key_builder":"build_attempt_link_idempotency_key(role, kind, source_ref, ordinal)"},
             "contracts":sorted(M0C_CONTRACTS),"production_module":module_text,"test_cowork_delta":delta_text,"created_at":utc()}
    return dossier


def _command_build_package_a_v5_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_a_v5(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package A v5 dossier requires v5 awaiting gate")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_v5_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate)
    if not state.get("package_a_verification"): raise ControllerError("Package A v5 dossier requires verified candidate")
    verification=_package_a_v5_validate_verification(directory,state,candidate,baseline,delta)
    if verification["aggregate"].get("all_passed") is not True: raise ControllerError("Package A v5 dossier requires all gates passed")
    dossier_dir=os.path.join(directory,"package-a-v5-dossier")
    if state.get("package_a_v5_dossier"):
        bound=state["package_a_v5_dossier"]
        dossier_info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_A_V5_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
        if not dossier_info or dossier_info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A v5 dossier changed")
        return {"schema_version":SCHEMA,"operation":"build_package_a_v5_dossier","reused":True,"path":dossier_info["path"],"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"]}
    if os.path.lexists(dossier_dir) and (os.path.islink(dossier_dir) or not os.path.isdir(dossier_dir)): raise ControllerError("Package A v5 dossier directory is unsafe")
    os.makedirs(dossier_dir,mode=0o700,exist_ok=True)
    dossier=_package_a_v5_dossier_content(directory,state,candidate,baseline,delta,verification)
    encoded=(json.dumps(dossier,sort_keys=True,indent=2)+"\n").encode("utf-8")
    if len(encoded)>PACKAGE_A_V5_DOSSIER_CAP: raise ControllerError("Package A v5 dossier exceeds 128 KiB cap (%d bytes)"%len(encoded))
    dossier_path=os.path.join(dossier_dir,candidate["id"]+".dossier.json")
    dossier_info=_package_a_adopt_bytes(dossier_path,dossier_dir,encoded,"v5 dossier")
    state["package_a_v5_dossier"]={"path":dossier_path,"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    append_event(directory,"package_a_v5_dossier_built",candidate_id=candidate["id"],sha256=dossier_info["sha256"],bytes=dossier_info["bytes"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"build_package_a_v5_dossier","reused":False,"path":dossier_path,"sha256":dossier_info["sha256"],"bytes":dossier_info["bytes"]}


def command_build_package_a_v5_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_build_package_a_v5_dossier(args)


def _package_a_v5_dossier_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_v5_dossier") if isinstance(state.get("package_a_v5_dossier"),dict) else {}
    if set(bound)!={"path","sha256","bytes","candidate_id","evidence_digest"}: raise ControllerError("Package A v5 dossier state binding is malformed")
    dossier_dir=os.path.join(directory,"package-a-v5-dossier")
    info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_A_V5_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256") or info.get("bytes")!=bound.get("bytes"): raise ControllerError("Package A v5 dossier changed")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if bound.get("candidate_id")!=candidate.get("id") or bound.get("evidence_digest")!=candidate.get("evidence_digest"):
        raise ControllerError("Package A v5 dossier candidate binding changed")
    return {"path":info["path"],"sha256":info["sha256"],"bytes":info["bytes"]}


def _package_a_v5_review_context(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_a_prerequisites_intact(directory,state); _package_a_v5_candidate_intact(directory,state,candidate,baseline)
    delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_v5_validate_verification(directory,state,candidate,baseline,delta)
    dossier=_package_a_v5_dossier_intact(directory,state)
    changed=[row["path"] for row in delta["files"]]
    if changed!=["scripts/cowork_dispatch.py","scripts/test_cowork.py"]: raise ControllerError("Package A v5 review changed-path binding is invalid")
    return {"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"dossier":dossier,"changed_paths":changed}


def _package_a_v5_review_schema(state: Dict[str,Any],context: Dict[str,Any],attempt_id: str,run: str,nonce: str) -> Dict[str,Any]:
    candidate=context["candidate"]; verification=context["verification"]; dossier=context["dossier"]
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","work_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce","candidate_id","evidence_digest","adoption_receipt_sha256","dossier_sha256","verification_aggregate_sha256","verification_receipt_sha256s","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_a_v5_review"},"work_id":{"type":"string","const":state["work_id"]},
            "policy":{"type":"string","const":POLICY_ID},"review_attempt_id":{"type":"string","const":attempt_id},
            "backend":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_A_CLAUDE_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"candidate_id":{"type":"string","const":candidate["id"]},
            "evidence_digest":{"type":"string","const":candidate["evidence_digest"]},"adoption_receipt_sha256":{"type":"string","const":adopt_bound.get("receipt_sha256")},
            "dossier_sha256":{"type":"string","const":dossier["sha256"]},"verification_aggregate_sha256":{"type":"string","const":verification["aggregate_info"]["sha256"]},
            "verification_receipt_sha256s":{"type":"array","minItems":5,"maxItems":5,"items":{"type":"string"}},
            "changed_paths":{"type":"array","minItems":2,"maxItems":2,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_a_v5_review_expected(state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    verification=context["verification"]; dossier=context["dossier"]
    adopt_bound=state.get("package_a_adoption") if isinstance(state.get("package_a_adoption"),dict) else {}
    return {"schema_version":SCHEMA,"kind":"package_a_v5_review","work_id":state["work_id"],"policy":POLICY_ID,"review_attempt_id":attempt["id"],
            "backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_nonce":attempt["nonce"],
            "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
            "adoption_receipt_sha256":adopt_bound.get("receipt_sha256"),"dossier_sha256":dossier["sha256"],
            "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],
            "verification_receipt_sha256s":[row["sha256"] for row in verification["refs"]],"changed_paths":context["changed_paths"]}


def _package_a_v5_review_attempt_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package A v5 review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"review attempt id"),(attempt.get("run_id"),"review run id"),(attempt.get("nonce"),"review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(directory,"package-a-review-attempts"); expected_schema=_package_a_v5_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_a_v5_review_expected(state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package A v5 review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_A_CLAUDE_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=context["candidate"]["id"] or attempt.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(directory,"logs")),("stderr",os.path.join(directory,"logs"))))):
        raise ControllerError("Package A v5 review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A v5 review schema binding changed")
    return attempt


def _package_a_v5_review_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_a_review") if isinstance(state.get("package_a_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict","model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package A v5 independent review state binding is malformed")
    item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package A v5 independent review envelope changed")
    try: envelope=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 independent review envelope is unreadable") from exc
    attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    _package_a_v5_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    packet=envelope.get("model_packet") if isinstance(envelope,dict) else None
    expected=_package_a_v5_review_expected(state,context,attempt); packet_keys=set(expected)|{"verdict","findings","checks"}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id","reviewer_session_id","terminal_receipt_sha256","model_packet_sha256","model_packet"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or
            envelope.get("kind")!="package_a_v5_review_envelope" or envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or
            envelope.get("candidate_id")!=context["candidate"]["id"] or envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            envelope.get("actor_id")!=PACKAGE_A_CLAUDE_REVIEW_ACTOR or envelope.get("run_id")!=attempt.get("run_id") or envelope.get("review_attempt_id")!=attempt.get("id") or
            envelope.get("reviewer_session_id")!=attempt.get("provider_session_id") or envelope.get("terminal_receipt_sha256")!=receipt["sha256"] or
            not isinstance(packet,dict) or set(packet)!=packet_keys or any(packet.get(k)!=v for k,v in expected.items()) or
            envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded")):
        raise ControllerError("Package A v5 independent review envelope binding changed")
    if (packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A v5 independent review verdict packet is malformed")
    expected_bound={"path":item["path"],"sha256":item["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":attempt["provider_session_id"],"policy":POLICY_ID,
        "verdict":packet["verdict"],"model_packet_sha256":envelope["model_packet_sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    if bound!=expected_bound or attempt.get("packet_sha256")!=item["sha256"] or not isinstance(attempt.get("consumed_at"),str):
        raise ControllerError("Package A v5 independent review state no longer matches its envelope")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":receipt}


def _package_a_v5_gate_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    if not isinstance(state.get("package_a_gate_receipt"),dict): return None
    sealed=_package_a_gate_receipt_intact(directory,state); receipt=sealed["receipt"]
    expected_phase={"pass":"completed","revise":"prepared","fail":"failed"}[receipt["disposition"]]
    if state.get("phase")!=expected_phase: raise ControllerError("Package A v5 fixed gate phase binding changed")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if (gate.get("kind")!="package_a_fixed_gate" or gate.get("gate_name")!=PACKAGE_A_GATE_PRINCIPAL or gate.get("verdict")!=receipt["disposition"] or
            gate.get("receipt_id")!=receipt["receipt_id"] or gate.get("receipt_sha256")!=sealed["info"]["sha256"] or gate.get("candidate_id")!=receipt["candidate_id"] or
            gate.get("evidence_digest")!=receipt["evidence_digest"] or gate.get("reason_code")!=receipt["reason_code"] or gate.get("policy")!=POLICY_ID):
        raise ControllerError("Package A v5 fixed gate state binding changed")
    if receipt["disposition"]=="pass":
        context=_package_a_v5_review_context(directory,state); review=_package_a_v5_review_intact(directory,state,context)
        if (context["verification"]["aggregate"].get("all_passed") is not True or review["packet"].get("verdict")!="pass" or
                context["verification"]["aggregate_info"]["sha256"]!=receipt.get("verification_aggregate_sha256") or review["info"]["sha256"]!=receipt.get("review_sha256")):
            raise ControllerError("Package A v5 passing gate evidence changed")
    event_kind={"pass":"package_a_gate_passed","revise":"package_a_correction_queued","fail":"package_a_gate_failed"}[receipt["disposition"]]
    if not any(row.get("kind")==event_kind and row.get("receipt_id")==receipt["receipt_id"] for row in recent_events(directory)):
        append_event(directory,event_kind,receipt_id=receipt["receipt_id"],gate_name=receipt["gate_name"],policy=POLICY_ID,candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],disposition=receipt["disposition"],next_state=expected_phase)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":expected_phase,"disposition":receipt["disposition"],
            "receipt":{"path":sealed["info"]["path"],"sha256":sealed["info"]["sha256"]},"reused":True,"delivery":None}


def _command_launch_package_a_v5_review(args: argparse.Namespace,directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    context=_package_a_v5_review_context(directory,state)
    dossier=context["dossier"]
    if state.get("package_a_review"): raise ControllerError("Package A v5 candidate already has an ingested independent review")
    existing=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
    if existing:
        _package_a_v5_review_attempt_intact(directory,state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _package_a_review_terminal(directory,existing)
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            append_event(directory,"package_a_review_launch_lost",attempt_id=existing["id"],classification=classification); save(directory,state)
        raise ControllerError("Package A v5 independent review attempt already exists")
    retries=state.get("package_a_review_retries",[])
    if not isinstance(retries,list) or len(retries)>1: raise ControllerError("Package A v5 review retry history is malformed")
    actor=PACKAGE_A_CLAUDE_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(directory,"package-a-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package A v5 review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_a_v5_review_schema(state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"v5 review schema")
    prompt=("Package A v5 hermetic review-rescue. Read ONLY the sealed review dossier at: %s. "
            "Do not read any other file, run tests, execute shell commands, spawn agents, or explore the repository. "
            "The dossier contains the full production module, bounded test diff, gate summaries, and exact controller bindings. "
            "Review the three pure record validators, fixed public APIs, reducer allow/refuse purity, JSON round trips, and negative controls. "
            "Return only the required schema JSON packet bound to the exact candidate_id, evidence_digest, adoption_receipt_sha256, dossier_sha256, and verification_aggregate_sha256 provided in the dossier." % dossier["path"])
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package A v5 review prompt exceeds bound")
    logs=os.path.join(directory,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-a-claude.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-a-claude.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind","claude_package_a_review_terminal","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    expected=_package_a_v5_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=305)).isoformat().replace("+00:00","Z")
    state["package_a_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_A_CLAUDE_REVIEW_BACKEND,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save(directory,state); append_event(directory,"package_a_review_starting",attempt_id=attempt_id,candidate_id=context["candidate"]["id"])
    try: pid,pgid=detached_spawn(wrapper,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["package_a_review_attempt"]["spawn_error"]=type(exc).__name__; state["package_a_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); state["package_a_review_attempt"]["terminal_at"]=utc()
        append_event(directory,"package_a_review_spawn_failed",attempt_id=attempt_id); save(directory,state); raise ControllerError("Package A v5 review controller spawn failed") from exc
    state["package_a_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"package_a_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_package_a_review","attempt_id":attempt_id,"run_id":run,"phase":state["phase"]}


def _command_ingest_package_a_v5_review(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    context=_package_a_v5_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A v5 review requires a quiescent controller-owned attempt")
    _package_a_v5_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_package_a_review_terminal(directory,attempt)
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            return _package_a_review_capacity_wait(directory,state,context,attempt,terminal,receipt,capacity_event)
        if terminal.get("timed_out"): raise ControllerError("Package A v5 review timed out; timeout is terminal for this package")
        raise ControllerError("Package A v5 independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-a-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package A v5 review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    prior_sessions={row.get("provider_session_id") for row in state.get("package_a_review_attempt_history",[]) if isinstance(row,dict)}
    if provider_session in prior_sessions: raise ControllerError("Package A v5 reviewer provider session is not distinct from prior attempts")
    expected=_package_a_v5_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package A v5 independent review packet failed strict binding validation")
    packets=os.path.join(directory,"packets"); destination=os.path.join(packets,context["candidate"]["id"]+".package-a-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    envelope={"schema_version":SCHEMA,"kind":"package_a_v5_review_envelope","work_id":state["work_id"],"policy":POLICY_ID,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,
        "run_id":attempt["run_id"],"review_attempt_id":attempt["id"],"reviewer_session_id":provider_session,
        "terminal_receipt_sha256":receipt["sha256"],"model_packet_sha256":model_packet_sha256,"model_packet":packet}
    copied=_package_a_adopt_json(destination,packets,envelope,"v5 independent review envelope")
    state["package_a_review"]={"path":destination,"sha256":copied["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_A_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,"verdict":packet["verdict"],
        "model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    attempt["consumed_at"]=utc(); attempt["receipt_sha256"]=receipt["sha256"]; attempt["packet_sha256"]=copied["sha256"]; attempt["provider_session_id"]=provider_session
    append_event(directory,"package_a_review_ingested",candidate_id=context["candidate"]["id"],packet_sha256=copied["sha256"],verdict=packet["verdict"],actor_id=PACKAGE_A_CLAUDE_REVIEW_ACTOR); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_a_review","verdict":packet["verdict"],"packet_sha256":copied["sha256"],"phase":state["phase"]}


def _command_retry_package_a_v5_review(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    if state.get("package_a_review"): raise ControllerError("Package A v5 review retry requires an unconsumed awaiting review")
    context=_package_a_v5_review_context(directory,state); attempt=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else {}
    retries=state.get("package_a_review_retries",[])
    if not attempt or attempt.get("consumed_at") or not isinstance(retries,list) or retries or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package A v5 review infrastructure retry is unavailable")
    _package_a_v5_review_attempt_intact(directory,state,context,attempt)
    schema_info=capped_regular_file_info(attempt.get("schema_path"),os.path.join(directory,"package-a-review-attempts"),PACKAGE_A_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_schema=_package_a_v5_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    if not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256"): raise ControllerError("Package A v5 review retry schema binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package A v5 review retry schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package A v5 review retry schema changed")
    evidence={}
    if attempt.get("spawn_error"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("spawn_error_sha256")!=digest_bytes(str(attempt["spawn_error"]).encode()): raise ControllerError("Package A v5 review spawn failure binding changed")
        evidence={"classification":"spawn_failure","receipt_sha256":None,"spawn_error_sha256":attempt["spawn_error_sha256"]}
    elif attempt.get("launch_lost"):
        if os.path.lexists(attempt.get("receipt_path","")) or attempt.get("launch_lost")!="prepared_launch_lost" or attempt.get("launch_lost_sha256")!=digest_bytes(b"prepared_launch_lost"):
            raise ControllerError("Package A v5 review launch-lost binding changed")
        evidence={"classification":"prepared_launch_lost","receipt_sha256":None,"spawn_error_sha256":attempt["launch_lost_sha256"]}
    else:
        terminal,receipt=_package_a_review_terminal(directory,attempt)
        output_exists=isinstance(attempt.get("output_path"),str) and os.path.lexists(attempt["output_path"])
        if terminal.get("exit_code")==0 or terminal.get("output_sha256") is not None or output_exists: raise ControllerError("Package A v5 review application result is not infrastructure-retryable")
        if terminal.get("timed_out"): raise ControllerError("Package A v5 review timeout is terminal; not retryable")
        if not terminal.get("output_limit_exceeded"): raise ControllerError("Package A v5 review failure is not the bounded stream overflow infrastructure class")
        capacity_check=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_check: raise ControllerError("Package A v5 review overflow concurrent with capacity event is not retryable")
        evidence={"classification":"bounded_stream_overflow","receipt_sha256":receipt["sha256"],"reviewer_session_id":attempt.get("reviewer_session_id"),"spawn_error_sha256":None}
    archived={**attempt,"retry_evidence":evidence,"schema_sha256":schema_info["sha256"]}
    history=state.get("package_a_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package A v5 review history is malformed")
    state["package_a_review_attempt_history"]=history+[archived]; state["package_a_review_retries"]=[{"at":utc(),"prior_attempt_id":attempt["id"],"evidence":evidence}]; state["package_a_review_attempt"]=None
    append_event(directory,"package_a_review_retry_released",attempt_id=attempt["id"],classification=evidence["classification"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_package_a_review","phase":state["phase"],"retry_released":True}


def _command_adjudicate_package_a_v5(directory: str,state: Dict[str,Any],candidate: Dict[str,Any]) -> Dict[str,Any]:
    """Derive the fixed v5 Package-A disposition: no revise path, needs_correction treated as fail."""
    replay=_package_a_v5_gate_replay(directory,state)
    if replay: return replay
    context=None; review=None; all_passed=False; review_verdict=None; review_infrastructure_exhausted=False; exhausted_review_receipt=None
    try:
        baseline=_package_a_prerequisites_intact(directory,state); _package_a_v5_candidate_intact(directory,state,candidate,baseline)
        delta=_package_a_builder_delta(directory,state,candidate); verification=_package_a_v5_validate_verification(directory,state,candidate,baseline,delta)
        dossier=_package_a_v5_dossier_intact(directory,state)
        context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"dossier":dossier,"changed_paths":[row["path"] for row in delta["files"]]}
        review=_package_a_v5_review_intact(directory,state,context) if isinstance(state.get("package_a_review"),dict) else None
        all_passed=verification["aggregate"]["all_passed"] is True
        review_verdict=(review or {}).get("packet",{}).get("verdict")
        active_review=state.get("package_a_review_attempt") if isinstance(state.get("package_a_review_attempt"),dict) else None
        review_retries=state.get("package_a_review_retries")
        if all_passed and review_verdict is None and active_review and isinstance(review_retries,list) and len(review_retries)==1:
            if process_alive(active_review.get("pid"),active_review.get("pgid")): raise ControllerError("Package A v5 independent review is still running")
            _package_a_v5_review_attempt_intact(directory,state,context,active_review)
            terminal,terminal_receipt=_package_a_review_terminal(directory,active_review)
            output_exists=isinstance(active_review.get("output_path"),str) and os.path.lexists(active_review["output_path"])
            capacity_event=_package_a_claude_capacity_event(active_review["stdout"],directory,active_review.get("reviewer_session_id",""))
            review_infrastructure_exhausted=(
                terminal.get("exit_code")!=0 and
                (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and
                terminal.get("output_sha256") is None and not output_exists and capacity_event is None)
            if review_infrastructure_exhausted: exhausted_review_receipt=terminal_receipt
        if all_passed and review_verdict=="pass": disposition,reason="pass","all_evidence_passed"
        elif review_verdict in {"fail","needs_correction"}: disposition,reason="fail","independent_review_failed"
        elif review_infrastructure_exhausted: disposition,reason="fail","review_infrastructure_exhausted"
        else: disposition,reason="fail","deterministic_or_review_dissent"
        verification_sha=verification["aggregate_info"]["sha256"]
        review_sha=review["info"]["sha256"] if review else (exhausted_review_receipt or {}).get("sha256")
    except ControllerError:
        if not isinstance(state.get("package_a_verification"),dict): raise
        disposition,reason="fail","candidate_or_evidence_invalid"; verification_sha=state["package_a_verification"].get("aggregate_sha256")
        review_sha=(state.get("package_a_review") or {}).get("sha256"); context=None
    if context is not None and all_passed and review_verdict is None and not review_infrastructure_exhausted:
        return {"schema_version":SCHEMA,"operation":"adjudicate_package_a","phase":"awaiting_gate","disposition":"awaiting_review","reused":False}
    core={"schema_version":SCHEMA,"kind":"package_a_gate_receipt","work_id":state["work_id"],"policy":POLICY_ID,
        "gate_name":"orchestrator-package-a-gate/v1","adjudicator_principal":PACKAGE_A_GATE_PRINCIPAL,"candidate_id":candidate.get("id"),
        "evidence_digest":candidate.get("evidence_digest"),"verification_aggregate_sha256":verification_sha,"review_sha256":review_sha,
        "correction_already_used":False,"disposition":disposition,"reason_code":reason}
    receipt_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"receipt_id":receipt_id,"issued_at":candidate.get("created_at") or state.get("created_at")}
    gate_dir=os.path.join(directory,"package-a-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir) or not inside(real(gate_dir),directory)):
        raise ControllerError("Package A v5 fixed gate directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    receipt_info=_package_a_adopt_json(os.path.join(gate_dir,receipt_id+".json"),gate_dir,receipt,"v5 fixed gate receipt")
    if disposition=="pass": state["phase"]="completed"
    else: state["phase"]="failed"
    state["gate"]={"kind":"package_a_fixed_gate","gate_name":PACKAGE_A_GATE_PRINCIPAL,"verdict":disposition,"reason_code":reason,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"receipt_id":receipt_id,"receipt_sha256":receipt_info["sha256"],"policy":POLICY_ID}
    state["package_a_gate_receipt"]={"path":receipt_info["path"],"sha256":receipt_info["sha256"],"receipt_id":receipt_id,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"disposition":disposition}
    save(directory,state)
    result=_package_a_v5_gate_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


