# ---------------------------------------------------------------------------
# Package B — lead dispatch adapters and uniform refusal lifecycle
# ---------------------------------------------------------------------------

def _is_package_b(state: Dict[str,Any]) -> bool:
    return state.get("work_id")==PACKAGE_B_WORK_ID


def _package_b_v5_prereq_source_intact(root: str) -> Dict[str,Any]:
    """Validate the Package A v5 completed state and return its worktree path."""
    v5_dir=work_dir(root,PACKAGE_B_PREREQ_WORK_ID); v5_state=load(v5_dir)
    if v5_state.get("phase")!="completed" or v5_state.get("work_id")!=PACKAGE_B_PREREQ_WORK_ID:
        raise ControllerError("Package B prerequisite Package A v5 must be in completed phase with exact identity")
    candidate=v5_state.get("candidate") if isinstance(v5_state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_B_PREREQ_CANDIDATE_ID or candidate.get("evidence_digest")!=PACKAGE_B_PREREQ_EVIDENCE_DIGEST:
        raise ControllerError("Package B prerequisite Package A v5 candidate identity changed")
    gate_bound=v5_state.get("package_a_gate_receipt") if isinstance(v5_state.get("package_a_gate_receipt"),dict) else {}
    gates_dir=os.path.join(v5_dir,"package-a-gates")
    gate_info=capped_regular_file_info(gate_bound.get("path"),gates_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(gate_bound.get("path"),str) else None
    if not gate_info or gate_info.get("sha256")!=PACKAGE_B_PREREQ_GATE_SHA256:
        raise ControllerError("Package B prerequisite Package A v5 gate receipt changed")
    prereq_bound=v5_state.get("package_a_prerequisites") if isinstance(v5_state.get("package_a_prerequisites"),dict) else {}
    prereq_dir=os.path.join(v5_dir,"prerequisites")
    prereq_info=capped_regular_file_info(prereq_bound.get("path"),prereq_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(prereq_bound.get("path"),str) else None
    if not prereq_info or prereq_info.get("sha256")!=PACKAGE_B_PREREQ_RECEIPT_SHA256:
        raise ControllerError("Package B prerequisite Package A v5 baseline receipt changed")
    wt=v5_state.get("worktree",{}).get("path","")
    if not wt or not os.path.isdir(wt): raise ControllerError("Package B prerequisite Package A v5 worktree is missing")
    for rel,sha in PACKAGE_B_SOURCE_FILES.items():
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=sha: raise ControllerError("Package B prerequisite source file changed: "+rel)
    return {"source_wt":wt,"v5_dir":v5_dir,"gate_sha256":gate_info["sha256"],"prereq_sha256":prereq_info["sha256"]}


def _package_b_prerequisites_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_b_prerequisites") if isinstance(state.get("package_b_prerequisites"),dict) else {}
    if set(bound)!={"path","sha256","fingerprint_digest","intent_path","intent_sha256"}:
        raise ControllerError("Package B prerequisite state binding is malformed")
    prereq_dir=os.path.join(directory,"package-b-prerequisites")
    path=bound.get("path"); info=capped_regular_file_info(path,prereq_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(path,str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package B prerequisite baseline receipt is missing or changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B prerequisite baseline receipt is unreadable") from exc
    if (receipt.get("kind")!="package_b_prerequisite_baseline" or receipt.get("work_id")!=PACKAGE_B_WORK_ID or
            receipt.get("base_head")!=PACKAGE_B_BASE_HEAD or receipt.get("prereq_work_id")!=PACKAGE_B_PREREQ_WORK_ID):
        raise ControllerError("Package B prerequisite baseline identity changed")
    fp=receipt.get("post_materialization_fingerprint") if isinstance(receipt.get("post_materialization_fingerprint"),dict) else {}
    if fp.get("digest")!=bound.get("fingerprint_digest"): raise ControllerError("Package B prerequisite fingerprint changed")
    wt=state.get("worktree",{}).get("path","")
    for rel,sha in PACKAGE_B_SOURCE_FILES.items():
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=sha:
            if not (state.get("attempt") and rel in PACKAGE_B_ALLOWED_BUILDER_PATHS):
                raise ControllerError("Package B immutable prerequisite file changed: "+rel)
    return receipt


def _command_materialize_package_b_prerequisites(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); wt=state["worktree"]["path"]
    if not _is_package_b(state) or state.get("phase")!="prepared" or state.get("attempt"):
        raise ControllerError("Package B materialization requires fresh prepared state with exact identity")
    require_frozen_brief(state,directory)
    if state["brief"]["sha256"]!=PACKAGE_B_BRIEF_SHA256: raise ControllerError("Package B brief SHA-256 changed")
    if state["repo"]["head"]!=PACKAGE_B_BASE_HEAD or git(wt,["rev-parse","HEAD"]).strip()!=PACKAGE_B_BASE_HEAD:
        raise ControllerError("Package B base HEAD changed")
    if not registered_worktree(state["repo"]["root"],wt,state["worktree"]["branch"]):
        raise ControllerError("Package B worktree registration is invalid")
    if state.get("package_b_prerequisites"):
        receipt=_package_b_prerequisites_intact(directory,state)
        if not any(x.get("kind")=="package_b_prerequisites_materialized" and x.get("receipt_sha256")==state["package_b_prerequisites"]["sha256"] for x in recent_events(directory)):
            append_event(directory,"package_b_prerequisites_materialized",receipt_sha256=state["package_b_prerequisites"]["sha256"],fingerprint_digest=state["package_b_prerequisites"]["fingerprint_digest"])
        return {"schema_version":SCHEMA,"operation":"materialize_package_b_prerequisites","reused":True,"receipt":state["package_b_prerequisites"],"fingerprint":receipt["post_materialization_fingerprint"]}
    root=os.path.dirname(directory); source=_package_b_v5_prereq_source_intact(root); source_wt=source["source_wt"]
    prereq=os.path.join(directory,"package-b-prerequisites")
    if os.path.lexists(prereq) and (os.path.islink(prereq) or not os.path.isdir(prereq)): raise ControllerError("Package B prerequisite directory is unsafe")
    os.makedirs(prereq,mode=0o700,exist_ok=True)
    intent_path=os.path.join(prereq,"materialization-intent.json"); receipt_path=os.path.join(prereq,"baseline.json")
    pre_status=set(git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines())
    if pre_status:
        recoverable={"?? "+rel for rel in PACKAGE_B_SOURCE_FILES if rel not in PACKAGE_B_BASE_FILE_HASHES}
        recoverable|={" M "+rel for rel in PACKAGE_B_BASE_FILE_HASHES}
        if not os.path.lexists(intent_path) or not pre_status.issubset(recoverable):
            raise ControllerError("Package B worktree must be clean before materialization or match its exact durable intent")
    rows=[{"path":rel,"sha256":sha,"source_path":os.path.join(source_wt,rel)} for rel,sha in PACKAGE_B_SOURCE_FILES.items()]
    intent={"schema_version":SCHEMA,"kind":"package_b_materialization_intent","work_id":PACKAGE_B_WORK_ID,"base_head":PACKAGE_B_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"planned_receipt":receipt_path,"files":[{k:v for k,v in row.items() if k!="source_path"} for row in rows]}
    prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not prior: raise ControllerError("Package B materialization intent is unsafe")
    prior_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(receipt_path) else None
    if os.path.lexists(receipt_path) and not prior_receipt: raise ControllerError("Package B baseline receipt is unsafe")
    if prior:
        try: prior_value=json.loads(Path(prior["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B materialization intent is unreadable") from exc
        if prior_value!=intent: raise ControllerError("Package B materialization intent conflicts with recovery")
    else: atomic_json(intent_path,intent); prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    for index,row in enumerate(rows):
        dest=os.path.join(wt,row["path"])
        if os.path.islink(dest): raise ControllerError("Package B destination symlink is unsafe")
        existing=capped_regular_file_info(dest,wt,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(dest) else None
        if existing and existing.get("sha256")==row["sha256"]: continue
        base_sha=PACKAGE_B_BASE_FILE_HASHES.get(row["path"])
        if os.path.lexists(dest) and (not existing or existing.get("sha256")!=base_sha):
            raise ControllerError("Package B destination conflicts with existing file")
        os.makedirs(os.path.dirname(dest),exist_ok=True)
        tmp=os.path.join(prereq,"copy-%d.tmp"%index)
        try:
            temp_info=capped_regular_file_info(tmp,prereq,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(tmp) else None
            if os.path.lexists(tmp) and not temp_info: raise ControllerError("Package B transaction temp is unsafe")
            if not temp_info or temp_info.get("sha256")!=row["sha256"]:
                flags=os.O_WRONLY|os.O_CREAT|(os.O_TRUNC if temp_info else os.O_EXCL)
                fd=os.open(tmp,flags,0o600)
                with os.fdopen(fd,"wb") as out,open(row["source_path"],"rb") as src: shutil.copyfileobj(src,out); out.flush(); os.fsync(out.fileno())
            if digest_bytes(Path(tmp).read_bytes())!=row["sha256"]: raise ControllerError("Package B prerequisite copy hash mismatch")
            os.replace(tmp,dest)
            dir_fd=os.open(os.path.dirname(dest),os.O_RDONLY)
            try: os.fsync(dir_fd)
            finally: os.close(dir_fd)
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    fp=worktree_fingerprint(wt)
    receipt={"schema_version":SCHEMA,"kind":"package_b_prerequisite_baseline","work_id":PACKAGE_B_WORK_ID,"base_head":PACKAGE_B_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"intent_sha256":prior["sha256"],"prereq_work_id":PACKAGE_B_PREREQ_WORK_ID,"prereq_candidate_id":PACKAGE_B_PREREQ_CANDIDATE_ID,"prereq_evidence_digest":PACKAGE_B_PREREQ_EVIDENCE_DIGEST,"prereq_gate_sha256":PACKAGE_B_PREREQ_GATE_SHA256,"files":[{k:v for k,v in row.items() if k!="source_path"} for row in rows],"post_materialization_fingerprint":fp,"created_at":utc()}
    reused=bool(prior_receipt)
    if prior_receipt:
        try: old=json.loads(Path(prior_receipt["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B orphan baseline receipt is unreadable") from exc
        receipt["created_at"]=old.get("created_at")
        if old!=receipt: raise ControllerError("Package B orphan baseline receipt conflicts with recovery")
    else: atomic_json(receipt_path,receipt); prior_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    state["package_b_prerequisites"]={"path":receipt_path,"sha256":prior_receipt["sha256"],"fingerprint_digest":fp["digest"],"intent_path":intent_path,"intent_sha256":prior["sha256"]}
    if not any(x.get("kind")=="package_b_prerequisites_materialized" and x.get("receipt_sha256")==prior_receipt["sha256"] for x in recent_events(directory)):
        append_event(directory,"package_b_prerequisites_materialized",receipt_sha256=prior_receipt["sha256"],fingerprint_digest=fp["digest"])
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"materialize_package_b_prerequisites","reused":reused,"receipt":state["package_b_prerequisites"],"fingerprint":fp}


def command_materialize_package_b_prerequisites(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_materialize_package_b_prerequisites(args)


def _package_b_attempt_intact(attempt: Dict[str,Any]) -> None:
    expected={"role":"implementer","backend":"claude_direct","provider":"claude","controller":"claude","model":"sonnet","effort":"medium","policy":POLICY_ID}
    if not isinstance(attempt,dict) or any(attempt.get(key)!=value for key,value in expected.items()) or not _safe_identifier(attempt.get("id"),"Package B attempt id") or not _safe_identifier(attempt.get("provider_session_id"),"Package B provider session id"):
        raise ControllerError("Package B implementer attempt identity changed")


def _package_b_candidate_intact(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> None:
    candidate_keys={"schema_version","id","evidence_digest","evidence","packet_verified","created_at"}
    evidence_keys={"packet_sha256","packet_path","evidence_kind","changed_paths","declared_artifacts","worktree_fingerprint","package_b_baseline_receipt_sha256","package_b_baseline_fingerprint_digest"}
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    created=candidate.get("created_at")
    digest=digest_bytes(json.dumps(evidence,sort_keys=True,separators=(",",":")).encode())
    current_status=git(state["worktree"]["path"],["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    current_fingerprint=worktree_fingerprint(state["worktree"]["path"])
    if (not isinstance(candidate,dict) or set(candidate)!=candidate_keys or candidate.get("schema_version")!=SCHEMA or candidate.get("packet_verified") is not True or
            not isinstance(created,str) or created!=(state.get("attempt") or {}).get("started_at") or len(created.encode())>64 or set(evidence)!=evidence_keys or evidence.get("evidence_kind")!="worker_packet" or
            evidence.get("package_b_baseline_receipt_sha256")!=state["package_b_prerequisites"]["sha256"] or
            evidence.get("package_b_baseline_fingerprint_digest")!=baseline["post_materialization_fingerprint"]["digest"] or
            evidence.get("changed_paths")!=current_status or evidence.get("worktree_fingerprint")!=current_fingerprint or candidate.get("evidence_digest")!=digest or candidate.get("id")!="package-b-"+digest[:32] or
            not candidate_intact(candidate,directory,state["worktree"]["path"])):
        raise ControllerError("Package B candidate deterministic evidence binding changed")


def _package_b_builder_delta(directory: str,state: Dict[str,Any],candidate: Dict[str,Any]) -> Dict[str,Any]:
    baseline=_package_b_prerequisites_intact(directory,state); wt=state["worktree"]["path"]
    status=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines(); paths=[x[3:] for x in status if len(x)>=4]
    # Fixture must remain byte-identical
    fixture_item=capped_regular_file_info(os.path.join(wt,PACKAGE_B_FIXTURE_PATH),wt,MAX_CANDIDATE_PATH_BYTES)
    if not fixture_item or fixture_item["sha256"]!=PACKAGE_B_FIXTURE_SHA256: raise ControllerError("Package B fixture is immutable and must not change")
    delta=[]
    for rel in sorted(PACKAGE_B_ALLOWED_BUILDER_PATHS):
        dest=os.path.join(wt,rel)
        if os.path.lexists(dest):
            item=capped_regular_file_info(dest,wt,MAX_CANDIDATE_PATH_BYTES)
            if not item: raise ControllerError("Package B builder delta path is not a safe regular file")
            baseline_sha=PACKAGE_B_SOURCE_FILES.get(rel); changed=item["sha256"]!=baseline_sha
            if changed: delta.append({"path":rel,"sha256":item["sha256"],"baseline_sha256":baseline_sha})
    # Only allowed paths may appear in status; no staged changes, commits, renames, deletions, symlinks
    for rel in paths:
        if rel not in PACKAGE_B_ALLOWED_BUILDER_PATHS and rel!=PACKAGE_B_FIXTURE_PATH:
            raise ControllerError("Package B builder delta escaped baseline allowlist: "+rel)
    value={"candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"baseline_receipt_sha256":state["package_b_prerequisites"]["sha256"],"files":delta}
    value["sha256"]=digest_bytes(json.dumps(value,sort_keys=True,separators=(",",":")).encode())
    bound=state.get("package_b_builder_delta") if isinstance(state.get("package_b_builder_delta"),dict) else {}
    if bound:
        if (set(bound)!={"path","sha256","candidate_id","evidence_digest","delta_sha256"} or
                bound.get("candidate_id")!=candidate.get("id") or bound.get("evidence_digest")!=candidate.get("evidence_digest") or
                bound.get("delta_sha256")!=value["sha256"]):
            raise ControllerError("Package B builder delta state binding is malformed")
        item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-b-delta"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
        if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package B builder delta receipt changed")
    return value


def _package_b_claimed_delta(packet: Dict[str,Any]) -> List[str]:
    normalized=[]
    for item in (packet.get("structured") or {}).get("changed_paths",[]):
        if not isinstance(item,str): raise ControllerError("Package B worker changed_paths is malformed")
        rel=item[3:] if item.startswith(("?? "," M ")) else item
        if (not rel or os.path.isabs(rel) or "\\" in rel or os.path.normpath(rel)!=rel or rel.startswith("../") or "/../" in rel):
            raise ControllerError("Package B worker changed_paths contains an unsafe alias")
        normalized.append(rel)
    if len(normalized)!=len(set(normalized)): raise ControllerError("Package B worker changed_paths contains duplicates after normalization")
    return normalized


def _normalize_package_b_structured(value: Any) -> Optional[Dict[str,Any]]:
    if not isinstance(value,dict): return None
    required={"outcome","summary","changed_paths","checks","findings","assumptions","next_action","site_map"}
    if set(value)!=required: return None
    if (value.get("outcome") not in {"completed","blocked","needs_authority","failed"} or
            not isinstance(value.get("summary"),str) or len(value.get("summary","").encode())>2000 or
            not isinstance(value.get("changed_paths"),list) or len(value["changed_paths"])>50 or
            not isinstance(value.get("site_map"),dict)): return None
    site_map=value["site_map"]
    if set(site_map)!=set(PACKAGE_B_SITE_KEYS): return None
    site_keys={"purpose","refusal_mapping","return_shape","trace_event","test_ids"}
    for row in site_map.values():
        if not isinstance(row,dict) or set(row)!=site_keys: return None
        if any(not isinstance(row[key],str) or not row[key] or len(row[key].encode())>300
               for key in ("purpose","refusal_mapping","return_shape","trace_event")): return None
        tests=row["test_ids"]
        if (not isinstance(tests,list) or not tests or len(tests)>12 or
                any(not isinstance(test,str) or not test or len(test.encode())>300 for test in tests) or
                len(tests)!=len(set(tests))): return None
    return value


def _package_b_collect_result(state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],candidate: Dict[str,Any],
                               changed: List[str],artifacts: List[Dict[str,Any]],delta: Dict[str,Any],delta_path: str,
                               delta_receipt_sha256: str,baseline_info: Dict[str,Any],phase_before_collect: str) -> Dict[str,Any]:
    return {"schema_version":SCHEMA,"work_id":state["work_id"],"operation":"collect",
            "gate":{"phase":"awaiting_gate","kind":"evidence_bound_candidate","candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"packet_verified":True},
            "phase_before_collect":phase_before_collect,"attempt":{k:attempt.get(k) for k in ("id","role","provider_session_id","pid")},
            "worktree":state["worktree"]["path"],"changed_paths":changed[:MAX_PATHS],"changed_paths_truncated":len(changed)>MAX_PATHS,
            "receipts":[baseline_info],"artifacts":artifacts,
            "worker_packet":{"path":packet["path"],"sha256":packet["sha256"],"outcome":packet["structured"]["outcome"],"summary":packet["structured"]["summary"],"next_action":packet["structured"]["next_action"]},
            "limitations":["provider output is not proof of correctness","no watcher or lease/fencing protocol is implemented","detached provider exit code is not collected","bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated","publishing remains unavailable in this bootstrap controller even when publish_external is requested"],
            "package_b_builder_delta":{**delta,"receipt_path":delta_path,"receipt_sha256":delta_receipt_sha256}}


def _package_b_collect_verified(directory: str,state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],
                                 changed: List[str],receipts: List[Dict[str,Any]],artifacts: List[Dict[str,Any]]) -> Dict[str,Any]:
    _package_b_attempt_intact(attempt)
    wt=state["worktree"]["path"]; baseline=_package_b_prerequisites_intact(directory,state)
    structured=_normalize_package_b_structured(packet.get("structured")) if packet else None
    if not structured or structured.get("outcome")!="completed": raise ControllerError("Package B worker packet outcome must be completed")
    candidate=candidate_record(packet,changed,artifacts,wt)
    candidate["evidence"]["package_b_baseline_receipt_sha256"]=state["package_b_prerequisites"]["sha256"]
    candidate["evidence"]["package_b_baseline_fingerprint_digest"]=baseline["post_materialization_fingerprint"]["digest"]
    candidate["evidence_digest"]=digest_bytes(json.dumps(candidate["evidence"],sort_keys=True,separators=(",",":")).encode())
    candidate["id"]="package-b-"+candidate["evidence_digest"][:32]
    candidate["created_at"]=attempt.get("started_at")
    _package_b_candidate_intact(directory,state,candidate,baseline)
    delta=_package_b_builder_delta(directory,state,candidate)
    claimed=_package_b_claimed_delta(packet)
    expected=[x["path"] for x in delta["files"]]
    if claimed!=expected: raise ControllerError("Package B worker changed_paths does not match derived builder delta")
    delta_dir=os.path.join(directory,"package-b-delta"); collect_dir=os.path.join(directory,"package-b-collect")
    for path,label in ((delta_dir,"delta directory"),(collect_dir,"collect directory")):
        if os.path.lexists(path) and (os.path.islink(path) or not os.path.isdir(path)): raise ControllerError("Package B %s is unsafe"%label)
        os.makedirs(path,mode=0o700,exist_ok=True)
    result_dir=os.path.join(directory,"package-b-results")
    if os.path.lexists(result_dir) and (os.path.islink(result_dir) or not os.path.isdir(result_dir)):
        raise ControllerError("Package B result directory is unsafe")
    os.makedirs(result_dir,mode=0o700,exist_ok=True)
    delta_path=os.path.join(delta_dir,candidate["id"]+".json"); result_path=os.path.join(result_dir,candidate["id"]+".json")
    intent_path=os.path.join(collect_dir,str(attempt.get("id"))+".intent.json")
    delta_sha=_package_a_json_sha256(delta)
    baseline_bound=state["package_b_prerequisites"]
    baseline_info=capped_regular_file_info(baseline_bound["path"],os.path.join(directory,"package-b-prerequisites"),MAX_PLAN_ARTIFACT_BYTES)
    if not baseline_info or baseline_info.get("sha256")!=baseline_bound["sha256"]: raise ControllerError("Package B baseline receipt changed during collection")
    phase_before_collect=state["phase"]
    result=_package_b_collect_result(state,attempt,packet,candidate,changed,artifacts,delta,delta_path,delta_sha,baseline_info,phase_before_collect)
    result_sha=_package_a_json_sha256(result)
    intent={"schema_version":SCHEMA,"kind":"package_b_collect_intent","work_id":state["work_id"],"attempt_id":attempt.get("id"),
            "provider_packet_path":packet["path"],"provider_packet_sha256":packet["sha256"],"baseline_receipt_sha256":state["package_b_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],"phase_before_collect":phase_before_collect,"candidate":candidate,
            "delta_path":delta_path,"delta_receipt_sha256":delta_sha,"delta_sha256":delta["sha256"],
            "result_path":result_path,"result_sha256":result_sha}
    if not os.path.lexists(intent_path) and (os.path.lexists(delta_path) or os.path.lexists(result_path)):
        raise ControllerError("Package B collect output cannot precede its durable intent")
    intent_info=_package_a_adopt_json(intent_path,collect_dir,intent,"collect intent")
    delta_info=_package_a_adopt_json(delta_path,delta_dir,delta,"builder delta receipt")
    if delta_info["sha256"]!=delta_sha: raise ControllerError("Package B builder delta receipt hash changed")
    result_info=_package_a_adopt_json(result_path,directory,result,"collect result")
    if result_info["sha256"]!=result_sha: raise ControllerError("Package B collect result hash changed")
    state["candidate"]=candidate; state["escalation"]=None; state["phase"]="awaiting_gate"
    state["package_b_builder_delta"]={"path":delta_path,"sha256":delta_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"delta_sha256":delta["sha256"]}
    state["package_b_collect"]={"intent_path":intent_path,"intent_sha256":intent_info["sha256"],"result_path":result_path,"result_sha256":result_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="candidate_collected" and row.get("candidate_id")==candidate["id"] for row in recent_events(directory)):
        append_event(directory,"candidate_collected",attempt_id=attempt.get("id"),candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],packet_verified=True)
    save(directory,state)
    return result


def _package_b_replay_collect(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_b_collect") if isinstance(state.get("package_b_collect"),dict) else {}
    keys={"intent_path","intent_sha256","result_path","result_sha256","candidate_id","evidence_digest"}
    if set(bound)!=keys: raise ControllerError("Package B collected state binding is malformed")
    collect_dir=os.path.join(directory,"package-b-collect")
    intent_info=capped_regular_file_info(bound["intent_path"],collect_dir,MAX_PLAN_ARTIFACT_BYTES)
    result_info=capped_regular_file_info(bound["result_path"],directory,MAX_PLAN_ARTIFACT_BYTES)
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not result_info or result_info.get("sha256")!=bound.get("result_sha256"):
        raise ControllerError("Package B collected intent or result binding changed")
    try: result=json.loads(Path(result_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B collected result is unreadable") from exc
    return result


def _package_b_probe_code() -> str:
    return ("import json,sys\n"
            "try:\n"
            "    import sys; sys.path.insert(0,'scripts')\n"
            "    from cowork_dispatch import decide,validate_dispatch_contract,validate_dispatch_decision\n"
            "    base={'schema_version':1,'record':'DispatchContract','role':'implementer','phase':None,'controller':'claude','kind':'dispatch','purpose':'launch','site':'controller_probe','resume_session_id':None,'created':1700000000.0}\n"
            "    c_allow=dict(base,contract_id='00000000-0000-0000-0000-000000000001')\n"
            "    c_refuse=dict(base,contract_id='00000000-0000-0000-0000-000000000002')\n"
            "    c_allow=validate_dispatch_contract(c_allow); c_refuse=validate_dispatch_contract(c_refuse)\n"
            "    allow_fact={'allowed':True,'refusal_code':None,'refusal_message':None,'source':None}\n"
            "    refuse_fact={'allowed':False,'refusal_code':'controller_not_allowed','refusal_message':'blocked by controller policy','source':'policy_guard'}\n"
            "    d_allow=decide(c_allow,policy_result=allow_fact); d_refuse=decide(c_refuse,policy_result=refuse_fact)\n"
            "    d_allow=validate_dispatch_decision(d_allow,c_allow); d_refuse=validate_dispatch_decision(d_refuse,c_refuse)\n"
            "    payload=[c_allow,d_allow,d_refuse]\n"
            "    round_trip=json.loads(json.dumps(payload,sort_keys=True))==payload\n"
            "    result={'allow':d_allow['outcome']=='allow','refuse':d_refuse['outcome']=='refuse','round_trip':round_trip,'records':len(payload)}\n"
            "    print(json.dumps(result))\n"
            "except Exception as e:\n"
            "    print(json.dumps({'error':str(e)}))\n")


def _package_b_probe_code_legacy_class_api() -> str:
    return ("import json,sys\n"
            "try:\n"
            "    import sys; sys.path.insert(0,'scripts')\n"
            "    from cowork_dispatch import DispatchContract,DispatchDecision,decide,validate_dispatch_contract,validate_dispatch_decision\n"
            "    c_allow=DispatchContract(purpose='test',role='implementer',policy='unrestricted',session_id='s1')\n"
            "    validate_dispatch_contract(c_allow)\n"
            "    d_allow=decide(c_allow)\n"
            "    validate_dispatch_decision(d_allow,c_allow)\n"
            "    c_refuse=DispatchContract(purpose='test',role='implementer',policy='blocked',session_id='s2')\n"
            "    d_refuse=decide(c_refuse)\n"
            "    validate_dispatch_decision(d_refuse,c_refuse)\n"
            "    r1=json.dumps(c_allow.__dict__,sort_keys=True)\n"
            "    r2=json.loads(r1)\n"
            "    result={'allow':d_allow.outcome=='allow','refuse':d_refuse.outcome=='refuse','round_trip':r2==c_allow.__dict__,'records':3}\n"
            "    print(json.dumps(result))\n"
            "except Exception as e:\n"
            "    print(json.dumps({'error':str(e)}))\n")


def _package_b_verification_static(state: Dict[str,Any],candidate: Dict[str,Any],delta: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    value={"work_id":state["work_id"],"package_id":PACKAGE_B_PACKAGE_ID,"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
            "policy":POLICY_ID,"baseline_receipt_sha256":state["package_b_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],
            "delta_receipt_sha256":state.get("package_b_builder_delta",{}).get("sha256"),"delta_sha256":delta["sha256"],
            "candidate_fingerprint_digest":candidate["evidence"]["worktree_fingerprint"]["digest"],
            "env_policy_digest":PACKAGE_B_ENV_POLICY_DIGEST}
    generation=state.get("package_b_verification_generation")
    if generation is not None:
        if generation not in {1,2}: raise ControllerError("Package B verification generation is invalid")
        value["verification_generation"]=generation
    return value


def _package_b_verification_specs(state: Optional[Dict[str,Any]]=None) -> List[Dict[str,Any]]:
    focused_uniform_argv=["python3","-m","unittest",PACKAGE_B_FOCUSED_UNIFORM_TEST]
    focused_sites_argv=["python3","-m","unittest"]+PACKAGE_B_FOCUSED_SITE_TESTS
    legacy_probe=bool(state and state.get("package_b_verification_generation")==1 and state.get("package_b_verification_probe_version") in {None,1})
    probe_code=_package_b_probe_code_legacy_class_api() if legacy_probe else _package_b_probe_code()
    return [
        {"label":"test_cowork","argv":["python3","-m","unittest","scripts/test_cowork.py"],"timeout":PACKAGE_B_TEST_TIMEOUT,"kind":"unittest"},
        {"label":"characterization","argv":["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],"timeout":180,"kind":"characterization_b"},
        {"label":"uniform_refusal_focused","argv":focused_uniform_argv,"timeout":60,"kind":"focused_unittest"},
        {"label":"site_coverage_focused","argv":focused_sites_argv,"timeout":120,"kind":"focused_unittest"},
        {"label":"structural_migration","argv":["controller","package-b-structural"],"timeout":0,"kind":"package_b_structural"},
        {"label":"scope_delta","argv":["controller","package-b-delta"],"timeout":0,"kind":"controller"},
        {"label":"diff_check","argv":["git","diff","--check"],"timeout":60,"kind":"empty"},
        {"label":"json_probe","argv":["python3","-c",probe_code],"timeout":30,"kind":"package_b_probe"},
    ]


def _package_b_probe_passes(raw: bytes) -> bool:
    try: probe=json.loads(raw.decode("utf-8").strip())
    except (UnicodeDecodeError,json.JSONDecodeError): return False
    return bool(probe.get("allow") and probe.get("refuse") and probe.get("round_trip") and probe.get("records")==3)


def _package_b_verification_dir(directory: str,candidate: Dict[str,Any],state: Optional[Dict[str,Any]]=None) -> str:
    generation=(state or {}).get("package_b_verification_generation")
    if generation is None: suffix=""
    elif generation in {1,2}: suffix="-g"+str(generation)
    else: raise ControllerError("Package B verification generation is invalid")
    return os.path.join(directory,"package-b-verification",candidate["id"]+suffix)


def _package_b_validate_verification(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_b_verification") if isinstance(state.get("package_b_verification"),dict) else {}
    if set(bound)!={"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"}: raise ControllerError("Package B verification state binding is malformed")
    verify_dir=_package_b_verification_dir(directory,candidate,state)
    intent_info=capped_regular_file_info(bound.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("intent_path"),str) else None
    aggregate_info=capped_regular_file_info(bound.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("aggregate_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not aggregate_info or aggregate_info.get("sha256")!=bound.get("aggregate_sha256"): raise ControllerError("Package B verification intent or aggregate changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text()); aggregate=json.loads(Path(aggregate_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B verification evidence is unreadable") from exc
    static=_package_b_verification_static(state,candidate,delta,baseline); specs=_package_b_verification_specs(state)
    expected_keys={"schema_version","kind","created_at","static","specs","receipt_paths","output_paths","terminal_paths","start_paths","aggregate_path"}
    if (not isinstance(intent,dict) or set(intent)!=expected_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_b_verification_intent" or
            not isinstance(intent.get("created_at"),str) or intent.get("static")!=static or intent.get("specs")!=specs):
        raise ControllerError("Package B verification intent binding changed")
    aggregate_refs=aggregate.get("receipts") if isinstance(aggregate,dict) else None
    if (not isinstance(aggregate_refs,list) or not aggregate_refs or len(aggregate_refs)>len(specs) or
            any(not isinstance(row,dict) for row in aggregate_refs)):
        raise ControllerError("Package B verification aggregate receipt prefix is malformed")
    prefix_len=len(aggregate_refs)
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs[:prefix_len],intent["receipt_paths"][:prefix_len],intent["output_paths"][:prefix_len],intent["terminal_paths"][:prefix_len],intent["start_paths"][:prefix_len])):
        info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_B_MAX_GATE_OUTPUT)
        if not info or not output_info: raise ControllerError("Package B verification receipt or output is missing or unsafe")
        try: raw=Path(output_info["path"]).read_bytes()
        except OSError as exc: raise ControllerError("Package B verification output is unreadable") from exc
        try: receipt=json.loads(Path(info["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B verification receipt is unreadable") from exc
        terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_B_MAX_GATE_OUTPUT+64*1024)
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
        receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
        structurally_bound=(isinstance(receipt,dict) and set(receipt)==receipt_keys and receipt.get("schema_version")==SCHEMA and receipt.get("kind")=="package_b_verification_receipt" and
                receipt.get("index")==index and receipt.get("label")==spec["label"] and receipt.get("argv")==spec["argv"] and receipt.get("cwd")==state["worktree"]["path"] and
                receipt.get("timeout_seconds")==spec["timeout"] and receipt.get("static")==static and bool(terminal_info) and
                receipt.get("start_path")==start_info["path"] and receipt.get("start_sha256")==start_info["sha256"] and
                receipt.get("terminal_path")==terminal_info["path"] and receipt.get("terminal_sha256")==terminal_info["sha256"])
        if not structurally_bound: raise ControllerError("Package B verification receipt structure changed")
        consistent=_package_a_receipt_consistent(spec,receipt,output_info,raw)
        # Historical Package B builds sealed an empty counter map when the
        # first focused/characterization command exited nonzero.  Authenticate
        # that exact legacy shape by reparsing the immutable output, but never
        # accept it for a passing receipt or anywhere except the final prefix.
        if (not consistent and index==prefix_len-1 and aggregate.get("all_passed") is False and receipt.get("passed") is False and
                receipt.get("counters")=={} and spec.get("kind") in {"focused_unittest","characterization_b"}):
            try: parsed_counters=_package_a_unittest_counters(raw)
            except ControllerError: parsed_counters=None
            if isinstance(parsed_counters,dict):
                normalized_receipt={**receipt,"counters":parsed_counters}
                consistent=_package_a_receipt_consistent(spec,normalized_receipt,output_info,raw)
        if not consistent: raise ControllerError("Package B verification receipt semantics changed: "+spec["label"])
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
    expected_all_passed=len(refs)==len(specs) and all(row["passed"] for row in refs)
    valid_prefix=(expected_all_passed or (not any(not row["passed"] for row in refs[:-1]) and refs[-1]["passed"] is False))
    if not valid_prefix:
        raise ControllerError("Package B verification aggregate is not a deterministic pass or first-failure prefix")
    for path in intent["receipt_paths"][prefix_len:]+intent["output_paths"][prefix_len:]+intent["terminal_paths"][prefix_len:]+intent["start_paths"][prefix_len:]:
        if os.path.lexists(path):
            raise ControllerError("Package B verification contains evidence after its first failed gate")
    aggregate_keys={"schema_version","kind","created_at","static","receipts","all_passed","post_fingerprint"}
    if (not isinstance(aggregate,dict) or set(aggregate)!=aggregate_keys or aggregate.get("schema_version")!=SCHEMA or aggregate.get("kind")!="package_b_verification_aggregate" or
            aggregate.get("created_at")!=intent["created_at"] or aggregate.get("static")!=static or aggregate.get("receipts")!=refs or aggregate.get("all_passed") is not expected_all_passed or
            aggregate.get("post_fingerprint")!=candidate["evidence"]["worktree_fingerprint"] or bound.get("candidate_id")!=candidate["id"] or bound.get("evidence_digest")!=candidate["evidence_digest"]):
        raise ControllerError("Package B verification aggregate binding changed")
    return {"intent":intent,"aggregate":aggregate,"aggregate_info":aggregate_info,"refs":refs}


def _command_verify_package_b_inner(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    _package_b_candidate_intact(directory,state,candidate,baseline)
    delta=_package_b_builder_delta(directory,state,candidate)
    if state.get("package_b_verification"):
        verified=_package_b_validate_verification(directory,state,candidate,baseline,delta)
        return {"schema_version":SCHEMA,"operation":"verify_package_b","reused":True,"aggregate_path":verified["aggregate_info"]["path"],"aggregate_sha256":verified["aggregate_info"]["sha256"],"all_passed":verified["aggregate"]["all_passed"]}
    _top_verify=os.path.join(directory,"package-b-verification")
    if os.path.lexists(_top_verify) and (os.path.islink(_top_verify) or not os.path.isdir(_top_verify) or not inside(os.path.realpath(_top_verify),directory)): raise ControllerError("Package B verification top-level directory is unsafe")
    static=_package_b_verification_static(state,candidate,delta,baseline); specs=_package_b_verification_specs(state); verify_dir=_package_b_verification_dir(directory,candidate,state)
    if os.path.lexists(verify_dir) and (os.path.islink(verify_dir) or not os.path.isdir(verify_dir)): raise ControllerError("Package B verification directory is unsafe")
    os.makedirs(verify_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(verify_dir,"intent.json"); aggregate_path=os.path.join(verify_dir,"aggregate.json")
    receipt_paths=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)]
    output_paths=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    terminal_paths=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    start_paths=[os.path.join(verify_dir,"%d-%s.start.json"%(i,s["label"])) for i,s in enumerate(specs)]
    base_intent={"schema_version":SCHEMA,"kind":"package_b_verification_intent","static":static,"specs":specs,"receipt_paths":receipt_paths,"output_paths":output_paths,"terminal_paths":terminal_paths,"start_paths":start_paths,"aggregate_path":aggregate_path}
    existing_intent=capped_regular_file_info(intent_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not existing_intent: raise ControllerError("Package B verification intent is unsafe")
    if existing_intent:
        try: intent=json.loads(Path(existing_intent["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B verification intent is unreadable") from exc
        if set(intent)!=(set(base_intent)|{"created_at"}) or {k:v for k,v in intent.items() if k!="created_at"}!=base_intent or not isinstance(intent.get("created_at"),str): raise ControllerError("Package B verification orphan intent conflicts")
    else:
        if os.path.lexists(aggregate_path) or any(os.path.lexists(path) for path in receipt_paths+output_paths+terminal_paths+start_paths): raise ControllerError("Package B verification output cannot precede durable intent")
        intent={**base_intent,"created_at":utc()}; existing_intent=_package_a_adopt_json(intent_path,verify_dir,intent,"b verification intent")
    wt=state["worktree"]["path"]; refs=[]
    hermetic_env=_package_a_v5_hermetic_env()
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs,receipt_paths,output_paths,terminal_paths,start_paths)):
        before=worktree_fingerprint(wt)
        if before!=candidate["evidence"]["worktree_fingerprint"]: raise ControllerError("Package B candidate changed before deterministic gate")
        prior=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(path) else None
        if os.path.lexists(path) and not prior: raise ControllerError("Package B verification orphan receipt is unsafe")
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(dt.datetime.fromisoformat(intent["created_at"].replace("Z","+00:00"))+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        result,raw,terminal_info=_package_a_execute_gate(spec,index,wt,verify_dir,terminal_path,start_path,static,wrapper_nonce,deadline_text,env=hermetic_env)
        output_info=_package_a_adopt_bytes(output_path,verify_dir,raw,"b gate output")
        result["output_path"]=output_info["path"]
        if prior:
            try: old=json.loads(Path(prior["path"]).read_text())
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B verification orphan receipt is unreadable") from exc
            receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            if (not isinstance(old,dict) or set(old)!=receipt_keys or old.get("schema_version")!=SCHEMA or old.get("kind")!="package_b_verification_receipt" or old.get("index")!=index or old.get("label")!=spec["label"] or old.get("argv")!=spec["argv"] or old.get("cwd")!=wt or old.get("timeout_seconds")!=spec["timeout"] or old.get("static")!=static or not output_info or not terminal_info or old.get("start_path")!=start_info["path"] or old.get("start_sha256")!=start_info["sha256"] or old.get("terminal_path")!=terminal_info["path"] or old.get("terminal_sha256")!=terminal_info["sha256"] or not _package_a_receipt_consistent(spec,old,output_info,raw)):
                raise ControllerError("Package B verification orphan receipt conflicts")
            refs.append({"index":index,"label":spec["label"],"path":prior["path"],"sha256":prior["sha256"],"counters":old["counters"],"passed":old["passed"]})
        else:
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            receipt={"schema_version":SCHEMA,"kind":"package_b_verification_receipt","index":index,"label":spec["label"],"argv":spec["argv"],"cwd":wt,"timeout_seconds":spec["timeout"],"static":static,
                     "start_path":start_info["path"],"start_sha256":start_info["sha256"],"terminal_path":terminal_info["path"],"terminal_sha256":terminal_info["sha256"],
                     **{k:result[k] for k in ("exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed")}}
            receipt_info=_package_a_adopt_json(path,verify_dir,receipt,"b verification receipt")
            refs.append({"index":index,"label":spec["label"],"path":receipt_info["path"],"sha256":receipt_info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
        if not refs[-1]["passed"]: break
    all_passed=all(row["passed"] for row in refs) and len(refs)==len(specs)
    post_fp=worktree_fingerprint(wt)
    aggregate={"schema_version":SCHEMA,"kind":"package_b_verification_aggregate","created_at":intent["created_at"],"static":static,"receipts":refs,"all_passed":all_passed,"post_fingerprint":post_fp}
    aggregate_info=_package_a_adopt_json(aggregate_path,verify_dir,aggregate,"b verification aggregate")
    state["package_b_verification"]={"intent_path":intent_path,"intent_sha256":existing_intent["sha256"],"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="package_b_verified" and row.get("candidate_id")==candidate["id"] for row in recent_events(directory)):
        append_event(directory,"package_b_verified",candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],all_passed=all_passed)
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"verify_package_b","reused":False,"aggregate_path":aggregate_path,"aggregate_sha256":aggregate_info["sha256"],"all_passed":all_passed}


def command_verify_package_b(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package B verification requires its canonical awaiting gate")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_b_prerequisites_intact(directory,state)
    with package_lock(directory): return _command_verify_package_b_inner(directory,state,candidate,baseline)


def _package_b_review_context(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_b_prerequisites_intact(directory,state); _package_b_candidate_intact(directory,state,candidate,baseline)
    delta=_package_b_builder_delta(directory,state,candidate); verification=_package_b_validate_verification(directory,state,candidate,baseline,delta)
    changed=[row["path"] for row in delta["files"]]
    return {"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":changed}


def _package_b_review_schema(state: Dict[str,Any],context: Dict[str,Any],attempt_id: str,run: str,nonce: str) -> Dict[str,Any]:
    candidate=context["candidate"]; verification=context["verification"]
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","work_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce","candidate_id","evidence_digest","baseline_receipt_sha256","verification_aggregate_sha256","verification_receipt_sha256s","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_b_review"},"work_id":{"type":"string","const":state["work_id"]},
            "policy":{"type":"string","const":POLICY_ID},"review_attempt_id":{"type":"string","const":attempt_id},
            "backend":{"type":"string","const":PACKAGE_B_CLAUDE_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_B_CLAUDE_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"candidate_id":{"type":"string","const":candidate["id"]},
            "evidence_digest":{"type":"string","const":candidate["evidence_digest"]},"baseline_receipt_sha256":{"type":"string","const":state["package_b_prerequisites"]["sha256"]},
            "verification_aggregate_sha256":{"type":"string","const":verification["aggregate_info"]["sha256"]},
            "verification_receipt_sha256s":{"type":"array","minItems":8,"maxItems":8,"items":{"type":"string"}},
            "changed_paths":{"type":"array","minItems":1,"maxItems":4,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_b_review_expected(state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    verification=context["verification"]
    return {"schema_version":SCHEMA,"kind":"package_b_review","work_id":state["work_id"],"policy":POLICY_ID,"review_attempt_id":attempt["id"],
            "backend":PACKAGE_B_CLAUDE_REVIEW_BACKEND,"actor_id":PACKAGE_B_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_nonce":attempt["nonce"],
            "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
            "baseline_receipt_sha256":state["package_b_prerequisites"]["sha256"],
            "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],
            "verification_receipt_sha256s":[row["sha256"] for row in verification["refs"]],"changed_paths":context["changed_paths"]}


def _package_b_review_transport_repair_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],envelope: Dict[str,Any],item: Dict[str,Any],bound: Dict[str,Any]) -> Dict[str,Any]:
    repair_bound=state.get("package_b_review_transport_repair") if isinstance(state.get("package_b_review_transport_repair"),dict) else {}
    if set(repair_bound)!={"path","sha256","repair_id","candidate_id","evidence_digest","source_attempt_id","exhausted_attempt_id"}:
        raise ControllerError("Package B review transport repair state binding is malformed")
    repair_dir=os.path.join(directory,"package-b-review-repairs")
    repair_info=capped_regular_file_info(repair_bound.get("path"),repair_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(repair_bound.get("path"),str) else None
    if not repair_info or repair_info.get("sha256")!=repair_bound.get("sha256"): raise ControllerError("Package B review transport repair receipt changed")
    try: repair=json.loads(Path(repair_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B review transport repair receipt is unreadable") from exc
    repair_keys={"schema_version","kind","work_id","policy","repair_id","bug_class","candidate_id","evidence_digest","verification_aggregate_sha256",
        "source_attempt_id","source_run_id","source_provider_session_id","source_output_path","source_output_sha256","source_terminal_sha256",
        "exhausted_attempt_id","exhausted_provider_session_id","exhausted_terminal_sha256","controller_bindings_sha256","issued_at"}
    if (not isinstance(repair,dict) or set(repair)!=repair_keys or repair.get("schema_version")!=SCHEMA or repair.get("kind")!="package_b_review_transport_repair" or
            repair.get("work_id")!=state["work_id"] or repair.get("policy")!=POLICY_ID or repair.get("repair_id")!=repair_bound.get("repair_id") or
            repair.get("bug_class")!="controller_owned_exact_array_bindings/v1" or repair.get("candidate_id")!=context["candidate"]["id"] or
            repair.get("evidence_digest")!=context["candidate"]["evidence_digest"] or repair.get("verification_aggregate_sha256")!=context["verification"]["aggregate_info"]["sha256"] or
            repair.get("source_attempt_id")!=repair_bound.get("source_attempt_id") or repair.get("exhausted_attempt_id")!=repair_bound.get("exhausted_attempt_id")):
        raise ControllerError("Package B review transport repair receipt binding changed")
    retries=state.get("package_b_review_retries")
    history=state.get("package_b_review_attempt_history")
    if not isinstance(retries,list) or len(retries)!=1 or not isinstance(history,list): raise ControllerError("Package B review transport repair history is malformed")
    source=retries[0]
    exhausted=next((row for row in history if isinstance(row,dict) and row.get("id")==repair["exhausted_attempt_id"]),None)
    if (not isinstance(source,dict) or source.get("id")!=repair["source_attempt_id"] or source.get("retry_reason")!="exact_array_binding_omission" or
            not isinstance(exhausted,dict) or exhausted.get("transport_repair_disposition")!="review_retry_exhausted"):
        raise ControllerError("Package B review transport repair attempt history changed")
    source_terminal,source_terminal_info=_review_terminal(directory,source,"package-b-review-attempts")
    exhausted_terminal,exhausted_terminal_info=_review_terminal(directory,exhausted,"package-b-review-attempts")
    output=capped_regular_file_info(repair.get("source_output_path"),os.path.join(directory,"package-b-review-attempts"),64*1024) if isinstance(repair.get("source_output_path"),str) else None
    if (not output or output.get("sha256")!=repair.get("source_output_sha256") or source_terminal_info.get("sha256")!=repair.get("source_terminal_sha256") or
            source_terminal.get("exit_code")!=0 or source_terminal.get("timed_out") or source_terminal.get("output_limit_exceeded") or
            exhausted_terminal_info.get("sha256")!=repair.get("exhausted_terminal_sha256") or exhausted_terminal.get("exit_code")==0 or
            not (exhausted_terminal.get("timed_out") or exhausted_terminal.get("output_limit_exceeded")) or exhausted_terminal.get("output_sha256") is not None):
        raise ControllerError("Package B review transport repair terminal evidence changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B repaired source review packet is unreadable") from exc
    expected=_package_b_review_expected(state,context,source); required=set(expected)|{"verdict","findings","checks"}; scalar_keys=set(expected)-{"verification_receipt_sha256s","changed_paths"}
    arrays_well_formed=(isinstance(packet,dict) and isinstance(packet.get("verification_receipt_sha256s"),list) and len(packet["verification_receipt_sha256s"])==8 and
        all(isinstance(x,str) and len(x.encode())<=128 for x in packet["verification_receipt_sha256s"]) and isinstance(packet.get("changed_paths"),list) and
        1<=len(packet["changed_paths"])<=4 and all(isinstance(x,str) and len(x.encode())<=500 for x in packet["changed_paths"]))
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=expected[k] for k in scalar_keys) or not arrays_well_formed or
            (packet.get("verification_receipt_sha256s")==expected["verification_receipt_sha256s"] and packet.get("changed_paths")==expected["changed_paths"]) or
            packet.get("verdict")!="pass" or packet.get("findings")!=[] or not isinstance(packet.get("checks"),list) or not packet["checks"] or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package B repaired source review is not the exact passing array-binding omission")
    provider_session=_package_a_claude_session(source["stdout"],directory,source.get("reviewer_session_id",""))
    exhausted_session=_package_a_claude_session(exhausted["stdout"],directory,exhausted.get("reviewer_session_id",""))
    controller_bindings={"verification_receipt_sha256s":expected["verification_receipt_sha256s"],"changed_paths":expected["changed_paths"]}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id","reviewer_session_id",
        "terminal_receipt_sha256","model_packet_sha256","model_packet","controller_bindings","repair_receipt_sha256"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or envelope.get("kind")!="package_b_review_envelope_repaired" or
            envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or envelope.get("candidate_id")!=context["candidate"]["id"] or
            envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or envelope.get("actor_id")!=PACKAGE_B_CLAUDE_REVIEW_ACTOR or
            envelope.get("run_id")!=source.get("run_id") or envelope.get("review_attempt_id")!=source.get("id") or envelope.get("reviewer_session_id")!=provider_session or
            envelope.get("terminal_receipt_sha256")!=source_terminal_info["sha256"] or envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or
            envelope.get("model_packet")!=packet or envelope.get("controller_bindings")!=controller_bindings or envelope.get("repair_receipt_sha256")!=repair_info["sha256"] or
            repair.get("source_run_id")!=source.get("run_id") or repair.get("source_provider_session_id")!=provider_session or
            repair.get("exhausted_provider_session_id")!=exhausted_session or provider_session==exhausted_session or
            repair.get("controller_bindings_sha256")!=_package_a_json_sha256(controller_bindings) or bound.get("sha256")!=item.get("sha256") or
            bound.get("model_packet_sha256")!=_package_a_json_sha256(packet) or bound.get("receipt_sha256")!=source_terminal_info["sha256"]):
        raise ControllerError("Package B repaired review envelope binding changed")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":source_terminal_info}


def _package_b_review_attempt_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package B review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"review attempt id"),(attempt.get("run_id"),"review run id"),(attempt.get("nonce"),"review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(directory,"package-b-review-attempts"); expected_schema=_package_b_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_B_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_b_review_expected(state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package B review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_B_CLAUDE_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_B_CLAUDE_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=context["candidate"]["id"] or attempt.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(directory,"logs")),("stderr",os.path.join(directory,"logs"))))):
        raise ControllerError("Package B review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package B review schema binding changed")
    return attempt


def _package_b_review_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_b_review") if isinstance(state.get("package_b_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict","model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package B independent review state binding is malformed")
    item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package B independent review envelope changed")
    try: envelope=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B independent review envelope is unreadable") from exc
    if isinstance(envelope,dict) and envelope.get("kind")=="package_b_review_envelope_repaired":
        return _package_b_review_transport_repair_intact(directory,state,context,envelope,item,bound)
    attempt=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else {}
    _package_b_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-b-review-attempts")
    packet=envelope.get("model_packet") if isinstance(envelope,dict) else None
    expected=_package_b_review_expected(state,context,attempt); packet_keys=set(expected)|{"verdict","findings","checks"}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id","reviewer_session_id","terminal_receipt_sha256","model_packet_sha256","model_packet"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or
            envelope.get("kind")!="package_b_review_envelope" or envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or
            envelope.get("candidate_id")!=context["candidate"]["id"] or envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            envelope.get("actor_id")!=PACKAGE_B_CLAUDE_REVIEW_ACTOR or envelope.get("run_id")!=attempt.get("run_id") or envelope.get("review_attempt_id")!=attempt.get("id") or
            envelope.get("reviewer_session_id")!=attempt.get("provider_session_id") or envelope.get("terminal_receipt_sha256")!=receipt["sha256"] or
            not isinstance(packet,dict) or set(packet)!=packet_keys or any(packet.get(k)!=v for k,v in expected.items()) or
            envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded")):
        raise ControllerError("Package B independent review envelope binding changed")
    if (packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package B independent review verdict packet is malformed")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":receipt}


def _package_b_gate_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    if not isinstance(state.get("package_b_gate_receipt"),dict): return None
    bound=state["package_b_gate_receipt"]
    gate_dir=os.path.join(directory,"package-b-gates")
    info=capped_regular_file_info(bound.get("path"),gate_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package B gate receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B gate receipt is unreadable") from exc
    if (receipt.get("kind")!="package_b_gate_receipt" or receipt.get("work_id")!=state["work_id"] or receipt.get("policy")!=POLICY_ID or
            receipt.get("gate_name")!=PACKAGE_B_GATE_PRINCIPAL or receipt.get("adjudicator_principal")!=PACKAGE_B_GATE_PRINCIPAL):
        raise ControllerError("Package B gate receipt identity changed")
    expected_phase={"pass":"completed","revise":"prepared","fail":"failed"}[receipt["disposition"]]
    if state.get("phase")!=expected_phase: raise ControllerError("Package B gate phase binding changed")
    event_kind={"pass":"package_b_gate_passed","revise":"package_b_correction_queued","fail":"package_b_gate_failed"}[receipt["disposition"]]
    if not any(row.get("kind")==event_kind and row.get("receipt_id")==receipt.get("receipt_id") for row in recent_events(directory)):
        append_event(directory,event_kind,receipt_id=receipt.get("receipt_id"),gate_name=receipt["gate_name"],policy=POLICY_ID,candidate_id=receipt.get("candidate_id"),evidence_digest=receipt.get("evidence_digest"),disposition=receipt["disposition"],next_state=expected_phase)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_b","phase":expected_phase,"disposition":receipt["disposition"],
            "receipt":{"path":info["path"],"sha256":info["sha256"]},"reused":True}


def _package_b_review_capacity_intact(directory: str,state: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    bound=state.get("package_b_review_capacity") if isinstance(state.get("package_b_review_capacity"),dict) else {}
    keys={"path","sha256","mode","retry_after","candidate_id","evidence_digest","review_attempt_id","provider_session_id","wakeup","consumed_at"}
    if set(bound)!=keys or state.get("phase")!=CAPACITY_WAITING: raise ControllerError("Package B review capacity state is malformed")
    info=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-b-review-capacity"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package B review capacity packet changed")
    try: packet=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B review capacity packet is unreadable") from exc
    if (packet.get("kind")!="package_b_review_capacity" or packet.get("policy")!=POLICY_ID or packet.get("candidate_id")!=bound.get("candidate_id") or
            packet.get("evidence_digest")!=bound.get("evidence_digest") or packet.get("review_attempt_id")!=bound.get("review_attempt_id") or
            packet.get("provider_session_id")!=bound.get("provider_session_id") or packet.get("mode")!=bound.get("mode") or packet.get("retry_after")!=bound.get("retry_after")):
        raise ControllerError("Package B review capacity binding changed")
    return packet,info


def _command_launch_package_b_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package B review requires its awaiting gate")
    context=_package_b_review_context(directory,state)
    if state.get("package_b_review"): raise ControllerError("Package B candidate already has an ingested independent review")
    existing=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else None
    if existing:
        _package_b_review_attempt_intact(directory,state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _review_terminal(directory,existing,"package-b-review-attempts")
            return {"schema_version":SCHEMA,"operation":"launch_package_b_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_b_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_b_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            append_event(directory,"package_b_review_launch_lost",attempt_id=existing["id"]); save(directory,state)
        raise ControllerError("Package B independent review attempt already exists")
    retries=state.get("package_b_review_retries",[])
    if not isinstance(retries,list) or len(retries)>1: raise ControllerError("Package B review retry history is malformed")
    actor=PACKAGE_B_CLAUDE_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(directory,"package-b-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package B review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_b_review_schema(state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"b review schema")
    expected_arrays=_package_b_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prompt=("Package B controller-owned independent review. Verify the six dispatch adapter sites, backstop, no-probe-after-refusal, and unrestricted-policy compatibility. "
            "Review only bounded controller-owned receipts. Return the required schema JSON packet bound to every exact identity. "
            "Copy verification_receipt_sha256s exactly as "+json.dumps(expected_arrays["verification_receipt_sha256s"],separators=(",",":"))+" and changed_paths exactly as "+
            json.dumps(expected_arrays["changed_paths"],separators=(",",":"))+". Do not infer or replace either array.")
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package B review prompt exceeds bound")
    logs=os.path.join(directory,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-b-claude.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-b-claude.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind","claude_package_a_review_terminal","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    expected=_package_b_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=305)).isoformat().replace("+00:00","Z")
    state["package_b_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_B_CLAUDE_REVIEW_BACKEND,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save(directory,state); append_event(directory,"package_b_review_starting",attempt_id=attempt_id,candidate_id=context["candidate"]["id"])
    try: pid,pgid=detached_spawn(wrapper,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["package_b_review_attempt"]["spawn_error"]=type(exc).__name__; state["package_b_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); state["package_b_review_attempt"]["terminal_at"]=utc()
        append_event(directory,"package_b_review_spawn_failed",attempt_id=attempt_id); save(directory,state); raise ControllerError("Package B review controller spawn failed") from exc
    state["package_b_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"package_b_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_package_b_review","attempt_id":attempt_id,"run_id":run,"phase":state["phase"]}


def _package_b_review_capacity_wait(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any],
                                     terminal: Dict[str,Any],receipt: Dict[str,Any],capacity_event: Dict[str,Any]) -> Dict[str,Any]:
    retry_after=parse_retry_after(capacity_event.get("rate_limit_info",{}).get("resetsAt"))
    mode=("scheduled" if isinstance(retry_after,str) else "manual_signal")
    cap_dir=os.path.join(directory,"package-b-review-capacity"); os.makedirs(cap_dir,mode=0o700,exist_ok=True)
    packet={"schema_version":SCHEMA,"kind":"package_b_review_capacity","work_id":state["work_id"],"policy":POLICY_ID,"candidate_id":context["candidate"]["id"],
            "evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),
            "mode":mode,"retry_after":retry_after,"terminal_receipt_sha256":receipt["sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"issued_at":utc()}
    path=os.path.join(cap_dir,attempt["id"]+".json"); info=_package_a_adopt_json(path,cap_dir,packet,"b review capacity packet")
    state["package_b_review_capacity"]={"path":path,"sha256":info["sha256"],"mode":mode,"retry_after":retry_after,"candidate_id":context["candidate"]["id"],
        "evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),
        "wakeup":None,"consumed_at":None}
    state["phase"]=CAPACITY_WAITING; append_event(directory,"package_b_review_capacity_wait",mode=mode,retry_after=retry_after,candidate_id=context["candidate"]["id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_b_review","phase":CAPACITY_WAITING,"capacity":{"mode":mode,"retry_after":retry_after,"failure_class":"subscription_quota_exhausted"}}


def _command_ingest_package_b_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state) or state.get("phase") not in {"awaiting_gate",CAPACITY_WAITING}: raise ControllerError("Package B review ingest requires awaiting gate")
    if state.get("phase")==CAPACITY_WAITING:
        if not isinstance(state.get("package_b_review_capacity"),dict): raise ControllerError("Package B review capacity state is malformed for ingest")
        return {"schema_version":SCHEMA,"operation":"ingest_package_b_review","phase":CAPACITY_WAITING,"capacity":state["package_b_review_capacity"]}
    context=_package_b_review_context(directory,state); attempt=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package B review requires a quiescent controller-owned attempt")
    _package_b_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-b-review-attempts")
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            with package_lock(directory): return _package_b_review_capacity_wait(directory,state,context,attempt,terminal,receipt,capacity_event)
        if terminal.get("timed_out"): raise ControllerError("Package B review timed out; timeout is terminal for this package")
        raise ControllerError("Package B independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-b-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package B review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    prior_sessions={row.get("provider_session_id") for row in state.get("package_b_review_attempt_history",[]) if isinstance(row,dict)}
    if provider_session in prior_sessions: raise ControllerError("Package B reviewer provider session is not distinct from prior attempts")
    expected=_package_b_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package B independent review packet failed strict binding validation")
    packets_dir=os.path.join(directory,"packets"); os.makedirs(packets_dir,mode=0o700,exist_ok=True)
    destination=os.path.join(packets_dir,context["candidate"]["id"]+".package-b-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    envelope={"schema_version":SCHEMA,"kind":"package_b_review_envelope","work_id":state["work_id"],"policy":POLICY_ID,"candidate_id":context["candidate"]["id"],
              "evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_B_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_attempt_id":attempt["id"],
              "reviewer_session_id":attempt.get("reviewer_session_id",""),"terminal_receipt_sha256":receipt["sha256"],"model_packet_sha256":model_packet_sha256,"model_packet":packet}
    envelope_info=_package_a_adopt_json(destination,packets_dir,envelope,"b review envelope")
    consumed=utc(); attempt["consumed_at"]=consumed; attempt["packet_sha256"]=envelope_info["sha256"]; attempt["provider_session_id"]=provider_session
    state["package_b_review"]={"path":destination,"sha256":envelope_info["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_B_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,
        "verdict":packet["verdict"],"model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    history=state.get("package_b_review_attempt_history",[]); history=list(history)+[{**attempt}]
    state["package_b_review_attempt_history"]=history; state["package_b_review_attempt"]={**attempt}
    append_event(directory,"package_b_review_ingested",candidate_id=context["candidate"]["id"],verdict=packet["verdict"],run_id=attempt["run_id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_b_review","phase":state["phase"],"verdict":packet["verdict"]}


def _command_retry_package_b_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package B review retry requires awaiting gate")
    context=_package_b_review_context(directory,state); attempt=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package B review retry requires a quiescent unconsumed attempt")
    _package_b_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-b-review-attempts")
    is_overflow=(terminal.get("exit_code")!=0 and (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and terminal.get("output_sha256") is None)
    binding_omission=False; provider_session=None
    if (terminal.get("exit_code")==0 and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded")):
        output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-b-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
        if output and terminal.get("output_sha256")==output.get("sha256") and terminal.get("output_bytes")==output.get("bytes"):
            try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
            except (OSError,json.JSONDecodeError): packet=None
            expected=_package_b_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
            scalar_keys=set(expected)-{"verification_receipt_sha256s","changed_paths"}
            arrays_well_formed=(isinstance(packet,dict) and isinstance(packet.get("verification_receipt_sha256s"),list) and len(packet["verification_receipt_sha256s"])==8 and
                all(isinstance(x,str) and len(x.encode())<=128 for x in packet["verification_receipt_sha256s"]) and isinstance(packet.get("changed_paths"),list) and
                1<=len(packet["changed_paths"])<=4 and all(isinstance(x,str) and len(x.encode())<=500 for x in packet["changed_paths"]))
            binding_omission=(isinstance(packet,dict) and set(packet)==required and all(packet.get(k)==expected[k] for k in scalar_keys) and arrays_well_formed and
                (packet.get("verification_receipt_sha256s")!=expected["verification_receipt_sha256s"] or packet.get("changed_paths")!=expected["changed_paths"]) and
                packet.get("verdict")=="pass" and packet.get("findings")==[] and isinstance(packet.get("checks"),list) and
                1<=len(packet["checks"])<=20 and all(isinstance(x,str) and len(x.encode())<=1000 for x in packet["checks"]))
            if binding_omission:
                provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    if not is_overflow and not binding_omission:
        raise ControllerError("Package B review retry is only available for bounded_stream_overflow or exact_array_binding_omission classification")
    retries=state.get("package_b_review_retries",[])
    if not isinstance(retries,list) or len(retries)>=1: raise ControllerError("Package B review infrastructure retry is already exhausted")
    classification="bounded_stream_overflow" if is_overflow else "exact_array_binding_omission"
    archived={**attempt,"retry_reason":classification,"terminal_receipt_sha256":receipt["sha256"],"provider_session_id":provider_session}
    retries=retries+[archived]; state["package_b_review_retries"]=retries; state["package_b_review_attempt"]=None
    history=state.get("package_b_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package B review attempt history is malformed")
    state["package_b_review_attempt_history"]=history+[archived]
    append_event(directory,"package_b_review_retry_queued",attempt_id=attempt["id"],retry_count=len(retries)); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_package_b_review","phase":state["phase"],"retry_evidence":{"classification":classification,"prior_attempt_id":attempt["id"],"retry_count":len(retries)}}


def _command_repair_package_b_review_binding(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package B review binding repair requires awaiting gate")
    context=_package_b_review_context(directory,state)
    if isinstance(state.get("package_b_review"),dict):
        repaired=_package_b_review_intact(directory,state,context)
        if repaired["envelope"].get("kind")!="package_b_review_envelope_repaired": raise ControllerError("Package B review is not the bounded repaired envelope")
        return {"schema_version":SCHEMA,"operation":"repair_package_b_review_binding","phase":state["phase"],"verdict":repaired["packet"]["verdict"],"reused":True}
    retries=state.get("package_b_review_retries")
    history=state.get("package_b_review_attempt_history")
    exhausted=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else {}
    if (not isinstance(retries,list) or len(retries)!=1 or not isinstance(history,list) or len(history)!=1 or not exhausted or
            exhausted.get("consumed_at") or process_alive(exhausted.get("pid"),exhausted.get("pgid"))):
        raise ControllerError("Package B review binding repair requires one archived omission and one quiescent exhausted retry")
    source=retries[0]
    source_base={k:v for k,v in source.items() if k not in {"retry_reason","terminal_receipt_sha256","provider_session_id"}}
    _package_b_review_attempt_intact(directory,state,context,source_base)
    _package_b_review_attempt_intact(directory,state,context,exhausted)
    source_terminal,source_terminal_info=_review_terminal(directory,source,"package-b-review-attempts")
    exhausted_terminal,exhausted_terminal_info=_review_terminal(directory,exhausted,"package-b-review-attempts")
    if (source.get("retry_reason")!="exact_array_binding_omission" or source.get("terminal_receipt_sha256")!=source_terminal_info["sha256"] or
            source_terminal.get("exit_code")!=0 or source_terminal.get("timed_out") or source_terminal.get("output_limit_exceeded") or
            exhausted_terminal.get("exit_code")==0 or not (exhausted_terminal.get("timed_out") or exhausted_terminal.get("output_limit_exceeded")) or
            exhausted_terminal.get("output_sha256") is not None or os.path.lexists(exhausted.get("output_path",""))):
        raise ControllerError("Package B review binding repair terminal disposition changed")
    output=capped_regular_file_info(source.get("output_path"),os.path.join(directory,"package-b-review-attempts"),64*1024) if isinstance(source.get("output_path"),str) else None
    if not output or output.get("sha256")!=source_terminal.get("output_sha256") or output.get("bytes")!=source_terminal.get("output_bytes"):
        raise ControllerError("Package B source review output changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B source review packet is unreadable") from exc
    expected=_package_b_review_expected(state,context,source); required=set(expected)|{"verdict","findings","checks"}; scalar_keys=set(expected)-{"verification_receipt_sha256s","changed_paths"}
    arrays_well_formed=(isinstance(packet,dict) and isinstance(packet.get("verification_receipt_sha256s"),list) and len(packet["verification_receipt_sha256s"])==8 and
        all(isinstance(x,str) and len(x.encode())<=128 for x in packet["verification_receipt_sha256s"]) and isinstance(packet.get("changed_paths"),list) and
        1<=len(packet["changed_paths"])<=4 and all(isinstance(x,str) and len(x.encode())<=500 for x in packet["changed_paths"]))
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=expected[k] for k in scalar_keys) or not arrays_well_formed or
            (packet.get("verification_receipt_sha256s")==expected["verification_receipt_sha256s"] and packet.get("changed_paths")==expected["changed_paths"]) or
            packet.get("verdict")!="pass" or packet.get("findings")!=[] or not isinstance(packet.get("checks"),list) or not packet["checks"] or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package B source review is not the exact passing array-binding omission")
    source_session=_package_a_claude_session(source["stdout"],directory,source.get("reviewer_session_id",""))
    exhausted_session=_package_a_claude_session(exhausted["stdout"],directory,exhausted.get("reviewer_session_id",""))
    if source.get("provider_session_id")!=source_session or source_session==exhausted_session:
        raise ControllerError("Package B review binding repair session provenance changed")
    controller_bindings={"verification_receipt_sha256s":expected["verification_receipt_sha256s"],"changed_paths":expected["changed_paths"]}
    core={"schema_version":SCHEMA,"kind":"package_b_review_transport_repair","work_id":state["work_id"],"policy":POLICY_ID,
        "bug_class":"controller_owned_exact_array_bindings/v1","candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"source_attempt_id":source["id"],"source_run_id":source["run_id"],
        "source_provider_session_id":source_session,"source_output_path":output["path"],"source_output_sha256":output["sha256"],"source_terminal_sha256":source_terminal_info["sha256"],
        "exhausted_attempt_id":exhausted["id"],"exhausted_provider_session_id":exhausted_session,"exhausted_terminal_sha256":exhausted_terminal_info["sha256"],
        "controller_bindings_sha256":_package_a_json_sha256(controller_bindings)}
    repair_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); repair={**core,"repair_id":repair_id,"issued_at":context["candidate"].get("created_at")}
    repair_dir=os.path.join(directory,"package-b-review-repairs")
    if os.path.lexists(repair_dir) and (os.path.islink(repair_dir) or not os.path.isdir(repair_dir) or not inside(real(repair_dir),directory)):
        raise ControllerError("Package B review binding repair directory is unsafe")
    os.makedirs(repair_dir,mode=0o700,exist_ok=True)
    repair_info=_package_a_adopt_json(os.path.join(repair_dir,repair_id+".json"),repair_dir,repair,"b review binding repair")
    envelope={"schema_version":SCHEMA,"kind":"package_b_review_envelope_repaired","work_id":state["work_id"],"policy":POLICY_ID,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_B_CLAUDE_REVIEW_ACTOR,
        "run_id":source["run_id"],"review_attempt_id":source["id"],"reviewer_session_id":source_session,"terminal_receipt_sha256":source_terminal_info["sha256"],
        "model_packet_sha256":_package_a_json_sha256(packet),"model_packet":packet,"controller_bindings":controller_bindings,"repair_receipt_sha256":repair_info["sha256"]}
    packets_dir=os.path.join(directory,"packets"); os.makedirs(packets_dir,mode=0o700,exist_ok=True)
    destination=os.path.join(packets_dir,context["candidate"]["id"]+".package-b-review-repaired.json")
    envelope_info=_package_a_adopt_json(destination,packets_dir,envelope,"b repaired review envelope")
    consumed=utc(); exhausted_archived={**exhausted,"consumed_at":consumed,"provider_session_id":exhausted_session,
        "transport_repair_disposition":"review_retry_exhausted","terminal_receipt_sha256":exhausted_terminal_info["sha256"]}
    state["package_b_review_attempt_history"]=history+[exhausted_archived]
    state["package_b_review_attempt"]=exhausted_archived
    state["package_b_review_transport_repair"]={"path":repair_info["path"],"sha256":repair_info["sha256"],"repair_id":repair_id,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"source_attempt_id":source["id"],"exhausted_attempt_id":exhausted["id"]}
    state["package_b_review"]={"path":destination,"sha256":envelope_info["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_B_CLAUDE_REVIEW_ACTOR,"run_id":source["run_id"],"provider_session_id":source_session,"policy":POLICY_ID,"verdict":"pass",
        "model_packet_sha256":_package_a_json_sha256(packet),"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":source_terminal_info["sha256"]}
    append_event(directory,"package_b_review_binding_repaired",repair_id=repair_id,candidate_id=context["candidate"]["id"],source_attempt_id=source["id"],exhausted_attempt_id=exhausted["id"],verdict="pass")
    save(directory,state)
    repaired=_package_b_review_intact(directory,state,context)
    return {"schema_version":SCHEMA,"operation":"repair_package_b_review_binding","phase":state["phase"],"verdict":repaired["packet"]["verdict"],"reused":False,
        "receipt":{"path":repair_info["path"],"sha256":repair_info["sha256"]}}


def command_register_package_b_review_capacity_wakeup(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_b_review_capacity_intact(directory,state)
    bound=state["package_b_review_capacity"]
    if bound.get("mode")!="scheduled" or not isinstance(bound.get("retry_after"),str): raise ControllerError("Package B manual review capacity cannot register an agent wakeup")
    ref=args.wakeup_ref.strip()
    if not ref or len(ref.encode())>500: raise ControllerError("Package B review wakeup reference is required and bounded")
    receipt_core={"schema_version":SCHEMA,"kind":"package_b_review_capacity_wakeup","work_id":state["work_id"],"policy":POLICY_ID,
        "capacity_packet_sha256":packet_info["sha256"],"candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],
        "review_attempt_id":bound["review_attempt_id"],"retry_after":bound["retry_after"],"wakeup_ref_sha256":digest_bytes(ref.encode())}
    lease_id=digest_bytes(json.dumps(receipt_core,sort_keys=True,separators=(",",":")).encode()); receipt={**receipt_core,"lease_id":lease_id,"issued_at":packet["issued_at"]}
    root=os.path.join(directory,"package-b-review-capacity-wakeups"); os.makedirs(root,mode=0o700,exist_ok=True); path=os.path.join(root,lease_id+".json")
    info=_package_a_adopt_json(path,root,receipt,"b review capacity wakeup")
    expected={"path":info["path"],"sha256":info["sha256"],"lease_id":lease_id,"wakeup_ref":ref,"consumed_at":None}
    if bound.get("wakeup") and bound["wakeup"]!=expected: raise ControllerError("Package B review capacity has a different wakeup")
    bound["wakeup"]=expected; append_event(directory,"package_b_review_capacity_wakeup_registered",lease_id=lease_id,candidate_id=bound["candidate_id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"register_package_b_review_capacity_wakeup","phase":CAPACITY_WAITING,"lease_id":lease_id,"retry_after":bound["retry_after"],"reused":False}


def command_resume_package_b_review_capacity(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_b_review_capacity_intact(directory,state); bound=state["package_b_review_capacity"]
    if bound.get("mode")!="scheduled": raise ControllerError("Package B manual review capacity requires an authenticated outer adapter signal")
    due=_parse_utc_instant(bound.get("retry_after"))
    if due>dt.datetime.now(dt.timezone.utc): raise ControllerError("Package B review capacity retry time has not elapsed")
    wake=bound.get("wakeup") if isinstance(bound.get("wakeup"),dict) else {}
    item=capped_regular_file_info(wake.get("path"),os.path.join(directory,"package-b-review-capacity-wakeups"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(wake.get("path"),str) else None
    if not item or item.get("sha256")!=wake.get("sha256") or wake.get("consumed_at") or bound.get("consumed_at"): raise ControllerError("Package B review capacity wakeup lease is missing or consumed")
    attempt=state["package_b_review_attempt"]; archived={**attempt,"capacity_packet_sha256":packet_info["sha256"],"capacity_disposition":"scheduled_continuation"}
    history=state.get("package_b_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package B review history is malformed")
    history=history+[archived]; consumed=utc(); wake["consumed_at"]=consumed; bound["consumed_at"]=consumed
    state["package_b_review_attempt_history"]=history; state["package_b_review_capacity_history"]=[{**bound}]
    state["package_b_review_attempt"]=None; state["package_b_review_capacity"]=None; state["phase"]="awaiting_gate"
    state["gate"]={"kind":"package_b_review_capacity_released","verdict":"awaiting_review","candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],"policy":POLICY_ID}
    append_event(directory,"package_b_review_capacity_released",lease_id=wake["lease_id"],candidate_id=bound["candidate_id"],next_state="awaiting_gate"); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"resume_package_b_review_capacity","phase":"awaiting_gate","delivery":"fresh_controller_review_continuation"}


def _command_adjudicate_package_b(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state): raise ControllerError("Package B fixed gate requires its canonical identity")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    replay=_package_b_gate_replay(directory,state)
    if replay: return replay
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package B fixed gate requires its awaiting candidate")
    try:
        baseline=_package_b_prerequisites_intact(directory,state); _package_b_attempt_intact(state.get("attempt")); _package_b_candidate_intact(directory,state,candidate,baseline)
        delta=_package_b_builder_delta(directory,state,candidate); verification=_package_b_validate_verification(directory,state,candidate,baseline,delta)
        context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":[row["path"] for row in delta["files"]]}
        review=_package_b_review_intact(directory,state,context) if isinstance(state.get("package_b_review"),dict) else None
        all_passed=verification["aggregate"]["all_passed"] is True
        review_verdict=(review or {}).get("packet",{}).get("verdict")
        review_infrastructure_exhausted=False; exhausted_review_receipt=None
        active_review=state.get("package_b_review_attempt") if isinstance(state.get("package_b_review_attempt"),dict) else None
        review_retries=state.get("package_b_review_retries")
        if all_passed and review_verdict is None and active_review and isinstance(review_retries,list) and len(review_retries)==1:
            if process_alive(active_review.get("pid"),active_review.get("pgid")): raise ControllerError("Package B independent review is still running")
            _package_b_review_attempt_intact(directory,state,context,active_review)
            terminal,terminal_receipt=_review_terminal(directory,active_review,"package-b-review-attempts")
            output_exists=isinstance(active_review.get("output_path"),str) and os.path.lexists(active_review["output_path"])
            capacity_event=_package_a_claude_capacity_event(active_review["stdout"],directory,active_review.get("reviewer_session_id",""))
            review_infrastructure_exhausted=(terminal.get("exit_code")!=0 and (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and terminal.get("output_sha256") is None and not output_exists and capacity_event is None)
            if review_infrastructure_exhausted: exhausted_review_receipt=terminal_receipt
        if all_passed and review_verdict=="pass": disposition,reason="pass","all_evidence_passed"
        elif review_verdict=="fail": disposition,reason="fail","independent_review_failed"
        elif review_infrastructure_exhausted: disposition,reason="fail","review_infrastructure_exhausted"
        elif state.get("package_b_correction_used") or state.get("package_b_correction_history"):
            disposition,reason="fail","correction_exhausted"
        else: disposition,reason="revise","deterministic_or_review_dissent"
        verification_sha=verification["aggregate_info"]["sha256"]
        review_sha=review["info"]["sha256"] if review else (exhausted_review_receipt or {}).get("sha256")
    except ControllerError:
        if not isinstance(state.get("package_b_verification"),dict): raise
        disposition,reason="fail","candidate_or_evidence_invalid"; verification_sha=state["package_b_verification"].get("aggregate_sha256")
        review_sha=(state.get("package_b_review") or {}).get("sha256"); context=None
    if context is not None and all_passed and review_verdict is None and not review_infrastructure_exhausted:
        return {"schema_version":SCHEMA,"operation":"adjudicate_package_b","phase":"awaiting_gate","disposition":"awaiting_review","reused":False}
    if disposition=="revise" and context is not None:
        if state.get("package_b_correction_used") or state.get("package_b_correction_history"):
            disposition,reason="fail","correction_exhausted"
    core={"schema_version":SCHEMA,"kind":"package_b_gate_receipt","work_id":state["work_id"],"policy":POLICY_ID,
        "gate_name":PACKAGE_B_GATE_PRINCIPAL,"adjudicator_principal":PACKAGE_B_GATE_PRINCIPAL,"candidate_id":candidate.get("id"),
        "evidence_digest":candidate.get("evidence_digest"),"verification_aggregate_sha256":verification_sha,"review_sha256":review_sha,
        "correction_already_used":bool(state.get("package_b_correction_used") or state.get("package_b_correction_history")),"disposition":disposition,"reason_code":reason}
    receipt_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"receipt_id":receipt_id,"issued_at":candidate.get("created_at") or state.get("created_at")}
    gate_dir=os.path.join(directory,"package-b-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir) or not inside(real(gate_dir),directory)):
        raise ControllerError("Package B fixed gate directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    receipt_info=_package_a_adopt_json(os.path.join(gate_dir,receipt_id+".json"),gate_dir,receipt,"b fixed gate receipt")
    if disposition=="revise":
        assert context is not None
        prior_attempt=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if (prior_attempt.get("role")!="implementer" or not isinstance(prior_attempt.get("provider_session_id"),str) or
                not prior_attempt.get("provider_session_id")):
            raise ControllerError("Package B correction lacks the exact implementer session")
        history=state.get("package_b_correction_history")
        if history not in (None,[]): raise ControllerError("Package B has exhausted its one bounded correction")
        state["package_b_correction_history"]=[{"path":receipt_info["path"],"sha256":receipt_info["sha256"],
            "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest")}]
        state["recovery_constraint"]={"kind":"package_b_exact_correction","role":"implementer",
            "provider_session_id":prior_attempt["provider_session_id"],"original_attempt_id":prior_attempt.get("id"),
            "original_attempt_started_at":prior_attempt.get("started_at"),"candidate_id":candidate.get("id"),
            "evidence_digest":candidate.get("evidence_digest"),"gate_receipt_path":receipt_info["path"],
            "gate_receipt_sha256":receipt_info["sha256"],"authorized_at":utc(),"consumed_at":None,"spawn_failures":[]}
        state.pop("package_b_correction_used",None)
        state["phase"]="prepared"
    elif disposition=="pass": state["phase"]="completed"
    else: state["phase"]="failed"
    state["gate"]={"kind":"package_b_fixed_gate","gate_name":PACKAGE_B_GATE_PRINCIPAL,"verdict":disposition,"reason_code":reason,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"receipt_id":receipt_id,"receipt_sha256":receipt_info["sha256"],"policy":POLICY_ID}
    state["package_b_gate_receipt"]={"path":receipt_info["path"],"sha256":receipt_info["sha256"],"receipt_id":receipt_id,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"disposition":disposition}
    save(directory,state)
    result=_package_b_gate_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


