def _package_b_nonpass_repair_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    bound=state.get("package_b_nonpass_gate_repair")
    if bound is None: return None
    keys={"path","sha256","repair_id","candidate_id","evidence_digest","prior_gate_receipt_sha256","verification_aggregate_sha256"}
    if not isinstance(bound,dict) or set(bound)!=keys: raise ControllerError("Package B nonpass gate repair state binding is malformed")
