def _command_repair_package_b_probe_gate(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_b(state): raise ControllerError("Package B probe repair requires its canonical identity")
    replay=_package_b_probe_repair_replay(directory,state)
    if replay: return replay
    if (state.get("phase")!="awaiting_gate" or state.get("package_b_verification_generation")!=1 or
            state.get("package_b_verification_probe_version") not in {None,1} or state.get("package_b_review") is not None):
        raise ControllerError("Package B probe repair requires the exact historical generation-one candidate")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_b_prerequisites_intact(directory,state); _package_b_attempt_intact(state.get("attempt")); _package_b_candidate_intact(directory,state,candidate,baseline)
    delta=_package_b_builder_delta(directory,state,candidate); verification=_package_b_validate_verification(directory,state,candidate,baseline,delta)
    refs=verification["refs"]
    if (verification["aggregate"].get("all_passed") is not False or len(refs)!=8 or refs[-1].get("index")!=7 or refs[-1].get("label")!="json_probe" or
            refs[-1].get("passed") is not False or any(row.get("passed") is not True for row in refs[:-1])):
        raise ControllerError("Package B verification is not the exact historical probe repair case")
    verify_dir=_package_b_verification_dir(directory,candidate,state)
    failed_info=capped_regular_file_info(refs[-1].get("path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES)
    if not failed_info or failed_info.get("sha256")!=refs[-1].get("sha256"): raise ControllerError("Package B failed probe receipt changed")
    try: failed_receipt=json.loads(Path(failed_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B failed probe receipt is unreadable") from exc
    output_info=capped_regular_file_info(failed_receipt.get("output_path"),verify_dir,PACKAGE_B_MAX_GATE_OUTPUT) if isinstance(failed_receipt,dict) and isinstance(failed_receipt.get("output_path"),str) else None
    if not output_info or output_info.get("sha256")!=failed_receipt.get("output_sha256"): raise ControllerError("Package B failed probe output changed")
    try: old_probe=json.loads(Path(output_info["path"]).read_text(encoding="utf-8").strip())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package B failed probe output is unreadable") from exc
    error=old_probe.get("error") if isinstance(old_probe,dict) and set(old_probe)=={"error"} else None
    if not isinstance(error,str) or not error.startswith("cannot import name 'DispatchContract' from 'cowork_dispatch'"):
        raise ControllerError("Package B failed probe is not the historical class-API mismatch")
    current_probe={"label":"json_probe","argv":["python3","-c",_package_b_probe_code()],"timeout":30,"kind":"package_b_probe"}
    probe_result=_package_a_gate_result(current_probe,state["worktree"]["path"])
    if probe_result.get("passed") is not True or not _package_b_probe_passes(probe_result.get("output",b"")):
        raise ControllerError("Package B corrected dict-record probe is not green")
    aggregate_info=verification["aggregate_info"]
    core={"schema_version":SCHEMA,"kind":"package_b_probe_gate_repair","work_id":state["work_id"],"policy":POLICY_ID,
        "bug_class":"class_api_probe_against_dict_contract/v1","candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
        "prior_aggregate_path":aggregate_info["path"],"prior_aggregate_sha256":aggregate_info["sha256"],
        "prior_failed_receipt_path":failed_info["path"],"prior_failed_receipt_sha256":failed_info["sha256"],"verification_generation":2}
    repair_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"repair_id":repair_id,"issued_at":candidate.get("created_at")}
    repair_dir=os.path.join(directory,"package-b-gate-repairs")
    if os.path.lexists(repair_dir) and (os.path.islink(repair_dir) or not os.path.isdir(repair_dir) or not inside(real(repair_dir),directory)):
        raise ControllerError("Package B probe repair directory is unsafe")
    os.makedirs(repair_dir,mode=0o700,exist_ok=True)
    repair_info=_package_a_adopt_json(os.path.join(repair_dir,repair_id+".json"),repair_dir,receipt,"b probe gate repair")
    history=state.get("package_b_verification_history")
    if not isinstance(history,list) or len(history)!=1: raise ControllerError("Package B verification repair history is malformed")
    old_bound=state.get("package_b_verification")
    state["package_b_verification_history"]=history+[{"binding":old_bound,"aggregate_path":aggregate_info["path"],"aggregate_sha256":aggregate_info["sha256"],
        "failed_receipt_path":failed_info["path"],"failed_receipt_sha256":failed_info["sha256"],"repair_receipt_path":repair_info["path"],"repair_receipt_sha256":repair_info["sha256"]}]
    state["package_b_probe_gate_repair"]={"path":repair_info["path"],"sha256":repair_info["sha256"],"repair_id":repair_id,
        "candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"prior_aggregate_sha256":aggregate_info["sha256"],
        "prior_failed_receipt_sha256":failed_info["sha256"],"verification_generation":2}
    state["package_b_verification_generation"]=2; state["package_b_verification_probe_version"]=2
    state.pop("package_b_verification",None)
    save(directory,state)
    result=_package_b_probe_repair_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


