# ---------------------------------------------------------------------------
# Package C — pending-turn and gate-repair AttemptLink retry linkage
# ---------------------------------------------------------------------------

def _is_package_c(state: Dict[str,Any]) -> bool:
    return state.get("work_id")==PACKAGE_C_WORK_ID


def _package_c_v3_plan_intact(root: str) -> None:
    v3_dir=work_dir(root,PACKAGE_C_V3_WORK_ID); v3=load(v3_dir)
    vc=v3.get("candidate") if isinstance(v3.get("candidate"),dict) else {}
    review=v3.get("plan_review") if isinstance(v3.get("plan_review"),dict) else {}
    review_file=file_info(review.get("path"),os.path.join(v3_dir,"packets")) if isinstance(review.get("path"),str) else None
    if (v3.get("phase")!="completed" or (v3.get("gate") or {}).get("verdict")!="pass" or
            (v3.get("gate") or {}).get("adjudicator_principal")!=PACKAGE_C_V3_ADJUDICATOR or
            vc.get("id")!=PACKAGE_C_V3_CANDIDATE_ID or vc.get("evidence_digest")!=PACKAGE_C_V3_EVIDENCE_DIGEST or
            not candidate_intact(vc,v3_dir,v3["worktree"]["path"]) or not review_file or
            review_file.get("sha256")!=PACKAGE_C_V3_REVIEW_SHA256 or review.get("sha256")!=PACKAGE_C_V3_REVIEW_SHA256 or
            review.get("verdict")!="pass" or review.get("candidate_id")!=vc.get("id") or
            review.get("plan_sha256")!=PACKAGE_C_V3_PLAN_SHA256):
        raise ControllerError("Package C frozen v3 plan authority is not intact")


def _package_c_prereq_source_intact(root: str) -> Dict[str,Any]:
    """Validate the completed Package B state and return its worktree path."""
    b_dir=work_dir(root,PACKAGE_C_PREREQ_WORK_ID); b_state=load(b_dir)
    if b_state.get("phase")!="completed" or b_state.get("work_id")!=PACKAGE_C_PREREQ_WORK_ID:
        raise ControllerError("Package C prerequisite Package B must be in completed phase with exact identity")
    candidate=b_state.get("candidate") if isinstance(b_state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_PREREQ_CANDIDATE_ID or candidate.get("evidence_digest")!=PACKAGE_C_PREREQ_EVIDENCE_DIGEST:
        raise ControllerError("Package C prerequisite Package B candidate identity changed")
    baseline=b_state.get("package_b_prerequisites") if isinstance(b_state.get("package_b_prerequisites"),dict) else {}
    if baseline.get("sha256")!=PACKAGE_C_PREREQ_BASELINE_RECEIPT_SHA256:
        raise ControllerError("Package C prerequisite Package B baseline receipt changed")
    delta=b_state.get("package_b_builder_delta") if isinstance(b_state.get("package_b_builder_delta"),dict) else {}
    if delta.get("sha256")!=PACKAGE_C_PREREQ_DELTA_SHA256:
        raise ControllerError("Package C prerequisite Package B builder-delta receipt changed")
    collect=b_state.get("package_b_collect") if isinstance(b_state.get("package_b_collect"),dict) else {}
    if collect.get("result_sha256")!=PACKAGE_C_PREREQ_RESULT_SHA256:
        raise ControllerError("Package C prerequisite Package B collected result changed")
    verification=b_state.get("package_b_verification") if isinstance(b_state.get("package_b_verification"),dict) else {}
    if verification.get("aggregate_sha256")!=PACKAGE_C_PREREQ_VERIFICATION_SHA256:
        raise ControllerError("Package C prerequisite Package B verification aggregate changed")
    review=b_state.get("package_b_review") if isinstance(b_state.get("package_b_review"),dict) else {}
    if review.get("sha256")!=PACKAGE_C_PREREQ_REVIEW_SHA256:
        raise ControllerError("Package C prerequisite Package B independent review changed")
    gate=b_state.get("package_b_gate_receipt") if isinstance(b_state.get("package_b_gate_receipt"),dict) else {}
    if gate.get("sha256")!=PACKAGE_C_PREREQ_GATE_SHA256 or gate.get("disposition")!="pass":
        raise ControllerError("Package C prerequisite Package B fixed gate receipt changed")
    wt=b_state.get("worktree",{}).get("path","")
    if not wt or not os.path.isdir(wt): raise ControllerError("Package C prerequisite Package B worktree is missing")
    for rel,sha in PACKAGE_C_SOURCE_FILES.items():
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=sha: raise ControllerError("Package C prerequisite source file changed: "+rel)
    return {"source_wt":wt,"b_dir":b_dir}


def _package_c_prerequisites_intact(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_c_prerequisites") if isinstance(state.get("package_c_prerequisites"),dict) else {}
    if set(bound)!={"path","sha256","fingerprint_digest","intent_path","intent_sha256"}:
        raise ControllerError("Package C prerequisite state binding is malformed")
    prereq_dir=os.path.join(directory,"package-c-prerequisites")
    path=bound.get("path"); info=capped_regular_file_info(path,prereq_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(path,str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C prerequisite baseline receipt is missing or changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C prerequisite baseline receipt is unreadable") from exc
    if (receipt.get("kind")!="package_c_prerequisite_baseline" or receipt.get("work_id")!=PACKAGE_C_WORK_ID or
            receipt.get("base_head")!=PACKAGE_C_BASE_HEAD or receipt.get("prereq_work_id")!=PACKAGE_C_PREREQ_WORK_ID):
        raise ControllerError("Package C prerequisite baseline identity changed")
    fp=receipt.get("post_materialization_fingerprint") if isinstance(receipt.get("post_materialization_fingerprint"),dict) else {}
    if fp.get("digest")!=bound.get("fingerprint_digest"): raise ControllerError("Package C prerequisite fingerprint changed")
    wt=state.get("worktree",{}).get("path","")
    for rel,sha in PACKAGE_C_SOURCE_FILES.items():
        item=capped_regular_file_info(os.path.join(wt,rel),wt,MAX_CANDIDATE_PATH_BYTES)
        if not item or item.get("sha256")!=sha:
            if not (state.get("attempt") and rel in PACKAGE_C_ALLOWED_BUILDER_PATHS):
                raise ControllerError("Package C immutable prerequisite file changed: "+rel)
    return receipt


def _command_materialize_package_c_prerequisites(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); wt=state["worktree"]["path"]
    if not _is_package_c(state) or state.get("phase")!="prepared" or state.get("attempt"):
        raise ControllerError("Package C materialization requires fresh prepared state with exact identity")
    require_frozen_brief(state,directory)
    if state["brief"]["sha256"]!=PACKAGE_C_BRIEF_SHA256: raise ControllerError("Package C brief SHA-256 changed")
    if state["repo"]["head"]!=PACKAGE_C_BASE_HEAD or git(wt,["rev-parse","HEAD"]).strip()!=PACKAGE_C_BASE_HEAD:
        raise ControllerError("Package C base HEAD changed")
    if not registered_worktree(state["repo"]["root"],wt,state["worktree"]["branch"]):
        raise ControllerError("Package C worktree registration is invalid")
    root=os.path.dirname(directory); _package_c_v3_plan_intact(root)
    if state.get("package_c_prerequisites"):
        receipt=_package_c_prerequisites_intact(directory,state)
        if not any(x.get("kind")=="package_c_prerequisites_materialized" and x.get("receipt_sha256")==state["package_c_prerequisites"]["sha256"] for x in recent_events(directory)):
            append_event(directory,"package_c_prerequisites_materialized",receipt_sha256=state["package_c_prerequisites"]["sha256"],fingerprint_digest=state["package_c_prerequisites"]["fingerprint_digest"])
        return {"schema_version":SCHEMA,"operation":"materialize_package_c_prerequisites","reused":True,"receipt":state["package_c_prerequisites"],"fingerprint":receipt["post_materialization_fingerprint"]}
    source=_package_c_prereq_source_intact(root); source_wt=source["source_wt"]
    prereq=os.path.join(directory,"package-c-prerequisites")
    if os.path.lexists(prereq) and (os.path.islink(prereq) or not os.path.isdir(prereq)): raise ControllerError("Package C prerequisite directory is unsafe")
    os.makedirs(prereq,mode=0o700,exist_ok=True)
    intent_path=os.path.join(prereq,"materialization-intent.json"); receipt_path=os.path.join(prereq,"baseline.json")
    pre_status=set(git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines())
    if pre_status:
        recoverable={"?? "+rel for rel in PACKAGE_C_SOURCE_FILES if rel not in PACKAGE_C_BASE_FILE_HASHES}
        recoverable|={" M "+rel for rel in PACKAGE_C_BASE_FILE_HASHES}
        if not os.path.lexists(intent_path) or not pre_status.issubset(recoverable):
            raise ControllerError("Package C worktree must be clean before materialization or match its exact durable intent")
    rows=[{"path":rel,"sha256":sha,"source_path":os.path.join(source_wt,rel)} for rel,sha in PACKAGE_C_SOURCE_FILES.items()]
    intent={"schema_version":SCHEMA,"kind":"package_c_materialization_intent","work_id":PACKAGE_C_WORK_ID,"base_head":PACKAGE_C_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"planned_receipt":receipt_path,"files":[{k:v for k,v in row.items() if k!="source_path"} for row in rows]}
    prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not prior: raise ControllerError("Package C materialization intent is unsafe")
    prior_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(receipt_path) else None
    if os.path.lexists(receipt_path) and not prior_receipt: raise ControllerError("Package C baseline receipt is unsafe")
    if prior:
        try: prior_value=json.loads(Path(prior["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C materialization intent is unreadable") from exc
        if prior_value!=intent: raise ControllerError("Package C materialization intent conflicts with recovery")
    else: atomic_json(intent_path,intent); prior=capped_regular_file_info(intent_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    for index,row in enumerate(rows):
        dest=os.path.join(wt,row["path"])
        if os.path.islink(dest): raise ControllerError("Package C destination symlink is unsafe")
        existing=capped_regular_file_info(dest,wt,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(dest) else None
        if existing and existing.get("sha256")==row["sha256"]: continue
        base_sha=PACKAGE_C_BASE_FILE_HASHES.get(row["path"])
        if os.path.lexists(dest) and (not existing or existing.get("sha256")!=base_sha):
            raise ControllerError("Package C destination conflicts with existing file")
        os.makedirs(os.path.dirname(dest),exist_ok=True)
        tmp=os.path.join(prereq,"copy-%d.tmp"%index)
        try:
            temp_info=capped_regular_file_info(tmp,prereq,MAX_CANDIDATE_PATH_BYTES) if os.path.lexists(tmp) else None
            if os.path.lexists(tmp) and not temp_info: raise ControllerError("Package C transaction temp is unsafe")
            if not temp_info or temp_info.get("sha256")!=row["sha256"]:
                flags=os.O_WRONLY|os.O_CREAT|(os.O_TRUNC if temp_info else os.O_EXCL)
                fd=os.open(tmp,flags,0o600)
                with os.fdopen(fd,"wb") as out,open(row["source_path"],"rb") as src: shutil.copyfileobj(src,out); out.flush(); os.fsync(out.fileno())
            if digest_bytes(Path(tmp).read_bytes())!=row["sha256"]: raise ControllerError("Package C prerequisite copy hash mismatch")
            os.replace(tmp,dest)
            dir_fd=os.open(os.path.dirname(dest),os.O_RDONLY)
            try: os.fsync(dir_fd)
            finally: os.close(dir_fd)
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    fp=worktree_fingerprint(wt)
    receipt={"schema_version":SCHEMA,"kind":"package_c_prerequisite_baseline","work_id":PACKAGE_C_WORK_ID,"base_head":PACKAGE_C_BASE_HEAD,"worktree":wt,"branch":state["worktree"]["branch"],"intent_sha256":prior["sha256"],"prereq_work_id":PACKAGE_C_PREREQ_WORK_ID,"prereq_candidate_id":PACKAGE_C_PREREQ_CANDIDATE_ID,"prereq_evidence_digest":PACKAGE_C_PREREQ_EVIDENCE_DIGEST,"prereq_gate_sha256":PACKAGE_C_PREREQ_GATE_SHA256,"files":[{k:v for k,v in row.items() if k!="source_path"} for row in rows],"post_materialization_fingerprint":fp,"created_at":utc()}
    reused=bool(prior_receipt)
    if prior_receipt:
        try: old=json.loads(Path(prior_receipt["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C orphan baseline receipt is unreadable") from exc
        receipt["created_at"]=old.get("created_at")
        if old!=receipt: raise ControllerError("Package C orphan baseline receipt conflicts with recovery")
    else: atomic_json(receipt_path,receipt); prior_receipt=capped_regular_file_info(receipt_path,prereq,MAX_PLAN_ARTIFACT_BYTES)
    state["package_c_prerequisites"]={"path":receipt_path,"sha256":prior_receipt["sha256"],"fingerprint_digest":fp["digest"],"intent_path":intent_path,"intent_sha256":prior["sha256"]}
    if not any(x.get("kind")=="package_c_prerequisites_materialized" and x.get("receipt_sha256")==prior_receipt["sha256"] for x in recent_events(directory)):
        append_event(directory,"package_c_prerequisites_materialized",receipt_sha256=prior_receipt["sha256"],fingerprint_digest=fp["digest"])
    save(directory,state)
    return {"schema_version":SCHEMA,"operation":"materialize_package_c_prerequisites","reused":reused,"receipt":state["package_c_prerequisites"],"fingerprint":fp}


def command_materialize_package_c_prerequisites(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_materialize_package_c_prerequisites(args)


def _package_c_attempt_intact(attempt: Dict[str,Any]) -> None:
    expected={"role":"implementer","backend":"claude_direct","provider":"claude","controller":"claude","model":"sonnet","effort":"medium","policy":POLICY_ID}
    if not isinstance(attempt,dict) or any(attempt.get(key)!=value for key,value in expected.items()) or not _safe_identifier(attempt.get("id"),"Package C attempt id") or not _safe_identifier(attempt.get("provider_session_id"),"Package C provider session id"):
        raise ControllerError("Package C implementer attempt identity changed")


def _package_c_candidate_intact(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> None:
    candidate_keys={"schema_version","id","evidence_digest","evidence","packet_verified","created_at"}
    evidence_keys={"packet_sha256","packet_path","evidence_kind","changed_paths","declared_artifacts","worktree_fingerprint","package_c_baseline_receipt_sha256","package_c_baseline_fingerprint_digest"}
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    created=candidate.get("created_at")
    digest=digest_bytes(json.dumps(evidence,sort_keys=True,separators=(",",":")).encode())
    current_status=git(state["worktree"]["path"],["status","--porcelain=v1","--untracked-files=all"]).splitlines()
    current_fingerprint=worktree_fingerprint(state["worktree"]["path"])
    if (not isinstance(candidate,dict) or set(candidate)!=candidate_keys or candidate.get("schema_version")!=SCHEMA or candidate.get("packet_verified") is not True or
            not isinstance(created,str) or created!=(state.get("attempt") or {}).get("started_at") or len(created.encode())>64 or set(evidence)!=evidence_keys or evidence.get("evidence_kind")!="worker_packet" or
            evidence.get("package_c_baseline_receipt_sha256")!=state["package_c_prerequisites"]["sha256"] or
            evidence.get("package_c_baseline_fingerprint_digest")!=baseline["post_materialization_fingerprint"]["digest"] or
            evidence.get("changed_paths")!=current_status or evidence.get("worktree_fingerprint")!=current_fingerprint or candidate.get("evidence_digest")!=digest or candidate.get("id")!="package-c-"+digest[:32] or
            not candidate_intact(candidate,directory,state["worktree"]["path"])):
        raise ControllerError("Package C candidate deterministic evidence binding changed")


def _package_c_builder_delta(directory: str,state: Dict[str,Any],candidate: Dict[str,Any]) -> Dict[str,Any]:
    baseline=_package_c_prerequisites_intact(directory,state); wt=state["worktree"]["path"]
    status=git(wt,["status","--porcelain=v1","--untracked-files=all"]).splitlines(); paths=[x[3:] for x in status if len(x)>=4]
    fixture_item=capped_regular_file_info(os.path.join(wt,PACKAGE_C_FIXTURE_PATH),wt,MAX_CANDIDATE_PATH_BYTES)
    if not fixture_item or fixture_item["sha256"]!=PACKAGE_C_FIXTURE_SHA256: raise ControllerError("Package C fixture is immutable and must not change")
    delta=[]
    for rel in sorted(PACKAGE_C_ALLOWED_BUILDER_PATHS):
        dest=os.path.join(wt,rel)
        if os.path.lexists(dest):
            item=capped_regular_file_info(dest,wt,MAX_CANDIDATE_PATH_BYTES)
            if not item: raise ControllerError("Package C builder delta path is not a safe regular file")
            baseline_sha=PACKAGE_C_SOURCE_FILES.get(rel); changed=item["sha256"]!=baseline_sha
            if changed: delta.append({"path":rel,"sha256":item["sha256"],"baseline_sha256":baseline_sha})
    for rel in paths:
        if rel not in PACKAGE_C_ALLOWED_BUILDER_PATHS and rel!=PACKAGE_C_FIXTURE_PATH:
            raise ControllerError("Package C builder delta escaped baseline allowlist: "+rel)
    value={"candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"baseline_receipt_sha256":state["package_c_prerequisites"]["sha256"],"files":delta}
    value["sha256"]=digest_bytes(json.dumps(value,sort_keys=True,separators=(",",":")).encode())
    bound=state.get("package_c_builder_delta") if isinstance(state.get("package_c_builder_delta"),dict) else {}
    if bound:
        if (set(bound)!={"path","sha256","candidate_id","evidence_digest","delta_sha256"} or
                bound.get("candidate_id")!=candidate.get("id") or bound.get("evidence_digest")!=candidate.get("evidence_digest") or
                bound.get("delta_sha256")!=value["sha256"]):
            raise ControllerError("Package C builder delta state binding is malformed")
        item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-c-delta"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
        if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C builder delta receipt changed")
    return value


def _package_c_claimed_delta(packet: Dict[str,Any]) -> List[str]:
    normalized=[]
    for item in (packet.get("structured") or {}).get("changed_paths",[]):
        if not isinstance(item,str): raise ControllerError("Package C worker changed_paths is malformed")
        rel=item[3:] if item.startswith(("?? "," M ")) else item
        if (not rel or os.path.isabs(rel) or "\\" in rel or os.path.normpath(rel)!=rel or rel.startswith("../") or "/../" in rel):
            raise ControllerError("Package C worker changed_paths contains an unsafe alias")
        normalized.append(rel)
    if len(normalized)!=len(set(normalized)): raise ControllerError("Package C worker changed_paths contains duplicates after normalization")
    return normalized


def _normalize_package_c_structured(value: Any) -> Optional[Dict[str,Any]]:
    if not isinstance(value,dict): return None
    required={"outcome","summary","changed_paths","checks","findings","assumptions","next_action",
              "pending_map","repair_map","migrated_tests","retired_witnesses","remaining_expected_failures","negative_controls"}
    if set(value)!=required: return None
    if (value.get("outcome") not in {"completed","blocked","needs_authority","failed"} or
            not isinstance(value.get("summary"),str) or len(value.get("summary","").encode())>2000 or
            not isinstance(value.get("changed_paths"),list) or len(value["changed_paths"])>50 or
            value.get("migrated_tests")!=list(PACKAGE_C_CONTRACT_TESTS) or
            value.get("retired_witnesses")!=list(PACKAGE_C_RETIRED_WITNESSES) or
            value.get("remaining_expected_failures")!=0): return None
    pending=value.get("pending_map"); repair=value.get("repair_map")
    if not isinstance(pending,dict) or set(pending)!=set(_PACKAGE_C_PENDING_MAPPING_SCHEMA["properties"]): return None
    if (pending.get("save_creates_no_attempt") is not True or pending.get("source_precedence")!=["event","session","fingerprint"] or
            pending.get("legacy_normalization")!="legacy" or pending.get("switch_carry") is not True or pending.get("clear_consume") is not True or
            pending.get("mismatch_fail_closed") is not True or pending.get("duplicate_replay_idempotent") is not True or pending.get("replay_link_kind")!="pending_replay"):
        return None
    tests=pending.get("test_ids")
    if not isinstance(tests,list) or not tests or len(tests)>12 or any(not isinstance(t,str) or not t for t in tests) or len(tests)!=len(set(tests)): return None
    if not isinstance(repair,dict) or set(repair)!=set(_PACKAGE_C_REPAIR_MAPPING_SCHEMA["properties"]): return None
    if (repair.get("distinct_identity_per_delivery") is not True or repair.get("repaired_source_linkage") is not True or
            repair.get("idempotency_key_includes_ordinal") is not True or repair.get("unchanged_prompt_bytes") is not True or
            repair.get("unchanged_cap_behavior") is not True or repair.get("link_kind")!="gate_repair"):
        return None
    rtests=repair.get("test_ids")
    if not isinstance(rtests,list) or not rtests or len(rtests)>12 or any(not isinstance(t,str) or not t for t in rtests) or len(rtests)!=len(set(rtests)): return None
    controls=value.get("negative_controls")
    if not isinstance(controls,list) or not controls or len(controls)>40: return None
    for row in controls:
        if not isinstance(row,dict) or set(row)!={"control","test","status"} or row.get("status") not in {"covered","not_covered"}: return None
    return value


def _package_c_collect_result(state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],candidate: Dict[str,Any],
                               changed: List[str],artifacts: List[Dict[str,Any]],delta: Dict[str,Any],delta_path: str,
                               delta_receipt_sha256: str,baseline_info: Dict[str,Any],phase_before_collect: str) -> Dict[str,Any]:
    return {"schema_version":SCHEMA,"work_id":state["work_id"],"operation":"collect",
            "gate":{"phase":"awaiting_gate","kind":"evidence_bound_candidate","candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"packet_verified":True},
            "phase_before_collect":phase_before_collect,"attempt":{k:attempt.get(k) for k in ("id","role","provider_session_id","pid")},
            "worktree":state["worktree"]["path"],"changed_paths":changed[:MAX_PATHS],"changed_paths_truncated":len(changed)>MAX_PATHS,
            "receipts":[baseline_info],"artifacts":artifacts,
            "worker_packet":{"path":packet["path"],"sha256":packet["sha256"],"outcome":packet["structured"]["outcome"],"summary":packet["structured"]["summary"],"next_action":packet["structured"]["next_action"]},
            "limitations":["provider output is not proof of correctness","no watcher or lease/fencing protocol is implemented","detached provider exit code is not collected","bootstrap authority principal identity is asserted by the caller, not cryptographically authenticated","publishing remains unavailable in this bootstrap controller even when publish_external is requested"],
            "package_c_builder_delta":{**delta,"receipt_path":delta_path,"receipt_sha256":delta_receipt_sha256}}


def _package_c_collect_verified(directory: str,state: Dict[str,Any],attempt: Dict[str,Any],packet: Dict[str,Any],
                                 changed: List[str],receipts: List[Dict[str,Any]],artifacts: List[Dict[str,Any]]) -> Dict[str,Any]:
    _package_c_attempt_intact(attempt)
    wt=state["worktree"]["path"]; baseline=_package_c_prerequisites_intact(directory,state)
    structured=_normalize_package_c_structured(packet.get("structured")) if packet else None
    if not structured or structured.get("outcome")!="completed": raise ControllerError("Package C worker packet outcome must be completed")
    candidate=candidate_record(packet,changed,artifacts,wt)
    candidate["evidence"]["package_c_baseline_receipt_sha256"]=state["package_c_prerequisites"]["sha256"]
    candidate["evidence"]["package_c_baseline_fingerprint_digest"]=baseline["post_materialization_fingerprint"]["digest"]
    candidate["evidence_digest"]=digest_bytes(json.dumps(candidate["evidence"],sort_keys=True,separators=(",",":")).encode())
    candidate["id"]="package-c-"+candidate["evidence_digest"][:32]
    candidate["created_at"]=attempt.get("started_at")
    _package_c_candidate_intact(directory,state,candidate,baseline)
    delta=_package_c_builder_delta(directory,state,candidate)
    claimed=_package_c_claimed_delta(packet)
    expected=[x["path"] for x in delta["files"]]
    if claimed!=expected: raise ControllerError("Package C worker changed_paths does not match derived builder delta")
    delta_dir=os.path.join(directory,"package-c-delta"); collect_dir=os.path.join(directory,"package-c-collect")
    for path,label in ((delta_dir,"delta directory"),(collect_dir,"collect directory")):
        if os.path.lexists(path) and (os.path.islink(path) or not os.path.isdir(path)): raise ControllerError("Package C %s is unsafe"%label)
        os.makedirs(path,mode=0o700,exist_ok=True)
    result_dir=os.path.join(directory,"package-c-results")
    if os.path.lexists(result_dir) and (os.path.islink(result_dir) or not os.path.isdir(result_dir)):
        raise ControllerError("Package C result directory is unsafe")
    os.makedirs(result_dir,mode=0o700,exist_ok=True)
    delta_path=os.path.join(delta_dir,candidate["id"]+".json"); result_path=os.path.join(result_dir,candidate["id"]+".json")
    intent_path=os.path.join(collect_dir,str(attempt.get("id"))+".intent.json")
    delta_sha=_package_a_json_sha256(delta)
    baseline_bound=state["package_c_prerequisites"]
    baseline_info=capped_regular_file_info(baseline_bound["path"],os.path.join(directory,"package-c-prerequisites"),MAX_PLAN_ARTIFACT_BYTES)
    if not baseline_info or baseline_info.get("sha256")!=baseline_bound["sha256"]: raise ControllerError("Package C baseline receipt changed during collection")
    phase_before_collect=state["phase"]
    result=_package_c_collect_result(state,attempt,packet,candidate,changed,artifacts,delta,delta_path,delta_sha,baseline_info,phase_before_collect)
    result_sha=_package_a_json_sha256(result)
    intent={"schema_version":SCHEMA,"kind":"package_c_collect_intent","work_id":state["work_id"],"attempt_id":attempt.get("id"),
            "provider_packet_path":packet["path"],"provider_packet_sha256":packet["sha256"],"baseline_receipt_sha256":state["package_c_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],"phase_before_collect":phase_before_collect,"candidate":candidate,
            "delta_path":delta_path,"delta_receipt_sha256":delta_sha,"delta_sha256":delta["sha256"],
            "result_path":result_path,"result_sha256":result_sha}
    if not os.path.lexists(intent_path) and (os.path.lexists(delta_path) or os.path.lexists(result_path)):
        raise ControllerError("Package C collect output cannot precede its durable intent")
    intent_info=_package_a_adopt_json(intent_path,collect_dir,intent,"collect intent")
    delta_info=_package_a_adopt_json(delta_path,delta_dir,delta,"builder delta receipt")
    if delta_info["sha256"]!=delta_sha: raise ControllerError("Package C builder delta receipt hash changed")
    result_info=_package_a_adopt_json(result_path,directory,result,"collect result")
    if result_info["sha256"]!=result_sha: raise ControllerError("Package C collect result hash changed")
    state["candidate"]=candidate; state["escalation"]=None; state["phase"]="awaiting_gate"
    state["package_c_builder_delta"]={"path":delta_path,"sha256":delta_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],"delta_sha256":delta["sha256"]}
    state["package_c_collect"]={"intent_path":intent_path,"intent_sha256":intent_info["sha256"],"result_path":result_path,"result_sha256":result_info["sha256"],"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"]}
    if not any(row.get("kind")=="candidate_collected" and row.get("candidate_id")==candidate["id"] for row in recent_events(directory)):
        append_event(directory,"candidate_collected",attempt_id=attempt.get("id"),candidate_id=candidate["id"],evidence_digest=candidate["evidence_digest"],packet_verified=True)
    save(directory,state)
    return result


def _package_c_replay_collect(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_c_collect") if isinstance(state.get("package_c_collect"),dict) else {}
    keys={"intent_path","intent_sha256","result_path","result_sha256","candidate_id","evidence_digest"}
    if set(bound)!=keys: raise ControllerError("Package C collected state binding is malformed")
    collect_dir=os.path.join(directory,"package-c-collect")
    intent_info=capped_regular_file_info(bound["intent_path"],collect_dir,MAX_PLAN_ARTIFACT_BYTES)
    result_info=capped_regular_file_info(bound["result_path"],directory,MAX_PLAN_ARTIFACT_BYTES)
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not result_info or result_info.get("sha256")!=bound.get("result_sha256"):
        raise ControllerError("Package C collected intent or result binding changed")
    try: result=json.loads(Path(result_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C collected result is unreadable") from exc
    return result


def _package_c_probe_code() -> str:
    return ("import json,sys,hashlib\n"
            "try:\n"
            "    sys.path.insert(0,'scripts')\n"
            "    from cowork_dispatch import validate_attempt_link, build_attempt_link_idempotency_key\n"
            "    _AID1='00000000-0000-0000-0000-000000000001'\n"
            "    _AID2='00000000-0000-0000-0000-000000000002'\n"
            "    _TS=1786701600.0\n"
            "    _SRC1=hashlib.sha256(b'pending-source-ref').hexdigest()\n"
            "    _SRC2=hashlib.sha256(b'pending-delivery-ref').hexdigest()\n"
            "    _SRC3=hashlib.sha256(b'repair-source-ref').hexdigest()\n"
            "    _SRC4=hashlib.sha256(b'repair-delivery-ref').hexdigest()\n"
            "    _SOURCE1={'kind':'trace_event','event_id':'evt-1','event_name':'pending_saved','session_id':None,'prompt_sha256':_SRC1,'created':_TS-2}\n"
            "    _SOURCE2={'kind':'trace_event','event_id':'evt-2','event_name':'gate_failed','session_id':None,'prompt_sha256':_SRC3,'created':_TS-1}\n"
            "    _DELIVERY1={'prompt_kind':'pending_turn','prompt_sha256':_SRC2,'prompt_bytes':20}\n"
            "    _DELIVERY2={'prompt_kind':'gate_repair','prompt_sha256':_SRC4,'prompt_bytes':18}\n"
            "    _KEY1=build_attempt_link_idempotency_key('implementer','pending_replay',_SOURCE1,0)\n"
            "    _KEY2=build_attempt_link_idempotency_key('implementer','gate_repair',_SOURCE2,1)\n"
            "    pending={'schema_version':1,'record':'AttemptLink','attempt_id':_AID1,\n"
            "        'role':'implementer','phase':'pending','kind':'pending_replay',\n"
            "        'source_ref':_SOURCE1,'delivery_ref':_DELIVERY1,\n"
            "        'idempotency_key':_KEY1,'created':_TS}\n"
            "    repair={'schema_version':1,'record':'AttemptLink','attempt_id':_AID2,\n"
            "        'role':'implementer','phase':'gate_repair','kind':'gate_repair',\n"
            "        'source_ref':_SOURCE2,'delivery_ref':_DELIVERY2,\n"
            "        'idempotency_key':_KEY2,'created':_TS}\n"
            "    pending=validate_attempt_link(pending); repair=validate_attempt_link(repair)\n"
            "    payload=[pending,repair]\n"
            "    round_trip=json.loads(json.dumps(payload,sort_keys=True))==payload\n"
            "    fabricated_rejected=False\n"
            "    try:\n"
            "        validate_attempt_link({'schema_version':1,'record':'AttemptLink','attempt_id':'not-a-uuid',\n"
            "            'role':'implementer','phase':'pending','kind':'pending_replay',\n"
            "            'source_ref':_SOURCE1,'delivery_ref':_DELIVERY1,\n"
            "            'idempotency_key':'x','created':_TS})\n"
            "    except Exception: fabricated_rejected=True\n"
            "    mismatch_rejected=False\n"
            "    try:\n"
            "        mismatched=dict(pending); mismatched['idempotency_key']=pending['idempotency_key'].replace('evt-1','evt-x')\n"
            "        validate_attempt_link(mismatched)\n"
            "    except Exception: mismatch_rejected=True\n"
            "    result={'pending_ok':pending['kind']=='pending_replay','repair_ok':repair['kind']=='gate_repair',\n"
            "            'round_trip':round_trip,'fabricated_rejected':fabricated_rejected,\n"
            "            'mismatch_rejected':mismatch_rejected,'records':2}\n"
            "    print(json.dumps(result))\n"
            "except Exception as e:\n"
            "    print(json.dumps({'error':str(e)}))\n")


def _package_c_probe_passes(raw: bytes) -> bool:
    try: probe=json.loads(raw.decode("utf-8").strip())
    except (UnicodeDecodeError,json.JSONDecodeError): return False
    return bool(probe.get("pending_ok") and probe.get("repair_ok") and probe.get("round_trip") and probe.get("fabricated_rejected") and probe.get("mismatch_rejected") and probe.get("records")==2)


def _package_c_verification_static(state: Dict[str,Any],candidate: Dict[str,Any],delta: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    return {"work_id":state["work_id"],"package_id":PACKAGE_C_PACKAGE_ID,"candidate_id":candidate["id"],"evidence_digest":candidate["evidence_digest"],
            "policy":POLICY_ID,"baseline_receipt_sha256":state["package_c_prerequisites"]["sha256"],
            "baseline_fingerprint_digest":baseline["post_materialization_fingerprint"]["digest"],
            "delta_receipt_sha256":state.get("package_c_builder_delta",{}).get("sha256"),"delta_sha256":delta["sha256"],
            "candidate_fingerprint_digest":candidate["evidence"]["worktree_fingerprint"]["digest"],
            "env_policy_digest":PACKAGE_C_ENV_POLICY_DIGEST}


def _package_c_verification_specs() -> List[Dict[str,Any]]:
    focused_contract_argv=["python3","-m","unittest"]+list(PACKAGE_C_CONTRACT_TESTS)
    focused_pending_argv=["python3","-m","unittest"]+list(PACKAGE_C_FOCUSED_PENDING_TESTS)
    focused_repair_argv=["python3","-m","unittest"]+list(PACKAGE_C_FOCUSED_REPAIR_TESTS)
    return [
        {"label":"test_cowork","argv":["python3","-m","unittest","scripts/test_cowork.py"],"timeout":PACKAGE_C_TEST_TIMEOUT,"kind":"unittest"},
        {"label":"characterization","argv":["python3","-m","unittest","scripts/test_dispatch_contract_characterization.py"],"timeout":180,"kind":"characterization_c"},
        {"label":"contract_migration_focused","argv":focused_contract_argv,"timeout":60,"kind":"focused_unittest"},
        {"label":"pending_linkage_focused","argv":focused_pending_argv,"timeout":90,"kind":"focused_unittest"},
        {"label":"gate_repair_focused","argv":focused_repair_argv,"timeout":90,"kind":"focused_unittest"},
        {"label":"structural_migration","argv":["controller","package-c-structural"],"timeout":0,"kind":"package_c_structural"},
        {"label":"scope_delta","argv":["controller","package-c-delta"],"timeout":0,"kind":"controller"},
        {"label":"diff_check","argv":["git","diff","--check"],"timeout":60,"kind":"empty"},
        {"label":"json_probe","argv":["python3","-c",_package_c_probe_code()],"timeout":30,"kind":"package_c_probe"},
    ]


def _package_c_verification_dir(directory: str,candidate: Dict[str,Any]) -> str:
    return os.path.join(directory,"package-c-verification",candidate["id"])


def _package_c_v2_verification_dir(directory: str,candidate: Dict[str,Any]) -> str:
    return os.path.join(directory,"package-c-verification-v2",candidate["id"])


def _package_c_v3_verification_dir(directory: str,candidate: Dict[str,Any]) -> str:
    return os.path.join(directory,"package-c-verification-v3",candidate["id"])


def _package_c_v4_verification_dir(directory: str,candidate: Dict[str,Any]) -> str:
    return os.path.join(directory,"package-c-verification-v4",candidate["id"])


def _package_c_rescue_dir(directory: str) -> str:
    return os.path.join(directory,"package-c-rescue")


def _package_c_tty_rescue_dir(directory: str) -> str:
    return os.path.join(directory,"package-c-tty-rescue")


def _package_c_probe_rescue_dir(directory: str) -> str:
    return os.path.join(directory,"package-c-probe-rescue")


def _package_c_effective_verify_dir(directory: str,candidate: Dict[str,Any],state: Dict[str,Any]) -> str:
    if state.get("package_c_probe_rescue_receipt"):
        return _package_c_v4_verification_dir(directory,candidate)
    if state.get("package_c_tty_rescue_receipt"):
        return _package_c_v3_verification_dir(directory,candidate)
    if state.get("package_c_rescue_receipt"):
        return _package_c_v2_verification_dir(directory,candidate)
    return _package_c_verification_dir(directory,candidate)


def _package_c_validate_verification(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any],delta: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_c_verification") if isinstance(state.get("package_c_verification"),dict) else {}
    if set(bound)!={"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"}: raise ControllerError("Package C verification state binding is malformed")
    verify_dir=_package_c_effective_verify_dir(directory,candidate,state)
    intent_info=capped_regular_file_info(bound.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("intent_path"),str) else None
    aggregate_info=capped_regular_file_info(bound.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("aggregate_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=bound.get("intent_sha256") or not aggregate_info or aggregate_info.get("sha256")!=bound.get("aggregate_sha256"): raise ControllerError("Package C verification intent or aggregate changed")
    try: intent=json.loads(Path(intent_info["path"]).read_text()); aggregate=json.loads(Path(aggregate_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C verification evidence is unreadable") from exc
    static=_package_c_verification_static(state,candidate,delta,baseline); specs=_package_c_verification_specs()
    expected_keys={"schema_version","kind","created_at","static","specs","receipt_paths","output_paths","terminal_paths","start_paths","aggregate_path"}
    if (not isinstance(intent,dict) or set(intent)!=expected_keys or intent.get("schema_version")!=SCHEMA or intent.get("kind")!="package_c_verification_intent" or
            not isinstance(intent.get("created_at"),str) or intent.get("static")!=static or intent.get("specs")!=specs):
        raise ControllerError("Package C verification intent binding changed")
    aggregate_refs=aggregate.get("receipts") if isinstance(aggregate,dict) else None
    if (not isinstance(aggregate_refs,list) or not aggregate_refs or len(aggregate_refs)>len(specs) or
            any(not isinstance(row,dict) for row in aggregate_refs)):
        raise ControllerError("Package C verification aggregate receipt prefix is malformed")
    prefix_len=len(aggregate_refs)
    refs=[]
    for index,(spec,path,output_path,terminal_path,start_path) in enumerate(zip(specs[:prefix_len],intent["receipt_paths"][:prefix_len],intent["output_paths"][:prefix_len],intent["terminal_paths"][:prefix_len],intent["start_paths"][:prefix_len])):
        info=capped_regular_file_info(path,verify_dir,MAX_PLAN_ARTIFACT_BYTES)
        output_info=capped_regular_file_info(output_path,verify_dir,PACKAGE_C_MAX_GATE_OUTPUT)
        if not info or not output_info: raise ControllerError("Package C verification receipt or output is missing or unsafe")
        try: raw=Path(output_info["path"]).read_bytes()
        except OSError as exc: raise ControllerError("Package C verification output is unreadable") from exc
        try: receipt=json.loads(Path(info["path"]).read_text())
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C verification receipt is unreadable") from exc
        terminal_info=capped_regular_file_info(terminal_path,verify_dir,PACKAGE_C_MAX_GATE_OUTPUT+64*1024)
        wrapper_nonce=digest_bytes(json.dumps({"static":static,"spec":spec,"index":index},sort_keys=True,separators=(",",":")).encode())[:32]
        cumulative_deadline=sum(row["timeout"]+10 for row in specs[:index+1]); deadline_text=(_parse_utc_instant(intent["created_at"])+dt.timedelta(seconds=cumulative_deadline)).isoformat().replace("+00:00","Z")
        start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,state["worktree"]["path"],static,wrapper_nonce,deadline_text)
        receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
        structurally_bound=(isinstance(receipt,dict) and set(receipt)==receipt_keys and receipt.get("schema_version")==SCHEMA and receipt.get("kind")=="package_c_verification_receipt" and
                receipt.get("index")==index and receipt.get("label")==spec["label"] and receipt.get("argv")==spec["argv"] and receipt.get("cwd")==state["worktree"]["path"] and
                receipt.get("timeout_seconds")==spec["timeout"] and receipt.get("static")==static and bool(terminal_info) and
                receipt.get("start_path")==start_info["path"] and receipt.get("start_sha256")==start_info["sha256"] and
                receipt.get("terminal_path")==terminal_info["path"] and receipt.get("terminal_sha256")==terminal_info["sha256"])
        if not structurally_bound: raise ControllerError("Package C verification receipt structure changed")
        if not _package_a_receipt_consistent(spec,receipt,output_info,raw): raise ControllerError("Package C verification receipt semantics changed: "+spec["label"])
        refs.append({"index":index,"label":spec["label"],"path":info["path"],"sha256":info["sha256"],"counters":receipt["counters"],"passed":receipt["passed"]})
    expected_all_passed=len(refs)==len(specs) and all(row["passed"] for row in refs)
    valid_prefix=(expected_all_passed or (not any(not row["passed"] for row in refs[:-1]) and refs[-1]["passed"] is False))
    if not valid_prefix:
        raise ControllerError("Package C verification aggregate is not a deterministic pass or first-failure prefix")
    for path in intent["receipt_paths"][prefix_len:]+intent["output_paths"][prefix_len:]+intent["terminal_paths"][prefix_len:]+intent["start_paths"][prefix_len:]:
        if os.path.lexists(path):
            raise ControllerError("Package C verification contains evidence after its first failed gate")
    aggregate_keys={"schema_version","kind","created_at","static","receipts","all_passed","post_fingerprint"}
    if (not isinstance(aggregate,dict) or set(aggregate)!=aggregate_keys or aggregate.get("schema_version")!=SCHEMA or aggregate.get("kind")!="package_c_verification_aggregate" or
            aggregate.get("created_at")!=intent["created_at"] or aggregate.get("static")!=static or aggregate.get("receipts")!=refs or aggregate.get("all_passed") is not expected_all_passed or
            aggregate.get("post_fingerprint")!=candidate["evidence"]["worktree_fingerprint"] or bound.get("candidate_id")!=candidate["id"] or bound.get("evidence_digest")!=candidate["evidence_digest"]):
        raise ControllerError("Package C verification aggregate binding changed")
    return {"intent":intent,"aggregate":aggregate,"aggregate_info":aggregate_info,"refs":refs}


def _command_verify_package_c_inner(directory: str,state: Dict[str,Any],candidate: Dict[str,Any],baseline: Dict[str,Any]) -> Dict[str,Any]:
    _package_c_candidate_intact(directory,state,candidate,baseline)
    delta=_package_c_builder_delta(directory,state,candidate)
    rescue_bound=state.get("package_c_rescue_receipt") if isinstance(state.get("package_c_rescue_receipt"),dict) else None
    if rescue_bound is None and candidate.get("id")==PACKAGE_C_RESCUE_CANDIDATE_ID:
        raise ControllerError("Package C verification for the terminal candidate requires the selector-v2 rescue receipt")
    tty_rescue_bound=state.get("package_c_tty_rescue_receipt") if isinstance(state.get("package_c_tty_rescue_receipt"),dict) else None
    probe_rescue_bound=state.get("package_c_probe_rescue_receipt") if isinstance(state.get("package_c_probe_rescue_receipt"),dict) else None
    if state.get("package_c_verification"):
        verified=_package_c_validate_verification(directory,state,candidate,baseline,delta)
