    if os.path.lexists(_top_verify) and (os.path.islink(_top_verify) or not os.path.isdir(_top_verify) or not inside(os.path.realpath(_top_verify),directory)): raise ControllerError("Package C verification top-level directory is unsafe")
    static=_package_c_verification_static(state,candidate,delta,baseline); specs=_package_c_verification_specs()
    if os.path.lexists(verify_dir) and (os.path.islink(verify_dir) or not os.path.isdir(verify_dir)): raise ControllerError("Package C verification directory is unsafe")
    os.makedirs(verify_dir,mode=0o700,exist_ok=True)
    intent_path=os.path.join(verify_dir,"intent.json"); aggregate_path=os.path.join(verify_dir,"aggregate.json")
    receipt_paths=[os.path.join(verify_dir,"%d-%s.json"%(i,s["label"])) for i,s in enumerate(specs)]
    output_paths=[os.path.join(verify_dir,"%d-%s.output.bin"%(i,s["label"])) for i,s in enumerate(specs)]
    terminal_paths=[os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,s["label"])) for i,s in enumerate(specs)]
