    base_intent={"schema_version":SCHEMA,"kind":"package_c_verification_intent","static":static,"specs":specs,"receipt_paths":receipt_paths,"output_paths":output_paths,"terminal_paths":terminal_paths,"start_paths":start_paths,"aggregate_path":aggregate_path}
    existing_intent=capped_regular_file_info(intent_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if os.path.lexists(intent_path) else None
    if os.path.lexists(intent_path) and not existing_intent: raise ControllerError("Package C verification intent is unsafe")
