        result,raw,terminal_info=_package_a_execute_gate(spec,index,wt,verify_dir,terminal_path,start_path,static,wrapper_nonce,deadline_text,env=hermetic_env)
        output_info=_package_a_adopt_bytes(output_path,verify_dir,raw,"c gate output")
        result["output_path"]=output_info["path"]
        if prior:
            try: old=json.loads(Path(prior["path"]).read_text())
            except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C verification orphan receipt is unreadable") from exc
            receipt_keys={"schema_version","kind","index","label","argv","cwd","timeout_seconds","static","start_path","start_sha256","terminal_path","terminal_sha256","exit_code","timed_out","output_limit_exceeded","output_path","output_sha256","output_bytes","output_total_seen","spawn_error","cleanup_error","counters","passed"}
            start_info=_package_a_gate_start_intact(start_path,verify_dir,spec,index,wt,static,wrapper_nonce,deadline_text)
            if (not isinstance(old,dict) or set(old)!=receipt_keys or old.get("schema_version")!=SCHEMA or old.get("kind")!="package_c_verification_receipt" or old.get("index")!=index or old.get("label")!=spec["label"] or old.get("argv")!=spec["argv"] or old.get("cwd")!=wt or old.get("timeout_seconds")!=spec["timeout"] or old.get("static")!=static or not output_info or not terminal_info or old.get("start_path")!=start_info["path"] or old.get("start_sha256")!=start_info["sha256"] or old.get("terminal_path")!=terminal_info["path"] or old.get("terminal_sha256")!=terminal_info["sha256"] or not _package_a_receipt_consistent(spec,old,output_info,raw)):
                raise ControllerError("Package C verification orphan receipt conflicts")
