def command_verify_package_c(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package C verification requires its canonical awaiting gate")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_c_prerequisites_intact(directory,state)
    root=os.path.dirname(directory); _package_c_v3_plan_intact(root)
    with package_lock(directory): return _command_verify_package_c_inner(directory,state,candidate,baseline)


def _package_c_review_context(directory: str,state: Dict[str,Any]) -> Dict[str,Any]:
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    baseline=_package_c_prerequisites_intact(directory,state); _package_c_candidate_intact(directory,state,candidate,baseline)
    delta=_package_c_builder_delta(directory,state,candidate); verification=_package_c_validate_verification(directory,state,candidate,baseline,delta)
    changed=[row["path"] for row in delta["files"]]
    return {"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":changed}


def _package_c_review_schema(state: Dict[str,Any],context: Dict[str,Any],attempt_id: str,run: str,nonce: str) -> Dict[str,Any]:
    candidate=context["candidate"]; verification=context["verification"]
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","work_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce","candidate_id","evidence_digest","baseline_receipt_sha256","verification_aggregate_sha256","verification_receipt_sha256s","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_c_review"},"work_id":{"type":"string","const":state["work_id"]},
            "policy":{"type":"string","const":POLICY_ID},"review_attempt_id":{"type":"string","const":attempt_id},
            "backend":{"type":"string","const":PACKAGE_C_CLAUDE_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_C_CLAUDE_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},"candidate_id":{"type":"string","const":candidate["id"]},
            "evidence_digest":{"type":"string","const":candidate["evidence_digest"]},"baseline_receipt_sha256":{"type":"string","const":state["package_c_prerequisites"]["sha256"]},
            "verification_aggregate_sha256":{"type":"string","const":verification["aggregate_info"]["sha256"]},
            "verification_receipt_sha256s":{"type":"array","minItems":9,"maxItems":9,"items":{"type":"string"}},
            "changed_paths":{"type":"array","minItems":1,"maxItems":5,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_c_review_expected(state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    verification=context["verification"]
    return {"schema_version":SCHEMA,"kind":"package_c_review","work_id":state["work_id"],"policy":POLICY_ID,"review_attempt_id":attempt["id"],
            "backend":PACKAGE_C_CLAUDE_REVIEW_BACKEND,"actor_id":PACKAGE_C_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_nonce":attempt["nonce"],
            "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
            "baseline_receipt_sha256":state["package_c_prerequisites"]["sha256"],
            "verification_aggregate_sha256":verification["aggregate_info"]["sha256"],
            "verification_receipt_sha256s":[row["sha256"] for row in verification["refs"]],"changed_paths":context["changed_paths"]}


def _package_c_review_attempt_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package C review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"review attempt id"),(attempt.get("run_id"),"review run id"),(attempt.get("nonce"),"review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(directory,"package-c-review-attempts"); expected_schema=_package_c_review_schema(state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_C_CLAUDE_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_c_review_expected(state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package C review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_C_CLAUDE_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_C_CLAUDE_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=context["candidate"]["id"] or attempt.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(directory,"logs")),("stderr",os.path.join(directory,"logs"))))):
        raise ControllerError("Package C review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package C review schema binding changed")
    return attempt


def _package_c_review_intact(directory: str,state: Dict[str,Any],context: Dict[str,Any]) -> Dict[str,Any]:
    bound=state.get("package_c_review") if isinstance(state.get("package_c_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict","model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package C independent review state binding is malformed")
    item=capped_regular_file_info(bound.get("path"),os.path.join(directory,"packets"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C independent review envelope changed")
    try: envelope=json.loads(Path(item["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C independent review envelope is unreadable") from exc
    attempt=state.get("package_c_review_attempt") if isinstance(state.get("package_c_review_attempt"),dict) else {}
    _package_c_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-c-review-attempts")
    packet=envelope.get("model_packet") if isinstance(envelope,dict) else None
    expected=_package_c_review_expected(state,context,attempt); packet_keys=set(expected)|{"verdict","findings","checks"}
    envelope_keys={"schema_version","kind","work_id","policy","candidate_id","evidence_digest","actor_id","run_id","review_attempt_id","reviewer_session_id","terminal_receipt_sha256","model_packet_sha256","model_packet"}
    if (not isinstance(envelope,dict) or set(envelope)!=envelope_keys or envelope.get("schema_version")!=SCHEMA or
            envelope.get("kind")!="package_c_review_envelope" or envelope.get("work_id")!=state["work_id"] or envelope.get("policy")!=POLICY_ID or
            envelope.get("candidate_id")!=context["candidate"]["id"] or envelope.get("evidence_digest")!=context["candidate"]["evidence_digest"] or
            envelope.get("actor_id")!=PACKAGE_C_CLAUDE_REVIEW_ACTOR or envelope.get("run_id")!=attempt.get("run_id") or envelope.get("review_attempt_id")!=attempt.get("id") or
            envelope.get("reviewer_session_id")!=attempt.get("provider_session_id") or envelope.get("terminal_receipt_sha256")!=receipt["sha256"] or
            not isinstance(packet,dict) or set(packet)!=packet_keys or any(packet.get(k)!=v for k,v in expected.items()) or
            envelope.get("model_packet_sha256")!=_package_a_json_sha256(packet) or terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded")):
        raise ControllerError("Package C independent review envelope binding changed")
    if (packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package C independent review verdict packet is malformed")
    return {"envelope":envelope,"packet":packet,"info":item,"receipt":receipt}


def _package_c_gate_replay(directory: str,state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    if not isinstance(state.get("package_c_gate_receipt"),dict): return None
    bound=state["package_c_gate_receipt"]
    gate_dir=os.path.join(directory,"package-c-gates")
    info=capped_regular_file_info(bound.get("path"),gate_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C gate receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C gate receipt is unreadable") from exc
    if (receipt.get("kind")!="package_c_gate_receipt" or receipt.get("work_id")!=state["work_id"] or receipt.get("policy")!=POLICY_ID or
            receipt.get("gate_name")!=PACKAGE_C_GATE_PRINCIPAL or receipt.get("adjudicator_principal")!=PACKAGE_C_GATE_PRINCIPAL):
        raise ControllerError("Package C gate receipt identity changed")
    expected_phase={"pass":"completed","revise":"prepared","fail":"failed"}[receipt["disposition"]]
    if state.get("phase")!=expected_phase: raise ControllerError("Package C gate phase binding changed")
    event_kind={"pass":"package_c_gate_passed","revise":"package_c_correction_queued","fail":"package_c_gate_failed"}[receipt["disposition"]]
    if not any(row.get("kind")==event_kind and row.get("receipt_id")==receipt.get("receipt_id") for row in recent_events(directory)):
        append_event(directory,event_kind,receipt_id=receipt.get("receipt_id"),gate_name=receipt["gate_name"],policy=POLICY_ID,candidate_id=receipt.get("candidate_id"),evidence_digest=receipt.get("evidence_digest"),disposition=receipt["disposition"],next_state=expected_phase)
    return {"schema_version":SCHEMA,"operation":"adjudicate_package_c","phase":expected_phase,"disposition":receipt["disposition"],
            "receipt":{"path":info["path"],"sha256":info["sha256"]},"reused":True}


def _package_c_review_capacity_intact(directory: str,state: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    bound=state.get("package_c_review_capacity") if isinstance(state.get("package_c_review_capacity"),dict) else {}
    keys={"path","sha256","mode","retry_after","candidate_id","evidence_digest","review_attempt_id","provider_session_id","wakeup","consumed_at"}
    if set(bound)!=keys or state.get("phase")!=CAPACITY_WAITING: raise ControllerError("Package C review capacity state is malformed")
    info=capped_regular_file_info(bound.get("path"),os.path.join(directory,"package-c-review-capacity"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C review capacity packet changed")
    try: packet=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C review capacity packet is unreadable") from exc
    if (packet.get("kind")!="package_c_review_capacity" or packet.get("policy")!=POLICY_ID or packet.get("candidate_id")!=bound.get("candidate_id") or
            packet.get("evidence_digest")!=bound.get("evidence_digest") or packet.get("review_attempt_id")!=bound.get("review_attempt_id") or
            packet.get("provider_session_id")!=bound.get("provider_session_id") or packet.get("mode")!=bound.get("mode") or packet.get("retry_after")!=bound.get("retry_after")):
        raise ControllerError("Package C review capacity binding changed")
    return packet,info


def _command_launch_package_c_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package C review requires its awaiting gate")
    context=_package_c_review_context(directory,state)
    if state.get("package_c_review"): raise ControllerError("Package C candidate already has an ingested independent review")
    existing=state.get("package_c_review_attempt") if isinstance(state.get("package_c_review_attempt"),dict) else None
    if existing:
        _package_c_review_attempt_intact(directory,state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _review_terminal(directory,existing,"package-c-review-attempts")
            return {"schema_version":SCHEMA,"operation":"launch_package_c_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_c_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_c_review","attempt_id":existing["id"],"run_id":existing["run_id"],"phase":state["phase"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            append_event(directory,"package_c_review_launch_lost",attempt_id=existing["id"]); save(directory,state)
        raise ControllerError("Package C independent review attempt already exists")
    retries=state.get("package_c_review_retries",[])
    if not isinstance(retries,list) or len(retries)>1: raise ControllerError("Package C review retry history is malformed")
    actor=PACKAGE_C_CLAUDE_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(directory,"package-c-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package C review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_c_review_schema(state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"c review schema")
    expected_arrays=_package_c_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prompt=("Package C controller-owned independent review. Verify the pending-turn source-precedence save/replay linkage and the gate-repair delivery linkage against the AttemptLink/v1 seam, and confirm Package B refusal behavior is unchanged. "
            "Review only bounded controller-owned receipts. Return the required schema JSON packet bound to every exact identity. "
            "Copy verification_receipt_sha256s exactly as "+json.dumps(expected_arrays["verification_receipt_sha256s"],separators=(",",":"))+" and changed_paths exactly as "+
            json.dumps(expected_arrays["changed_paths"],separators=(",",":"))+". Do not infer or replace either array.")
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package C review prompt exceeds bound")
    logs=os.path.join(directory,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-c-claude.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-c-claude.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind","claude_package_a_review_terminal","--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    expected=_package_c_review_expected(state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=305)).isoformat().replace("+00:00","Z")
    state["package_c_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_C_CLAUDE_REVIEW_BACKEND,
        "candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save(directory,state); append_event(directory,"package_c_review_starting",attempt_id=attempt_id,candidate_id=context["candidate"]["id"])
    try: pid,pgid=detached_spawn(wrapper,state["worktree"]["path"],stdout,stderr)
    except (OSError,ControllerError) as exc:
        state["package_c_review_attempt"]["spawn_error"]=type(exc).__name__; state["package_c_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); state["package_c_review_attempt"]["terminal_at"]=utc()
        append_event(directory,"package_c_review_spawn_failed",attempt_id=attempt_id); save(directory,state); raise ControllerError("Package C review controller spawn failed") from exc
    state["package_c_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); append_event(directory,"package_c_review_running",attempt_id=attempt_id,pid=pid); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"launch_package_c_review","attempt_id":attempt_id,"run_id":run,"phase":state["phase"]}


