def _package_c_review_capacity_wait(directory: str,state: Dict[str,Any],context: Dict[str,Any],attempt: Dict[str,Any],
                                     terminal: Dict[str,Any],receipt: Dict[str,Any],capacity_event: Dict[str,Any]) -> Dict[str,Any]:
    retry_after=parse_retry_after(capacity_event.get("rate_limit_info",{}).get("resetsAt"))
    mode=("scheduled" if isinstance(retry_after,str) else "manual_signal")
    cap_dir=os.path.join(directory,"package-c-review-capacity"); os.makedirs(cap_dir,mode=0o700,exist_ok=True)
    packet={"schema_version":SCHEMA,"kind":"package_c_review_capacity","work_id":state["work_id"],"policy":POLICY_ID,"candidate_id":context["candidate"]["id"],
            "evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),
            "mode":mode,"retry_after":retry_after,"terminal_receipt_sha256":receipt["sha256"],"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"issued_at":utc()}
    path=os.path.join(cap_dir,attempt["id"]+".json"); info=_package_a_adopt_json(path,cap_dir,packet,"c review capacity packet")
    state["package_c_review_capacity"]={"path":path,"sha256":info["sha256"],"mode":mode,"retry_after":retry_after,"candidate_id":context["candidate"]["id"],
        "evidence_digest":context["candidate"]["evidence_digest"],"review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),
        "wakeup":None,"consumed_at":None}
    state["phase"]=CAPACITY_WAITING; append_event(directory,"package_c_review_capacity_wait",mode=mode,retry_after=retry_after,candidate_id=context["candidate"]["id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_c_review","phase":CAPACITY_WAITING,"capacity":{"mode":mode,"retry_after":retry_after,"failure_class":"subscription_quota_exhausted"}}


def _command_ingest_package_c_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state) or state.get("phase") not in {"awaiting_gate",CAPACITY_WAITING}: raise ControllerError("Package C review ingest requires awaiting gate")
    if state.get("phase")==CAPACITY_WAITING:
        if not isinstance(state.get("package_c_review_capacity"),dict): raise ControllerError("Package C review capacity state is malformed for ingest")
        return {"schema_version":SCHEMA,"operation":"ingest_package_c_review","phase":CAPACITY_WAITING,"capacity":state["package_c_review_capacity"]}
    context=_package_c_review_context(directory,state); attempt=state.get("package_c_review_attempt") if isinstance(state.get("package_c_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package C review requires a quiescent controller-owned attempt")
    _package_c_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-c-review-attempts")
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            return _package_c_review_capacity_wait(directory,state,context,attempt,terminal,receipt,capacity_event)
        if terminal.get("timed_out"): raise ControllerError("Package C review timed out; timeout is terminal for this package")
        raise ControllerError("Package C independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(directory,"package-c-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package C review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],directory,attempt.get("reviewer_session_id",""))
    prior_sessions={row.get("provider_session_id") for row in state.get("package_c_review_attempt_history",[]) if isinstance(row,dict)}
    if provider_session in prior_sessions: raise ControllerError("Package C reviewer provider session is not distinct from prior attempts")
    expected=_package_c_review_expected(state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package C independent review packet failed strict binding validation")
    packets_dir=os.path.join(directory,"packets"); os.makedirs(packets_dir,mode=0o700,exist_ok=True)
    destination=os.path.join(packets_dir,context["candidate"]["id"]+".package-c-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    envelope={"schema_version":SCHEMA,"kind":"package_c_review_envelope","work_id":state["work_id"],"policy":POLICY_ID,"candidate_id":context["candidate"]["id"],
              "evidence_digest":context["candidate"]["evidence_digest"],"actor_id":PACKAGE_C_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_attempt_id":attempt["id"],
              "reviewer_session_id":attempt.get("reviewer_session_id",""),"terminal_receipt_sha256":receipt["sha256"],"model_packet_sha256":model_packet_sha256,"model_packet":packet}
    envelope_info=_package_a_adopt_json(destination,packets_dir,envelope,"c review envelope")
    consumed=utc(); attempt["consumed_at"]=consumed; attempt["packet_sha256"]=envelope_info["sha256"]; attempt["provider_session_id"]=provider_session
    state["package_c_review"]={"path":destination,"sha256":envelope_info["sha256"],"candidate_id":context["candidate"]["id"],"evidence_digest":context["candidate"]["evidence_digest"],
        "actor_id":PACKAGE_C_CLAUDE_REVIEW_ACTOR,"run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,
        "verdict":packet["verdict"],"model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":context["verification"]["aggregate_info"]["sha256"],"receipt_sha256":receipt["sha256"]}
    history=state.get("package_c_review_attempt_history",[]); history=list(history)+[{**attempt}]
    state["package_c_review_attempt_history"]=history; state["package_c_review_attempt"]={**attempt}
    append_event(directory,"package_c_review_ingested",candidate_id=context["candidate"]["id"],verdict=packet["verdict"],run_id=attempt["run_id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_c_review","phase":state["phase"],"verdict":packet["verdict"]}


