def _command_retry_package_c_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state) or state.get("phase")!="awaiting_gate": raise ControllerError("Package C review retry requires awaiting gate")
    context=_package_c_review_context(directory,state); attempt=state.get("package_c_review_attempt") if isinstance(state.get("package_c_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package C review retry requires a quiescent unconsumed attempt")
    _package_c_review_attempt_intact(directory,state,context,attempt)
    terminal,receipt=_review_terminal(directory,attempt,"package-c-review-attempts")
    is_overflow=(terminal.get("exit_code")!=0 and (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and terminal.get("output_sha256") is None)
    if not is_overflow:
        raise ControllerError("Package C review retry is only available for bounded_stream_overflow infrastructure classification")
    retries=state.get("package_c_review_retries",[])
    if not isinstance(retries,list) or len(retries)>=1: raise ControllerError("Package C review infrastructure retry is already exhausted")
    archived={**attempt,"retry_reason":"bounded_stream_overflow","terminal_receipt_sha256":receipt["sha256"],"provider_session_id":None}
    retries=retries+[archived]; state["package_c_review_retries"]=retries; state["package_c_review_attempt"]=None
    history=state.get("package_c_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package C review attempt history is malformed")
    state["package_c_review_attempt_history"]=history+[archived]
    append_event(directory,"package_c_review_retry_queued",attempt_id=attempt["id"],retry_count=len(retries)); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"retry_package_c_review","phase":state["phase"],"retry_evidence":{"classification":"bounded_stream_overflow","prior_attempt_id":attempt["id"],"retry_count":len(retries)}}


def command_retry_package_c_review(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_retry_package_c_review(args)


def command_register_package_c_review_capacity_wakeup(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_c_review_capacity_intact(directory,state)
    bound=state["package_c_review_capacity"]
    if bound.get("mode")!="scheduled" or not isinstance(bound.get("retry_after"),str): raise ControllerError("Package C manual review capacity cannot register an agent wakeup")
    ref=args.wakeup_ref.strip()
    if not ref or len(ref.encode())>500: raise ControllerError("Package C review wakeup reference is required and bounded")
    receipt_core={"schema_version":SCHEMA,"kind":"package_c_review_capacity_wakeup","work_id":state["work_id"],"policy":POLICY_ID,
        "capacity_packet_sha256":packet_info["sha256"],"candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],
        "review_attempt_id":bound["review_attempt_id"],"retry_after":bound["retry_after"],"wakeup_ref_sha256":digest_bytes(ref.encode())}
    lease_id=digest_bytes(json.dumps(receipt_core,sort_keys=True,separators=(",",":")).encode()); receipt={**receipt_core,"lease_id":lease_id,"issued_at":packet["issued_at"]}
    root=os.path.join(directory,"package-c-review-capacity-wakeups"); os.makedirs(root,mode=0o700,exist_ok=True); path=os.path.join(root,lease_id+".json")
    info=_package_a_adopt_json(path,root,receipt,"c review capacity wakeup")
    expected={"path":info["path"],"sha256":info["sha256"],"lease_id":lease_id,"wakeup_ref":ref,"consumed_at":None}
    if bound.get("wakeup") and bound["wakeup"]!=expected: raise ControllerError("Package C review capacity has a different wakeup")
    bound["wakeup"]=expected; append_event(directory,"package_c_review_capacity_wakeup_registered",lease_id=lease_id,candidate_id=bound["candidate_id"]); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"register_package_c_review_capacity_wakeup","phase":CAPACITY_WAITING,"lease_id":lease_id,"retry_after":bound["retry_after"],"reused":False}


def command_resume_package_c_review_capacity(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory); packet,packet_info=_package_c_review_capacity_intact(directory,state); bound=state["package_c_review_capacity"]
    if bound.get("mode")!="scheduled": raise ControllerError("Package C manual review capacity requires an authenticated outer adapter signal")
    due=_parse_utc_instant(bound.get("retry_after"))
    if due>dt.datetime.now(dt.timezone.utc): raise ControllerError("Package C review capacity retry time has not elapsed")
    wake=bound.get("wakeup") if isinstance(bound.get("wakeup"),dict) else {}
    item=capped_regular_file_info(wake.get("path"),os.path.join(directory,"package-c-review-capacity-wakeups"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(wake.get("path"),str) else None
    if not item or item.get("sha256")!=wake.get("sha256") or wake.get("consumed_at") or bound.get("consumed_at"): raise ControllerError("Package C review capacity wakeup lease is missing or consumed")
    attempt=state["package_c_review_attempt"]; archived={**attempt,"capacity_packet_sha256":packet_info["sha256"],"capacity_disposition":"scheduled_continuation"}
    history=state.get("package_c_review_attempt_history",[])
    if not isinstance(history,list): raise ControllerError("Package C review history is malformed")
    history=history+[archived]; consumed=utc(); wake["consumed_at"]=consumed; bound["consumed_at"]=consumed
    state["package_c_review_attempt_history"]=history; state["package_c_review_capacity_history"]=[{**bound}]
    state["package_c_review_attempt"]=None; state["package_c_review_capacity"]=None; state["phase"]="awaiting_gate"
    state["gate"]={"kind":"package_c_review_capacity_released","verdict":"awaiting_review","candidate_id":bound["candidate_id"],"evidence_digest":bound["evidence_digest"],"policy":POLICY_ID}
    append_event(directory,"package_c_review_capacity_released",lease_id=wake["lease_id"],candidate_id=bound["candidate_id"],next_state="awaiting_gate"); save(directory,state)
    return {"schema_version":SCHEMA,"operation":"resume_package_c_review_capacity","phase":"awaiting_gate","delivery":"fresh_controller_review_continuation"}


def _command_adjudicate_package_c(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state): raise ControllerError("Package C fixed gate requires its canonical identity")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    replay=_package_c_gate_replay(directory,state)
    if replay: return replay
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C fixed gate requires its awaiting candidate")
    root=os.path.dirname(directory)
    try:
        _package_c_v3_plan_intact(root)
        baseline=_package_c_prerequisites_intact(directory,state); _package_c_attempt_intact(state.get("attempt")); _package_c_candidate_intact(directory,state,candidate,baseline)
        delta=_package_c_builder_delta(directory,state,candidate); verification=_package_c_validate_verification(directory,state,candidate,baseline,delta)
        context={"candidate":candidate,"baseline":baseline,"delta":delta,"verification":verification,"changed_paths":[row["path"] for row in delta["files"]]}
        review=_package_c_review_intact(directory,state,context) if isinstance(state.get("package_c_review"),dict) else None
        all_passed=verification["aggregate"]["all_passed"] is True
        review_verdict=(review or {}).get("packet",{}).get("verdict")
        review_infrastructure_exhausted=False; exhausted_review_receipt=None
        active_review=state.get("package_c_review_attempt") if isinstance(state.get("package_c_review_attempt"),dict) else None
        review_retries=state.get("package_c_review_retries")
        if all_passed and review_verdict is None and active_review and isinstance(review_retries,list) and len(review_retries)==1:
            if process_alive(active_review.get("pid"),active_review.get("pgid")): raise ControllerError("Package C independent review is still running")
            _package_c_review_attempt_intact(directory,state,context,active_review)
            terminal,terminal_receipt=_review_terminal(directory,active_review,"package-c-review-attempts")
            output_exists=isinstance(active_review.get("output_path"),str) and os.path.lexists(active_review["output_path"])
            capacity_event=_package_a_claude_capacity_event(active_review["stdout"],directory,active_review.get("reviewer_session_id",""))
            review_infrastructure_exhausted=(terminal.get("exit_code")!=0 and (terminal.get("timed_out") is True or terminal.get("output_limit_exceeded") is True) and terminal.get("output_sha256") is None and not output_exists and capacity_event is None)
            if review_infrastructure_exhausted: exhausted_review_receipt=terminal_receipt
        if all_passed and review_verdict=="pass": disposition,reason="pass","all_evidence_passed"
        elif review_verdict=="fail": disposition,reason="fail","independent_review_failed"
        elif review_infrastructure_exhausted: disposition,reason="fail","review_infrastructure_exhausted"
        elif state.get("package_c_correction_used") or state.get("package_c_correction_history"):
            disposition,reason="fail","correction_exhausted"
        else: disposition,reason="revise","deterministic_or_review_dissent"
        verification_sha=verification["aggregate_info"]["sha256"]
        review_sha=review["info"]["sha256"] if review else (exhausted_review_receipt or {}).get("sha256")
    except ControllerError:
        if not isinstance(state.get("package_c_verification"),dict): raise
        disposition,reason="fail","candidate_or_evidence_invalid"; verification_sha=state["package_c_verification"].get("aggregate_sha256")
        review_sha=(state.get("package_c_review") or {}).get("sha256"); context=None
    if context is not None and all_passed and review_verdict is None and not review_infrastructure_exhausted:
        return {"schema_version":SCHEMA,"operation":"adjudicate_package_c","phase":"awaiting_gate","disposition":"awaiting_review","reused":False}
    if disposition=="revise" and context is not None:
        if state.get("package_c_correction_used") or state.get("package_c_correction_history"):
            disposition,reason="fail","correction_exhausted"
    core={"schema_version":SCHEMA,"kind":"package_c_gate_receipt","work_id":state["work_id"],"policy":POLICY_ID,
        "gate_name":PACKAGE_C_GATE_PRINCIPAL,"adjudicator_principal":PACKAGE_C_GATE_PRINCIPAL,"candidate_id":candidate.get("id"),
        "evidence_digest":candidate.get("evidence_digest"),"verification_aggregate_sha256":verification_sha,"review_sha256":review_sha,
        "correction_already_used":bool(state.get("package_c_correction_used") or state.get("package_c_correction_history")),"disposition":disposition,"reason_code":reason}
    receipt_id=digest_bytes(json.dumps(core,sort_keys=True,separators=(",",":")).encode()); receipt={**core,"receipt_id":receipt_id,"issued_at":candidate.get("created_at") or state.get("created_at")}
    gate_dir=os.path.join(directory,"package-c-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir) or not inside(real(gate_dir),directory)):
        raise ControllerError("Package C fixed gate directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    receipt_info=_package_a_adopt_json(os.path.join(gate_dir,receipt_id+".json"),gate_dir,receipt,"c fixed gate receipt")
    if disposition=="revise":
        assert context is not None
        prior_attempt=state.get("attempt") if isinstance(state.get("attempt"),dict) else {}
        if (prior_attempt.get("role")!="implementer" or not isinstance(prior_attempt.get("provider_session_id"),str) or
                not prior_attempt.get("provider_session_id")):
            raise ControllerError("Package C correction lacks the exact implementer session")
        history=state.get("package_c_correction_history")
        if history not in (None,[]): raise ControllerError("Package C has exhausted its one bounded correction")
        state["package_c_correction_history"]=[{"path":receipt_info["path"],"sha256":receipt_info["sha256"],
            "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest")}]
        state["recovery_constraint"]={"kind":"package_c_exact_correction","role":"implementer",
            "provider_session_id":prior_attempt["provider_session_id"],"original_attempt_id":prior_attempt.get("id"),
            "original_attempt_started_at":prior_attempt.get("started_at"),"candidate_id":candidate.get("id"),
            "evidence_digest":candidate.get("evidence_digest"),"gate_receipt_path":receipt_info["path"],
            "gate_receipt_sha256":receipt_info["sha256"],"authorized_at":utc(),"consumed_at":None,"spawn_failures":[]}
        state.pop("package_c_correction_used",None)
        state["phase"]="prepared"
    elif disposition=="pass": state["phase"]="completed"
    else: state["phase"]="failed"
    state["gate"]={"kind":"package_c_fixed_gate","gate_name":PACKAGE_C_GATE_PRINCIPAL,"verdict":disposition,"reason_code":reason,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"receipt_id":receipt_id,"receipt_sha256":receipt_info["sha256"],"policy":POLICY_ID}
    state["package_c_gate_receipt"]={"path":receipt_info["path"],"sha256":receipt_info["sha256"],"receipt_id":receipt_id,
        "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),"disposition":disposition}
    save(directory,state)
    result=_package_c_gate_replay(directory,state)
    assert result is not None
    result["reused"]=False
    return result


def command_adjudicate_package_c(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_adjudicate_package_c(args)


_RESCUE_BINDING_KEYS = frozenset({"path","sha256","rescue_id","candidate_id","evidence_digest","selector_bug","authority_date"})
_RESCUE_RECEIPT_KEYS = frozenset({"schema_version","kind","work_id","policy","bug_class","authority_date","candidate_id","evidence_digest",
                                   "failed_aggregate_sha256","failed_pending_receipt_sha256","terminal_gate_receipt_sha256",
                                   "selector_v2_pending_tests","selector_v2_repair_tests","prior_revision","issued_at","rescue_id"})


def _package_c_rescue_replay(directory: str,state: Dict[str,Any],bound: Dict[str,Any]) -> Dict[str,Any]:
    # Require state is in the expected post-rescue awaiting_gate shape
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C rescue replay requires awaiting_gate phase")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C rescue replay requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C rescue replay requires exact evidence digest")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if gate.get("kind")!="package_c_gate_selection_rescued": raise ControllerError("Package C rescue replay requires gate_selection_rescued gate kind")
    rescue_dir=_package_c_rescue_dir(directory)
    info=capped_regular_file_info(bound.get("path"),rescue_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C rescue receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C rescue receipt is unreadable") from exc
    if (not isinstance(receipt,dict) or set(receipt)!=_RESCUE_RECEIPT_KEYS or receipt.get("schema_version")!=SCHEMA or
            receipt.get("kind")!="package_c_gate_selection_rescue" or receipt.get("work_id")!=state["work_id"] or
            receipt.get("policy")!=POLICY_ID or receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            receipt.get("failed_aggregate_sha256")!=PACKAGE_C_RESCUE_FAILED_AGGREGATE_SHA256 or
            receipt.get("failed_pending_receipt_sha256")!=PACKAGE_C_RESCUE_FAILED_PENDING_SHA256 or
            receipt.get("terminal_gate_receipt_sha256")!=PACKAGE_C_RESCUE_TERMINAL_GATE_SHA256 or
            receipt.get("bug_class")!=PACKAGE_C_RESCUE_SELECTOR_BUG or
            receipt.get("authority_date")!=PACKAGE_C_RESCUE_AUTHORITY_DATE or
            receipt.get("rescue_id")!=bound.get("rescue_id") or
            receipt.get("selector_v2_pending_tests")!=list(PACKAGE_C_FOCUSED_PENDING_TESTS) or
            receipt.get("selector_v2_repair_tests")!=list(PACKAGE_C_FOCUSED_REPAIR_TESTS)):
        raise ControllerError("Package C rescue receipt binding changed")
    if receipt.get("prior_revision")!=PACKAGE_C_RESCUE_REVISION:
        raise ControllerError("Package C rescue receipt prior_revision does not match sealed binding")
    try: _parse_utc_instant(receipt.get("issued_at"))
    except ControllerError as exc: raise ControllerError("Package C rescue receipt issued_at is malformed") from exc
    if not any(row.get("kind")=="package_c_gate_selection_rescued" and row.get("rescue_id")==receipt["rescue_id"]
               for row in recent_events(directory)):
        append_event(directory,"package_c_gate_selection_rescued",rescue_id=receipt["rescue_id"],
            candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],
            failed_aggregate_sha256=receipt["failed_aggregate_sha256"],
            terminal_gate_sha256=receipt["terminal_gate_receipt_sha256"],next_state="awaiting_gate")
    return {"schema_version":SCHEMA,"operation":"rescue_package_c_gate_selection","phase":"awaiting_gate",
            "rescue_id":receipt["rescue_id"],"rescue_receipt_sha256":info["sha256"],
            "candidate_id":receipt["candidate_id"],"reused":True}


_TTY_RESCUE_BINDING_KEYS = frozenset({"path","sha256","rescue_id","candidate_id","evidence_digest","bug_class","authority_date"})
_TTY_RESCUE_RECEIPT_KEYS = frozenset({"schema_version","kind","work_id","policy","bug_class","authority_date","candidate_id","evidence_digest",
                                      "selector_rescue_sha256","contaminated_aggregate_sha256",
                                      "contaminated_receipt_sha256","contaminated_terminal_sha256","contaminated_output_sha256",
                                      "prior_revision","issued_at","rescue_id"})
_TTY_V2_VERIFICATION_BINDING_KEYS = frozenset({"intent_path","intent_sha256","aggregate_path","aggregate_sha256","candidate_id","evidence_digest"})
_TTY_V2_ARCHIVE_KEYS = frozenset({"kind","verification","archived_at"})
_PROBE_RESCUE_BINDING_KEYS = frozenset({"path","sha256","rescue_id","candidate_id","evidence_digest","bug_class","authority_date"})
_PROBE_RESCUE_RECEIPT_KEYS = frozenset({"schema_version","kind","work_id","policy","bug_class","authority_date","candidate_id","evidence_digest",
                                        "tty_rescue_sha256","v3_intent_sha256","v3_aggregate_sha256",
                                        "failed_probe_receipt_sha256","failed_probe_terminal_sha256","failed_probe_output_sha256",
                                        "prior_revision","issued_at","rescue_id"})
_PROBE_V3_ARCHIVE_KEYS = frozenset({"kind","verification","archived_at"})


def _package_c_tty_validate_contaminated_v2(directory: str,candidate: Dict[str,Any],verification_binding: Any,selector_rescue_bound: Any) -> None:
    if not isinstance(selector_rescue_bound,dict) or set(selector_rescue_bound)!=_RESCUE_BINDING_KEYS:
        raise ControllerError("Package C TTY rescue selector rescue binding has wrong key set")
    if (selector_rescue_bound.get("sha256")!=PACKAGE_C_TTY_RESCUE_SELECTOR_RESCUE_SHA or
            selector_rescue_bound.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            selector_rescue_bound.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            selector_rescue_bound.get("selector_bug")!=PACKAGE_C_RESCUE_SELECTOR_BUG or
            selector_rescue_bound.get("authority_date")!=PACKAGE_C_RESCUE_AUTHORITY_DATE):
        raise ControllerError("Package C TTY rescue selector rescue receipt SHA mismatch")
    rescue_dir=_package_c_rescue_dir(directory)
    sel_info=capped_regular_file_info(selector_rescue_bound.get("path"),rescue_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(selector_rescue_bound.get("path"),str) else None
    if not sel_info or sel_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_SELECTOR_RESCUE_SHA:
        raise ControllerError("Package C TTY rescue selector rescue receipt is missing or changed on disk")
    try: sel_receipt=json.loads(Path(sel_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C TTY rescue selector rescue receipt is unreadable") from exc
    if not isinstance(sel_receipt,dict) or set(sel_receipt)!=_RESCUE_RECEIPT_KEYS:
        raise ControllerError("Package C TTY rescue selector rescue receipt schema mismatch")
    if (selector_rescue_bound.get("rescue_id")!=sel_receipt.get("rescue_id") or
            sel_receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            sel_receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            sel_receipt.get("bug_class")!=PACKAGE_C_RESCUE_SELECTOR_BUG or
            sel_receipt.get("authority_date")!=PACKAGE_C_RESCUE_AUTHORITY_DATE):
        raise ControllerError("Package C TTY rescue selector rescue binding changed")
    if not isinstance(verification_binding,dict) or set(verification_binding)!=_TTY_V2_VERIFICATION_BINDING_KEYS:
        raise ControllerError("Package C TTY rescue contaminated verification binding has wrong key set")
    if verification_binding.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID:
        raise ControllerError("Package C TTY rescue contaminated verification binding candidate_id mismatch")
    if verification_binding.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST:
        raise ControllerError("Package C TTY rescue contaminated verification binding evidence_digest mismatch")
    verify_dir=_package_c_v2_verification_dir(directory,candidate)
    intent_info=capped_regular_file_info(verification_binding.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification_binding.get("intent_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_INTENT_SHA:
        raise ControllerError("Package C TTY rescue contaminated intent is missing or changed")
    if verification_binding.get("intent_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_INTENT_SHA:
        raise ControllerError("Package C TTY rescue contaminated verification binding intent_sha256 mismatch")
    agg_info=capped_regular_file_info(verification_binding.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification_binding.get("aggregate_path"),str) else None
    if not agg_info or agg_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_AGGREGATE_SHA:
        raise ControllerError("Package C contaminated verification aggregate is missing or changed")
    if verification_binding.get("aggregate_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_AGGREGATE_SHA:
        raise ControllerError("Package C TTY rescue contaminated verification binding aggregate_sha256 mismatch")
    try: aggregate=json.loads(Path(agg_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C contaminated aggregate is unreadable") from exc
    receipts=aggregate.get("receipts") if isinstance(aggregate,dict) else None
    if not isinstance(receipts,list) or len(receipts)!=1: raise ControllerError("Package C contaminated aggregate must have exactly one receipt")
    sole=receipts[0]
    if (not isinstance(sole,dict) or sole.get("label")!="test_cowork" or sole.get("index")!=0 or
            sole.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_RECEIPT_SHA or sole.get("passed") is not False):
        raise ControllerError("Package C contaminated aggregate sole receipt binding mismatch")
    receipt_info=capped_regular_file_info(sole.get("path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(sole.get("path"),str) else None
    if not receipt_info or receipt_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_RECEIPT_SHA:
        raise ControllerError("Package C contaminated verification receipt is missing or changed")
    try: receipt_doc=json.loads(Path(receipt_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C contaminated verification receipt is unreadable") from exc
    if (not isinstance(receipt_doc,dict) or
            receipt_doc.get("timed_out") is not True or
            receipt_doc.get("exit_code")!=-15 or
            receipt_doc.get("cleanup_error")!="permission_denied" or
            receipt_doc.get("passed") is not False or
            receipt_doc.get("counters")!={"parse_error":1} or
            receipt_doc.get("terminal_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_TERMINAL_SHA or
            receipt_doc.get("output_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_OUTPUT_SHA):
        raise ControllerError("Package C contaminated verification receipt facts do not match TTY contamination signature")
    terminal_info=capped_regular_file_info(receipt_doc.get("terminal_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(receipt_doc.get("terminal_path"),str) else None
    if not terminal_info or terminal_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_TERMINAL_SHA:
        raise ControllerError("Package C contaminated terminal file is missing or changed")
    output_info=capped_regular_file_info(receipt_doc.get("output_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(receipt_doc.get("output_path"),str) else None
    if not output_info or output_info.get("sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_OUTPUT_SHA:
        raise ControllerError("Package C contaminated output file is missing or changed")
    specs=_package_c_verification_specs()
    for i,spec in enumerate(specs[1:],1):
        later_paths=(
            os.path.join(verify_dir,"%d-%s.json"%(i,spec["label"])),
            os.path.join(verify_dir,"%d-%s.output.bin"%(i,spec["label"])),
            os.path.join(verify_dir,"%d-%s.terminal.bin"%(i,spec["label"])),
            os.path.join(verify_dir,"%d-%s.start.json"%(i,spec["label"])),
        )
        if any(os.path.lexists(path) for path in later_paths):
            raise ControllerError("Package C contaminated v2 dir has unexpected later-gate artifact: %s"%spec["label"])


def _package_c_tty_rescue_replay(directory: str,state: Dict[str,Any],bound: Dict[str,Any]) -> Dict[str,Any]:
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C TTY rescue replay requires awaiting_gate phase")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C TTY rescue replay requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C TTY rescue replay requires exact evidence digest")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if gate.get("kind")!="package_c_tty_verification_rescued": raise ControllerError("Package C TTY rescue replay requires tty_verification_rescued gate kind")
    v2_archive=state.get("package_c_v2_archive")
    if not isinstance(v2_archive,dict) or set(v2_archive)!=_TTY_V2_ARCHIVE_KEYS:
        raise ControllerError("Package C TTY rescue replay requires intact v2_archive with exact keys")
    if v2_archive.get("kind")!="tty_contaminated_verification_v2_terminal":
        raise ControllerError("Package C TTY rescue replay requires tty_contaminated_verification_v2_terminal archive kind")
    try: _parse_utc_instant(v2_archive.get("archived_at"))
    except ControllerError as exc: raise ControllerError("Package C TTY rescue replay v2_archive archived_at is malformed") from exc
    _package_c_tty_validate_contaminated_v2(directory,candidate,v2_archive.get("verification"),state.get("package_c_rescue_receipt"))
    tty_rescue_dir=_package_c_tty_rescue_dir(directory)
    info=capped_regular_file_info(bound.get("path"),tty_rescue_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C TTY rescue receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C TTY rescue receipt is unreadable") from exc
    if (not isinstance(receipt,dict) or set(receipt)!=_TTY_RESCUE_RECEIPT_KEYS or receipt.get("schema_version")!=SCHEMA or
            receipt.get("kind")!="package_c_tty_contaminated_verification_rescue" or receipt.get("work_id")!=state["work_id"] or
            receipt.get("policy")!=POLICY_ID or receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            receipt.get("selector_rescue_sha256")!=PACKAGE_C_TTY_RESCUE_SELECTOR_RESCUE_SHA or
            receipt.get("contaminated_aggregate_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_AGGREGATE_SHA or
            receipt.get("contaminated_receipt_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_RECEIPT_SHA or
            receipt.get("contaminated_terminal_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_TERMINAL_SHA or
            receipt.get("contaminated_output_sha256")!=PACKAGE_C_TTY_RESCUE_CONTAMINATED_OUTPUT_SHA or
            receipt.get("bug_class")!=PACKAGE_C_TTY_RESCUE_BUG_CLASS or
            receipt.get("authority_date")!=PACKAGE_C_TTY_RESCUE_AUTHORITY_DATE or
            receipt.get("rescue_id")!=bound.get("rescue_id")):
        raise ControllerError("Package C TTY rescue receipt binding changed")
    if receipt.get("prior_revision")!=PACKAGE_C_TTY_RESCUE_REVISION:
        raise ControllerError("Package C TTY rescue receipt prior_revision does not match sealed binding")
    try: _parse_utc_instant(receipt.get("issued_at"))
    except ControllerError as exc: raise ControllerError("Package C TTY rescue receipt issued_at is malformed") from exc
    if not any(row.get("kind")=="package_c_tty_verification_rescued" and row.get("rescue_id")==receipt["rescue_id"]
               for row in recent_events(directory)):
        append_event(directory,"package_c_tty_verification_rescued",rescue_id=receipt["rescue_id"],
            candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],
            contaminated_aggregate_sha256=receipt["contaminated_aggregate_sha256"],next_state="awaiting_gate")
    return {"schema_version":SCHEMA,"operation":"rescue_package_c_tty_contaminated_verification","phase":"awaiting_gate",
            "rescue_id":receipt["rescue_id"],"rescue_receipt_sha256":info["sha256"],
            "candidate_id":receipt["candidate_id"],"reused":True}


def _command_rescue_package_c_tty_contaminated_verification(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state): raise ControllerError("Package C TTY verification rescue requires its canonical identity")
    tty_bound=state.get("package_c_tty_rescue_receipt")
    if tty_bound is not None:
        if (not isinstance(tty_bound,dict) or set(tty_bound)!=_TTY_RESCUE_BINDING_KEYS or
                not isinstance(tty_bound.get("path"),str) or
                not isinstance(tty_bound.get("sha256"),str) or len(tty_bound.get("sha256",""))!=64 or
                not isinstance(tty_bound.get("rescue_id"),str) or len(tty_bound.get("rescue_id",""))!=64 or
                tty_bound.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
                tty_bound.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
                tty_bound.get("bug_class")!=PACKAGE_C_TTY_RESCUE_BUG_CLASS or
                tty_bound.get("authority_date")!=PACKAGE_C_TTY_RESCUE_AUTHORITY_DATE):
            raise ControllerError("Package C TTY rescue receipt state binding is malformed or tampered")
        return _package_c_tty_rescue_replay(directory,state,tty_bound)
    # Accept only the exact bound contaminated state
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C TTY verification rescue requires awaiting_gate phase")
    if state.get("revision")!=PACKAGE_C_TTY_RESCUE_REVISION: raise ControllerError("Package C TTY verification rescue requires exact revision %d"%PACKAGE_C_TTY_RESCUE_REVISION)
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C TTY verification rescue requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C TTY verification rescue requires exact evidence digest")
    rescue_bound=state.get("package_c_rescue_receipt") if isinstance(state.get("package_c_rescue_receipt"),dict) else None
    if rescue_bound is None: raise ControllerError("Package C TTY verification rescue requires selector-v2 rescue receipt")
    verification=state.get("package_c_verification") if isinstance(state.get("package_c_verification"),dict) else None
    if not verification: raise ControllerError("Package C TTY verification rescue requires an active contaminated verification binding")
    _package_c_tty_validate_contaminated_v2(directory,candidate,verification,rescue_bound)
    # Validate correction_used is set and must be preserved
    correction_used=state.get("package_c_correction_used")
    if not isinstance(correction_used,dict) or not correction_used:
        raise ControllerError("Package C TTY verification rescue requires correction_used to be recorded")
    # Validate full Package C authority chain
    root=os.path.dirname(directory)
    require_frozen_brief(state,directory)
    if state["brief"]["sha256"]!=PACKAGE_C_BRIEF_SHA256: raise ControllerError("Package C brief SHA-256 changed")
    _package_c_v3_plan_intact(root)
    baseline=_package_c_prerequisites_intact(directory,state)
    _package_c_attempt_intact(state.get("attempt"))
    _package_c_candidate_intact(directory,state,candidate,baseline)
    # Write TTY rescue receipt (immutable — must happen before state mutation)
    tty_rescue_dir=_package_c_tty_rescue_dir(directory)
    if os.path.lexists(tty_rescue_dir) and (os.path.islink(tty_rescue_dir) or not os.path.isdir(tty_rescue_dir) or not inside(real(tty_rescue_dir),directory)):
        raise ControllerError("Package C TTY rescue directory is unsafe")
    os.makedirs(tty_rescue_dir,mode=0o700,exist_ok=True)
    rescue_immutable={"schema_version":SCHEMA,"kind":"package_c_tty_contaminated_verification_rescue","work_id":state["work_id"],"policy":POLICY_ID,
        "bug_class":PACKAGE_C_TTY_RESCUE_BUG_CLASS,"authority_date":PACKAGE_C_TTY_RESCUE_AUTHORITY_DATE,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "selector_rescue_sha256":PACKAGE_C_TTY_RESCUE_SELECTOR_RESCUE_SHA,
        "contaminated_aggregate_sha256":PACKAGE_C_TTY_RESCUE_CONTAMINATED_AGGREGATE_SHA,
        "contaminated_receipt_sha256":PACKAGE_C_TTY_RESCUE_CONTAMINATED_RECEIPT_SHA,
        "contaminated_terminal_sha256":PACKAGE_C_TTY_RESCUE_CONTAMINATED_TERMINAL_SHA,
        "contaminated_output_sha256":PACKAGE_C_TTY_RESCUE_CONTAMINATED_OUTPUT_SHA,
        "prior_revision":state["revision"]}
    rescue_id=digest_bytes(json.dumps(rescue_immutable,sort_keys=True,separators=(",",":")).encode())
    rescue_path=os.path.join(tty_rescue_dir,rescue_id+".json")
    issued_at=utc()
    # Detect safe orphan from a prior crash (receipt written, state save not yet committed)
    if os.path.lexists(rescue_path):
        if os.path.islink(rescue_path): raise ControllerError("Package C TTY rescue receipt orphan is a symlink")
        orphan_info=capped_regular_file_info(rescue_path,tty_rescue_dir,MAX_PLAN_ARTIFACT_BYTES)
        if not orphan_info: raise ControllerError("Package C TTY rescue receipt orphan is not a safe regular file")
        try: orphan=json.loads(Path(orphan_info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C TTY rescue receipt orphan is unreadable") from exc
        orphan_expected_keys=set(rescue_immutable)|{"rescue_id","issued_at"}
        if not isinstance(orphan,dict) or set(orphan)!=orphan_expected_keys:
            raise ControllerError("Package C TTY rescue receipt orphan has unexpected keys")
        if orphan.get("rescue_id")!=rescue_id:
            raise ControllerError("Package C TTY rescue receipt orphan rescue_id conflicts")
        for k,v in rescue_immutable.items():
            if orphan.get(k)!=v: raise ControllerError("Package C TTY rescue receipt orphan field %s conflicts"%k)
        orphan_issued_at=orphan.get("issued_at")
        if not isinstance(orphan_issued_at,str) or not orphan_issued_at:
            raise ControllerError("Package C TTY rescue receipt orphan issued_at is malformed")
        try: _parse_utc_instant(orphan_issued_at)
        except ControllerError as exc: raise ControllerError("Package C TTY rescue receipt orphan issued_at is not a valid timestamp") from exc
        issued_at=orphan_issued_at
    rescue_receipt={**rescue_immutable,"rescue_id":rescue_id,"issued_at":issued_at}
    rescue_info=_package_a_adopt_json(rescue_path,tty_rescue_dir,rescue_receipt,"c TTY verification rescue")
    # Archive v2 verification state reference; clear active verification; retain rescue_receipt and correction_used
    state["package_c_v2_archive"]={"kind":"tty_contaminated_verification_v2_terminal","verification":dict(verification),"archived_at":utc()}
    state["package_c_tty_rescue_receipt"]={"path":rescue_info["path"],"sha256":rescue_info["sha256"],"rescue_id":rescue_id,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "bug_class":PACKAGE_C_TTY_RESCUE_BUG_CLASS,"authority_date":PACKAGE_C_TTY_RESCUE_AUTHORITY_DATE}
    state.pop("package_c_verification",None)
    state["gate"]={"kind":"package_c_tty_verification_rescued","verdict":"awaiting_gate",
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "rescue_id":rescue_id,"rescue_receipt_sha256":rescue_info["sha256"],"policy":POLICY_ID}
    save(directory,state)
    result=_package_c_tty_rescue_replay(directory,state,state["package_c_tty_rescue_receipt"])
    result["reused"]=False
    return result


def command_rescue_package_c_tty_contaminated_verification(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_rescue_package_c_tty_contaminated_verification(args)


def _package_c_probe_validate_v3_verification(directory: str,candidate: Dict[str,Any],verification_binding: Any,tty_rescue_bound: Any,v2_archive: Any) -> None:
    if not isinstance(tty_rescue_bound,dict) or set(tty_rescue_bound)!=_TTY_RESCUE_BINDING_KEYS:
        raise ControllerError("Package C probe rescue TTY rescue binding has wrong key set")
    if tty_rescue_bound.get("sha256")!=PACKAGE_C_PROBE_RESCUE_TTY_RESCUE_SHA:
        raise ControllerError("Package C probe rescue TTY rescue receipt SHA mismatch")
    if (tty_rescue_bound.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            tty_rescue_bound.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            tty_rescue_bound.get("bug_class")!=PACKAGE_C_TTY_RESCUE_BUG_CLASS or
            tty_rescue_bound.get("authority_date")!=PACKAGE_C_TTY_RESCUE_AUTHORITY_DATE):
        raise ControllerError("Package C probe rescue TTY rescue binding fields mismatch")
    tty_rescue_dir=_package_c_tty_rescue_dir(directory)
    tty_info=capped_regular_file_info(tty_rescue_bound.get("path"),tty_rescue_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(tty_rescue_bound.get("path"),str) else None
    if not tty_info or tty_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_TTY_RESCUE_SHA:
        raise ControllerError("Package C probe rescue TTY rescue receipt file is missing or changed")
    try: tty_receipt=json.loads(Path(tty_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue TTY rescue receipt is unreadable") from exc
    if not isinstance(tty_receipt,dict) or set(tty_receipt)!=_TTY_RESCUE_RECEIPT_KEYS:
        raise ControllerError("Package C probe rescue TTY rescue receipt schema mismatch")
    if (tty_rescue_bound.get("rescue_id")!=tty_receipt.get("rescue_id") or
            tty_receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            tty_receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST):
        raise ControllerError("Package C probe rescue TTY rescue receipt binding changed")
    if not isinstance(v2_archive,dict) or set(v2_archive)!=_TTY_V2_ARCHIVE_KEYS:
        raise ControllerError("Package C probe rescue v2 archive has wrong key set")
    if v2_archive.get("kind")!="tty_contaminated_verification_v2_terminal":
        raise ControllerError("Package C probe rescue v2 archive has wrong kind")
    try: _parse_utc_instant(v2_archive.get("archived_at"))
    except ControllerError as exc: raise ControllerError("Package C probe rescue v2 archive archived_at is malformed") from exc
    if not isinstance(verification_binding,dict) or set(verification_binding)!=_TTY_V2_VERIFICATION_BINDING_KEYS:
        raise ControllerError("Package C probe rescue v3 verification binding has wrong key set")
    if verification_binding.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID:
        raise ControllerError("Package C probe rescue v3 verification binding candidate_id mismatch")
    if verification_binding.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST:
        raise ControllerError("Package C probe rescue v3 verification binding evidence_digest mismatch")
    verify_dir=_package_c_v3_verification_dir(directory,candidate)
    intent_info=capped_regular_file_info(verification_binding.get("intent_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification_binding.get("intent_path"),str) else None
    if not intent_info or intent_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_V3_INTENT_SHA:
        raise ControllerError("Package C probe rescue v3 intent is missing or changed")
    if verification_binding.get("intent_sha256")!=PACKAGE_C_PROBE_RESCUE_V3_INTENT_SHA:
        raise ControllerError("Package C probe rescue v3 verification binding intent_sha256 mismatch")
    agg_info=capped_regular_file_info(verification_binding.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification_binding.get("aggregate_path"),str) else None
    if not agg_info or agg_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_V3_AGGREGATE_SHA:
        raise ControllerError("Package C probe rescue v3 aggregate is missing or changed")
    if verification_binding.get("aggregate_sha256")!=PACKAGE_C_PROBE_RESCUE_V3_AGGREGATE_SHA:
        raise ControllerError("Package C probe rescue v3 verification binding aggregate_sha256 mismatch")
    try: aggregate=json.loads(Path(agg_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue v3 aggregate is unreadable") from exc
    receipts=aggregate.get("receipts") if isinstance(aggregate,dict) else None
    if not isinstance(receipts,list) or len(receipts)!=9:
        raise ControllerError("Package C probe rescue v3 aggregate must have exactly nine receipts")
    if aggregate.get("all_passed") is not False:
        raise ControllerError("Package C probe rescue v3 aggregate all_passed must be False")
    for ref in receipts[:8]:
        if not isinstance(ref,dict) or ref.get("passed") is not True:
            raise ControllerError("Package C probe rescue v3 aggregate first eight receipts must all have passed=True")
    last=receipts[8]
    if (not isinstance(last,dict) or last.get("label")!="json_probe" or last.get("index")!=8 or
            last.get("sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_RECEIPT_SHA or last.get("passed") is not False):
        raise ControllerError("Package C probe rescue v3 aggregate last receipt binding mismatch")
    receipt_info=capped_regular_file_info(last.get("path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(last.get("path"),str) else None
    if not receipt_info or receipt_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_RECEIPT_SHA:
        raise ControllerError("Package C probe rescue failed probe receipt is missing or changed")
    try: receipt_doc=json.loads(Path(receipt_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue failed probe receipt is unreadable") from exc
    if (not isinstance(receipt_doc,dict) or receipt_doc.get("label")!="json_probe" or receipt_doc.get("index")!=8 or
            receipt_doc.get("passed") is not False or
            receipt_doc.get("terminal_sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_TERMINAL_SHA or
            receipt_doc.get("output_sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_OUTPUT_SHA):
        raise ControllerError("Package C probe rescue failed probe receipt facts do not match probe error signature")
    terminal_info=capped_regular_file_info(receipt_doc.get("terminal_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(receipt_doc.get("terminal_path"),str) else None
    if not terminal_info or terminal_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_TERMINAL_SHA:
        raise ControllerError("Package C probe rescue failed probe terminal file is missing or changed")
    output_info=capped_regular_file_info(receipt_doc.get("output_path"),verify_dir,PACKAGE_C_MAX_GATE_OUTPUT) if isinstance(receipt_doc.get("output_path"),str) else None
    if not output_info or output_info.get("sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_OUTPUT_SHA:
        raise ControllerError("Package C probe rescue failed probe output file is missing or changed")
    try: output_raw=Path(output_info["path"]).read_bytes()
    except OSError as exc: raise ControllerError("Package C probe rescue failed probe output is unreadable") from exc
    try: output_text=output_raw.decode("utf-8")
    except UnicodeDecodeError as exc: raise ControllerError("Package C probe rescue failed probe output is not valid UTF-8") from exc
    try: output_obj=json.loads(output_text)
    except json.JSONDecodeError as exc: raise ControllerError("Package C probe rescue failed probe output is not valid JSON") from exc
    if not isinstance(output_obj,dict) or output_obj.get("error")!=PACKAGE_C_PROBE_RESCUE_FAILED_OUTPUT_TEXT:
        raise ControllerError("Package C probe rescue failed probe output does not contain the exact error message")
    try: intent=json.loads(Path(intent_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue v3 intent is unreadable") from exc
    for i,start_path in enumerate(intent.get("start_paths",[])[:9]):
        si=capped_regular_file_info(start_path,verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(start_path,str) else None
        if not si: raise ControllerError("Package C probe rescue v3 start file for gate %d is missing or unsafe"%i)
    for path in (intent.get("receipt_paths",[])[9:]+intent.get("output_paths",[])[9:]+
                 intent.get("terminal_paths",[])[9:]+intent.get("start_paths",[])[9:]):
        if os.path.lexists(path): raise ControllerError("Package C probe rescue v3 verification has unexpected later-gate evidence")


def _package_c_probe_rescue_replay(directory: str,state: Dict[str,Any],bound: Dict[str,Any]) -> Dict[str,Any]:
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C probe rescue replay requires awaiting_gate phase")
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C probe rescue replay requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C probe rescue replay requires exact evidence digest")
    gate=state.get("gate") if isinstance(state.get("gate"),dict) else {}
    if gate.get("kind")!="package_c_probe_contract_verification_rescued": raise ControllerError("Package C probe rescue replay requires probe_contract_verification_rescued gate kind")
    v3_archive=state.get("package_c_v3_archive")
    if not isinstance(v3_archive,dict) or set(v3_archive)!=_PROBE_V3_ARCHIVE_KEYS:
        raise ControllerError("Package C probe rescue replay requires intact v3_archive with exact keys")
    if v3_archive.get("kind")!="probe_contract_verification_v3_terminal":
        raise ControllerError("Package C probe rescue replay requires probe_contract_verification_v3_terminal archive kind")
    try: _parse_utc_instant(v3_archive.get("archived_at"))
    except ControllerError as exc: raise ControllerError("Package C probe rescue replay v3_archive archived_at is malformed") from exc
    tty_rescue_bound=state.get("package_c_tty_rescue_receipt") if isinstance(state.get("package_c_tty_rescue_receipt"),dict) else None
    _package_c_probe_validate_v3_verification(directory,candidate,v3_archive.get("verification"),tty_rescue_bound,state.get("package_c_v2_archive"))
    probe_rescue_dir=_package_c_probe_rescue_dir(directory)
    info=capped_regular_file_info(bound.get("path"),probe_rescue_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C probe rescue receipt changed")
    try: receipt=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue receipt is unreadable") from exc
    if (not isinstance(receipt,dict) or set(receipt)!=_PROBE_RESCUE_RECEIPT_KEYS or receipt.get("schema_version")!=SCHEMA or
            receipt.get("kind")!="package_c_probe_contract_verification_rescue" or receipt.get("work_id")!=state["work_id"] or
            receipt.get("policy")!=POLICY_ID or receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
            receipt.get("tty_rescue_sha256")!=PACKAGE_C_PROBE_RESCUE_TTY_RESCUE_SHA or
            receipt.get("v3_intent_sha256")!=PACKAGE_C_PROBE_RESCUE_V3_INTENT_SHA or
            receipt.get("v3_aggregate_sha256")!=PACKAGE_C_PROBE_RESCUE_V3_AGGREGATE_SHA or
            receipt.get("failed_probe_receipt_sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_RECEIPT_SHA or
            receipt.get("failed_probe_terminal_sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_TERMINAL_SHA or
            receipt.get("failed_probe_output_sha256")!=PACKAGE_C_PROBE_RESCUE_FAILED_OUTPUT_SHA or
            receipt.get("bug_class")!=PACKAGE_C_PROBE_RESCUE_BUG_CLASS or
            receipt.get("authority_date")!=PACKAGE_C_PROBE_RESCUE_AUTHORITY_DATE or
            receipt.get("rescue_id")!=bound.get("rescue_id")):
        raise ControllerError("Package C probe rescue receipt binding changed")
    if receipt.get("prior_revision")!=PACKAGE_C_PROBE_RESCUE_REVISION:
        raise ControllerError("Package C probe rescue receipt prior_revision does not match sealed binding")
    try: _parse_utc_instant(receipt.get("issued_at"))
    except ControllerError as exc: raise ControllerError("Package C probe rescue receipt issued_at is malformed") from exc
    if not any(row.get("kind")=="package_c_probe_contract_verification_rescued" and row.get("rescue_id")==receipt["rescue_id"]
               for row in recent_events(directory)):
        append_event(directory,"package_c_probe_contract_verification_rescued",rescue_id=receipt["rescue_id"],
            candidate_id=receipt["candidate_id"],evidence_digest=receipt["evidence_digest"],
            v3_aggregate_sha256=receipt["v3_aggregate_sha256"],next_state="awaiting_gate")
    return {"schema_version":SCHEMA,"operation":"rescue_package_c_probe_contract_verification","phase":"awaiting_gate",
            "rescue_id":receipt["rescue_id"],"rescue_receipt_sha256":info["sha256"],
            "candidate_id":receipt["candidate_id"],"reused":True}


def _command_rescue_package_c_probe_contract_verification(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state): raise ControllerError("Package C probe rescue requires its canonical identity")
    probe_bound=state.get("package_c_probe_rescue_receipt")
    if probe_bound is not None:
        if (not isinstance(probe_bound,dict) or set(probe_bound)!=_PROBE_RESCUE_BINDING_KEYS or
                not isinstance(probe_bound.get("path"),str) or
                not isinstance(probe_bound.get("sha256"),str) or len(probe_bound.get("sha256",""))!=64 or
                not isinstance(probe_bound.get("rescue_id"),str) or len(probe_bound.get("rescue_id",""))!=64 or
                probe_bound.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
                probe_bound.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
                probe_bound.get("bug_class")!=PACKAGE_C_PROBE_RESCUE_BUG_CLASS or
                probe_bound.get("authority_date")!=PACKAGE_C_PROBE_RESCUE_AUTHORITY_DATE):
            raise ControllerError("Package C probe rescue receipt state binding is malformed or tampered")
        return _package_c_probe_rescue_replay(directory,state,probe_bound)
    if state.get("phase")!="awaiting_gate": raise ControllerError("Package C probe rescue requires awaiting_gate phase")
    if state.get("revision")!=PACKAGE_C_PROBE_RESCUE_REVISION: raise ControllerError("Package C probe rescue requires exact revision %d"%PACKAGE_C_PROBE_RESCUE_REVISION)
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C probe rescue requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C probe rescue requires exact evidence digest")
    tty_rescue_bound=state.get("package_c_tty_rescue_receipt") if isinstance(state.get("package_c_tty_rescue_receipt"),dict) else None
    if tty_rescue_bound is None: raise ControllerError("Package C probe rescue requires TTY verification rescue receipt")
    verification=state.get("package_c_verification") if isinstance(state.get("package_c_verification"),dict) else None
    if not verification: raise ControllerError("Package C probe rescue requires an active failed v3 verification binding")
    v2_archive=state.get("package_c_v2_archive") if isinstance(state.get("package_c_v2_archive"),dict) else None
    if not v2_archive: raise ControllerError("Package C probe rescue requires the v2 verification archive from TTY rescue")
    _package_c_probe_validate_v3_verification(directory,candidate,verification,tty_rescue_bound,v2_archive)
    correction_used=state.get("package_c_correction_used")
    if not isinstance(correction_used,dict) or not correction_used:
        raise ControllerError("Package C probe rescue requires correction_used to be recorded")
    root=os.path.dirname(directory)
    require_frozen_brief(state,directory)
    if state["brief"]["sha256"]!=PACKAGE_C_BRIEF_SHA256: raise ControllerError("Package C brief SHA-256 changed")
    _package_c_v3_plan_intact(root)
    baseline=_package_c_prerequisites_intact(directory,state)
    _package_c_attempt_intact(state.get("attempt"))
    _package_c_candidate_intact(directory,state,candidate,baseline)
    probe_rescue_dir=_package_c_probe_rescue_dir(directory)
    if os.path.lexists(probe_rescue_dir) and (os.path.islink(probe_rescue_dir) or not os.path.isdir(probe_rescue_dir) or not inside(real(probe_rescue_dir),directory)):
        raise ControllerError("Package C probe rescue directory is unsafe")
    os.makedirs(probe_rescue_dir,mode=0o700,exist_ok=True)
    rescue_immutable={"schema_version":SCHEMA,"kind":"package_c_probe_contract_verification_rescue","work_id":state["work_id"],"policy":POLICY_ID,
        "bug_class":PACKAGE_C_PROBE_RESCUE_BUG_CLASS,"authority_date":PACKAGE_C_PROBE_RESCUE_AUTHORITY_DATE,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "tty_rescue_sha256":PACKAGE_C_PROBE_RESCUE_TTY_RESCUE_SHA,
        "v3_intent_sha256":PACKAGE_C_PROBE_RESCUE_V3_INTENT_SHA,
        "v3_aggregate_sha256":PACKAGE_C_PROBE_RESCUE_V3_AGGREGATE_SHA,
        "failed_probe_receipt_sha256":PACKAGE_C_PROBE_RESCUE_FAILED_RECEIPT_SHA,
        "failed_probe_terminal_sha256":PACKAGE_C_PROBE_RESCUE_FAILED_TERMINAL_SHA,
        "failed_probe_output_sha256":PACKAGE_C_PROBE_RESCUE_FAILED_OUTPUT_SHA,
        "prior_revision":state["revision"]}
    rescue_id=digest_bytes(json.dumps(rescue_immutable,sort_keys=True,separators=(",",":")).encode())
    rescue_path=os.path.join(probe_rescue_dir,rescue_id+".json")
    issued_at=utc()
    if os.path.lexists(rescue_path):
        if os.path.islink(rescue_path): raise ControllerError("Package C probe rescue receipt orphan is a symlink")
        orphan_info=capped_regular_file_info(rescue_path,probe_rescue_dir,MAX_PLAN_ARTIFACT_BYTES)
        if not orphan_info: raise ControllerError("Package C probe rescue receipt orphan is not a safe regular file")
        try: orphan=json.loads(Path(orphan_info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C probe rescue receipt orphan is unreadable") from exc
        orphan_expected_keys=set(rescue_immutable)|{"rescue_id","issued_at"}
        if not isinstance(orphan,dict) or set(orphan)!=orphan_expected_keys:
            raise ControllerError("Package C probe rescue receipt orphan has unexpected keys")
        if orphan.get("rescue_id")!=rescue_id:
            raise ControllerError("Package C probe rescue receipt orphan rescue_id conflicts")
        for k,v in rescue_immutable.items():
            if orphan.get(k)!=v: raise ControllerError("Package C probe rescue receipt orphan field %s conflicts"%k)
        orphan_issued_at=orphan.get("issued_at")
        if not isinstance(orphan_issued_at,str) or not orphan_issued_at:
            raise ControllerError("Package C probe rescue receipt orphan issued_at is malformed")
        try: _parse_utc_instant(orphan_issued_at)
        except ControllerError as exc: raise ControllerError("Package C probe rescue receipt orphan issued_at is not a valid timestamp") from exc
        issued_at=orphan_issued_at
    rescue_receipt={**rescue_immutable,"rescue_id":rescue_id,"issued_at":issued_at}
    rescue_info=_package_a_adopt_json(rescue_path,probe_rescue_dir,rescue_receipt,"c probe rescue")
    state["package_c_v3_archive"]={"kind":"probe_contract_verification_v3_terminal","verification":dict(verification),"archived_at":utc()}
    state["package_c_probe_rescue_receipt"]={"path":rescue_info["path"],"sha256":rescue_info["sha256"],"rescue_id":rescue_id,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "bug_class":PACKAGE_C_PROBE_RESCUE_BUG_CLASS,"authority_date":PACKAGE_C_PROBE_RESCUE_AUTHORITY_DATE}
    state.pop("package_c_verification",None)
    state["gate"]={"kind":"package_c_probe_contract_verification_rescued","verdict":"awaiting_gate",
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "rescue_id":rescue_id,"rescue_receipt_sha256":rescue_info["sha256"],"policy":POLICY_ID}
    save(directory,state)
    result=_package_c_probe_rescue_replay(directory,state,state["package_c_probe_rescue_receipt"])
    result["reused"]=False
    return result


def command_rescue_package_c_probe_contract_verification(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_rescue_package_c_probe_contract_verification(args)


def _command_rescue_package_c_gate_selection(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id); state=load(directory)
    if not _is_package_c(state): raise ControllerError("Package C gate-selection rescue requires its canonical identity")
    rescue_bound=state.get("package_c_rescue_receipt")
    if rescue_bound is not None:
        if (not isinstance(rescue_bound,dict) or set(rescue_bound)!=_RESCUE_BINDING_KEYS or
                not isinstance(rescue_bound.get("path"),str) or
                not isinstance(rescue_bound.get("sha256"),str) or len(rescue_bound.get("sha256",""))!=64 or
                not isinstance(rescue_bound.get("rescue_id"),str) or len(rescue_bound.get("rescue_id",""))!=64 or
                rescue_bound.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
                rescue_bound.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST or
                rescue_bound.get("selector_bug")!=PACKAGE_C_RESCUE_SELECTOR_BUG or
                rescue_bound.get("authority_date")!=PACKAGE_C_RESCUE_AUTHORITY_DATE):
            raise ControllerError("Package C rescue receipt state binding is malformed or tampered")
        return _package_c_rescue_replay(directory,state,rescue_bound)
    # Accept only the exact bound terminal state
    if state.get("phase")!="failed": raise ControllerError("Package C gate-selection rescue requires failed phase")
    if state.get("revision")!=PACKAGE_C_RESCUE_REVISION: raise ControllerError("Package C gate-selection rescue requires exact revision %d"%PACKAGE_C_RESCUE_REVISION)
    candidate=state.get("candidate") if isinstance(state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RESCUE_CANDIDATE_ID: raise ControllerError("Package C gate-selection rescue requires exact candidate id")
    if candidate.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST: raise ControllerError("Package C gate-selection rescue requires exact evidence digest")
    # Verify v1 selector is no longer active in specs
    v2_specs=_package_c_verification_specs()
    pending_spec=next((s for s in v2_specs if s["label"]=="pending_linkage_focused"),None)
    repair_spec=next((s for s in v2_specs if s["label"]=="gate_repair_focused"),None)
    if (not pending_spec or any(t in pending_spec["argv"] for t in _PACKAGE_C_FOCUSED_PENDING_TESTS_V1) or
            not repair_spec or any(t in repair_spec["argv"] for t in _PACKAGE_C_FOCUSED_REPAIR_TESTS_V1)):
        raise ControllerError("Selector-v1 invented test IDs still present in verification specs")
    # Check verification aggregate binding
    verification=state.get("package_c_verification") if isinstance(state.get("package_c_verification"),dict) else {}
    if verification.get("aggregate_sha256")!=PACKAGE_C_RESCUE_FAILED_AGGREGATE_SHA256:
        raise ControllerError("Package C rescue requires the exact failed verification aggregate")
    # Check terminal gate receipt binding
    gate_bound=state.get("package_c_gate_receipt") if isinstance(state.get("package_c_gate_receipt"),dict) else {}
    if gate_bound.get("sha256")!=PACKAGE_C_RESCUE_TERMINAL_GATE_SHA256:
        raise ControllerError("Package C rescue requires the exact terminal gate receipt")
    # Check correction history (first adjudication revise receipt) and correction_used (correction was launched)
    correction_history=state.get("package_c_correction_history")
    if not isinstance(correction_history,list) or not correction_history:
        raise ControllerError("Package C rescue requires a non-empty correction history")
    correction_used=state.get("package_c_correction_used")
    if not isinstance(correction_used,dict) or not correction_used:
        raise ControllerError("Package C rescue requires correction_used to be recorded as consumed")
    # Validate terminal gate receipt on disk
    gate_dir=os.path.join(directory,"package-c-gates")
    gate_info=capped_regular_file_info(gate_bound.get("path"),gate_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(gate_bound.get("path"),str) else None
    if not gate_info or gate_info.get("sha256")!=PACKAGE_C_RESCUE_TERMINAL_GATE_SHA256:
        raise ControllerError("Package C terminal gate receipt is missing or changed")
    try: gate_receipt=json.loads(Path(gate_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C terminal gate receipt is unreadable") from exc
    if (gate_receipt.get("disposition")!="fail" or gate_receipt.get("reason_code")!="correction_exhausted" or
            gate_receipt.get("candidate_id")!=PACKAGE_C_RESCUE_CANDIDATE_ID or
            gate_receipt.get("evidence_digest")!=PACKAGE_C_RESCUE_EVIDENCE_DIGEST):
        raise ControllerError("Package C terminal gate receipt does not match bound correction-exhausted state")
    # Validate failed verification aggregate and failed pending receipt on disk
    verify_dir=_package_c_verification_dir(directory,candidate)
    agg_info=capped_regular_file_info(verification.get("aggregate_path"),verify_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification.get("aggregate_path"),str) else None
    if not agg_info or agg_info.get("sha256")!=PACKAGE_C_RESCUE_FAILED_AGGREGATE_SHA256:
        raise ControllerError("Package C failed verification aggregate is missing or changed")
    try: aggregate=json.loads(Path(agg_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C failed verification aggregate is unreadable") from exc
    receipts=aggregate.get("receipts") if isinstance(aggregate,dict) else None
    if not isinstance(receipts,list): raise ControllerError("Package C failed aggregate receipts are malformed")
    pending_ref=next((r for r in receipts if isinstance(r,dict) and r.get("label")=="pending_linkage_focused"),None)
    if not pending_ref or pending_ref.get("sha256")!=PACKAGE_C_RESCUE_FAILED_PENDING_SHA256:
        raise ControllerError("Package C failed pending receipt SHA-256 mismatch")
    # Validate candidate test_cowork.py SHA (the unchanged candidate bytes)
    wt=state["worktree"]["path"]
    tc_info=capped_regular_file_info(os.path.join(wt,"scripts/test_cowork.py"),wt,MAX_CANDIDATE_PATH_BYTES)
    if not tc_info or tc_info.get("sha256")!=PACKAGE_C_RESCUE_TEST_COWORK_SHA256:
        raise ControllerError("Package C candidate scripts/test_cowork.py SHA-256 mismatch")
    # Validate full Package C authority chain
    root=os.path.dirname(directory)
    require_frozen_brief(state,directory)
    if state["brief"]["sha256"]!=PACKAGE_C_BRIEF_SHA256: raise ControllerError("Package C brief SHA-256 changed")
    _package_c_v3_plan_intact(root)
    baseline=_package_c_prerequisites_intact(directory,state)
    _package_c_attempt_intact(state.get("attempt"))
    _package_c_candidate_intact(directory,state,candidate,baseline)
    # Write rescue receipt (immutable gate — must happen before state mutation)
    rescue_dir=_package_c_rescue_dir(directory)
    if os.path.lexists(rescue_dir) and (os.path.islink(rescue_dir) or not os.path.isdir(rescue_dir) or not inside(real(rescue_dir),directory)):
        raise ControllerError("Package C rescue directory is unsafe")
    os.makedirs(rescue_dir,mode=0o700,exist_ok=True)
    rescue_immutable={"schema_version":SCHEMA,"kind":"package_c_gate_selection_rescue","work_id":state["work_id"],"policy":POLICY_ID,
        "bug_class":PACKAGE_C_RESCUE_SELECTOR_BUG,"authority_date":PACKAGE_C_RESCUE_AUTHORITY_DATE,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "failed_aggregate_sha256":PACKAGE_C_RESCUE_FAILED_AGGREGATE_SHA256,
        "failed_pending_receipt_sha256":PACKAGE_C_RESCUE_FAILED_PENDING_SHA256,
        "terminal_gate_receipt_sha256":PACKAGE_C_RESCUE_TERMINAL_GATE_SHA256,
        "selector_v2_pending_tests":list(PACKAGE_C_FOCUSED_PENDING_TESTS),
        "selector_v2_repair_tests":list(PACKAGE_C_FOCUSED_REPAIR_TESTS),
        "prior_revision":state["revision"]}
    rescue_id=digest_bytes(json.dumps(rescue_immutable,sort_keys=True,separators=(",",":")).encode())
    rescue_path=os.path.join(rescue_dir,rescue_id+".json")
    issued_at=utc()
    # Detect safe bounded orphan from a prior crash (receipt written, state save not yet committed)
    if os.path.lexists(rescue_path):
        if os.path.islink(rescue_path): raise ControllerError("Package C rescue receipt orphan is a symlink")
        orphan_info=capped_regular_file_info(rescue_path,rescue_dir,MAX_PLAN_ARTIFACT_BYTES)
        if not orphan_info: raise ControllerError("Package C rescue receipt orphan is not a safe regular file")
        try: orphan=json.loads(Path(orphan_info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C rescue receipt orphan is unreadable") from exc
        orphan_expected_keys=set(rescue_immutable)|{"rescue_id","issued_at"}
        if not isinstance(orphan,dict) or set(orphan)!=orphan_expected_keys:
            raise ControllerError("Package C rescue receipt orphan has unexpected keys")
        if orphan.get("rescue_id")!=rescue_id:
            raise ControllerError("Package C rescue receipt orphan rescue_id conflicts")
        for k,v in rescue_immutable.items():
            if orphan.get(k)!=v: raise ControllerError("Package C rescue receipt orphan field %s conflicts"%k)
        orphan_issued_at=orphan.get("issued_at")
        if not isinstance(orphan_issued_at,str) or not orphan_issued_at:
            raise ControllerError("Package C rescue receipt orphan issued_at is malformed")
        try: _parse_utc_instant(orphan_issued_at)
        except ControllerError as exc: raise ControllerError("Package C rescue receipt orphan issued_at is not a valid timestamp") from exc
        issued_at=orphan_issued_at
    rescue_receipt={**rescue_immutable,"rescue_id":rescue_id,"issued_at":issued_at}
    rescue_info=_package_a_adopt_json(rescue_path,rescue_dir,rescue_receipt,"c gate selection rescue")
    # Archive v1 state references; clear active verification and gate receipt; transition to awaiting_gate
    state["package_c_v1_archive"]={"kind":"gate_selection_v1_terminal","gate_receipt":dict(gate_bound),
        "verification":dict(verification),"archived_at":utc()}
    state["package_c_rescue_receipt"]={"path":rescue_info["path"],"sha256":rescue_info["sha256"],"rescue_id":rescue_id,
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "selector_bug":PACKAGE_C_RESCUE_SELECTOR_BUG,"authority_date":PACKAGE_C_RESCUE_AUTHORITY_DATE}
    state.pop("package_c_verification",None)
    state.pop("package_c_gate_receipt",None)
    state["phase"]="awaiting_gate"
    state["gate"]={"kind":"package_c_gate_selection_rescued","verdict":"awaiting_gate",
        "candidate_id":PACKAGE_C_RESCUE_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RESCUE_EVIDENCE_DIGEST,
        "rescue_id":rescue_id,"rescue_receipt_sha256":rescue_info["sha256"],"policy":POLICY_ID}
    save(directory,state)
    result=_package_c_rescue_replay(directory,state,state["package_c_rescue_receipt"])
    result["reused"]=False
    return result


def command_rescue_package_c_gate_selection(args: argparse.Namespace) -> Dict[str,Any]:
    directory=work_dir(real(args.state_root),args.work_id)
    with package_lock(directory): return _command_rescue_package_c_gate_selection(args)


# ---------------------------------------------------------------------------
# Package C independent-review recovery lifecycle
# ---------------------------------------------------------------------------

def _package_c_rr_source_intact(root: str) -> Tuple[str, Dict[str,Any]]:
    """Validate frozen Package C source state against all brief authority bindings."""
    source_dir=work_dir(root,PACKAGE_C_RR_SOURCE_WORK_ID)
    try: raw=Path(state_path(source_dir)).read_bytes()
    except OSError as exc: raise ControllerError("Package C RR source state is unreadable") from exc
    if digest_bytes(raw)!=PACKAGE_C_RR_SOURCE_STATE_SHA256: raise ControllerError("Package C RR source state SHA-256 changed from brief authority")
    try: source_state=json.loads(raw)
    except json.JSONDecodeError as exc: raise ControllerError("Package C RR source state is not valid JSON") from exc
    if source_state.get("revision")!=PACKAGE_C_RR_SOURCE_REVISION: raise ControllerError("Package C RR source state revision changed")
    if source_state.get("phase")!="failed": raise ControllerError("Package C RR source state phase is not failed")
    candidate=source_state.get("candidate") if isinstance(source_state.get("candidate"),dict) else {}
    if candidate.get("id")!=PACKAGE_C_RR_CANDIDATE_ID or candidate.get("evidence_digest")!=PACKAGE_C_RR_EVIDENCE_DIGEST:
        raise ControllerError("Package C RR source candidate identity changed")
    evidence=candidate.get("evidence") if isinstance(candidate.get("evidence"),dict) else {}
    fp=evidence.get("worktree_fingerprint") if isinstance(evidence.get("worktree_fingerprint"),dict) else {}
    if fp.get("digest")!=PACKAGE_C_RR_FINGERPRINT: raise ControllerError("Package C RR source candidate fingerprint changed")
    verification=source_state.get("package_c_verification") if isinstance(source_state.get("package_c_verification"),dict) else {}
    if verification.get("aggregate_sha256")!=PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256:
        raise ControllerError("Package C RR source verification aggregate SHA-256 changed")
    v4_dir=os.path.join(source_dir,"package-c-verification-v4")
    agg_info=capped_regular_file_info(verification.get("aggregate_path"),v4_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(verification.get("aggregate_path"),str) else None
    if not agg_info or agg_info.get("sha256")!=PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256: raise ControllerError("Package C RR source verification aggregate file changed")
    gate_bound=source_state.get("package_c_gate_receipt") if isinstance(source_state.get("package_c_gate_receipt"),dict) else {}
    gate_dir=os.path.join(source_dir,"package-c-gates")
    gate_info=capped_regular_file_info(gate_bound.get("path"),gate_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(gate_bound.get("path"),str) else None
    if not gate_info or gate_info.get("sha256")!=PACKAGE_C_RR_FAILED_GATE_SHA256: raise ControllerError("Package C RR source failed gate receipt changed")
    try: gate_doc=json.loads(Path(gate_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR source failed gate receipt is unreadable") from exc
    if gate_doc.get("reason_code")!=PACKAGE_C_RR_GATE_REASON: raise ControllerError("Package C RR source failed gate reason_code changed")
    attempts_dir=os.path.join(source_dir,"package-c-review-attempts")
    for expected_sha,label in ((PACKAGE_C_RR_FIRST_TIMEOUT_SHA256,"first"),(PACKAGE_C_RR_SECOND_TIMEOUT_SHA256,"second")):
        found=False
        if os.path.isdir(attempts_dir):
            for fname in os.listdir(attempts_dir):
                if not fname.endswith(".terminal.json"): continue
                fpath=os.path.join(attempts_dir,fname)
                if os.path.islink(fpath): continue
                try: fdata=Path(fpath).read_bytes()
                except OSError: continue
                if digest_bytes(fdata)==expected_sha: found=True; break
        if not found: raise ControllerError("Package C RR source %s timeout terminal receipt is missing or changed"%label)
    return source_dir, source_state


def _package_c_rr_aggregate_intact(source_dir: str, source_state: Dict[str,Any]) -> Tuple[str, List[Dict[str,Any]]]:
    """Return (aggregate_path, receipt_refs) from the verified v4 aggregate."""
    verification=source_state.get("package_c_verification") if isinstance(source_state.get("package_c_verification"),dict) else {}
    agg_path=verification.get("aggregate_path","")
    v4_dir=os.path.join(source_dir,"package-c-verification-v4")
    agg_info=capped_regular_file_info(agg_path,v4_dir,MAX_PLAN_ARTIFACT_BYTES) if agg_path else None
    if not agg_info or agg_info.get("sha256")!=PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256: raise ControllerError("Package C RR verification aggregate changed")
    try: agg=json.loads(Path(agg_info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR verification aggregate is unreadable") from exc
    refs=agg.get("receipts") if isinstance(agg,dict) else None
    if not isinstance(refs,list) or len(refs)!=9 or not all(isinstance(r,dict) and r.get("passed") is True for r in refs):
        raise ControllerError("Package C RR verification aggregate receipts changed or not all-pass")
    return agg_info["path"], refs


def _package_c_rr_dossier_content(rr_dir: str, rr_state: Dict[str,Any], source_dir: str, source_state: Dict[str,Any], agg_path: str, refs: List[Dict[str,Any]]) -> Dict[str,Any]:
    """Build the bounded dossier from the read-only Package C candidate."""
    candidate=source_state.get("candidate") if isinstance(source_state.get("candidate"),dict) else {}
    wt=source_state.get("worktree",{}).get("path","")
    if not wt or not os.path.isdir(wt): raise ControllerError("Package C RR product worktree is not accessible")
    gate_bound=source_state.get("package_c_gate_receipt") if isinstance(source_state.get("package_c_gate_receipt"),dict) else {}
    gate_summaries=[{"index":r["index"],"label":r["label"],"sha256":r["sha256"],"passed":r["passed"]} for r in refs]
    # Read the key new production file (cowork_dispatch.py)
    dispatch_path=os.path.join(wt,"scripts/cowork_dispatch.py")
    dispatch_info=capped_regular_file_info(dispatch_path,wt,MAX_CANDIDATE_PATH_BYTES)
    if not dispatch_info: raise ControllerError("Package C RR cowork_dispatch.py is not a safe regular file")
    try: dispatch_text=Path(dispatch_info["path"]).read_text(encoding="utf-8")
    except (OSError,UnicodeDecodeError) as exc: raise ControllerError("Package C RR cowork_dispatch.py is unreadable") from exc
    # Git diffs for modified files (cap each to avoid overflow)
    diffs={}
    _DIFF_CAP=24*1024
    for rel in ("scripts/cowork.py","scripts/cowork_state.py","scripts/test_cowork.py"):
        try: r=subprocess.run(["git","diff","HEAD","--",rel],cwd=wt,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
        except subprocess.TimeoutExpired as exc: raise ControllerError("Package C RR git diff timed out") from exc
        if r.returncode not in (0,1): raise ControllerError("Package C RR git diff failed for "+rel)
        text=r.stdout[:_DIFF_CAP].decode("utf-8","replace")
        diffs[rel]=text if len(r.stdout)<=_DIFF_CAP else text+"...[truncated]"
    # Read the fixture (small)
    fixture_path=os.path.join(wt,"scripts/fixtures/dispatch_contract_characterization_sources.json")
    fixture_info=capped_regular_file_info(fixture_path,wt,64*1024)
    fixture_text=None
    if fixture_info:
        try: fixture_text=Path(fixture_info["path"]).read_text(encoding="utf-8")
        except (OSError,UnicodeDecodeError): fixture_text=None
    # File-hash table for all 6 changed paths
    file_hashes={}
    for rel in PACKAGE_C_RR_CHANGED_PATHS:
        p=os.path.join(wt,rel)
        info=capped_regular_file_info(p,wt,MAX_CANDIDATE_PATH_BYTES)
        if info: file_hashes[rel]=info["sha256"]
    dossier={"schema_version":SCHEMA,"kind":"package_c_rr_review_dossier",
             "package_id":PACKAGE_C_RR_PACKAGE_ID,"policy":POLICY_ID,
             "candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest"),
             "candidate_fingerprint_digest":PACKAGE_C_RR_FINGERPRINT,
             "source_work_id":PACKAGE_C_RR_SOURCE_WORK_ID,"source_revision":PACKAGE_C_RR_SOURCE_REVISION,
             "source_state_sha256":PACKAGE_C_RR_SOURCE_STATE_SHA256,
             "verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,
             "failed_gate_sha256":PACKAGE_C_RR_FAILED_GATE_SHA256,
             "gate_reason":PACKAGE_C_RR_GATE_REASON,
             "first_timeout_sha256":PACKAGE_C_RR_FIRST_TIMEOUT_SHA256,
             "second_timeout_sha256":PACKAGE_C_RR_SECOND_TIMEOUT_SHA256,
             "controller_source_sha256":PACKAGE_C_RR_CONTROLLER_SOURCE_SHA256,
             "controller_tests_sha256":PACKAGE_C_RR_CONTROLLER_TESTS_SHA256,
             "changed_paths":PACKAGE_C_RR_CHANGED_PATHS,
             "file_hashes":file_hashes,
             "gate_summaries":gate_summaries,
             "verification_receipt_sha256s":[r["sha256"] for r in refs],
             "authority_statement":("Package C controller-owned independent-review recovery. "
                                    "The candidate passed all nine v4 deterministic gates. "
                                    "Two prior review attempts were killed at the 300-second controller limit. "
                                    "This recovery uses a 900-second bounded reviewer. "
                                    "Review cowork_dispatch.py AttemptLink/v1 seam, "
                                    "pending-turn source-precedence save/replay linkage, "
                                    "gate-repair delivery linkage, and confirm Package B refusal behavior unchanged. "
                                    "No new implementation. Read-only review of candidate files and this dossier only."),
             "production_module":dispatch_text,
             "changed_file_diffs":diffs,
             "fixture":fixture_text,
             "created_at":utc()}
    return dossier


def _command_build_package_c_rr_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir)
    if rr_state.get("rr_review"): raise ControllerError("Package C RR dossier cannot be rebuilt after review is ingested")
    root=os.path.dirname(rr_dir); source_dir,source_state=_package_c_rr_source_intact(root)
    agg_path,refs=_package_c_rr_aggregate_intact(source_dir,source_state)
    candidate=source_state.get("candidate") if isinstance(source_state.get("candidate"),dict) else {}
    dossier_dir=os.path.join(rr_dir,"rr-dossier")
    if rr_state.get("rr_dossier"):
        bound=rr_state["rr_dossier"]
        info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_C_RR_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
        if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C RR dossier changed")
        return {"schema_version":SCHEMA,"operation":"build_package_c_rr_dossier","reused":True,"path":info["path"],"sha256":info["sha256"],"bytes":info["bytes"]}
    if os.path.lexists(dossier_dir) and (os.path.islink(dossier_dir) or not os.path.isdir(dossier_dir)): raise ControllerError("Package C RR dossier directory is unsafe")
    os.makedirs(dossier_dir,mode=0o700,exist_ok=True)
    dossier=_package_c_rr_dossier_content(rr_dir,rr_state,source_dir,source_state,agg_path,refs)
    encoded=(json.dumps(dossier,sort_keys=True,indent=2)+"\n").encode("utf-8")
    if len(encoded)>PACKAGE_C_RR_DOSSIER_CAP: raise ControllerError("Package C RR dossier exceeds 128 KiB cap (%d bytes)"%len(encoded))
    dossier_path=os.path.join(dossier_dir,candidate.get("id","unknown")+".rr-dossier.json")
    info=_package_a_adopt_bytes(dossier_path,dossier_dir,encoded,"c rr dossier")
    rr_state["rr_dossier"]={"path":dossier_path,"sha256":info["sha256"],"bytes":info["bytes"],"candidate_id":candidate.get("id"),"evidence_digest":candidate.get("evidence_digest")}
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"build_package_c_rr_dossier","reused":False,"path":dossier_path,"sha256":info["sha256"],"bytes":info["bytes"]}


def command_build_package_c_rr_dossier(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id)
    with package_lock(rr_dir): return _command_build_package_c_rr_dossier(args)


def _package_c_rr_dossier_intact(rr_dir: str, rr_state: Dict[str,Any]) -> Dict[str,Any]:
    bound=rr_state.get("rr_dossier") if isinstance(rr_state.get("rr_dossier"),dict) else {}
    if set(bound)!={"path","sha256","bytes","candidate_id","evidence_digest"}: raise ControllerError("Package C RR dossier state binding is malformed")
    dossier_dir=os.path.join(rr_dir,"rr-dossier")
    info=capped_regular_file_info(bound.get("path"),dossier_dir,PACKAGE_C_RR_DOSSIER_CAP) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256") or info.get("bytes")!=bound.get("bytes"): raise ControllerError("Package C RR dossier changed")
    if bound.get("candidate_id")!=PACKAGE_C_RR_CANDIDATE_ID or bound.get("evidence_digest")!=PACKAGE_C_RR_EVIDENCE_DIGEST: raise ControllerError("Package C RR dossier candidate binding changed")
    return {"path":info["path"],"sha256":info["sha256"],"bytes":info["bytes"]}


def _package_c_rr_review_schema(rr_state: Dict[str,Any], context: Dict[str,Any], attempt_id: str, run: str, nonce: str) -> Dict[str,Any]:
    dossier=context["dossier"]; refs=context["refs"]
    return {"type":"object","additionalProperties":False,
        "required":["schema_version","kind","package_id","policy","review_attempt_id","backend","actor_id","run_id","review_nonce",
                    "candidate_id","evidence_digest","dossier_sha256","verification_aggregate_sha256",
                    "verification_receipt_sha256s","changed_paths","verdict","findings","checks"],
        "properties":{
            "schema_version":{"type":"integer","const":1},"kind":{"type":"string","const":"package_c_rr_review"},
            "package_id":{"type":"string","const":PACKAGE_C_RR_PACKAGE_ID},
            "policy":{"type":"string","const":POLICY_ID},"review_attempt_id":{"type":"string","const":attempt_id},
            "backend":{"type":"string","const":PACKAGE_C_RR_REVIEW_BACKEND},"actor_id":{"type":"string","const":PACKAGE_C_RR_REVIEW_ACTOR},
            "run_id":{"type":"string","const":run},"review_nonce":{"type":"string","const":nonce},
            "candidate_id":{"type":"string","const":PACKAGE_C_RR_CANDIDATE_ID},
            "evidence_digest":{"type":"string","const":PACKAGE_C_RR_EVIDENCE_DIGEST},
            "dossier_sha256":{"type":"string","const":dossier["sha256"]},
            "verification_aggregate_sha256":{"type":"string","const":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256},
            "verification_receipt_sha256s":{"type":"array","minItems":9,"maxItems":9,"items":{"type":"string"}},
            "changed_paths":{"type":"array","minItems":6,"maxItems":6,"items":{"type":"string"}},
            "verdict":{"type":"string","enum":["pass","needs_correction","fail"]},
            "findings":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
            "checks":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":1000}},
        }}


def _package_c_rr_review_expected(rr_state: Dict[str,Any], context: Dict[str,Any], attempt: Dict[str,Any]) -> Dict[str,Any]:
    dossier=context["dossier"]; refs=context["refs"]
    return {"schema_version":SCHEMA,"kind":"package_c_rr_review","package_id":PACKAGE_C_RR_PACKAGE_ID,
            "policy":POLICY_ID,"review_attempt_id":attempt["id"],
            "backend":PACKAGE_C_RR_REVIEW_BACKEND,"actor_id":PACKAGE_C_RR_REVIEW_ACTOR,
            "run_id":attempt["run_id"],"review_nonce":attempt["nonce"],
            "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
            "dossier_sha256":dossier["sha256"],
            "verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,
            "verification_receipt_sha256s":[r["sha256"] for r in refs],
            "changed_paths":PACKAGE_C_RR_CHANGED_PATHS}


def _package_c_rr_review_terminal(rr_dir: str, attempt: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    review_dir=os.path.join(rr_dir,"rr-review-attempts")
    receipt=capped_regular_file_info(attempt.get("receipt_path"),review_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(attempt.get("receipt_path"),str) else None
    if not receipt: raise ControllerError("Package C RR review terminal receipt is missing or unsafe")
    try: terminal=json.loads(Path(receipt["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR review terminal receipt is unreadable") from exc
    keys={"schema_version","kind","policy","attempt_id","argv_digest","nonce","started_at","finished_at","exit_code","output_path","output_sha256","output_bytes","stdout_sha256","stdout_bytes","stderr_sha256","stderr_bytes","timed_out","output_limit_exceeded"}
    expected={"schema_version":SCHEMA,"kind":PACKAGE_C_RR_TERMINAL_KIND,"policy":POLICY_ID,"attempt_id":attempt.get("id"),"argv_digest":attempt.get("argv_digest"),"nonce":attempt.get("nonce"),"output_path":attempt.get("output_path")}
    if (not isinstance(terminal,dict) or set(terminal)!=keys or any(terminal.get(k)!=v for k,v in expected.items()) or
            not isinstance(terminal.get("started_at"),str) or not isinstance(terminal.get("finished_at"),str) or
            isinstance(terminal.get("exit_code"),bool) or not isinstance(terminal.get("exit_code"),int) or
            isinstance(terminal.get("output_bytes"),bool) or not isinstance(terminal.get("output_bytes"),int) or terminal["output_bytes"]<0 or
            not isinstance(terminal.get("timed_out"),bool) or not isinstance(terminal.get("output_limit_exceeded"),bool) or
            (terminal.get("output_sha256") is not None and not _sha256_hex(terminal.get("output_sha256")))):
        raise ControllerError("Package C RR review terminal binding changed")
    for label in ("stdout","stderr"):
        item=capped_regular_file_info(attempt.get(label),os.path.join(rr_dir,"logs"),PACKAGE_C_RR_REVIEW_LOG_CAP) if isinstance(attempt.get(label),str) else None
        if not item or terminal.get(label+"_sha256")!=item["sha256"] or terminal.get(label+"_bytes")!=item["bytes"]: raise ControllerError("Package C RR review terminal log binding changed")
    return terminal,receipt


def _package_c_rr_review_attempt_intact(rr_dir: str, rr_state: Dict[str,Any], context: Dict[str,Any], attempt: Dict[str,Any]) -> Dict[str,Any]:
    base={"id","actor_id","run_id","nonce","prepared_at","launch_deadline","backend","candidate_id","evidence_digest","policy","schema_path","schema_sha256","output_path","reviewer_session_id","stdout","stderr","receipt_path","receipt_sha256","argv_digest","binding_sha256","pid","pgid","consumed_at"}
    variants=(base,base|{"started_at"},base|{"spawn_error","spawn_error_sha256","terminal_at"},base|{"launch_lost","launch_lost_sha256","terminal_at"},base|{"started_at","packet_sha256","provider_session_id"})
    if not isinstance(attempt,dict) or set(attempt) not in variants: raise ControllerError("Package C RR review attempt schema is malformed")
    for value,label in ((attempt.get("id"),"rr review attempt id"),(attempt.get("run_id"),"rr review run id"),(attempt.get("nonce"),"rr review nonce")):
        _safe_identifier(value,label)
    review_dir=os.path.join(rr_dir,"rr-review-attempts"); expected_schema=_package_c_rr_review_schema(rr_state,context,attempt["id"],attempt["run_id"],attempt["nonce"])
    schema_info=capped_regular_file_info(attempt.get("schema_path"),review_dir,PACKAGE_C_RR_REVIEW_LOG_CAP) if isinstance(attempt.get("schema_path"),str) else None
    expected_binding=_package_c_rr_review_expected(rr_state,context,attempt)
    try: _parse_utc_instant(attempt.get("prepared_at")); _parse_utc_instant(attempt.get("launch_deadline"))
    except ControllerError as exc: raise ControllerError("Package C RR review attempt time binding changed") from exc
    if (attempt.get("actor_id")!=PACKAGE_C_RR_REVIEW_ACTOR or attempt.get("backend")!=PACKAGE_C_RR_REVIEW_BACKEND or attempt.get("policy")!=POLICY_ID or
            not isinstance(attempt.get("reviewer_session_id"),str) or not attempt["reviewer_session_id"] or
            attempt.get("candidate_id")!=PACKAGE_C_RR_CANDIDATE_ID or attempt.get("evidence_digest")!=PACKAGE_C_RR_EVIDENCE_DIGEST or
            not schema_info or schema_info.get("sha256")!=attempt.get("schema_sha256") or
            attempt.get("binding_sha256")!=digest_bytes(json.dumps(expected_binding,sort_keys=True,separators=(",",":")).encode()) or
            any(not isinstance(attempt.get(key),str) or not inside(attempt[key],root) for key,root in (("output_path",review_dir),("receipt_path",review_dir),("stdout",os.path.join(rr_dir,"logs")),("stderr",os.path.join(rr_dir,"logs"))))):
        raise ControllerError("Package C RR review attempt binding changed")
    try: schema=json.loads(Path(schema_info["path"]).read_text())
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR review schema is unreadable") from exc
    if schema!=expected_schema: raise ControllerError("Package C RR review schema binding changed")
    return attempt


def _package_c_rr_context(rr_dir: str, rr_state: Dict[str,Any], source_dir: str, source_state: Dict[str,Any]) -> Dict[str,Any]:
    agg_path,refs=_package_c_rr_aggregate_intact(source_dir,source_state)
    dossier=_package_c_rr_dossier_intact(rr_dir,rr_state)
    return {"refs":refs,"agg_path":agg_path,"dossier":dossier}


def _package_c_rr_review_capacity_wait(rr_dir: str, rr_state: Dict[str,Any], context: Dict[str,Any], attempt: Dict[str,Any],
                                        terminal: Dict[str,Any], receipt: Dict[str,Any], capacity_event: Dict[str,Any]) -> Dict[str,Any]:
    retry_after=parse_retry_after(capacity_event.get("rate_limit_info",{}).get("resetsAt"))
    mode=("scheduled" if isinstance(retry_after,str) else "manual_signal")
    cap_dir=os.path.join(rr_dir,"rr-review-capacity"); os.makedirs(cap_dir,mode=0o700,exist_ok=True)
    packet={"schema_version":SCHEMA,"kind":"package_c_rr_review_capacity","package_id":PACKAGE_C_RR_PACKAGE_ID,"policy":POLICY_ID,
            "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
            "review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),
            "mode":mode,"retry_after":retry_after,"terminal_receipt_sha256":receipt["sha256"],
            "verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,"issued_at":utc()}
    path=os.path.join(cap_dir,attempt["id"]+".json"); info=_package_a_adopt_json(path,cap_dir,packet,"c rr review capacity packet")
    rr_state["rr_review_capacity"]={"path":path,"sha256":info["sha256"],"mode":mode,"retry_after":retry_after,
        "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
        "review_attempt_id":attempt["id"],"provider_session_id":attempt.get("reviewer_session_id",""),"wakeup":None,"consumed_at":None}
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_c_rr_review","phase":"awaiting_capacity","capacity":{"mode":mode,"retry_after":retry_after,"failure_class":"subscription_quota_exhausted"}}


def _package_c_rr_review_capacity_intact(rr_dir: str, rr_state: Dict[str,Any]) -> Tuple[Dict[str,Any],Dict[str,Any]]:
    bound=rr_state.get("rr_review_capacity") if isinstance(rr_state.get("rr_review_capacity"),dict) else {}
    if not bound: raise ControllerError("Package C RR review capacity state is not set")
    cap_dir=os.path.join(rr_dir,"rr-review-capacity")
    info=capped_regular_file_info(bound.get("path"),cap_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not info or info.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C RR review capacity packet changed")
    try: packet=json.loads(Path(info["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR review capacity packet is unreadable") from exc
    return packet, info


def _command_launch_package_c_rr_review(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir)
    if rr_state.get("rr_review"): raise ControllerError("Package C RR review already ingested")
    if rr_state.get("rr_supersession"): raise ControllerError("Package C RR supersession already applied")
    root=os.path.dirname(rr_dir); source_dir,source_state=_package_c_rr_source_intact(root)
    context=_package_c_rr_context(rr_dir,rr_state,source_dir,source_state)
    existing=rr_state.get("rr_review_attempt") if isinstance(rr_state.get("rr_review_attempt"),dict) else None
    if existing:
        _package_c_rr_review_attempt_intact(rr_dir,rr_state,context,existing)
        if os.path.lexists(existing["receipt_path"]):
            _package_c_rr_review_terminal(rr_dir,existing)
            return {"schema_version":SCHEMA,"operation":"launch_package_c_rr_review","attempt_id":existing["id"],"run_id":existing["run_id"],"reused":True,"terminal_ready":True}
        if process_alive(existing.get("pid"),existing.get("pgid")):
            return {"schema_version":SCHEMA,"operation":"launch_package_c_rr_review","attempt_id":existing["id"],"run_id":existing["run_id"],"reused":True,"terminal_ready":False}
        if existing.get("pid") is None and not existing.get("spawn_error") and not existing.get("launch_lost"):
            deadline=_parse_utc_instant(existing["launch_deadline"])
            if dt.datetime.now(dt.timezone.utc)<deadline:
                return {"schema_version":SCHEMA,"operation":"launch_package_c_rr_review","attempt_id":existing["id"],"run_id":existing["run_id"],"reused":True,"launch_ambiguous_until":existing["launch_deadline"]}
            classification="prepared_launch_lost"; existing["launch_lost"]=classification; existing["launch_lost_sha256"]=digest_bytes(classification.encode()); existing["terminal_at"]=utc()
            save_rr(rr_dir,rr_state)
        raise ControllerError("Package C RR independent review attempt already exists")
    actor=PACKAGE_C_RR_REVIEW_ACTOR; run=str(uuid.uuid4()); attempt_id=str(uuid.uuid4()); nonce=uuid.uuid4().hex; reviewer_session_id=str(uuid.uuid4())
    review_dir=os.path.join(rr_dir,"rr-review-attempts")
    if os.path.lexists(review_dir) and (os.path.islink(review_dir) or not os.path.isdir(review_dir)): raise ControllerError("Package C RR review directory is unsafe")
    os.makedirs(review_dir,mode=0o700,exist_ok=True)
    schema_path=os.path.join(review_dir,attempt_id+".schema.json"); output_path=os.path.join(review_dir,attempt_id+".output.json"); receipt_path=os.path.join(review_dir,attempt_id+".terminal.json")
    schema=_package_c_rr_review_schema(rr_state,context,attempt_id,run,nonce); schema_info=_package_a_adopt_json(schema_path,review_dir,schema,"c rr review schema")
    expected=_package_c_rr_review_expected(rr_state,context,{"id":attempt_id,"run_id":run,"nonce":nonce,"reviewer_session_id":reviewer_session_id})
    dossier=context["dossier"]
    prompt=("Package C controller-owned independent-review recovery. "
            "Read ONLY the sealed review dossier at: %s. "
            "Do not read any other file, run tests, execute shell commands, spawn agents, or explore the repository. "
            "The dossier contains the full cowork_dispatch.py production module, git diffs for changed files, "
            "gate summaries, and exact controller bindings. "
            "Review the AttemptLink/v1 seam in cowork_dispatch.py, pending-turn source-precedence save/replay linkage, "
            "gate-repair delivery linkage, and confirm Package B refusal behavior is unchanged. "
            "Return only the required schema JSON packet bound to the exact candidate_id, evidence_digest, "
            "dossier_sha256, and verification_aggregate_sha256 provided in the dossier. "
            "Copy verification_receipt_sha256s exactly as %s and changed_paths exactly as %s. "
            "Do not infer or replace either array." % (
                dossier["path"],
                json.dumps([r["sha256"] for r in context["refs"]],separators=(",",":")),
                json.dumps(PACKAGE_C_RR_CHANGED_PATHS,separators=(",",":"))));
    if len(prompt.encode())>MAX_INSTRUCTION: raise ControllerError("Package C RR review prompt exceeds bound")
    logs=os.path.join(rr_dir,"logs"); os.makedirs(logs,mode=0o700,exist_ok=True); stdout=os.path.join(logs,attempt_id+".package-c-rr.stdout.log"); stderr=os.path.join(logs,attempt_id+".package-c-rr.stderr.log")
    schema_json=json.dumps(schema,sort_keys=True,separators=(",",":"))
    claude_argv=[resolve_executable(args.claude_bin),"-p","--safe-mode","--permission-mode","plan","--disallowedTools","Agent,Task,Bash","--output-format","stream-json","--verbose","--json-schema",schema_json,"--model","claude-sonnet-4-6","--effort","medium","--session-id",reviewer_session_id,prompt]
    argv_digest=digest_bytes(json.dumps(claude_argv).encode())
    wrapper=[sys.executable,os.path.abspath(__file__),"review-wrapper","--terminal-kind",PACKAGE_C_RR_TERMINAL_KIND,"--receipt",receipt_path,"--attempt-id",attempt_id,"--argv-digest",argv_digest,"--nonce",nonce,"--output-path",output_path,"--stdout-path",stdout,"--stderr-path",stderr,"--codex-argv-json",json.dumps(claude_argv)]
    prepared_at=utc(); launch_deadline=(dt.datetime.now(dt.timezone.utc)+dt.timedelta(seconds=905)).isoformat().replace("+00:00","Z")
    rr_state["rr_review_attempt"]={"id":attempt_id,"actor_id":actor,"run_id":run,"nonce":nonce,"prepared_at":prepared_at,"launch_deadline":launch_deadline,"backend":PACKAGE_C_RR_REVIEW_BACKEND,
        "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,"policy":POLICY_ID,"schema_path":schema_path,"schema_sha256":schema_info["sha256"],
        "output_path":output_path,"reviewer_session_id":reviewer_session_id,"stdout":stdout,"stderr":stderr,"receipt_path":receipt_path,"receipt_sha256":None,"argv_digest":argv_digest,
        "binding_sha256":digest_bytes(json.dumps(expected,sort_keys=True,separators=(",",":")).encode()),"pid":None,"pgid":None,"consumed_at":None}
    save_rr(rr_dir,rr_state)
    try: pid,pgid=detached_spawn(wrapper,rr_dir,stdout,stderr)
    except (OSError,ControllerError) as exc:
        rr_state["rr_review_attempt"]["spawn_error"]=type(exc).__name__; rr_state["rr_review_attempt"]["spawn_error_sha256"]=digest_bytes(type(exc).__name__.encode()); rr_state["rr_review_attempt"]["terminal_at"]=utc()
        save_rr(rr_dir,rr_state); raise ControllerError("Package C RR review controller spawn failed") from exc
    rr_state["rr_review_attempt"].update({"pid":pid,"pgid":pgid,"started_at":utc()}); save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"launch_package_c_rr_review","attempt_id":attempt_id,"run_id":run}


def command_launch_package_c_rr_review(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id)
    with package_lock(rr_dir): return _command_launch_package_c_rr_review(args)


def _command_ingest_package_c_rr_review(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir)
    if rr_state.get("rr_supersession"): raise ControllerError("Package C RR supersession already applied; no further ingestion")
    if rr_state.get("rr_review"): return {"schema_version":SCHEMA,"operation":"ingest_package_c_rr_review","verdict":rr_state["rr_review"]["verdict"],"reused":True}
    cap=rr_state.get("rr_review_capacity")
    if isinstance(cap,dict) and cap and not cap.get("consumed_at"):
        return {"schema_version":SCHEMA,"operation":"ingest_package_c_rr_review","phase":"awaiting_capacity","capacity":cap}
    root=os.path.dirname(rr_dir); source_dir,source_state=_package_c_rr_source_intact(root)
    context=_package_c_rr_context(rr_dir,rr_state,source_dir,source_state)
    attempt=rr_state.get("rr_review_attempt") if isinstance(rr_state.get("rr_review_attempt"),dict) else {}
    if not attempt or attempt.get("consumed_at") or process_alive(attempt.get("pid"),attempt.get("pgid")): raise ControllerError("Package C RR review requires a quiescent controller-owned attempt")
    _package_c_rr_review_attempt_intact(rr_dir,rr_state,context,attempt)
    terminal,receipt=_package_c_rr_review_terminal(rr_dir,attempt)
    if terminal.get("exit_code")!=0 or terminal.get("timed_out") or terminal.get("output_limit_exceeded"):
        capacity_event=_package_a_claude_capacity_event(attempt["stdout"],rr_dir,attempt.get("reviewer_session_id",""))
        if capacity_event and not terminal.get("timed_out") and not terminal.get("output_limit_exceeded"):
            return _package_c_rr_review_capacity_wait(rr_dir,rr_state,context,attempt,terminal,receipt,capacity_event)
        if terminal.get("timed_out"): raise ControllerError("Package C RR review timed out; timeout is terminal fail-closed for recovery")
        if terminal.get("output_limit_exceeded"): raise ControllerError("Package C RR review output overflow; fail-closed for recovery")
        raise ControllerError("Package C RR independent review did not exit successfully")
    output=capped_regular_file_info(attempt.get("output_path"),os.path.join(rr_dir,"rr-review-attempts"),64*1024) if isinstance(attempt.get("output_path"),str) else None
    if not output or terminal.get("output_sha256")!=output["sha256"] or terminal.get("output_bytes")!=output["bytes"]: raise ControllerError("Package C RR review output binding changed")
    try: packet=json.loads(Path(output["path"]).read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR review output must be JSON") from exc
    provider_session=_package_a_claude_session(attempt["stdout"],rr_dir,attempt.get("reviewer_session_id",""))
    history=rr_state.get("rr_review_attempt_history",[])
    prior_sessions={row.get("provider_session_id") for row in (history if isinstance(history,list) else []) if isinstance(row,dict)}
    if provider_session in prior_sessions: raise ControllerError("Package C RR reviewer provider session is not distinct from prior attempts")
    expected=_package_c_rr_review_expected(rr_state,context,attempt); required=set(expected)|{"verdict","findings","checks"}
    if (not isinstance(packet,dict) or set(packet)!=required or any(packet.get(k)!=v for k,v in expected.items()) or
            packet.get("verdict") not in {"pass","needs_correction","fail"} or not isinstance(packet.get("findings"),list) or len(packet["findings"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["findings"]) or not isinstance(packet.get("checks"),list) or len(packet["checks"])>20 or
            any(not isinstance(x,str) or len(x.encode())>1000 for x in packet["checks"])):
        raise ControllerError("Package C RR independent review packet failed strict binding validation")
    if packet.get("verdict")!="pass": raise ControllerError("Package C RR review verdict is not pass; fail-closed")
    packets_dir=os.path.join(rr_dir,"rr-packets"); os.makedirs(packets_dir,mode=0o700,exist_ok=True)
    destination=os.path.join(packets_dir,PACKAGE_C_RR_CANDIDATE_ID+".rr-review.json")
    model_packet_sha256=_package_a_json_sha256(packet)
    envelope={"schema_version":SCHEMA,"kind":"package_c_rr_review_envelope","package_id":PACKAGE_C_RR_PACKAGE_ID,"policy":POLICY_ID,
              "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
              "actor_id":PACKAGE_C_RR_REVIEW_ACTOR,"run_id":attempt["run_id"],"review_attempt_id":attempt["id"],
              "reviewer_session_id":provider_session,"terminal_receipt_sha256":receipt["sha256"],
              "model_packet_sha256":model_packet_sha256,"model_packet":packet}
    envelope_info=_package_a_adopt_json(destination,packets_dir,envelope,"c rr review envelope")
    consumed=utc(); attempt["consumed_at"]=consumed; attempt["packet_sha256"]=envelope_info["sha256"]; attempt["provider_session_id"]=provider_session
    rr_state["rr_review"]={"path":destination,"sha256":envelope_info["sha256"],"candidate_id":PACKAGE_C_RR_CANDIDATE_ID,
        "evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,"actor_id":PACKAGE_C_RR_REVIEW_ACTOR,
        "run_id":attempt["run_id"],"provider_session_id":provider_session,"policy":POLICY_ID,"verdict":packet["verdict"],
        "model_packet_sha256":model_packet_sha256,"verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,"receipt_sha256":receipt["sha256"]}
    history=list(rr_state.get("rr_review_attempt_history",[]) if isinstance(rr_state.get("rr_review_attempt_history"),list) else [])
    rr_state["rr_review_attempt_history"]=history+[{**attempt}]; rr_state["rr_review_attempt"]={**attempt}
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"ingest_package_c_rr_review","verdict":packet["verdict"],"envelope_sha256":envelope_info["sha256"]}


def command_ingest_package_c_rr_review(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id)
    with package_lock(rr_dir): return _command_ingest_package_c_rr_review(args)


def command_register_package_c_rr_review_capacity_wakeup(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir); packet,packet_info=_package_c_rr_review_capacity_intact(rr_dir,rr_state)
    bound=rr_state["rr_review_capacity"]
    if bound.get("mode")!="scheduled" or not isinstance(bound.get("retry_after"),str): raise ControllerError("Package C RR manual review capacity cannot register an agent wakeup")
    ref=args.wakeup_ref.strip()
    if not ref or len(ref.encode())>500: raise ControllerError("Package C RR review wakeup reference is required and bounded")
    receipt_core={"schema_version":SCHEMA,"kind":"package_c_rr_review_capacity_wakeup","package_id":PACKAGE_C_RR_PACKAGE_ID,"policy":POLICY_ID,
        "capacity_packet_sha256":packet_info["sha256"],"candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
        "review_attempt_id":bound["review_attempt_id"],"retry_after":bound["retry_after"],"wakeup_ref_sha256":digest_bytes(ref.encode())}
    lease_id=digest_bytes(json.dumps(receipt_core,sort_keys=True,separators=(",",":")).encode()); receipt={**receipt_core,"lease_id":lease_id,"issued_at":packet["issued_at"]}
    root=os.path.join(rr_dir,"rr-review-capacity-wakeups"); os.makedirs(root,mode=0o700,exist_ok=True); path=os.path.join(root,lease_id+".json")
    info=_package_a_adopt_json(path,root,receipt,"c rr review capacity wakeup")
    expected={"path":info["path"],"sha256":info["sha256"],"lease_id":lease_id,"wakeup_ref":ref,"consumed_at":None}
    if bound.get("wakeup") and bound["wakeup"]!=expected: raise ControllerError("Package C RR review capacity has a different wakeup")
    bound["wakeup"]=expected; save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"register_package_c_rr_review_capacity_wakeup","lease_id":lease_id,"retry_after":bound["retry_after"],"reused":False}


def command_resume_package_c_rr_review_capacity(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir); packet,packet_info=_package_c_rr_review_capacity_intact(rr_dir,rr_state); bound=rr_state["rr_review_capacity"]
    if bound.get("mode")!="scheduled": raise ControllerError("Package C RR manual review capacity requires an authenticated outer adapter signal")
    due=_parse_utc_instant(bound.get("retry_after"))
    if due>dt.datetime.now(dt.timezone.utc): raise ControllerError("Package C RR review capacity retry time has not elapsed")
    wake=bound.get("wakeup") if isinstance(bound.get("wakeup"),dict) else {}
    item=capped_regular_file_info(wake.get("path"),os.path.join(rr_dir,"rr-review-capacity-wakeups"),MAX_PLAN_ARTIFACT_BYTES) if isinstance(wake.get("path"),str) else None
    if not item or item.get("sha256")!=wake.get("sha256") or wake.get("consumed_at") or bound.get("consumed_at"): raise ControllerError("Package C RR review capacity wakeup lease is missing or consumed")
    attempt=rr_state["rr_review_attempt"]; archived={**attempt,"capacity_packet_sha256":packet_info["sha256"],"capacity_disposition":"scheduled_continuation"}
    history=list(rr_state.get("rr_review_attempt_history",[]) if isinstance(rr_state.get("rr_review_attempt_history"),list) else [])
    consumed=utc(); wake["consumed_at"]=consumed; bound["consumed_at"]=consumed
    rr_state["rr_review_attempt_history"]=history+[archived]; rr_state["rr_review_capacity_history"]=[{**bound}]
    rr_state["rr_review_attempt"]=None; rr_state["rr_review_capacity"]=None
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"resume_package_c_rr_review_capacity","delivery":"fresh_controller_review_continuation"}


def _package_c_rr_review_intact(rr_dir: str, rr_state: Dict[str,Any]) -> Dict[str,Any]:
    bound=rr_state.get("rr_review") if isinstance(rr_state.get("rr_review"),dict) else {}
    keys={"path","sha256","candidate_id","evidence_digest","actor_id","run_id","provider_session_id","policy","verdict","model_packet_sha256","verification_aggregate_sha256","receipt_sha256"}
    if set(bound)!=keys: raise ControllerError("Package C RR review state binding is malformed")
    if (bound.get("candidate_id")!=PACKAGE_C_RR_CANDIDATE_ID or bound.get("evidence_digest")!=PACKAGE_C_RR_EVIDENCE_DIGEST or
            bound.get("actor_id")!=PACKAGE_C_RR_REVIEW_ACTOR or bound.get("policy")!=POLICY_ID or
            bound.get("verification_aggregate_sha256")!=PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256 or bound.get("verdict")!="pass"):
        raise ControllerError("Package C RR review state binding fields changed")
    packets_dir=os.path.join(rr_dir,"rr-packets")
    item=capped_regular_file_info(bound.get("path"),packets_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(bound.get("path"),str) else None
    if not item or item.get("sha256")!=bound.get("sha256"): raise ControllerError("Package C RR review envelope changed")
    return {"info":item,"bound":bound}


def _package_c_rr_supersession_replay(rr_dir: str, rr_state: Dict[str,Any]) -> Optional[Dict[str,Any]]:
    sup=rr_state.get("rr_supersession") if isinstance(rr_state.get("rr_supersession"),dict) else {}
    if sup:
        keys={"receipt_path","receipt_sha256","supersession_id","source_gate_new_receipt_path","source_gate_new_receipt_sha256","applied_at"}
        if set(sup)!=keys: raise ControllerError("Package C RR supersession state binding is malformed")
        sup_dir=os.path.join(rr_dir,"rr-supersession")
        receipt_info=capped_regular_file_info(sup.get("receipt_path"),sup_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(sup.get("receipt_path"),str) else None
        if not receipt_info or receipt_info.get("sha256")!=sup.get("receipt_sha256"): raise ControllerError("Package C RR supersession receipt changed")
        return {"schema_version":SCHEMA,"operation":"apply_package_c_rr_supersession","reused":True,
                "supersession_id":sup["supersession_id"],"receipt_sha256":sup["receipt_sha256"],
                "source_gate_new_receipt_sha256":sup["source_gate_new_receipt_sha256"]}
    # Crash-recovery: pending marker was written before source mutation but rr_supersession was not yet committed
    pending=rr_state.get("rr_supersession_pending") if isinstance(rr_state.get("rr_supersession_pending"),dict) else {}
    if not pending: return None
    return _package_c_rr_supersession_pending_recovery(rr_dir,rr_state,pending)


def _package_c_rr_supersession_pending_recovery(rr_dir: str, rr_state: Dict[str,Any], pending: Dict[str,Any]) -> Dict[str,Any]:
    """Finish an interrupted supersession whose pending marker survived the crash but whose
    rr_supersession entry was never committed to the recovery state."""
    required={"supersession_id","receipt_path","receipt_sha256","source_gate_new_receipt_path","source_gate_new_receipt_sha256"}
    if set(pending)!=required: raise ControllerError("Package C RR supersession pending marker has unexpected keys")
    sup_dir=os.path.join(rr_dir,"rr-supersession")
    receipt_info=capped_regular_file_info(pending.get("receipt_path"),sup_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(pending.get("receipt_path"),str) else None
    if not receipt_info or receipt_info.get("sha256")!=pending.get("receipt_sha256"): raise ControllerError("Package C RR supersession pending receipt changed during crash recovery")
    root=os.path.dirname(rr_dir); source_dir=work_dir(root,PACKAGE_C_RR_SOURCE_WORK_ID)
    try: raw=Path(state_path(source_dir)).read_bytes()
    except OSError as exc: raise ControllerError("Package C RR source state unreadable during crash recovery") from exc
    try: source_state=json.loads(raw)
    except json.JSONDecodeError as exc: raise ControllerError("Package C RR source state invalid JSON during crash recovery") from exc
    sup_id=pending["supersession_id"]
    # Determine how far the interrupted supersession progressed
    source_is_completed=(isinstance(source_state,dict) and source_state.get("phase")=="completed" and
                         isinstance(source_state.get("package_c_rr_supersession"),dict) and
                         source_state["package_c_rr_supersession"].get("supersession_id")==sup_id)
    source_is_failed=(isinstance(source_state,dict) and source_state.get("phase")=="failed" and
                      source_state.get("revision")==PACKAGE_C_RR_SOURCE_REVISION and digest_bytes(raw)==PACKAGE_C_RR_SOURCE_STATE_SHA256)
    if not source_is_completed and not source_is_failed:
        raise ControllerError("Package C RR supersession crash recovery: source state is in an unrecognised transition state")
    gate_dir=os.path.join(source_dir,"package-c-gates")
    gate_info=capped_regular_file_info(pending.get("source_gate_new_receipt_path"),gate_dir,MAX_PLAN_ARTIFACT_BYTES) if isinstance(pending.get("source_gate_new_receipt_path"),str) else None
    if not gate_info or gate_info.get("sha256")!=pending.get("source_gate_new_receipt_sha256"): raise ControllerError("Package C RR supersession crash recovery: new gate receipt changed")
    if source_is_failed:
        # Crash happened after pending write but before source mutation — apply source mutation now
        try: gate_receipt=json.loads(Path(gate_info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR crash recovery gate receipt unreadable") from exc
        new_gate_receipt_id=gate_receipt.get("receipt_id","")
        source_state["phase"]="completed"
        source_state["gate"]={"kind":PACKAGE_C_RR_GATE_KIND,"gate_name":PACKAGE_C_GATE_PRINCIPAL,"verdict":"pass",
            "reason_code":PACKAGE_C_RR_GATE_REASON_PASS,"candidate_id":PACKAGE_C_RR_CANDIDATE_ID,
            "evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,"receipt_id":new_gate_receipt_id,
            "receipt_sha256":gate_info["sha256"],"policy":POLICY_ID}
        if isinstance(source_state.get("package_c_gate_receipt"),dict):
            source_state["package_c_gate_receipt"]["sha256"]=gate_info["sha256"]
            source_state["package_c_gate_receipt"]["path"]=gate_info["path"]
            source_state["package_c_gate_receipt"]["receipt_id"]=new_gate_receipt_id
            source_state["package_c_gate_receipt"]["disposition"]="pass"
        source_state["package_c_rr_supersession"]={"receipt_sha256":receipt_info["sha256"],"supersession_id":sup_id,"recovery_package_id":PACKAGE_C_RR_PACKAGE_ID}
        save(source_dir,source_state)
    # Append applied event if missing (idempotent guard)
    applied_kind="package_c_rr_supersession_applied"
    source_events_path=os.path.join(source_dir,"events.jsonl")
    try: existing=Path(source_events_path).read_text(encoding="utf-8").splitlines() if os.path.lexists(source_events_path) else []
    except (OSError,UnicodeDecodeError): existing=[]
    if not any(applied_kind in line for line in existing):
        row={"at":utc(),"kind":applied_kind,"supersession_id":sup_id,"new_phase":"completed","recovery":"crash_recovery"}
        with open(source_events_path,"ab") as out:
            out.write((json.dumps(row,sort_keys=True,separators=(",",":"))+"\n").encode()); out.flush(); os.fsync(out.fileno())
    # Commit recovery state: promote pending to full supersession
    rr_state["rr_supersession"]={"receipt_path":receipt_info["path"],"receipt_sha256":receipt_info["sha256"],
        "supersession_id":sup_id,"source_gate_new_receipt_path":gate_info["path"],
        "source_gate_new_receipt_sha256":gate_info["sha256"],"applied_at":utc()}
    rr_state.pop("rr_supersession_pending",None)
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"apply_package_c_rr_supersession","reused":False,
            "supersession_id":sup_id,"receipt_sha256":receipt_info["sha256"],
            "source_gate_new_receipt_sha256":gate_info["sha256"],"crash_recovered":True}


def _command_apply_package_c_rr_supersession(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id); rr_state=load_rr(rr_dir)
    replay=_package_c_rr_supersession_replay(rr_dir,rr_state)
    if replay: return replay
    if not rr_state.get("rr_review"): raise ControllerError("Package C RR supersession requires an ingested passing review")
    # Validate both the review envelope and source state
    _package_c_rr_review_intact(rr_dir,rr_state)
    root=os.path.dirname(rr_dir); source_dir,source_state=_package_c_rr_source_intact(root)
    agg_path,refs=_package_c_rr_aggregate_intact(source_dir,source_state)
    dossier=_package_c_rr_dossier_intact(rr_dir,rr_state)
    review_bound=rr_state["rr_review"]
    # Build supersession receipt (content-addressed; idempotent on crash)
    sup_dir=os.path.join(rr_dir,"rr-supersession")
    if os.path.lexists(sup_dir) and (os.path.islink(sup_dir) or not os.path.isdir(sup_dir)): raise ControllerError("Package C RR supersession directory is unsafe")
    os.makedirs(sup_dir,mode=0o700,exist_ok=True)
    receipt_immutable={"schema_version":SCHEMA,"kind":"package_c_rr_supersession_receipt",
        "package_id":PACKAGE_C_RR_PACKAGE_ID,"policy":POLICY_ID,
        "source_work_id":PACKAGE_C_RR_SOURCE_WORK_ID,"source_revision":PACKAGE_C_RR_SOURCE_REVISION,
        "source_state_sha256":PACKAGE_C_RR_SOURCE_STATE_SHA256,
        "source_gate_sha256":PACKAGE_C_RR_FAILED_GATE_SHA256,
        "first_timeout_sha256":PACKAGE_C_RR_FIRST_TIMEOUT_SHA256,
        "second_timeout_sha256":PACKAGE_C_RR_SECOND_TIMEOUT_SHA256,
        "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
        "candidate_fingerprint_digest":PACKAGE_C_RR_FINGERPRINT,
        "verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,
        "dossier_sha256":dossier["sha256"],"review_envelope_sha256":review_bound["sha256"]}
    supersession_id=digest_bytes(json.dumps(receipt_immutable,sort_keys=True,separators=(",",":")).encode())
    receipt_path=os.path.join(sup_dir,supersession_id+".json")
    issued_at=utc()
    if os.path.lexists(receipt_path):
        if os.path.islink(receipt_path): raise ControllerError("Package C RR supersession receipt orphan is a symlink")
        orphan_info=capped_regular_file_info(receipt_path,sup_dir,MAX_PLAN_ARTIFACT_BYTES)
        if not orphan_info: raise ControllerError("Package C RR supersession receipt orphan is not a safe regular file")
        try: orphan=json.loads(Path(orphan_info["path"]).read_text(encoding="utf-8"))
        except (OSError,json.JSONDecodeError) as exc: raise ControllerError("Package C RR supersession receipt orphan is unreadable") from exc
        expected_keys=set(receipt_immutable)|{"supersession_id","issued_at"}
        if not isinstance(orphan,dict) or set(orphan)!=expected_keys: raise ControllerError("Package C RR supersession receipt orphan has unexpected keys")
        if orphan.get("supersession_id")!=supersession_id: raise ControllerError("Package C RR supersession receipt orphan id conflicts")
        for k,v in receipt_immutable.items():
            if orphan.get(k)!=v: raise ControllerError("Package C RR supersession receipt orphan field %s conflicts"%k)
        try: _parse_utc_instant(orphan.get("issued_at",""))
        except ControllerError: raise ControllerError("Package C RR supersession receipt orphan issued_at is malformed")
        issued_at=orphan["issued_at"]
    full_receipt={**receipt_immutable,"supersession_id":supersession_id,"issued_at":issued_at}
    receipt_info=_package_a_adopt_json(receipt_path,sup_dir,full_receipt,"c rr supersession receipt")
    # Build new gate receipt for Package C (content-addressed; written to source package-c-gates)
    gate_dir=os.path.join(source_dir,"package-c-gates")
    if os.path.lexists(gate_dir) and (os.path.islink(gate_dir) or not os.path.isdir(gate_dir)): raise ControllerError("Package C gates directory is unsafe")
    os.makedirs(gate_dir,mode=0o700,exist_ok=True)
    gate_core={"schema_version":SCHEMA,"kind":PACKAGE_C_RR_GATE_KIND,"work_id":PACKAGE_C_RR_SOURCE_WORK_ID,"policy":POLICY_ID,
               "gate_name":PACKAGE_C_GATE_PRINCIPAL,"adjudicator_principal":PACKAGE_C_GATE_PRINCIPAL,
               "candidate_id":PACKAGE_C_RR_CANDIDATE_ID,"evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,
               "verification_aggregate_sha256":PACKAGE_C_RR_VERIFICATION_AGGREGATE_SHA256,
               "review_envelope_sha256":review_bound["sha256"],
               "supersession_receipt_sha256":receipt_info["sha256"],
               "recovery_package_id":PACKAGE_C_RR_PACKAGE_ID,
               "prior_state_revision":PACKAGE_C_RR_SOURCE_REVISION,
               "prior_gate_sha256":PACKAGE_C_RR_FAILED_GATE_SHA256,
               "first_timeout_sha256":PACKAGE_C_RR_FIRST_TIMEOUT_SHA256,
               "second_timeout_sha256":PACKAGE_C_RR_SECOND_TIMEOUT_SHA256,
               "disposition":"pass","reason_code":PACKAGE_C_RR_GATE_REASON_PASS}
    new_gate_receipt_id=digest_bytes(json.dumps(gate_core,sort_keys=True,separators=(",",":")).encode())
    new_gate_receipt={**gate_core,"receipt_id":new_gate_receipt_id,"issued_at":source_state.get("candidate",{}).get("created_at") or issued_at}
    new_gate_path=os.path.join(gate_dir,new_gate_receipt_id+".json")
    new_gate_info=_package_a_adopt_json(new_gate_path,gate_dir,new_gate_receipt,"c rr supersession gate receipt")
    # Append intent event to Package C events.jsonl (idempotent: skip if already present)
    intent_kind="package_c_rr_supersession_intent"
    source_events_path=os.path.join(source_dir,"events.jsonl")
    try:
        existing_events=Path(source_events_path).read_text(encoding="utf-8").splitlines() if os.path.lexists(source_events_path) else []
    except (OSError,UnicodeDecodeError): existing_events=[]
    already_has_intent=any(intent_kind in line for line in existing_events)
    if not already_has_intent:
        intent_row={"at":utc(),"kind":intent_kind,"supersession_id":supersession_id,"recovery_package_id":PACKAGE_C_RR_PACKAGE_ID,"new_gate_receipt_id":new_gate_receipt_id}
        encoded=(json.dumps(intent_row,sort_keys=True,separators=(",",":"))+"\n").encode()
        if os.path.islink(source_events_path): raise ControllerError("Package C events file may not be a symlink")
        with open(source_events_path,"ab") as out: out.write(encoded); out.flush(); os.fsync(out.fileno())
    # Persist pending marker BEFORE mutating source state: crash-recovery entry point
    rr_state["rr_supersession_pending"]={"supersession_id":supersession_id,
        "receipt_path":receipt_info["path"],"receipt_sha256":receipt_info["sha256"],
        "source_gate_new_receipt_path":new_gate_info["path"],"source_gate_new_receipt_sha256":new_gate_info["sha256"]}
    save_rr(rr_dir,rr_state)
    # Atomically update Package C source state (revision 24 → 25, phase failed → completed)
    if source_state.get("phase")=="failed" and source_state.get("revision")==PACKAGE_C_RR_SOURCE_REVISION:
        source_state["phase"]="completed"
        source_state["gate"]={"kind":PACKAGE_C_RR_GATE_KIND,"gate_name":PACKAGE_C_GATE_PRINCIPAL,"verdict":"pass",
            "reason_code":PACKAGE_C_RR_GATE_REASON_PASS,"candidate_id":PACKAGE_C_RR_CANDIDATE_ID,
            "evidence_digest":PACKAGE_C_RR_EVIDENCE_DIGEST,"receipt_id":new_gate_receipt_id,
            "receipt_sha256":new_gate_info["sha256"],"policy":POLICY_ID}
        source_state["package_c_gate_receipt"]["sha256"]=new_gate_info["sha256"]
        source_state["package_c_gate_receipt"]["path"]=new_gate_info["path"]
        source_state["package_c_gate_receipt"]["receipt_id"]=new_gate_receipt_id
        source_state["package_c_gate_receipt"]["disposition"]="pass"
        source_state["package_c_rr_supersession"]={"receipt_sha256":receipt_info["sha256"],"supersession_id":supersession_id,"recovery_package_id":PACKAGE_C_RR_PACKAGE_ID}
        save(source_dir,source_state)
    # Append applied event to Package C events.jsonl
    applied_kind="package_c_rr_supersession_applied"
    try: existing_events2=Path(source_events_path).read_text(encoding="utf-8").splitlines()
    except (OSError,UnicodeDecodeError): existing_events2=[]
    if not any(applied_kind in line for line in existing_events2):
        applied_row={"at":utc(),"kind":applied_kind,"supersession_id":supersession_id,"new_receipt_id":new_gate_receipt_id,"new_phase":"completed"}
        encoded2=(json.dumps(applied_row,sort_keys=True,separators=(",",":"))+"\n").encode()
        with open(source_events_path,"ab") as out: out.write(encoded2); out.flush(); os.fsync(out.fileno())
    # Promote pending to full supersession and clean up pending marker
    rr_state["rr_supersession"]={"receipt_path":receipt_info["path"],"receipt_sha256":receipt_info["sha256"],
        "supersession_id":supersession_id,"source_gate_new_receipt_path":new_gate_info["path"],
        "source_gate_new_receipt_sha256":new_gate_info["sha256"],"applied_at":utc()}
    rr_state.pop("rr_supersession_pending",None)
    save_rr(rr_dir,rr_state)
    return {"schema_version":SCHEMA,"operation":"apply_package_c_rr_supersession","reused":False,
            "supersession_id":supersession_id,"receipt_sha256":receipt_info["sha256"],
            "source_gate_new_receipt_sha256":new_gate_info["sha256"]}


def command_apply_package_c_rr_supersession(args: argparse.Namespace) -> Dict[str,Any]:
    rr_dir=work_dir(real(args.state_root),args.work_id)
    with package_lock(rr_dir): return _command_apply_package_c_rr_supersession(args)


def parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Deterministic bounded work-package controller")
    sub = p.add_subparsers(dest="command", required=True)
    a = sub.add_parser("prepare", help="freeze a brief and create an isolated worktree")
    a.add_argument("--repo", default=os.getcwd()); a.add_argument("--brief-file", required=True); a.add_argument("--work-id"); a.add_argument("--state-root"); a.add_argument("--backend", default="claude_direct", choices=("claude_direct", "cowork_headless"))
    a = sub.add_parser("launch", help="start or exactly resume a direct Claude attempt")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True); a.add_argument("--role", required=True, choices=sorted(ROLES)); a.add_argument("--resume", action="store_true"); a.add_argument("--claude-bin", default="claude"); a.add_argument("--model"); a.add_argument("--effort", choices=("low", "medium", "high", "xhigh", "max"))
    a = sub.add_parser("materialize-package-a-prerequisites", help="materialize and seal the Package A prerequisite baseline")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("adopt-package-a-candidate", help="transactionally copy v3 candidate files into a fresh v4 worktree")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("build-package-a-v4-dossier", help="build and seal the 128 KiB compact v4 review dossier")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("build-package-a-v5-dossier", help="build and seal the 128 KiB compact v5 review dossier")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("verify-package-a", help="run and seal deterministic Package A candidate gates")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("launch-package-a-review", help="launch the controller-owned read-only Package A Claude review")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True); a.add_argument("--claude-bin", default="claude")
    a = sub.add_parser("ingest-package-a-review", help="ingest the controller-owned Package A Terra review")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
    a = sub.add_parser("retry-package-a-review", help="release the one typed Package A review infrastructure retry")
    a.add_argument("--state-root", required=True); a.add_argument("--work-id", required=True)
